import React from "react";
import { Button, Tooltip } from "antd";
import { FilterOutlined, RedoOutlined } from "@ant-design/icons";
import PhoneInput from "react-phone-number-input";
import { useDashboard } from "../context";
import { RIDE_STATUS_LABELS } from "../constants";
import TimeRangeSelector from "./TimeRangeSelector";

let typingTimeout;

// Status chips (color -> statusCount key) shown left-to-right.
const STATUS_TILES: { color: string; countKey: string }[] = [
  { color: "brown", countKey: "brown" },
  { color: "purple", countKey: "purple" },
  { color: "amber", countKey: "amber" },
  { color: "aqua", countKey: "aqua" },
  { color: "blue", countKey: "blue" },
  { color: "red", countKey: "red" },
  { color: "green", countKey: "green" },
  { color: "gray", countKey: "gray" },
  { color: "black", countKey: "black" },
];

// Toolbar of the all-rides table: phone search, time range, more filters and
// refresh on one line; status chips with counts underneath.
const StatusFilterBar: React.FC = () => {
  const {
    statusSelected,
    setStatusPagePaths,
    statusCount,
    showTableFilterModal,
    setShowTableFilterModal,
    projectFilterLoading,
    statusFilterLoading,
    setProjectFilterLoading,
    searchPage,
    setPhonePagePaths,
    setTimePagePaths,
  } = useDashboard();

  return (
    <div className="ride-toolbar">
      <div className="ride-toolbar__row">
        <div className="ride-toolbar__search">
          <PhoneInput
            placeholder="Search by phone number"
            defaultCountry="US"
            allowClear
            aria-label="Search rides by passenger phone"
            onChange={(phone) => {
              console.log("phone", phone);
              if (typingTimeout) clearTimeout(typingTimeout);
              typingTimeout = setTimeout(() => {
                setPhonePagePaths(phone);
              }, 700);
            }}
          />
        </div>

        <div className="ride-toolbar__time">
          <TimeRangeSelector
            onChange={(value) => {
              console.log("value here", value);
              setTimePagePaths(value);
            }}
            value={undefined}
          />
        </div>

        <div className="ride-toolbar__actions">
          <Tooltip title={showTableFilterModal ? "Hide filters" : "More filters"}>
            <Button
              className={`beam-btn icon-btn ride-toolbar__btn ${
                showTableFilterModal ? "is-active" : ""
              }`}
              aria-label={showTableFilterModal ? "Hide filters" : "More filters"}
              aria-pressed={!!showTableFilterModal}
              onClick={() => {
                setShowTableFilterModal(!showTableFilterModal);
              }}
            >
              <FilterOutlined />
            </Button>
          </Tooltip>

          <Tooltip title="Refresh">
            <Button
              className="beam-btn icon-btn ride-toolbar__btn"
              aria-label="Refresh rides"
              loading={projectFilterLoading || statusFilterLoading}
              onClick={() => {
                setProjectFilterLoading(true);
                searchPage();
              }}
            >
              {!projectFilterLoading && !statusFilterLoading && <RedoOutlined />}
            </Button>
          </Tooltip>
        </div>
      </div>

      <div className="ride-chips" role="group" aria-label="Filter by status">
        <button
          type="button"
          className={`ride-chip ${
            statusSelected === undefined ? "is-active" : ""
          }`}
          aria-pressed={statusSelected === undefined}
          onClick={() => {
            setStatusPagePaths(undefined);
          }}
        >
          All
          <span className="ride-chip__count">{statusCount.live}</span>
        </button>

        {STATUS_TILES.map((tile) => (
          <button
            key={tile.color}
            type="button"
            className={`ride-chip ride-chip--${tile.color} ${
              statusSelected === tile.color ? "is-active" : ""
            }`}
            aria-pressed={statusSelected === tile.color}
            onClick={() => {
              setStatusPagePaths(tile.color);
            }}
          >
            <span className="ride-chip__dot" aria-hidden="true" />
            {RIDE_STATUS_LABELS[tile.color]}
            <span className="ride-chip__count">
              {statusCount[tile.countKey]}
            </span>
          </button>
        ))}
      </div>
    </div>
  );
};

export default StatusFilterBar;
