import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Redirect, useHistory, useParams } from "react-router-dom";
import { Alert, Button, Spin, Tooltip } from "antd";
import {
  CloseOutlined,
  LeftOutlined,
  MenuFoldOutlined,
  MenuOutlined,
  MenuUnfoldOutlined,
} from "@ant-design/icons";

import { SectionDef } from "./data";
import { EMPTY_FILTERS, Filters } from "./types";
import { useProgramsData } from "./api/useProgramsData";
import { sectionIcon } from "./icons";
import Hero from "./Hero";
import SignupSection from "./SignupSection";
import EventsSection from "./EventsSection";
import EventPage from "./EventPage";
import "./Programs.scss";

const COLLAPSE_KEY = "programs.navCollapsed";

const MOBILE_QUERY = "(max-width: 768px)";

const readCollapsed = () => {
  try {
    return localStorage.getItem(COLLAPSE_KEY) === "1";
  } catch {
    return false;
  }
};

/** Tracks the phone breakpoint, matching $pg-mobile in Programs.scss. */
const useIsMobile = () => {
  const [mobile, setMobile] = useState(() => window.matchMedia(MOBILE_QUERY).matches);
  useEffect(() => {
    const mq = window.matchMedia(MOBILE_QUERY);
    const onChange = () => setMobile(mq.matches);
    // Safari < 14 only has the deprecated addListener.
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", onChange);
      else mq.removeListener(onChange);
    };
  }, []);
  return mobile;
};

/**
 * Public programs page, served at /programs/:section, with each event on
 * its own page at /programs/:section/:eventId. No sign-in: Recreational
 * and Traveler embed the CPC sign-up form, the others are an explorer
 * over static events.
 *
 * The filters live here so they carry over between sections.
 */
const ProgramsPage: FC = () => {
  const { section, eventId } = useParams<{ section?: string; eventId?: string }>();
  const history = useHistory();
  const { loading, error, sections, signups, events, filterDefs, config, reload } =
    useProgramsData();
  const current = sections.find((s) => s.id === section);
  const event = eventId ? events.find((e) => e.id === eventId && e.section === section) : undefined;

  const [filters, setFilters] = useState<Filters>(EMPTY_FILTERS);
  const [collapsed, setCollapsed] = useState(readCollapsed);
  const [menuOpen, setMenuOpen] = useState(false);
  const isMobile = useIsMobile();
  // The content pane is the page's only scroller; header and sidebar stay put.
  const contentRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (!event) {
      document.title = current ? `${current.label} | Beam` : "Programs | Beam";
    }
    contentRef.current?.scrollTo({ top: 0 });
  }, [current, event]);

  useEffect(() => {
    try {
      localStorage.setItem(COLLAPSE_KEY, collapsed ? "1" : "0");
    } catch {
      // Storage can be blocked; the rail just won't remember its state.
    }
  }, [collapsed]);

  // The phone menu closes on navigation and when leaving the phone layout.
  useEffect(() => setMenuOpen(false), [section, eventId, isMobile]);

  // Esc closes the phone menu.
  useEffect(() => {
    if (!menuOpen) return undefined;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setMenuOpen(false);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [menuOpen]);

  const upcoming = useMemo(() => {
    const counts: Record<string, number> = {};
    events.forEach((e) => {
      counts[e.section] = (counts[e.section] ?? 0) + 1;
    });
    return counts;
  }, [events]);

  // Until the event form loads, `sections` holds only the two sign-up
  // sections, so /programs/clinics must wait rather than redirect away.
  if (!current) {
    if (loading) {
      return (
        <div className="programs-shell programs-shell--booting">
          <Spin size="large" tip="Loading programs..." />
        </div>
      );
    }
    // Keep the query string (it carries `?token=`) across the redirect.
    return <Redirect to={{ pathname: `/programs/${sections[0].id}`, search: history.location.search }} />;
  }
  if (eventId && !event && !loading && !error) {
    return <Redirect to={{ pathname: `/programs/${current.id}`, search: history.location.search }} />;
  }

  // Carry the query string (it may hold `?token=`) when switching sections.
  const go = (id: string) => history.push({ pathname: `/programs/${id}`, search: history.location.search });

  // Phones: open/close the slide-in menu. Larger screens: full sidebar or icon rail.
  const railCollapsed = collapsed && !isMobile;
  const toggleMenu = () => (isMobile ? setMenuOpen((o) => !o) : setCollapsed((c) => !c));
  const menuLabel = isMobile
    ? menuOpen ? "Close menu" : "Open menu"
    : collapsed ? "Expand sidebar" : "Collapse sidebar";
  const menuIcon = isMobile
    ? menuOpen ? <CloseOutlined /> : <MenuOutlined />
    : collapsed ? <MenuUnfoldOutlined /> : <MenuFoldOutlined />;

  return (
    <div className="programs-shell">
      {/* A div, not <header>: index.css forces padding on every header. */}
      <div className="programs-header" role="banner">
        <div className="programs-header__brand">
          <Tooltip title={isMobile ? undefined : menuLabel} placement="bottomLeft">
            <button
              type="button"
              className="programs-header__menu"
              aria-label={menuLabel}
              aria-expanded={isMobile ? menuOpen : !collapsed}
              aria-controls="programs-nav"
              onClick={toggleMenu}
            >
              {menuIcon}
            </button>
          </Tooltip>
          <img src={config.logoUrl} alt="Beam" className="programs-header__logo" />
          <span className="programs-header__title">Programs</span>
        </div>
        <span className="programs-header__season">
          <span className="programs-header__dot" /> Registration open · 2026–27 season
        </span>
      </div>

      <div
        className={`programs-shell__body${railCollapsed ? " is-collapsed" : ""}${
          menuOpen ? " is-menu-open" : ""
        }`}
      >
        {isMobile && (
          <div className="programs-nav__backdrop" aria-hidden="true" onClick={() => setMenuOpen(false)} />
        )}
        <nav id="programs-nav" className="programs-nav" aria-label="Programs">
          <ul>
            {sections.map((s) => (
              <NavItem
                key={s.id}
                section={s}
                active={s.id === current.id}
                collapsed={railCollapsed}
                count={upcoming[s.id]}
                onClick={() => go(s.id)}
              />
            ))}
          </ul>
          {!isMobile && (
            <Tooltip title={menuLabel} placement="right">
              <button
                type="button"
                className="programs-nav__handle"
                aria-label={menuLabel}
                onClick={toggleMenu}
              >
                <LeftOutlined />
              </button>
            </Tooltip>
          )}
        </nav>

        <main ref={contentRef} className="programs-content">
          {/* Keyed by page so the entry animation replays on every switch. */}
          <div key={event?.id ?? current.id} className="programs-content__inner">
            {error && (
              <Alert
                type="error"
                showIcon
                className="programs-alert"
                message="Programs could not be loaded"
                description={error}
                action={
                  <Button size="small" onClick={reload}>
                    Retry
                  </Button>
                }
              />
            )}
            {event ? (
              <EventPage event={event} events={events} sections={sections} />
            ) : (
              <>
                <Hero section={current} events={events} />
                {current.kind === "form" ? (
                  <SignupSection section={current} signup={signups[current.id]} />
                ) : loading ? (
                  <div className="programs-card programs-loading">
                    <Spin size="large" tip={`Loading ${current.label.toLowerCase()}...`} />
                  </div>
                ) : (
                  <EventsSection
                    section={current}
                    events={events}
                    filterDefs={filterDefs}
                    filters={filters}
                    onFiltersChange={setFilters}
                  />
                )}
              </>
            )}
          </div>
        </main>
      </div>
    </div>
  );
};

const NavItem: FC<{
  section: SectionDef;
  active: boolean;
  collapsed: boolean;
  count?: number;
  onClick: () => void;
}> = ({ section, active, collapsed, count, onClick }) => {
  const button = (
    <button
      type="button"
      className={`programs-nav__item${active ? " is-active" : ""}`}
      aria-current={active ? "page" : undefined}
      onClick={onClick}
    >
      <span className="programs-nav__icon">{sectionIcon(section.id)}</span>
      <span className="programs-nav__text">
        <span className="programs-nav__label">{section.label}</span>
        <span className="programs-nav__hint">{section.hint}</span>
      </span>
      {count ? <span className="programs-nav__count">{count}</span> : null}
    </button>
  );

  return (
    <li>
      {collapsed ? (
        <Tooltip title={section.label} placement="right">
          {button}
        </Tooltip>
      ) : (
        button
      )}
    </li>
  );
};

export default ProgramsPage;
