import React, { FC } from "react";

import { PricingWindows } from "../../types";
import { AmountRuleFields, DateField, FormRow, SwitchField } from "../fields";
import { SectionProps } from "./types";

const PricingWindowsSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const w = config.pricingWindows;
  const patchEarly = (changes: Partial<PricingWindows["earlyBird"]>) =>
    patch({ pricingWindows: { ...w, earlyBird: { ...w.earlyBird, ...changes } } });
  const patchLate = (changes: Partial<PricingWindows["late"]>) =>
    patch({ pricingWindows: { ...w, late: { ...w.late, ...changes } } });

  return (
    <>
      <SwitchField
        label="Early-bird discount"
        checked={w.earlyBird.enabled}
        disabled={disabled}
        onChange={(enabled) => patchEarly({ enabled })}
      />
      {w.earlyBird.enabled && (
        <FormRow>
          <AmountRuleFields
            value={w.earlyBird}
            currency={config.currency}
            valueLabel="Discount value"
            disabled={disabled}
            onChange={(rule) => patchEarly(rule)}
          />
          <DateField
            label="Register before"
            required
            value={w.earlyBird.endDate}
            disabled={disabled}
            onChange={(endDate) => patchEarly({ endDate })}
          />
        </FormRow>
      )}

      <SwitchField
        label="Late registration surcharge"
        checked={w.late.enabled}
        disabled={disabled}
        onChange={(enabled) => patchLate({ enabled })}
      />
      {w.late.enabled && (
        <FormRow>
          <AmountRuleFields
            value={w.late}
            currency={config.currency}
            valueLabel="Surcharge value"
            disabled={disabled}
            onChange={(rule) => patchLate(rule)}
          />
          <DateField
            label="Applies from"
            required
            value={w.late.startDate}
            disabled={disabled}
            onChange={(startDate) => patchLate({ startDate })}
          />
        </FormRow>
      )}
    </>
  );
};

export default PricingWindowsSection;
