import React, { FC, useMemo } from "react";
import moment from "moment";

import { ProgramEvent, SectionDef } from "./data";
import { sectionIcon } from "./icons";

/**
 * The section header: a plain white dashboard card matching the /sports
 * (School3) chrome. Event sections add the headline stats; form sections stay
 * compact so the sign-up form sits close to the top of the page.
 */
const Hero: FC<{ section: SectionDef; events: ProgramEvent[] }> = ({ section, events }) => {
  const compact = section.kind === "form";
  return (
    <section className={`programs-hero${compact ? " is-compact" : ""}`}>
      <div className="programs-hero__main">
        <span className="programs-hero__icon">{sectionIcon(section.id)}</span>
        <div>
          <span className="programs-hero__eyebrow">{section.eyebrow}</span>
          <h1>{section.title}</h1>
          <p>{section.description}</p>
        </div>
      </div>
      {!compact && <Stats section={section} events={events} />}
    </section>
  );
};

const Stats: FC<{ section: SectionDef; events: ProgramEvent[] }> = ({ section, events }) => {
  const stats = useMemo(() => {
    const today = moment().startOf("day");
    const sectionEvents = events
      .filter((e) => e.section === section.id)
      .sort((a, b) => a.start.localeCompare(b.start));
    const upcoming = sectionEvents.filter((e) => moment(e.end ?? e.start).isSameOrAfter(today));

    // The soonest upcoming event, or the most recent past one when the section
    // has none coming up, so a past event is never labelled "Next date".
    const next = upcoming[0];
    const last = sectionEvents[sectionEvents.length - 1];
    const dateStat = next
      ? { value: moment(next.start).format("MMM D"), label: "Next date" }
      : last
        ? { value: moment(last.start).format("MMM D"), label: "Last event" }
        : { value: "—", label: "Next date" };

    // These soccer events are free, so a price tile says nothing. The useful
    // "who is this for" is the age range the section covers, read off each
    // event's Age group answer. Labels sort by their number ("U-8" < "U-18"),
    // with open-ended ones ("Above 18", "18+") placed last.
    const ageNum = (label: string): number => {
      const match = label.match(/\d+/);
      const n = match ? parseInt(match[0], 10) : 0;
      return /above|over|\+/i.test(label) ? n + 0.5 : n;
    };
    const ageGroups = Array.from(new Set(sectionEvents.flatMap((e) => e.ageGroups)))
      .filter(Boolean)
      .sort((a, b) => ageNum(a) - ageNum(b));
    const ageStat = ageGroups.length
      ? ageGroups.length === 1
        ? ageGroups[0]
        : `${ageGroups[0]} – ${ageGroups[ageGroups.length - 1]}`
      : "—";

    return [
      { value: String(sectionEvents.length), label: "Events" },
      dateStat,
      { value: ageStat, label: "Age groups" },
    ];
  }, [events, section.id]);

  return (
    <dl className="programs-hero__stats">
      {stats.map((s, i) => (
        <div key={s.label} style={{ animationDelay: `${120 + i * 80}ms` }}>
          <dt>{s.label}</dt>
          <dd>{s.value}</dd>
        </div>
      ))}
    </dl>
  );
};

export default Hero;
