import React, { FC, useState } from "react";
import { Modal, Row, Col, Form, Button, DatePicker, message } from "antd";
import moment, { Moment } from "moment";
import ResponderInput from "../../../../common/ResponderInput";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";

const GPSReportModal: FC<{
  visible: boolean;
  onClose: () => void;
  onProceed: (driver: any, startDateTime: string, endDateTime: string) => void;
  loading?: boolean;
}> = ({ visible, onClose, onProceed, loading = false }) => {
  const [form] = Form.useForm();
  const { adminUserRoles } = useSelector((state: RootState) => state.auth);
  const [driver, setDriver] = useState<any>(undefined);

  const handleCancel = () => {
    form.resetFields();
    setDriver(undefined);
    onClose();
  };

  const handleProceed = () => {
    form
      .validateFields()
      .then((values) => {
        const { startDateTime, endDateTime } = values;
        
        // Validate date range
        const start = moment(startDateTime);
        const end = moment(endDateTime);
        const hoursDiff = end.diff(start, "hours", true);

        if (hoursDiff > 24) {
          message.error("Maximum 24 hours allowed for GPS report range");
          return;
        }

        if (hoursDiff <= 0) {
          message.error("End date/time must be after start date/time");
          return;
        }

        if (!driver) {
          message.error("Please select a driver");
          return;
        }

        onProceed(
          driver,
          startDateTime.format("YYYY-MM-DD HH:mm:ss"),
          endDateTime.format("YYYY-MM-DD HH:mm:ss")
        );
      })
      .catch((error) => {
        console.error("Validation failed:", error);
      });
  };

  const handleDriverChange = (value: any) => {
    console.log('handle driver change', value);
    setDriver(value);
    form.setFieldsValue({ driver: value?.id });
  };

  return (
    <Modal
      title="Generate GPS Report"
      visible={visible}
      onCancel={handleCancel}
      width="600px"
      className="beam-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <Form
        className="auth-form"
        name="gps-report-form"
        id="gps-report-form"
        layout="vertical"
        form={form}
        requiredMark={false}
      >
        <Form.Item
          name="driver"
          label="Driver"
          rules={[{ required: true, message: "**Required Field" }]}
          className="mt-3"
        >
          <ResponderInput
            value={driver}
            onChange={handleDriverChange}
            placeholder="Select Driver"
            adminRoles={adminUserRoles}
          />
        </Form.Item>

        <Form.Item
          name="startDateTime"
          label="Start Date & Time"
          rules={[{ required: true, message: "**Required Field" }]}
          className="mt-3"
        >
          <DatePicker
            showTime={{ format: "HH:mm" }}
            format="YYYY-MM-DD HH:mm"
            style={{ width: "100%" }}
            placeholder="Select Start Date & Time"
          />
        </Form.Item>

        <Form.Item
          name="endDateTime"
          label="End Date & Time"
          rules={[
            { required: true, message: "**Required Field" },
            ({ getFieldValue }) => ({
              validator(_, value) {
                if (!value || !getFieldValue("startDateTime")) {
                  return Promise.resolve();
                }
                const start = moment(getFieldValue("startDateTime"));
                const end = moment(value);
                const hoursDiff = end.diff(start, "hours", true);

                if (hoursDiff <= 0) {
                  return Promise.reject(
                    new Error("End date/time must be after start date/time")
                  );
                }
                if (hoursDiff > 24) {
                  return Promise.reject(
                    new Error("Maximum 24 hours allowed for GPS report range")
                  );
                }
                return Promise.resolve();
              },
            }),
          ]}
          className="mt-3"
        >
          <DatePicker
            showTime={{ format: "HH:mm" }}
            format="YYYY-MM-DD HH:mm"
            style={{ width: "100%" }}
            placeholder="Select End Date & Time"
          />
        </Form.Item>

        <Form.Item className="action-grp mt-4">
          <Row>
            <Col span={14} className="pr-2">
              <Button
                loading={loading}
                className="beam-btn green-btn cover w-full"
                onClick={handleProceed}
              >
                Proceed
              </Button>
            </Col>
            <Col span={10} className="pl-2">
              <Button
                className="beam-btn orange-btn bordered w-full"
                onClick={handleCancel}
              >
                Cancel
              </Button>
            </Col>
          </Row>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default GPSReportModal;

