import React from "react";

// Titled group of form fields. The title only shows inside the Ride dispatch
// shell (.ride-shell); elsewhere the section is a plain wrapper. A section
// whose children all render nothing is hidden (see DispatchPanel.scss).
const FormSection: React.FC<{ title: string }> = ({ title, children }) => (
  <section className="ride-section" aria-label={title}>
    <div className="ride-section__head">
      <h4 className="ride-section__title">{title}</h4>
    </div>
    <div className="ride-section__body">{children}</div>
  </section>
);

export default FormSection;
