import React, { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { Card, Row, Col, Spin } from "antd";
import {
  SocketTopics,
  UserTopics,
} from "../../constants/enums";
import {
  getVehicleTypesPath
} from "../../hooks/socketConstants";
import useSocketActions from "../../hooks/socketActions";
import { useLocation } from "react-router-dom";
import { getVehicleTypesTopic } from "hooks/MQTTConstants";
import classNames from "classnames";

const VehicleTypeInput = (props: any) => {
  const { value, placeholder, onChange, socket } = props;
  const { projects, encrypted_token, vehicleTypes } = useSelector(
    (state: RootState) => state.auth
  );

  const [searching, setSearching] = useState(false);
  const [options, setOptions] = useState([]);
  const dispatch = useDispatch();
  const { getUserRequestPayload } = useSocketActions();

  const getVehicleType = () => {
    if (vehicleTypes) {
      setOptions(vehicleTypes);
    } else {
      setSearching(true);


      console.log('projects', projects);
      
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        getUserRequestPayload(
          projects?.adminUserId,
          "$",
          getVehicleTypesPath()
        ),
        getVehicleTypesTopic(encrypted_token?.connectionId),
        projects?.userServiceId
      );
    }
  };

  useEffect(() => {
    if (projects?.userServiceId) {
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        getVehicleTypesTopic(encrypted_token?.connectionId),
        (response) => {
          setSearching(false);
          const opts =
            response?.data?.[0]?.[0]
              ?.map((x) => ({
                id: x._id,
                name: x.name,
                obj: x,
              }))
              .filter(
                (x) => !options.find((y) => x.id === y.id)
              ) || [];

          const mergedOptions = [...options, ...opts];
          setOptions(mergedOptions);
          dispatch({
            type: "SET_VEHICLE_TYPES",
            payload: mergedOptions,
          });
        }
      );
    }
  }, [projects?.userServiceId]);

  useEffect(() => {
    getVehicleType();
  }, []);

  // const handleSelect = (option) => {
  //   onChange({
  //     type: "vehicleType",
  //     value: option.id,
  //     name: option.name,
  //   });
  // };

  const handleSelect = (option) => {
    if (selectedId === option.id) {
      // Double-click: deselect
      onChange(undefined);
    } else {
      // Select
      onChange({
        type: "vehicleType",
        value: option.id,
        name: option.name,
      });
    }
  };

  const selectedId = value?.value;

  return (
    <div>
      {/* <h4>{placeholder || "Select Vehicle Type"}</h4> */}
      {searching ? (
        <Spin />
      ) : (
        <Row gutter={[16, 16]}>
          {options.map((option) => (
            <Col key={option.id} sm={12} md={8}>
              <Card
                hoverable
                className={classNames("vehicle-card", {
                  selected: selectedId === option.id,
                })}
                onClick={() => handleSelect(option)}
                style={{
                  border:
                    selectedId === option.id
                      ? "2px solid #1890ff"
                      : "1px solid #e8e8e8",
                  borderRadius: 8,
                  textAlign: "center",
                }}
              >
                {option.name}
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </div>
  );
};

export default VehicleTypeInput;
