import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Col, Row, Table, Tabs, Tag, Tooltip } from "antd";
import { ColumnsType } from "antd/lib/table";
import {
  BellOutlined,
  CalendarOutlined,
  FileTextOutlined,
  HourglassOutlined,
  ScheduleOutlined,
  WalletOutlined,
  WarningOutlined,
} from "@ant-design/icons";
import moment from "moment";

import {
  Domain,
  LedgerAction,
  LedgerRow,
  ScheduleItem,
  ScheduleStatus,
  TransactionFilter,
} from "../types";
import { ALERTS, DAY, LEDGER_ROWS, NOW } from "../mockData";
import {
  DUNNING_META,
  EMPTY_FILTER,
  buildSchedule,
  filterLedgerRows,
  filterScheduleItems,
  formatMoney,
  formatMoneyShort,
  formatOffset,
} from "../selectors";
import KpiCards, { KpiTile } from "../KpiCards";
import LedgerGrid from "../LedgerGrid";
import ActionModals, { ActionTarget } from "../ActionModals";
import TransactionFilters, { FilterMode } from "../TransactionFilters";

const STAGE_TONE: Record<string, string> = {
  info: "#1F9D55",
  warning: "#FBAE16",
  danger: "#FF5F25",
  critical: "#E5484D",
};

const STATUS_META: Record<ScheduleStatus, { label: string; color: string; bg: string }> = {
  upcoming: { label: "Upcoming", color: "#508AFA", bg: "#E6F0FF" },
  due: { label: "Due", color: "#FBAE16", bg: "#FEF5E1" },
  overdue: { label: "Overdue", color: "#E5484D", bg: "#FDECEC" },
  suspended: { label: "Suspended", color: "#5a6478", bg: "#EFF2F7" },
};

/** Filters handed over by another screen. The nonce re-applies an identical preset. */
export interface TransactionPreset {
  filter: Partial<TransactionFilter>;
  tab?: FilterMode;
  nonce: number;
}

interface Props {
  domain: Domain;
  preset: TransactionPreset | null;
}

/**
 * Every transaction of the domain. Two tabs share one filter: the
 * ledger (each invoiced line with its executive actions) and the
 * payment schedule (what is coming due and what is late, staged by the
 * dunning benchmarks). Other screens land here with a preset applied.
 */
const TransactionsScreen: FC<Props> = ({ domain, preset }) => {
  const [tab, setTab] = useState<FilterMode>("ledger");
  const [filter, setFilter] = useState<TransactionFilter>(EMPTY_FILTER);
  const [action, setAction] = useState<LedgerAction | null>(null);
  const [actionTarget, setActionTarget] = useState<ActionTarget | null>(null);

  /* A preset replaces the filter wholesale; the nonce lets the same preset land twice. */
  useEffect(() => {
    if (!preset) return;
    setFilter({ ...EMPTY_FILTER, ...preset.filter });
    setTab(preset.tab || (preset.filter.scheduleStatuses && preset.filter.scheduleStatuses.length > 0 ? "schedule" : "ledger"));
  }, [preset && preset.nonce]); // eslint-disable-line react-hooks/exhaustive-deps

  const rows = LEDGER_ROWS[domain];
  const ledger = useMemo(() => filterLedgerRows(rows, filter), [rows, filter]);

  const schedule = useMemo(() => buildSchedule(rows, ALERTS[domain], NOW), [rows, domain]);
  const visibleSchedule = useMemo(
    () => filterScheduleItems(schedule, rows, filter),
    [schedule, rows, filter]
  );

  /* ---- tiles ---- */

  const sum = (items: { amount: number }[]) => items.reduce((acc, item) => acc + item.amount, 0);

  const ledgerTiles = useMemo<KpiTile[]>(() => {
    const invoiced = ledger.reduce((acc, r) => acc + r.invoicedServiceFee, 0);
    const collected = ledger.reduce((acc, r) => acc + r.collected, 0);
    const outstanding = ledger.reduce((acc, r) => acc + r.outstanding, 0);
    const pastDue = ledger.reduce((acc, r) => acc + r.pastDue, 0);
    const late = ledger.filter((r) => r.pastDue > 0).length;
    return [
      {
        key: "invoiced",
        label: "Invoiced",
        hint: `${formatMoney(invoiced)} across ${ledger.length} lines in the current filter`,
        value: formatMoneyShort(invoiced),
        sub: `${ledger.length} lines`,
        icon: <FileTextOutlined />,
        color: "#463BBD",
        bg: "#ECEAFB",
      },
      {
        key: "collected",
        label: "Collected",
        hint: formatMoney(collected),
        value: formatMoneyShort(collected),
        sub: invoiced > 0 ? `${Math.round((collected / invoiced) * 100)}% of invoiced` : "-",
        icon: <WalletOutlined />,
        color: "#1F9D55",
        bg: "#E4F6EC",
      },
      {
        key: "outstanding",
        label: "Outstanding",
        hint: `${formatMoney(outstanding)} scheduled but not yet due`,
        value: formatMoneyShort(outstanding),
        sub: "not yet due",
        icon: <CalendarOutlined />,
        color: "#508AFA",
        bg: "#E6F0FF",
      },
      {
        key: "pastDue",
        label: "Past due",
        hint: `${formatMoney(pastDue)} past the scheduled payment hour`,
        value: formatMoneyShort(pastDue),
        sub: `${late} ${late === 1 ? "line" : "lines"} late`,
        icon: <WarningOutlined />,
        color: "#E5484D",
        bg: "#FDECEC",
      },
    ];
  }, [ledger]);

  const scheduleTiles = useMemo<KpiTile[]>(() => {
    const dueThisWeek = visibleSchedule.filter(
      (i) => i.dueAt >= NOW && i.dueAt <= NOW + 7 * DAY && i.status === "upcoming"
    );
    const dueNextMonth = visibleSchedule.filter(
      (i) => i.dueAt >= NOW && i.dueAt <= NOW + 30 * DAY && i.status === "upcoming"
    );
    const overdue = visibleSchedule.filter((i) => i.status === "overdue" || i.status === "suspended");
    const atRisk = visibleSchedule.filter((i) => i.stage === "T+240h" || i.stage === "T+336h");
    return [
      {
        key: "week",
        label: "Due this week",
        hint: `${dueThisWeek.length} installments in the next 7 days`,
        value: formatMoneyShort(sum(dueThisWeek)),
        sub: `${dueThisWeek.length} installments`,
        icon: <CalendarOutlined />,
        color: "#508AFA",
        bg: "#E6F0FF",
      },
      {
        key: "month",
        label: "Due next 30 days",
        hint: `${dueNextMonth.length} installments in the next 30 days`,
        value: formatMoneyShort(sum(dueNextMonth)),
        sub: `${dueNextMonth.length} installments`,
        icon: <ScheduleOutlined />,
        color: "#463BBD",
        bg: "#ECEAFB",
      },
      {
        key: "overdue",
        label: "Overdue",
        hint: `${overdue.length} balances past their payment hour`,
        value: formatMoneyShort(sum(overdue)),
        sub: `${overdue.length} balances`,
        icon: <WarningOutlined />,
        color: "#E5484D",
        bg: "#FDECEC",
      },
      {
        key: "risk",
        label: "Suspension risk",
        hint: "Balances at the final escalation or the suspension threshold",
        value: formatMoneyShort(sum(atRisk)),
        sub: `${atRisk.length} at T+240h / T+336h`,
        icon: <HourglassOutlined />,
        color: "#FBAE16",
        bg: "#FEF5E1",
      },
    ];
  }, [visibleSchedule]);

  /* ---- actions ---- */

  const openRowAction = (next: LedgerAction, row: LedgerRow) => {
    setAction(next);
    setActionTarget({ level: "individual", label: row.entity, rows: [row] });
  };

  const notify = (item: ScheduleItem) => {
    const row =
      rows.find((r) => r.key === item.ledgerKey) ||
      rows.find((r) => r.entity === item.entity && r.project === item.project);
    setAction("notify");
    setActionTarget({ level: "individual", label: item.entity, rows: row ? [row] : [] });
  };

  const scheduleColumns: ColumnsType<ScheduleItem> = [
    {
      title: "Due",
      key: "due",
      width: 170,
      sorter: (a, b) => a.dueAt - b.dueAt,
      defaultSortOrder: "ascend",
      render: (_: unknown, item) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{moment(item.dueAt).format("D MMM, HH:mm")}</div>
          <div className="cfo-cell__sub cfo-cell__sub--plain">{formatOffset(item.dueAt, NOW)}</div>
        </div>
      ),
    },
    {
      title: "Entity",
      key: "entity",
      render: (_: unknown, item) => (
        <div className="cfo-cell">
          <div className="cfo-cell__main">{item.entity}</div>
          <div className="cfo-cell__sub">{item.entityRole}</div>
        </div>
      ),
    },
    { title: "Project", dataIndex: "project", key: "project" },
    {
      title: "Amount",
      key: "amount",
      align: "right",
      sorter: (a, b) => a.amount - b.amount,
      render: (_: unknown, item) => (
        <span className={item.status === "overdue" || item.status === "suspended" ? "cfo-amount--due" : undefined}>
          {formatMoney(item.amount, item.currency)}
        </span>
      ),
    },
    {
      title: "Stage",
      key: "stage",
      width: 220,
      render: (_: unknown, item) => {
        if (item.stage === "scheduled") {
          return <Tag className="cfo-stage-tag">Scheduled</Tag>;
        }
        const meta = DUNNING_META[item.stage];
        return (
          <Tooltip title={meta.label}>
            <Tag className="cfo-stage-tag" style={{ color: STAGE_TONE[meta.tone], borderColor: STAGE_TONE[meta.tone] }}>
              {item.stage} · {meta.label}
            </Tag>
          </Tooltip>
        );
      },
    },
    {
      title: "Status",
      key: "status",
      width: 110,
      render: (_: unknown, item) => {
        const meta = STATUS_META[item.status];
        return (
          <Tag className="cfo-status-tag" style={{ color: meta.color, background: meta.bg, borderColor: meta.bg }}>
            {meta.label}
          </Tag>
        );
      },
    },
    {
      title: "Action",
      key: "action",
      width: 80,
      fixed: "right",
      render: (_: unknown, item) => (
        <Tooltip title="Send reminder">
          <Button
            className="beam-btn icon-btn blue-btn cover"
            style={{ boxShadow: "none" }}
            onClick={() => notify(item)}
          >
            <BellOutlined />
          </Button>
        </Tooltip>
      ),
    },
  ];

  const resultCount = tab === "ledger" ? ledger.length : visibleSchedule.length;

  return (
    <div className="school-overview cfo-transactions">
      <Row justify="space-between" align="middle" className="overview-header" gutter={[0, 12]}>
        <Col>
          <h2 className="overview-title">Transactions</h2>
          <p className="overview-subtitle">
            {rows.length} ledger lines · {schedule.length} scheduled payments · reminders follow each payment
            configuration
          </p>
        </Col>
      </Row>

      <KpiCards tiles={tab === "ledger" ? ledgerTiles : scheduleTiles} />

      <Tabs
        className="cfo-tabs mt-3"
        activeKey={tab}
        onChange={(key) => setTab(key as FilterMode)}
        items={[
          {
            key: "ledger",
            label: (
              <span>
                <FileTextOutlined /> Ledger <span className="cfo-tabs__count">{ledger.length}</span>
              </span>
            ),
          },
          {
            key: "schedule",
            label: (
              <span>
                <ScheduleOutlined /> Payment schedule <span className="cfo-tabs__count">{visibleSchedule.length}</span>
              </span>
            ),
          },
        ]}
      />

      <TransactionFilters
        domain={domain}
        mode={tab}
        filter={filter}
        onChange={setFilter}
        rows={rows}
        resultCount={resultCount}
      />

      <Row gutter={20} className="scrollable-table mt-3" style={{ display: "grid" }}>
        <Col span={24} style={{ overflow: "auto" }}>
          {tab === "ledger" ? (
            <LedgerGrid rows={ledger} currency="USD" onRowAction={openRowAction} highlightKey={null} />
          ) : (
            <Table<ScheduleItem>
              rowKey="id"
              dataSource={visibleSchedule}
              columns={scheduleColumns}
              scroll={{ x: 1000 }}
              pagination={{ pageSize: 10, showSizeChanger: false }}
            />
          )}
        </Col>
      </Row>

      <ActionModals
        action={action}
        target={actionTarget}
        currency="USD"
        onClose={() => {
          setAction(null);
          setActionTarget(null);
        }}
      />
    </div>
  );
};

export default TransactionsScreen;
