/**
 * Payment configuration helpers - pure functions over the section 4
 * schema of payment-config-integration.md: defaults, descriptions,
 * the amount-due order (6.1), the payment schedule (6.2), validation
 * (a port of api-admin-core's rules) and configuration diffs.
 *
 * No React and no other dashboard module here, so it can be imported
 * from mock data and screens alike without a cycle.
 */
import moment from "moment";

import {
  AmountLine,
  AmountRule,
  AppliedAdjustments,
  BillingCycle,
  Currency,
  DeepPartial,
  InvoiceSettings,
  LocationInfo,
  MemberRequest,
  PaymentConfig,
  ReminderChannel,
  ScheduleLine,
} from "./types";

const DAY = 24 * 60 * 60 * 1000;
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/* ------------------------------------------------------------------ */
/* Option lists                                                        */
/* ------------------------------------------------------------------ */

export const CURRENCIES: Currency[] = [
  "USD", "AUD", "PEN", "GBP", "EUR", "PKR", "INR",
  "SAR", "AED", "CAD", "ZAR", "ZMW", "NAD",
];

export const BILLING_CYCLES: { value: BillingCycle; label: string }[] = [
  { value: "daily", label: "Daily" },
  { value: "weekly", label: "Weekly" },
  { value: "monthly", label: "Monthly" },
  { value: "quarterly", label: "Quarterly" },
  { value: "yearly", label: "Yearly" },
];

export const REMINDER_CHANNELS: { value: ReminderChannel; label: string }[] = [
  { value: "email", label: "Email" },
  { value: "sms", label: "SMS" },
  { value: "push", label: "Push" },
];

