const isPlainObject = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === "object" && !Array.isArray(value);

const deepMerge = <T>(base: T, patch: any): T => {
  if (!isPlainObject(base) || !isPlainObject(patch)) {
    return (patch === undefined ? base : patch) as T;
  }
  const out: Record<string, unknown> = { ...(base as Record<string, unknown>) };
  Object.keys(patch).forEach((key) => {
    const next = patch[key];
    if (next === undefined) return;
    const current = out[key];
    out[key] =
      isPlainObject(current) && isPlainObject(next)
        ? deepMerge(current, next)
        : next;
  });
  return out as T;
};

/** A full configuration from a partial one: objects merge, arrays and nulls replace. */
export const makeConfig = (partial: DeepPartial<PaymentConfig>): PaymentConfig =>
  deepMerge(buildDefaultPaymentConfig(), partial);

/** Configurations are plain data, so a JSON round trip is a safe deep clone. */
export const cloneConfig = (config: PaymentConfig): PaymentConfig =>
  JSON.parse(JSON.stringify(config));

export const newId = (prefix: string): string =>
  `${prefix}-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;

export const round2 = (value: number): number =>
  Math.round((value + Number.EPSILON) * 100) / 100;

/* ------------------------------------------------------------------ */
/* Money                                                               */
/* ------------------------------------------------------------------ */

export const money = (value: number, currency: string = "USD"): string =>
  new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);

export const ruleAmount = (rule: AmountRule, base: number): number =>
  rule.amountType === "percentage" ? round2((base * rule.value) / 100) : rule.value;

export const describeAmount = (rule: AmountRule, currency: string): string =>
  rule.amountType === "percentage" ? `${rule.value}%` : money(rule.value, currency);

const fmtDate = (at: number | null, fallback: string) =>
  at === null ? fallback : moment(at).format("D MMM YYYY");

/* ------------------------------------------------------------------ */
/* Descriptions                                                        */
/* ------------------------------------------------------------------ */

const CYCLE_NOUN: Record<BillingCycle, string> = {
  daily: "day",
  weekly: "week",
  monthly: "month",
  quarterly: "quarter",
  yearly: "year",
};

/** "Deposit $200 + 2 installments, deferred 30 days" / "$450 per month, 12 cycles, auto-pay on". */
export const describePlan = (config: PaymentConfig): string => {
  const { currency } = config;
  if (config.planType === "recurring") {
    const r = config.recurring;
    const parts = [`${money(r.amount, currency)} per ${CYCLE_NOUN[r.billingCycle]}`];
    parts.push(r.numberOfCycles ? `${r.numberOfCycles} cycles` : r.endDate ? `until ${fmtDate(r.endDate, "")}` : "open ended");
    if (r.autoPay) parts.push("auto-pay on");
    return parts.join(", ");
  }

  const { deposit, installments, dueDate } = config.upfront;
  const parts: string[] = [];
  if (deposit.enabled) parts.push(`Deposit ${describeAmount(deposit, currency)}`);
  if (installments.enabled && installments.items.length > 0) {
    const n = installments.items.length;
    parts.push(`${n} installment${n === 1 ? "" : "s"}`);
  }
  if (parts.length === 0) {
    return `Full amount due ${fmtDate(dueDate, "at registration")}`;
  }
  let text = parts.join(" + ");
  const { deferred } = installments;
  if (installments.enabled && deferred.enabled) {
    text +=
      deferred.startDaysAfterRegistration !== null
        ? `, deferred ${deferred.startDaysAfterRegistration} days`
        : `, deferred to ${fmtDate(deferred.startDate, "")}`;
  }
  return text;
};

export const describeCollection = (config: PaymentConfig): string => {
  if (config.collectionMethod === "invoice") {
    const { brand, recipient } = config.invoice;
    const parts = ["Invoice"];
    if (brand.name) parts.push(brand.name);
    if (recipient.name) parts.push(`bill to ${recipient.name}`);
    return parts.join(" - ");
  }
  const parts = ["Credit card"];
  if (config.card.saveCardForAutoPay) parts.push("saved for auto-pay");
  if (config.card.surcharge) {
    parts.push(`${describeAmount(config.card.surcharge, config.currency)} surcharge`);
  }
  return parts.join(", ");
};

export const describeScholarship = (config: PaymentConfig): string => {
  const s = config.scholarship;
  if (!s.enabled) return "Not offered";
  const parts = [`Up to ${describeAmount(s, config.currency)}`];
  parts.push(s.maxAwards === null ? "unlimited awards" : `max ${s.maxAwards} awards`);
  const gates = [s.requiresApproval ? "approval" : "", s.requiresDocuments ? "documents" : ""].filter(Boolean);
  if (gates.length) parts.push(`${gates.join(" + ")} required`);
  return parts.join(", ");
};

/** One line per active pricing rule. */
export const describeDiscounts = (config: PaymentConfig): string[] => {
  const { currency } = config;
  const out: string[] = [];
  const { earlyBird, late } = config.pricingWindows;
  if (earlyBird.enabled) {
    out.push(`Early-bird ${describeAmount(earlyBird, currency)} before ${fmtDate(earlyBird.endDate, "-")}`);
  }
  if (late.enabled) {
    out.push(`Late surcharge ${describeAmount(late, currency)} from ${fmtDate(late.startDate, "-")}`);
  }
  const { sibling, waivers, promoCodes } = config.discounts;
  if (sibling.enabled) {
    out.push(`Sibling ${describeAmount(sibling, currency)} from child ${sibling.appliesFromChild}`);
  }
  waivers.forEach((w) => out.push(`${w.name || "Waiver"} waiver ${describeAmount(w, currency)}`));
  promoCodes.forEach((p) =>
    out.push(`${p.code || "Promo"} ${describeAmount(p, currency)}${p.expiry ? ` until ${fmtDate(p.expiry, "")}` : ""}`)
  );
  return out;
};

export const describeLateFee = (config: PaymentConfig): string =>
  config.lateFee.enabled
    ? `${describeAmount(config.lateFee, config.currency)} after a ${config.lateFee.graceDays}-day grace period`
    : "Not charged";

/** Reminder stages in the dashboard's hour notation (14 days = T+336h). */
export const describeReminders = (config: PaymentConfig): string => {
  const r = config.reminders;
  const parts: string[] = [];
  if (r.preDueDays.length) {
    parts.push(`Pre-due ${r.preDueDays.slice().sort((a, b) => b - a).map((d) => `T-${d * 24}h`).join(" / ")}`);
  }
  if (r.onDueDate) parts.push("on due date");
  if (r.pastDueDays.length) {
    parts.push(`past due ${r.pastDueDays.slice().sort((a, b) => a - b).map((d) => `T+${d * 24}h`).join(" / ")}`);
  }
  if (r.suspensionAfterDays !== null) parts.push(`suspension T+${r.suspensionAfterDays * 24}h`);
  if (r.channels.length) parts.push(r.channels.join(" + "));
  return parts.length ? parts.join(", ") : "No reminders";
};

/* ------------------------------------------------------------------ */
/* Amount due (6.1)                                                    */
/* ------------------------------------------------------------------ */

export const EMPTY_APPLIED: AppliedAdjustments = {
  scholarshipAward: null,
  waiverId: null,
  promoCode: null,
  childNumber: 1,
};

/**
 * The amount one registration owes, in the fixed order of section 6.1:
 * base, pricing window, waiver, sibling, promo code, scholarship. Each
 * step rounds half-up to two decimals and never goes below zero. The
 * card surcharge is not part of the total.
 */
export const computeAmountDue = (
  config: PaymentConfig,
  applied: AppliedAdjustments = EMPTY_APPLIED,
  registeredAt: number = Date.now()
): { total: number; lines: AmountLine[] } => {
  const { currency } = config;
  const lines: AmountLine[] = [{ key: "base", label: "Base amount", amount: config.totalAmount }];
  let running = round2(config.totalAmount);

  const deduct = (key: AmountLine["key"], label: string, rule: AmountRule) => {
    const amount = Math.min(running, ruleAmount(rule, running));
    if (amount <= 0) return;
    running = round2(Math.max(0, running - amount));
    lines.push({ key, label, amount: -amount });
  };

  const { earlyBird, late } = config.pricingWindows;
  if (earlyBird.enabled && earlyBird.endDate !== null && registeredAt < earlyBird.endDate) {
    deduct("earlyBird", `Early-bird ${describeAmount(earlyBird, currency)}`, earlyBird);
  } else if (late.enabled && late.startDate !== null && registeredAt >= late.startDate) {
    const amount = ruleAmount(late, running);
    running = round2(running + amount);
    lines.push({ key: "late", label: `Late surcharge ${describeAmount(late, currency)}`, amount });
  }

  const waiver = applied.waiverId
    ? config.discounts.waivers.find((w) => w._id === applied.waiverId)
    : null;
  if (waiver) deduct("waiver", `${waiver.name} waiver`, waiver);

  const { sibling } = config.discounts;
  if (sibling.enabled && applied.childNumber >= sibling.appliesFromChild) {
    deduct("sibling", `Sibling discount (child ${applied.childNumber})`, sibling);
  }

  if (applied.promoCode) {
    const code = applied.promoCode.trim().toLowerCase();
    const promo = config.discounts.promoCodes.find(
      (p) => p.code.toLowerCase() === code && (p.expiry === null || p.expiry > registeredAt)
    );
    if (promo) deduct("promo", `Promo ${promo.code}`, promo);
  }

  if (config.scholarship.enabled && applied.scholarshipAward && applied.scholarshipAward > 0) {
    const cap = ruleAmount(config.scholarship, running);
    const award = Math.min(applied.scholarshipAward, cap, running);
    if (award > 0) {
      running = round2(running - award);
      lines.push({ key: "scholarship", label: "Scholarship award", amount: -award });
    }
  }

  return { total: running, lines };
};

/* ------------------------------------------------------------------ */
/* Payment schedule (6.2)                                              */
/* ------------------------------------------------------------------ */

const CYCLE_UNIT: Record<BillingCycle, [number, moment.unitOfTime.DurationConstructor]> = {
  daily: [1, "day"],
  weekly: [1, "week"],
  monthly: [1, "month"],
  quarterly: [3, "month"],
  yearly: [1, "year"],
};

/**
 * The schedule one registration pays on, for `total` (the 6.1 result).
 * Upfront: deposit, then installments as a share of the remainder with
 * the last one absorbing rounding; a deferred start pushes early or
 * undated installments to the deferral date. Recurring: one line per
 * cycle, twelve shown when open ended.
 */
export const buildPaymentPlan = (
  config: PaymentConfig,
  total: number,
  registeredAt: number = Date.now()
): ScheduleLine[] => {
  const surchargeNote =
    config.collectionMethod === "card" && config.card.surcharge
      ? `+ ${describeAmount(config.card.surcharge, config.currency)} card surcharge`
      : undefined;
  const withNote = (line: ScheduleLine): ScheduleLine =>
    surchargeNote ? { ...line, note: line.note ? `${line.note}; ${surchargeNote}` : surchargeNote } : line;

  if (config.planType === "recurring") {
    const r = config.recurring;
    const start = r.startDate !== null ? r.startDate : registeredAt;
    const [step, unit] = CYCLE_UNIT[r.billingCycle];
    let count = r.numberOfCycles !== null ? r.numberOfCycles : 0;
    if (!count && r.endDate !== null) {
      let cursor = moment(start);
      while (cursor.valueOf() <= r.endDate && count < 120) {
        count += 1;
        cursor = cursor.add(step, unit);
      }
    }
    const openEnded = !count;
    if (openEnded) count = 12;
    const lines: ScheduleLine[] = [];
    for (let i = 0; i < count; i += 1) {
      lines.push(
        withNote({
          key: `cycle-${i + 1}`,
          label: `Cycle ${i + 1}`,
          amount: r.amount,
          dueAt: moment(start).add(i * step, unit).valueOf(),
          note: openEnded && i === count - 1 ? "continues every cycle" : r.autoPay ? "auto-pay" : undefined,
        })
      );
    }
    return lines;
  }

  const { deposit, installments, dueDate } = config.upfront;
  const lines: ScheduleLine[] = [];
  let remainder = round2(total);

  if (deposit.enabled) {
    const amount = Math.min(remainder, ruleAmount(deposit, total));
    remainder = round2(remainder - amount);
    lines.push(
      withNote({
        key: "deposit",
        label: "Deposit",
        amount,
        dueAt: deposit.dueDate !== null ? deposit.dueDate : registeredAt,
        note: deposit.dueDate === null ? "at registration" : undefined,
      })
    );
  }

  const items = installments.enabled ? installments.items : [];
  if (items.length > 0) {
    const base = remainder;
    const amounts = items.map((item) => ruleAmount(item, base));
    const others = amounts.slice(0, -1).reduce((acc, a) => acc + a, 0);
    amounts[amounts.length - 1] = round2(base - others);

    const { deferred } = installments;
    const deferralStart = deferred.enabled
      ? deferred.startDaysAfterRegistration !== null
        ? registeredAt + deferred.startDaysAfterRegistration * DAY
        : deferred.startDate
      : null;

    items.forEach((item, i) => {
      let dueAt = item.dueDate;
      let note: string | undefined;
      if (deferralStart !== null && (dueAt === null || dueAt < deferralStart)) {
        dueAt = deferralStart;
        note = "deferred start";
      }
      lines.push(
        withNote({
          key: item._id || `inst-${i + 1}`,
          label: item.name || `Installment ${i + 1}`,
          amount: amounts[i],
          dueAt,
          note,
        })
      );
    });
    return lines;
  }

  if (lines.length === 0 || remainder > 0) {
    lines.push(
      withNote({
        key: "full",
        label: deposit.enabled ? "Balance" : "Full amount",
        amount: remainder,
        dueAt: dueDate,
        note: dueDate === null ? "due at issue" : undefined,
      })
    );
  }
  return lines;
};

/* ------------------------------------------------------------------ */
/* Validation (port of api-admin-core validatePaymentConfig)           */
/* ------------------------------------------------------------------ */

const checkRule = (
  errors: string[],
  label: string,
  rule: AmountRule,
  { allowZero = false }: { allowZero?: boolean } = {}
) => {
  if (!(rule.value > 0) && !(allowZero && rule.value === 0)) {
    errors.push(`${label}: value must be greater than 0`);
  }
  if (rule.amountType === "percentage" && rule.value > 100) {
    errors.push(`${label}: percentage cannot exceed 100`);
  }
};

/** Human-readable problems; empty when the configuration is valid. */
export const validatePaymentConfig = (config: PaymentConfig): string[] => {
  const errors: string[] = [];

  if (!config.name) errors.push("Name is required");
  if (config.totalAmount < 0) errors.push("Total amount cannot be negative");

  if (config.collectionMethod === "invoice") {
    const { brand, recipient } = config.invoice;
    if (!brand.name) errors.push("Invoice: brand name is required");
    if (brand.contactEmail && !EMAIL_RE.test(brand.contactEmail)) {
      errors.push("Invoice: contact email is not valid");
    }
    if (recipient.email && !EMAIL_RE.test(recipient.email)) {
      errors.push("Invoice: recipient email is not valid");
    }
  } else if (config.card.surcharge) {
    checkRule(errors, "Card surcharge", config.card.surcharge, { allowZero: true });
  }

  if (config.planType === "upfront") {
    const { deposit, installments } = config.upfront;
    let fixedSum = 0;
    let percentSum = 0;
    const addTo = (rule: AmountRule) => {
      if (rule.amountType === "percentage") percentSum += rule.value;
      else fixedSum += rule.value;
    };

    if (deposit.enabled) {
      checkRule(errors, "Deposit", deposit);
      addTo(deposit);
    }
    if (installments.enabled) {
      if (!installments.items.length) errors.push("At least one installment is required");
      installments.items.forEach((row, i) => {
        if (!row.name) errors.push(`Installment ${i + 1}: name is required`);
        checkRule(errors, `Installment ${i + 1}`, row);
        addTo(row);
      });

      const { deferred } = installments;
      if (deferred.enabled) {
        const hasDays = deferred.startDaysAfterRegistration !== null;
        const hasDate = deferred.startDate !== null;
        if (!hasDays && !hasDate) {
          errors.push("Deferred start: set days after registration or a start date");
        } else if (hasDays && hasDate) {
          errors.push("Deferred start: choose either days after registration or a start date, not both");
        } else if (
          hasDays &&
          !(Number.isInteger(deferred.startDaysAfterRegistration) && (deferred.startDaysAfterRegistration as number) >= 0)
        ) {
          errors.push("Deferred start: days after registration must be a whole number of 0 or more");
        }
      }
    }
    if (percentSum > 100) errors.push("Deposit and installment percentages exceed 100%");
    if (config.totalAmount > 0 && fixedSum > config.totalAmount) {
      errors.push("Deposit and installment amounts exceed the total amount");
    }
  } else {
    const { amount, numberOfCycles, startDate, endDate } = config.recurring;
    if (!(amount > 0)) errors.push("Recurring amount must be greater than 0");
    if (numberOfCycles !== null && !(numberOfCycles >= 1)) errors.push("Number of cycles must be at least 1");
    if (startDate !== null && endDate !== null && endDate < startDate) {
      errors.push("Recurring end date must be after the start date");
    }
  }

  if (config.scholarship.enabled) {
    checkRule(errors, "Scholarship", config.scholarship);
    if (config.scholarship.maxAwards !== null && !(config.scholarship.maxAwards >= 1)) {
      errors.push("Scholarship: max awards must be at least 1");
    }
  }

  const { earlyBird, late } = config.pricingWindows;
  if (earlyBird.enabled) {
    checkRule(errors, "Early bird", earlyBird);
    if (earlyBird.endDate === null) errors.push("Early bird: end date is required");
  }
  if (late.enabled) {
    checkRule(errors, "Late fee window", late);
    if (late.startDate === null) errors.push("Late fee window: start date is required");
  }

  const { sibling, waivers, promoCodes } = config.discounts;
  if (sibling.enabled) {
    checkRule(errors, "Sibling discount", sibling);
    if (!(sibling.appliesFromChild >= 1)) errors.push("Sibling discount: applies-from child must be at least 1");
  }
  waivers.forEach((row, i) => {
    if (!row.name) errors.push(`Waiver ${i + 1}: name is required`);
    checkRule(errors, `Waiver ${i + 1}`, row);
  });
  const seenCodes = new Set<string>();
  promoCodes.forEach((row, i) => {
    if (!row.code) errors.push(`Promo code ${i + 1}: code is required`);
    else if (seenCodes.has(row.code.toLowerCase())) errors.push(`Promo code ${i + 1}: duplicate code "${row.code}"`);
    else seenCodes.add(row.code.toLowerCase());
    checkRule(errors, `Promo code ${i + 1}`, row);
    if (row.maxUses !== null && !(row.maxUses >= 1)) errors.push(`Promo code ${i + 1}: max uses must be at least 1`);
  });

  if (config.lateFee.enabled) {
    if (!(config.lateFee.graceDays >= 0)) errors.push("Late fee: grace days cannot be negative");
    checkRule(errors, "Late fee", config.lateFee);
  }

  if (config.reminders.suspensionAfterDays !== null && !(config.reminders.suspensionAfterDays >= 0)) {
    errors.push("Suspension after days cannot be negative");
  }

  return errors;
};

/** Form panel keys, in display order. */
export type FormSectionKey =
  | "basics"
  | "collection"
  | "plan"
  | "scholarship"
  | "windows"
  | "discounts"
  | "lateFee"
  | "reminders";

/** Which panel a validation message belongs to, for the header badge. */
export const sectionOfError = (message: string): FormSectionKey => {
  if (/^(Invoice|Card surcharge)/.test(message)) return "collection";
  if (/^(Deposit|Installment|At least one installment|Deferred start|Recurring|Number of cycles)/.test(message)) return "plan";
  if (/^Scholarship/.test(message)) return "scholarship";
  if (/^(Early bird|Late fee window)/.test(message)) return "windows";
  if (/^(Sibling|Waiver|Promo)/.test(message)) return "discounts";
  if (/^Late fee/.test(message)) return "lateFee";
  if (/^Suspension/.test(message)) return "reminders";
  return "basics";
};

