const getPath = (obj: unknown, path: string): unknown =>
  path.split(".").reduce<any>((acc, key) => (acc == null ? undefined : acc[key]), obj);

/** Labels of every field that differs between two configurations, in schema order. */
export const diffConfigs = (base: PaymentConfig, other: PaymentConfig): string[] => {
  const labels: string[] = [];
  const toggledGroups = new Set<string>();
  CONFIG_FIELD_LABELS.forEach((field) => {
    if (field.group && !field.toggle && toggledGroups.has(field.group)) return;
    const a = JSON.stringify(getPath(base, field.path) ?? null);
    const b = JSON.stringify(getPath(other, field.path) ?? null);
    if (a === b) return;
    if (field.toggle && field.group) toggledGroups.add(field.group);
    labels.push(field.label);
  });
  return labels;
};

/** Configuration diffs plus the applied-adjustment differences, for the "Customised" chips. */
export const diffRequests = (
  base: MemberRequest,
  other: MemberRequest,
  currency: string
): string[] => {
  const labels = diffConfigs(base.config, other.config);
  const a = base.applied;
  const b = other.applied;
  if ((a.scholarshipAward || 0) !== (b.scholarshipAward || 0)) {
    labels.push(b.scholarshipAward ? `Scholarship award ${money(b.scholarshipAward, currency)}` : "Scholarship award removed");
  }
  if ((a.waiverId || null) !== (b.waiverId || null)) {
    const waiver = other.config.discounts.waivers.find((w) => w._id === b.waiverId);
    labels.push(waiver ? `Waiver: ${waiver.name}` : "Waiver removed");
  }
  if ((a.promoCode || "").toLowerCase() !== (b.promoCode || "").toLowerCase()) {
    labels.push(b.promoCode ? `Promo ${b.promoCode}` : "Promo removed");
  }
  if (a.childNumber !== b.childNumber) labels.push(`Child #${b.childNumber}`);
  return labels;
};
