/**
 * Pure helpers for the fleet dashboard. Nothing here touches `google` so it
 * can be unit tested (School's gpsConstants reads `google` at import time).
 */

/* ------------------------------------------------------------------ live */

export type VehicleStatus = "green" | "amber" | "red" | "gray" | string;

export interface FleetVehicle {
  id: string;
  name: string;
  /** Driver name when the vehicle has its own name, else the beam id. */
  subtitle?: string;
  status: VehicleStatus;
  lat?: number;
  lng?: number;
  lastSeen?: number;
  /** The driver signed in to this vehicle (vehicles and drivers are paired). */
  driver?: DriverInfo;
  /** Ride progress when the driver is on a ride. */
  trip?: TripStage;
  raw: any;
}

export interface DriverInfo {
  name?: string;
  phone?: string;
  email?: string;
  customId?: string;
}

/** hpd-dps `displayStatusName` while a driver works a ride. */
export type TripStage = "assigned" | "arrived" | "started";

export const TRIP_META: Record<TripStage, { label: string; tone: "blue" | "amber" | "green" }> = {
  assigned: { label: "En route", tone: "blue" },
  arrived: { label: "Arrived", tone: "amber" },
  started: { label: "On trip", tone: "green" },
};

const toTripStage = (value: any): TripStage | undefined =>
  value === "assigned" || value === "arrived" || value === "started" ? value : undefined;

/** hpd-dps colours responders by status; the car icons share the same names. */
export const STATUS_META: Record<string, { label: string; tone: "green" | "amber" | "red" | "gray" }> = {
  green: { label: "Available", tone: "green" },
  amber: { label: "Away", tone: "amber" },
  red: { label: "Unavailable", tone: "red" },
  gray: { label: "Busy", tone: "gray" },
};

export const statusMeta = (status: VehicleStatus) =>
  STATUS_META[status] ?? { label: status ? `${status}` : "Unknown", tone: "gray" as const };

const toEpoch = (value: any): number | undefined => {
  if (value === undefined || value === null || value === "") return undefined;
  const n = typeof value === "number" ? value : Date.parse(value);
  if (!Number.isFinite(n)) return undefined;
  // Seconds → ms.
  return n < 1e12 ? n * 1000 : n;
};

/** Same location/title rules as School's MapService.createPlaceMarker. */
export const toVehicle = (responder: any, vehicles?: any[]): FleetVehicle => {
  const feature = responder?.location?.geoJson?.features?.find(
    (f: any) => f?.geometry?.coordinates?.length > 0
  );
  const coords = feature?.geometry?.coordinates;
  const person = [responder?.profile?.firstName, responder?.profile?.lastName].filter(Boolean).join(" ");
  const beamId = responder?.beamIds?.[0];
  const vehicleName = vehicles?.find((v) => v?.id === responder?.id)?.name;
  const ids = responder?.alternativeIds ?? {};
  const driver: DriverInfo = {
    name: person || undefined,
    phone: ids.phone || undefined,
    email: ids.email || undefined,
    customId: ids.customId || undefined,
  };
  return {
    id: `${responder?.id}`,
    name: vehicleName || beamId || person || `${responder?.id}`,
    subtitle: vehicleName ? person || beamId : beamId && person ? person : undefined,
    status: responder?.status || "gray",
    lat: typeof coords?.[1] === "number" ? coords[1] : undefined,
    lng: typeof coords?.[0] === "number" ? coords[0] : undefined,
    lastSeen: toEpoch(
      feature?.properties?.timestamp ?? responder?.location?.timestamp ?? responder?.location?.updatedAt
    ),
    driver: Object.values(driver).some(Boolean) ? driver : undefined,
    trip: toTripStage(responder?.displayStatusName),
    raw: responder,
  };
};

export const hasLocation = (v: FleetVehicle) => v.lat !== undefined && v.lng !== undefined;

export interface VehicleFilter {
  search: string;
  /** Empty = all statuses. */
  statuses: string[];
  locatedOnly: boolean;
  /** Ride progress stages to keep; empty or unset = any. */
  trips?: TripStage[];
  /** Only vehicles whose driver has a ride offer pending (see VehicleOffers). */
  offered?: boolean;
}

/** A ride currently offered to a vehicle's driver (host-provided, e.g. Ride). */
export interface VehicleOffer {
  pageId: string;
  /** Epoch ms (local clock) when the offer runs out. */
  expiresAt: number;
  /** Ride description for the tooltip (e.g. the pickup address). */
  label?: string;
}

/** Vehicle id (responder id) -> its pending offer. */
export type VehicleOffers = Record<string, VehicleOffer>;

export const filterVehicles = (vehicles: FleetVehicle[], filter: VehicleFilter, offers?: VehicleOffers) => {
  const q = filter.search.trim().toLowerCase();
  return vehicles.filter((v) => {
    if (filter.locatedOnly && !hasLocation(v)) return false;
    if (filter.offered && !offers?.[v.id]) return false;
    if (filter.statuses.length && !filter.statuses.includes(v.status)) return false;
    if (filter.trips?.length && !(v.trip && filter.trips.includes(v.trip))) return false;
    if (!q) return true;
    return [v.name, v.subtitle, v.id, v.driver?.phone, v.driver?.email, v.driver?.customId].some((f) =>
      `${f ?? ""}`.toLowerCase().includes(q)
    );
  });
};

export const countByStatus = (vehicles: FleetVehicle[]) =>
  vehicles.reduce<Record<string, number>>((acc, v) => {
    acc[v.status] = (acc[v.status] ?? 0) + 1;
    return acc;
  }, {});

/* --------------------------------------------------------------- history */

export interface TrackPoint {
  t: number;
  lat: number;
  lng: number;
  /** m/s, as the IoT channel reports it (School colours with unit "mps"). */
  speed: number;
  heading: number;
}

/** Same thresholds as School's gpsConstants.Speed (m/s). */
export const MOTION_MPS = 0.5;
export const SPEEDING_MPS = 13.4;

export type SpeedBand = "idle" | "moving" | "speeding";

export const SPEED_COLORS: Record<SpeedBand, string> = {
  idle: "#FBAE16",
  moving: "#40CC52",
  speeding: "#FF5F25",
};

export const speedBand = (mps: number): SpeedBand =>
  mps <= MOTION_MPS ? "idle" : mps >= SPEEDING_MPS ? "speeding" : "moving";

/** `/getRange` samples → time-ordered points with a location. */
export const parseTrack = (samples: any[] | undefined): TrackPoint[] =>
  (samples ?? [])
    .filter((s) => s?.dataset?.locationGps?.lat !== undefined && s?.dataset?.locationGps?.long !== undefined)
    .map((s) => ({
      t: toEpoch(s.timestamp) ?? 0,
      lat: Number(s.dataset.locationGps.lat),
      lng: Number(s.dataset.locationGps.long),
      speed: Number(s.dataset.speedGps) || 0,
      heading: Number(s.dataset.headingGps) || 0,
    }))
    .sort((a, b) => a.t - b.t);

export const haversineMeters = (a: { lat: number; lng: number }, b: { lat: number; lng: number }) => {
  const R = 6371000;
  const rad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * rad;
  const dLng = (b.lng - a.lng) * rad;
  const h =
    Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.atan2(Math.sqrt(h), Math.sqrt(1 - h));
};

export interface Stop {
  start: number;
  end: number;
  lat: number;
  lng: number;
  /** Index of the first point of the stop, for jumping playback there. */
  index: number;
}

export interface TrackSummary {
  distanceM: number;
  durationMs: number;
  movingMs: number;
  idleMs: number;
  maxSpeed: number;
  avgMovingSpeed: number;
  speedingMs: number;
  stops: Stop[];
}

export const DEFAULT_MIN_STOP_MS = 3 * 60 * 1000;

/**
 * Time between consecutive points is attributed to the band of the earlier
 * point. Gaps longer than `maxGapMs` (device off / no signal) count as neither
 * moving nor idle.
 */
export const summarizeTrack = (
  points: TrackPoint[],
  minStopMs = DEFAULT_MIN_STOP_MS,
  maxGapMs = 10 * 60 * 1000
): TrackSummary => {
  const summary: TrackSummary = {
    distanceM: 0,
    durationMs: points.length > 1 ? points[points.length - 1].t - points[0].t : 0,
    movingMs: 0,
    idleMs: 0,
    maxSpeed: 0,
    avgMovingSpeed: 0,
    speedingMs: 0,
    stops: [],
  };
  let movingDistance = 0;
  let stopStart: number | undefined;

  const closeStop = (endIdx: number) => {
    if (stopStart === undefined) return;
    const first = points[stopStart];
    const last = points[endIdx];
    if (last.t - first.t >= minStopMs) {
      summary.stops.push({ start: first.t, end: last.t, lat: first.lat, lng: first.lng, index: stopStart });
    }
    stopStart = undefined;
  };

  points.forEach((p, i) => {
    summary.maxSpeed = Math.max(summary.maxSpeed, p.speed);
    const band = speedBand(p.speed);
    if (band === "idle") {
      if (stopStart === undefined) stopStart = i;
    } else {
      closeStop(i);
    }
    const next = points[i + 1];
    if (!next) return;
    const d = haversineMeters(p, next);
    summary.distanceM += d;
    const dt = next.t - p.t;
    if (dt <= 0 || dt > maxGapMs) return;
    if (band === "idle") {
      summary.idleMs += dt;
    } else {
      summary.movingMs += dt;
      movingDistance += d;
      if (band === "speeding") summary.speedingMs += dt;
    }
  });
  closeStop(points.length - 1);

  summary.avgMovingSpeed = summary.movingMs > 0 ? movingDistance / (summary.movingMs / 1000) : 0;
  return summary;
};

/**
 * Contiguous runs of the same speed band, each sharing its first point with
 * the previous run's last so the drawn line has no gaps.
 */
export const segmentsBySpeed = (points: TrackPoint[]) => {
  const runs: { band: SpeedBand; path: { lat: number; lng: number }[] }[] = [];
  points.forEach((p, i) => {
    const band = speedBand(p.speed);
    const last = runs[runs.length - 1];
    const ll = { lat: p.lat, lng: p.lng };
    if (last && last.band === band) {
      last.path.push(ll);
    } else {
      if (last) last.path.push(ll);
      if (i < points.length - 1 || !last) runs.push({ band, path: [ll] });
    }
  });
  return runs.filter((r) => r.path.length > 1 || points.length === 1);
};

/** Evenly thin `items` to at most `max`, always keeping the last one. */
export const downsample = <T>(items: T[], max: number): T[] => {
  if (items.length <= max) return items;
  const step = items.length / max;
  const out: T[] = [];
  for (let i = 0; i < max - 1; i += 1) out.push(items[Math.floor(i * step)]);
  out.push(items[items.length - 1]);
  return out;
};

/** Index of the last point at or before `t` (0 when `t` is before the track). */
export const indexAtTime = (points: TrackPoint[], t: number) => {
  let lo = 0;
  let hi = points.length - 1;
  if (hi < 0 || t <= points[0].t) return 0;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (points[mid].t <= t) lo = mid;
    else hi = mid - 1;
  }
  return lo;
};

/* ----------------------------------------------------------------- units */

export type SpeedUnit = "mph" | "kph";

export const formatSpeed = (mps: number, unit: SpeedUnit) =>
  `${Math.round(unit === "mph" ? mps * 2.23694 : mps * 3.6)} ${unit === "mph" ? "mph" : "km/h"}`;

export const formatDistance = (meters: number, unit: SpeedUnit) => {
  const value = unit === "mph" ? meters / 1609.344 : meters / 1000;
  return `${value < 10 ? value.toFixed(1) : Math.round(value)} ${unit === "mph" ? "mi" : "km"}`;
};

export const formatDuration = (ms: number) => {
  const mins = Math.round(ms / 60000);
  if (mins < 60) return `${mins}m`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return m ? `${h}h ${m}m` : `${h}h`;
};

/** Vehicles per ride stage (drivers not on a ride are not counted). */
export const countByTrip = (vehicles: FleetVehicle[]) =>
  vehicles.reduce<Record<string, number>>((acc, v) => {
    if (v.trip) acc[v.trip] = (acc[v.trip] ?? 0) + 1;
    return acc;
  }, {});

/** Vehicles in the list whose driver has a ride offer pending. */
export const countOffered = (vehicles: FleetVehicle[], offers?: VehicleOffers) =>
  offers ? vehicles.filter((v) => !!offers[v.id]).length : 0;
