import React from "react";
import {
  CalendarOutlined,
  FlagOutlined,
  MedicineBoxOutlined,
  RocketOutlined,
  TeamOutlined,
  TrophyOutlined,
} from "@ant-design/icons";

/**
 * Icons for the sections we know by name. The section list is built from the
 * event form at runtime, so anything an admin adds later falls back to the
 * calendar rather than rendering nothing.
 */
const BY_SLUG: Record<string, React.ReactNode> = {
  recreational: <TeamOutlined />,
  traveler: <RocketOutlined />,
  clinics: <MedicineBoxOutlined />,
  camps: <FlagOutlined />,
  events: <TrophyOutlined />,
  "special-events": <TrophyOutlined />,
};

export const sectionIcon = (slug: string): React.ReactNode =>
  BY_SLUG[slug] ?? <CalendarOutlined />;
