import React from "react";
import { Button, Col, Progress, Row, Tooltip } from "antd";
import { ColumnsType } from "antd/lib/table";
import { EditOutlined, SendOutlined } from "@ant-design/icons";
import moment from "moment";

import { BillableEntity, Domain, EntityKind, ProjectRollup } from "./types";
import { DOMAIN_LABELS, getPaymentConfig } from "./mockData";
import { projectNames } from "./mockEntities";
import { describePlan } from "./paymentConfig";
import { billingStatusOf, formatMoney } from "./selectors";
import StatusTag from "./StatusTag";

interface Ctx<T> {
  domain: Domain;
  onSend: (record: T) => void;
  onEdit: (record: T) => void;
}

/* ---------- shared cells ---------- */

const money = (value: number, currency: string, tone?: "in" | "out" | "due") => {
  if (value <= 0) return <span className="cfo-muted">-</span>;
  return (
    <span className={tone ? `cfo-amount--${tone}` : undefined}>
      {formatMoney(value, currency)}
    </span>
  );
};

const date = (value: number | null | undefined) =>
  value ? moment(value).format("D MMM YYYY") : <span className="cfo-muted">-</span>;

const planOf = (configId: string | null) => {
  const config = getPaymentConfig(configId);
  if (!config) return <span className="cfo-muted">Not configured</span>;
  return (
    <div className="cfo-cell">
      <div className="cfo-cell__main">{config.name}</div>
      <div className="cfo-cell__sub cfo-cell__sub--plain">{describePlan(config)}</div>
    </div>
  );
};

/** The Action column: send a payment request, or edit the request terms. */
const actionColumn = <T,>(ctx: Ctx<T>, editable: (record: T) => boolean = () => true) => ({
  title: "Action",
  key: "action",
  width: 110,
  fixed: "right" as const,
  render: (_: unknown, record: T) => (
    <Row style={{ width: 100 }} className="cfo-row-actions">
      <Col span={12}>
        <Tooltip title="Send payment request">
          <Button
            className="beam-btn icon-btn blue-btn cover"
            style={{ boxShadow: "none" }}
            onClick={(e) => {
              e.stopPropagation();
              ctx.onSend(record);
            }}
          >
            <SendOutlined />
          </Button>
        </Tooltip>
      </Col>
      <Col span={12}>
        <Tooltip title="Edit payment request">
          <Button
            className="beam-btn icon-btn yellow-btn cover"
            style={{ boxShadow: "none" }}
            disabled={!editable(record)}
            onClick={(e) => {
              e.stopPropagation();
              ctx.onEdit(record);
            }}
          >
            <EditOutlined />
          </Button>
        </Tooltip>
      </Col>
    </Row>
  ),
});

const statusColumn = <T,>(statusOf: (record: T) => ReturnType<typeof billingStatusOf>) => ({
  title: "Status",
  key: "status",
  width: 110,
  render: (_: unknown, record: T) => <StatusTag status={statusOf(record)} />,
});

const nameCell = (main: string, sub?: string) => (
  <div className="cfo-cell">
    <div className="cfo-cell__main">{main}</div>
    {sub && <div className="cfo-cell__sub cfo-cell__sub--plain">{sub}</div>}
  </div>
);

/* ---------- players / students ---------- */

export const playerColumns = (ctx: Ctx<BillableEntity>): ColumnsType<BillableEntity> => {
  const labels = DOMAIN_LABELS[ctx.domain];
  return [
    statusColumn<BillableEntity>((e) => billingStatusOf(e.billing)),
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
      sorter: (a, b) => a.name.localeCompare(b.name),
      render: (_: string, e) => nameCell(e.name, e.email),
    },
    {
      title: "Guardian",
      key: "household",
      render: (_: unknown, e) => e.household || "-",
    },
    {
      title: labels.navSingular.team,
      key: "project",
      render: (_: unknown, e) => projectNames(e).join(", ") || "-",
    },
    {
      title: "Plan",
      key: "plan",
      width: 240,
      render: (_: unknown, e) => planOf(e.paymentConfigId),
    },
    {
      title: "Billed",
      key: "billed",
      align: "right",
      sorter: (a, b) => a.billing.billed - b.billing.billed,
      render: (_: unknown, e) => money(e.billing.billed, e.billing.currency),
    },
    {
      title: "Collected",
      key: "collected",
      align: "right",
      sorter: (a, b) => a.billing.collected - b.billing.collected,
      render: (_: unknown, e) => money(e.billing.collected, e.billing.currency, "in"),
    },
    {
      title: "Outstanding",
      key: "outstanding",
      align: "right",
      render: (_: unknown, e) => money(e.billing.outstanding, e.billing.currency),
    },
    {
      title: "Past due",
      key: "pastDue",
      align: "right",
      sorter: (a, b) => a.billing.pastDue - b.billing.pastDue,
      render: (_: unknown, e) => money(e.billing.pastDue, e.billing.currency, "due"),
    },
    {
      title: "Next due",
      key: "nextDue",
      render: (_: unknown, e) => date(e.billing.nextDueAt),
    },
    actionColumn(ctx, (e) => !!e.paymentConfigId),
  ];
};

/* ---------- coaches / staff / vendors ---------- */

export const payeeColumns = (
  kind: Extract<EntityKind, "coaches" | "staff" | "vendors">,
  ctx: Ctx<BillableEntity>
): ColumnsType<BillableEntity> => {
  const labels = DOMAIN_LABELS[ctx.domain];
  const middle: ColumnsType<BillableEntity> =
    kind === "vendors"
      ? [
          {
            title: "Category",
            key: "category",
            render: (_: unknown, e) => e.category || "-",
          },
          {
            title: "Project",
            key: "project",
            render: (_: unknown, e) => projectNames(e).join(", ") || "-",
          },
          {
            title: "Invoice ID",
            key: "invoice",
            render: (_: unknown, e) => (
              <code className="cfo-invoice-id">
                V1001-VND-INV2609-{e.id.replace(/\D/g, "").padStart(3, "0")}
              </code>
            ),
          },
        ]
      : [
          {
            title: "Role",
            dataIndex: "role",
            key: "role",
          },
          kind === "staff"
            ? {
                title: "Department",
                key: "department",
                render: (_: unknown, e) => e.department || "-",
              }
            : {
                title: labels.nav.teams,
                key: "project",
                render: (_: unknown, e) => projectNames(e).join(", ") || "-",
              },
          {
            title: "Contract",
            key: "contract",
            render: (_: unknown, e) => (
              <span className="cfo-capitalize">{e.contract || "-"}</span>
            ),
          },
        ];

  return [
    statusColumn<BillableEntity>((e) => billingStatusOf(e.billing)),
    {
      title: kind === "vendors" ? "Vendor" : "Name",
      dataIndex: "name",
      key: "name",
      sorter: (a, b) => a.name.localeCompare(b.name),
      render: (_: string, e) => nameCell(e.name, e.email),
    },
    ...middle,
    {
      title: kind === "vendors" ? "Amount" : "Fee",
      key: "billed",
      align: "right",
      sorter: (a, b) => a.billing.billed - b.billing.billed,
      render: (_: unknown, e) => money(e.billing.billed, e.billing.currency),
    },
    {
      title: "Paid",
      key: "collected",
      align: "right",
      render: (_: unknown, e) => money(e.billing.collected, e.billing.currency, "in"),
    },
    {
      title: "Owed",
      key: "owed",
      align: "right",
      sorter: (a, b) =>
        a.billing.outstanding + a.billing.pastDue - (b.billing.outstanding + b.billing.pastDue),
      render: (_: unknown, e) =>
        money(
          e.billing.outstanding + e.billing.pastDue,
          e.billing.currency,
          e.billing.pastDue > 0 ? "due" : undefined
        ),
    },
    {
      title: kind === "vendors" ? "Due date" : "Next payout",
      key: "nextDue",
      render: (_: unknown, e) => date(e.billing.nextDueAt),
    },
    actionColumn(ctx),
  ];
};

/* ---------- teams / classes / events ---------- */

export const projectColumns = (
  group: "team" | "event",
  ctx: Ctx<ProjectRollup>
): ColumnsType<ProjectRollup> => [
  statusColumn<ProjectRollup>((p) => p.status),
  {
    title: group === "event" ? "Event" : "Name",
    dataIndex: "name",
    key: "name",
    sorter: (a, b) => a.name.localeCompare(b.name),
    render: (_: string, p) => nameCell(p.name, p.kind),
  },
  ...(group === "event"
    ? ([
        {
          title: "Dates",
          key: "dates",
          render: (_: unknown, p: ProjectRollup) =>
            p.startsAt
              ? `${moment(p.startsAt).format("D MMM")} - ${moment(p.endsAt || p.startsAt).format(
                  "D MMM YYYY"
                )}`
              : "-",
        },
        {
          title: "Participants",
          dataIndex: "memberCount",
          key: "members",
          align: "right" as const,
        },
      ] as ColumnsType<ProjectRollup>)
    : ([
        {
          title: "Members",
          dataIndex: "memberCount",
          key: "members",
          align: "right" as const,
        },
      ] as ColumnsType<ProjectRollup>)),
  {
    title: "Payment config",
    key: "config",
    width: 240,
    render: (_: unknown, p) => planOf(p.paymentConfigId),
  },
  {
    title: "Billed",
    key: "billed",
    align: "right",
    sorter: (a, b) => a.billing.billed - b.billing.billed,
    render: (_: unknown, p) => money(p.billing.billed, p.currency),
  },
  {
    title: "Collected",
    key: "collected",
    align: "right",
    render: (_: unknown, p) => money(p.billing.collected, p.currency, "in"),
  },
  {
    title: "Outstanding",
    key: "outstanding",
    align: "right",
    render: (_: unknown, p) => money(p.billing.outstanding, p.currency),
  },
  ...(group === "team"
    ? ([
        {
          title: "Past due",
          key: "pastDue",
          align: "right" as const,
          render: (_: unknown, p: ProjectRollup) =>
            money(p.billing.pastDue, p.currency, "due"),
        },
        {
          title: "Collected %",
          key: "pct",
          width: 150,
          render: (_: unknown, p: ProjectRollup) => (
            <Progress
              percent={p.collectedPct}
              size="small"
              strokeColor={p.collectedPct >= 90 ? "#1F9D55" : p.collectedPct >= 50 ? "#FBAE16" : "#E5484D"}
              trailColor="#EEF1F6"
            />
          ),
        },
      ] as ColumnsType<ProjectRollup>)
    : []),
  actionColumn(ctx),
];
