import React from "react";
import { Tooltip } from "antd";
import { LoadingOutlined, ExclamationCircleOutlined } from "@ant-design/icons";
import moment from "moment";
import { RIDE_STATUS_LABELS } from "../constants";

// Coloured status pill for a ride row. Optimistic "Submitting…" rows show a
// spinner (or a red "Failed" pill) instead of a status.
export const StatusTag: React.FC<{ status?: string; record?: any }> = ({
  status,
  record,
}) => {
  const pending = record?.action?.pendingSubmission;
  if (pending) {
    const failed = !!record?.action?.failed;
    return (
      <span
        className={`ride-status ride-status--${failed ? "failed" : "pending"}`}
      >
        {failed ? (
          <ExclamationCircleOutlined aria-hidden="true" />
        ) : (
          <LoadingOutlined aria-hidden="true" />
        )}
        {failed ? "Failed" : "Submitting"}
      </span>
    );
  }
  const color = status ?? "gray";
  const label = RIDE_STATUS_LABELS[color] ?? color;
  return (
    <span className={`ride-status ride-status--${color}`}>
      <span className="ride-status__dot" aria-hidden="true" />
      {label}
    </span>
  );
};

// "Requested at" cell: the row's clock time plus a relative age, with the
// full date in a tooltip. Placeholder rows keep their own text.
export const RequestedAtCell: React.FC<{ text?: string; record?: any }> = ({
  text,
  record,
}) => {
  const createdAt = Number(record?._createdAt);
  if (record?.action?.pendingSubmission || !createdAt) {
    return <span className="ride-time">{text}</span>;
  }
  const at = moment(createdAt);
  return (
    <Tooltip title={at.format("ddd D MMM YYYY, HH:mm:ss")}>
      <span className="ride-time" tabIndex={0}>
        <span className="ride-time__abs">{text}</span>
        <span className="ride-time__rel">{at.fromNow()}</span>
      </span>
    </Tooltip>
  );
};
