import React, { useState } from "react";
import { Row, Col, Radio, Form, Input, Button } from "antd";
import { SocketTopics } from "constants/enums";
import {
  sharePaymentUrlPublishTopic,
  getVerifyCustomerPublishTopic,
} from "hooks/MQTTConstants";
import { pushNotification } from "utils/notifications";
import EditPaymentModal from "components/Modals/Payment/EditPaymentModal";
import EditPaymentPayFastModal from "components/Modals/Payment/EditPaymentPayFastModal";
import { useDispatchPanel } from "../context";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

// Web booker: the passenger proves they own the phone/email with an OTP before
// their card on file is loaded.
const CardOtpGate: React.FC = () => {
  const {
    socket,
    encrypted_token,
    form,
    projects,
    cardOtpError,
    setCardOtpError,
    cardOtpPendingRef,
  } = useDispatchPanel();
  const [sent, setSent] = useState<boolean>(false);
  const [code, setCode] = useState<string>("");

  const publishVerify = (bookingOtp?: string) => {
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getVerifyCustomerPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        notificationChannels: {
          phone: form.getFieldValue("passengerPhoneNumber"),
          email: form.getFieldValue("passengerEmail"),
        },
        userServiceId: projects?.userServiceId,
        ...(bookingOtp !== undefined ? { bookingOtp } : {}),
      }),
      undefined,
      undefined,
      { retryOnAckTimeout: false }
    );
  };

  const sendCode = () => {
    setCardOtpError(undefined);
    publishVerify();
    setSent(true);
    pushNotification(
      "Verification code sent on notification channels",
      "success",
      "TOP_CENTER",
      3000
    );
  };

  const verifyCode = () => {
    if (!code.trim()) return;
    cardOtpPendingRef.current = code.trim();
    publishVerify(code.trim());
  };

  return (
    <div className="mb-3">
      <span>Verify your phone or email to use your saved card</span>
      {sent ? (
        <div className="d-flex mt-2">
          <Input
            placeholder="Verification code"
            value={code}
            onChange={(e) => setCode(e.target.value)}
            onPressEnter={(e) => {
              e.preventDefault();
              verifyCode();
            }}
          />
          <Button className="beam-btn ml-2" onClick={verifyCode}>
            Verify
          </Button>
          <Button className="ml-2" onClick={sendCode}>
            Resend
          </Button>
        </div>
      ) : (
        <div className="mt-2">
          <Button className="beam-btn" onClick={sendCode}>
            Send code
          </Button>
        </div>
      )}
      {cardOtpError && <p className="error mt-2">{cardOtpError}</p>}
    </div>
  );
};

const PaymentProviderSection: React.FC = () => {
  const {
    isAddCardModalVisible,
    setIsAddCardModalVisible,
    webBooker,
    payWith,
    setPayWith,
    socket,
    encrypted_token,
    form,
    projects,
    verifiedOtp,
  } = useDispatchPanel();

  if (!isAddCardModalVisible) return null;

  // Every web booker verifies, including a plain userId + lat/lng link, whose
  // userId is not signed and so proves nothing.
  const needsOtp = webBooker;
  const payment = needsOtp
    ? {
        ...isAddCardModalVisible,
        bookingOtp: verifiedOtp,
        userServiceId: projects?.userServiceId,
      }
    : isAddCardModalVisible;

  return (
    <Row className="mt-3">
      <Col span={24}>
        <Form.Item
          name="payWith"
          rules={[{ required: true, message: "Select a provider" }]}
        >
          <div className="d-flex flex-column justify-content-start align-items-start mb-3">
            <div className="ant-col ant-form-item-label">
              <label className="ant-form-item-required">
                Pay with provider
              </label>
            </div>

            <Radio.Group
              onChange={(e) => {
                setPayWith(e.target.value);
              }}
              disabled={webBooker}
              value={payWith}
            >
              <Radio value="stripe">Stripe</Radio>
              <Radio value="paystack">PayStack</Radio>
            </Radio.Group>
          </div>
        </Form.Item>

        {needsOtp && !verifiedOtp && <CardOtpGate />}

        {payWith === "stripe" && (!needsOtp || verifiedOtp) && (
          <EditPaymentModal
            onClose={() => {
              setIsAddCardModalVisible(undefined);
            }}
            socket={socket}
            payment={payment}
            onShare={() => {
              const phone = form.getFieldValue("passengerPhoneNumber");
              const email = form.getFieldValue("passengerEmail");
              if ((phone && phone !== "") || (email && email !== "")) {
                socket.publishToEvent(
                  SocketTopics.PublishPageTopics,
                  sharePaymentUrlPublishTopic(encrypted_token?.connectionId),
                  wrapRequestPayload({
                    userId: encrypted_token?.userId,
                    notificationChannels: {
                      email,
                      phone,
                    },
                  }),
      undefined,
      undefined,
      { retryOnAckTimeout: false }
                );
                pushNotification(
                  "Payment link shared successfully",
                  "success",
                  "TOP_CENTER",
                  1000
                );
              }
            }}
          />
        )}
        {payWith === "paystack" && (!needsOtp || verifiedOtp) && (
          <EditPaymentPayFastModal
            onClose={() => {
              setIsAddCardModalVisible(undefined);
            }}
            socket={socket}
            payment={payment}
            onShare={() => {
              console.log("disable share");
            }}
          />
        )}
      </Col>
    </Row>
  );
};

export default PaymentProviderSection;
