import React from "react";
import { Drawer } from "antd";
import DispatchPanel from "../../../DispatchPanel";

export const ChatDrawer = ({ url, onClose }: { url?: string; onClose: () => void }) => (
  <Drawer title="Chat" placement="right" onClose={onClose} visible={!!url} width={480} maskClosable>
    <iframe
      src={url}
      width="100%"
      height="100%"
      style={{ border: "none" }}
      allow="camera; microphone; fullscreen"
      allowFullScreen
    />
  </Drawer>
);

export const AssignmentDrawer = ({
  open,
  socket,
  title,
  preferredDriverId,
  onClose,
  onDone,
}: {
  open: boolean;
  socket: ISocket;
  title?: React.ReactNode;
  preferredDriverId?: string;
  /** Drawer dismissed: also clears the selected page. */
  onClose: () => void;
  /** Panel finished its own flow: just hide the drawer. */
  onDone: () => void;
}) => (
  <Drawer
    title={title ?? "Assign driver"}
    placement="right"
    onClose={onClose}
    visible={open}
    width={760}
    className="mx-assign-drawer"
    maskClosable
  >
    {open && (
      <DispatchPanel
        socket={socket}
        params={{ screens: { form: true, map: false }, setScreens: () => {} }}
        showOnlyAssignment={true}
        preferredDriverId={preferredDriverId}
        toggleDispatch={onDone}
      />
    )}
  </Drawer>
);
