import React from "react";
import { Alert, Button, Space } from "antd";
import { useDispatchPanel } from "../context";

// Persistent messages above the action buttons: the "changed by someone
// else" notice for the loaded ride, and submit problems that offer a Retry.
const SubmitAlerts: React.FC = () => {
  const {
    rideNotice,
    setRideNotice,
    reloadRide,
    ridePageId,
    submitIssue,
    searching,
  } = useDispatchPanel();

  const showNotice =
    rideNotice && ridePageId && rideNotice.pageId === ridePageId?.toString();

  if (!showNotice && !submitIssue) return null;

  return (
    <div className="ride-alerts px-2 mt-2">
      {showNotice && (
        <Alert
          type="warning"
          showIcon
          message={rideNotice.message}
          closable
          onClose={() => setRideNotice(undefined)}
          action={
            <Button
              size="small"
              onClick={() => reloadRide(ridePageId, { resetForm: true })}
            >
              Reload
            </Button>
          }
        />
      )}
      {submitIssue && (
        <Alert
          className={showNotice ? "mt-2" : ""}
          type="error"
          showIcon
          message={submitIssue.message}
          action={
            <Space direction="vertical">
              {submitIssue.retry && (
                <Button
                  size="small"
                  type="primary"
                  loading={searching}
                  onClick={() => submitIssue.retry()}
                >
                  Retry
                </Button>
              )}
              {submitIssue.dismiss && (
                <Button size="small" onClick={() => submitIssue.dismiss()}>
                  Dismiss
                </Button>
              )}
            </Space>
          }
        />
      )}
    </div>
  );
};

export default SubmitAlerts;
