import * as XLSX from "xlsx";
import jsPDF from "jspdf";
import autoTable from "jspdf-autotable";
import { RideRow } from "../types";

// Columns that render widgets rather than data.
const NON_DATA_COLUMNS = ["pageStatus", "action"];

/** Nested objects (the raw page, changelog, ...) don't belong in a sheet. */
const flattenRow = (row: RideRow) =>
  Object.fromEntries(
    Object.entries(row).filter(([, value]) => value === null || typeof value !== "object")
  );

export const exportToSpreadsheet = (rows: RideRow[], fileType: "xlsx" | "csv") => {
  const worksheet = XLSX.utils.json_to_sheet(rows.filter((r) => !r.isShift).map(flattenRow));
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, "Data");
  XLSX.writeFile(workbook, `table_data.${fileType}`);
};

export const exportToPDF = (rows: RideRow[], columns: { title?: any; dataIndex?: any }[]) => {
  const dataColumns = columns.filter(
    (col) => col.dataIndex && !NON_DATA_COLUMNS.includes(col.dataIndex)
  );
  const doc = new jsPDF();
  // @ts-ignore
  autoTable(doc, {
    head: [dataColumns.map((col) => col.title)],
    body: rows
      .filter((r) => !r.isShift)
      .map((row) => dataColumns.map((col) => row[col.dataIndex] ?? "")),
  });
  doc.save("table_data.pdf");
};
