import {
  I18nText,
  ProjectForm,
  RawProject,
  SurveyElement,
} from "./beamTypes";
import { beamViteUrlFor, ProgramsConfig } from "./config";
import {
  eventSectionFrom,
  FORM_SECTIONS,
  ProgramEvent,
  ProgramLevel,
  SectionDef,
  slugify,
} from "../data";

/**
 * Turns the organization's projects and their `project:extendedBio` answers
 * into the events the page renders, and turns the form's widgets into the
 * filter controls above them.
 *
 * Nothing here talks to the network, so it can be reasoned about (and tested)
 * on fixtures of the real payloads.
 */

/** Headlines and labels come back as light HTML from the form editor. */
export const stripHtml = (value: string): string =>
  value
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/\s+/g, " ")
    .trim();

/** Reads the language the answers were given in, falling back to `default`. */
export const textOf = (text: I18nText | undefined, language = "default"): string => {
  if (!text) return "";
  const raw = text[language] ?? text.default ?? "";
  return stripHtml(raw);
};

const norm = (value: unknown): string => `${value ?? ""}`.trim().toLowerCase();

export const choiceLabels = (element: SurveyElement, language?: string): string[] =>
  (element.choices ?? [])
    .map((choice) => textOf(choice.label, language) || choice.imageUrl || "")
    .filter(Boolean);

/* ------------------------------------------------------------------ *
 * Recognising the two widgets the page's own layout depends on
 * ------------------------------------------------------------------ */

/**
 * The event-type widget decides which sidebar section a project belongs to,
 * so its answer is routing rather than a filter.
 *
 * Its choices are whatever the admin typed, so it cannot be recognised by
 * them. It is found by its headline ("Select Project Event Type"), and the
 * id can be pinned with `?sectionElementId=` or
 * `REACT_APP_PROGRAMS_SECTION_ELEMENT_ID` if a form words it differently.
 */
const SECTION_HEADLINE = /\b(event\s*type|programme?\s*type|program|category|section)\b/i;

const CHOICE_TYPES = new Set(["multipleChoiceSingle", "multipleChoiceMulti", "pictureSelection"]);

export const findSectionElement = (
  elements: SurveyElement[],
  pinnedId?: string
): SurveyElement | undefined => {
  const choiceElements = elements.filter(
    (element) => CHOICE_TYPES.has(element.type) && (element.choices?.length ?? 0) >= 1
  );
  if (pinnedId) {
    const pinned = choiceElements.find((element) => element.id === pinnedId);
    if (pinned) return pinned;
  }
  return choiceElements.find((element) => SECTION_HEADLINE.test(textOf(element.headline)));
};

/**
 * The subtype widget colours the card and labels it Recreational or Travel.
 * Unlike the event type, its two values are fixed by the product, so it is
 * recognised by its choices.
 */
const LEVEL_BY_CHOICE: Record<string, ProgramLevel> = {
  rec: "rec",
  recreational: "rec",
  travel: "travel",
  traveler: "travel",
  traveller: "travel",
};

export const findLevelElement = (elements: SurveyElement[]): SurveyElement | undefined =>
  elements.find((element) => {
    const labels = choiceLabels(element);
    return labels.length >= 2 && labels.every((label) => LEVEL_BY_CHOICE[norm(label)]);
  });

/**
 * The sidebar: the two sign-up sections, then one section per choice of the
 * event-type widget. A new program added in the form builder shows up here
 * on the next load; a choice that collides with a sign-up slug is dropped so
 * `recreational` always stays the form.
 */
export const buildSections = (
  forms: ProjectForm[],
  pinnedSectionElementId?: string
): SectionDef[] => {
  const seen = new Set(FORM_SECTIONS.map((section) => section.id));
  const sections = [...FORM_SECTIONS];

  forms.forEach((form) => {
    const element = findSectionElement(form.elements, pinnedSectionElementId);
    if (!element) return;
    choiceLabels(element).forEach((label) => {
      const slug = slugify(label);
      if (!slug || seen.has(slug)) return;
      seen.add(slug);
      sections.push(eventSectionFrom(label));
    });
  });

  return sections;
};

/* ------------------------------------------------------------------ *
 * Filters
 * ------------------------------------------------------------------ */

export type MatchMode = "single" | "multi";

/** A choice dropdown, or a date-range picker over the event's own dates. */
export type FilterKind = "choice" | "date";

export interface FilterDef {
  /** The element id, which is also the key in `extendedBio.answers`. */
  id: string;
  /** The form the element belongs to; answers of other forms never match. */
  surveyId: string;
  label: string;
  kind: FilterKind;
  matchMode: MatchMode;
  /** The element's choice labels (data.blocks[].elements[].choices); empty for a date. */
  options: string[];
}

/** A choice widget whose answer is an array of labels rather than one. */
const MULTI_TYPES = new Set(["multipleChoiceMulti", "ranking"]);

const matchModeFor = (element: SurveyElement): MatchMode =>
  MULTI_TYPES.has(element.type) || element.allowMulti === true ? "multi" : "single";

/** Flattens an answer into the scalars used to read age groups off a project. */
const answerScalars = (answer: unknown): string[] => {
  if (answer === undefined || answer === null || answer === "") return [];
  if (Array.isArray(answer)) return answer.flatMap(answerScalars);
  if (typeof answer === "object") {
    const record = answer as Record<string, unknown>;
    const value = record.name ?? record.id ?? record.city;
    return value ? [`${value}`] : [];
  }
  return [`${answer}`];
};

const isChoice = (element: SurveyElement): boolean => (element.choices?.length ?? 0) > 0;
const isDate = (element: SurveyElement): boolean => element.type === "date";

/**
 * The filter controls for one form: a dropdown per choice widget and a
 * date-range picker per date widget (data.blocks[].elements[]).
 *
 * The widgets the admin marked "Use as filter" (`isFilter`) are the intended
 * set, so when a form marks any, only those appear — this is how the event-type
 * widget is kept out of the filters while a date widget is let in. When a form
 * marks none (older orgs), the page falls back to every choice widget, never an
 * unmarked date, so the controls are never empty just because the flag is unset.
 */
export const buildFilterDefs = (
  form: ProjectForm,
  options: { language?: string } = {}
): FilterDef[] => {
  const { language } = options;

  const candidates = form.elements.filter((element) => isChoice(element) || isDate(element));
  const marked = candidates.filter((element) => element.isFilter === true);
  const chosen = marked.length > 0 ? marked : candidates.filter(isChoice);

  return chosen.map((element) => ({
    id: element.id,
    surveyId: form.id,
    label: textOf(element.headline, language) || element.id,
    kind: isDate(element) ? "date" : "choice",
    matchMode: matchModeFor(element),
    options: isDate(element) ? [] : choiceLabels(element, language),
  }));
};

/**
 * A date filter matches on the event's own day span rather than a stored
 * answer (events carry a date, but rarely answer the form's date question):
 * the project's `start`..`end` must overlap the picked range. Day strings
 * compare lexically (`YYYY-MM-DD`); an open bound is unbounded on that side.
 */
export const eventInDateRange = (
  event: { start: string; end?: string },
  range: { from?: string; to?: string }
): boolean => {
  const first = event.start;
  const last = event.end ?? event.start;
  if (range.from && last < range.from) return false;
  if (range.to && first > range.to) return false;
  return true;
};

/** One stored answer item against a chosen value; objects compare by id. */
const itemMatches = (item: unknown, value: string): boolean => {
  if (item && typeof item === "object") {
    const record = item as Record<string, unknown>;
    return [record.id, record.name, record.city].some((candidate) => `${candidate}` === value);
  }
  return `${item}` === value;
};

/** A missing answer never matches; array answers match when any item does. */
export const answerMatches = (answer: unknown, value: string): boolean => {
  if (answer === undefined || answer === null || answer === "") return false;
  if (Array.isArray(answer)) return answer.some((item) => itemMatches(item, value));
  return itemMatches(answer, value);
};

/* ------------------------------------------------------------------ *
 * Projects to events
 * ------------------------------------------------------------------ */

const isoDay = (value: string | null | undefined): string | undefined => {
  if (!value) return undefined;
  const day = `${value}`.slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(day) ? day : undefined;
};

const addressOf = (project: RawProject): string | undefined => {
  const attributes = project.location?.attributes;
  if (attributes) {
    const parts = [attributes.address, attributes.city, attributes.state, attributes.country];
    const joined = parts.filter(Boolean).join(", ");
    if (joined) return joined;
  }
  return project.startPoint?.trim() || undefined;
};

/**
 * Both dates are full timestamps. They are only shown as a time of day when
 * they actually differ — on most projects they are the same instant, which
 * is a created-at default rather than a schedule.
 */
const timeOf = (project: RawProject): string | undefined => {
  const { startDate, endDate } = project;
  if (!startDate || !endDate || startDate === endDate) return undefined;
  const start = new Date(startDate);
  const end = new Date(endDate);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return undefined;
  if (isoDay(startDate) !== isoDay(endDate)) return undefined;
  const fmt = (date: Date) =>
    date.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  return `${fmt(start)} – ${fmt(end)}`;
};

export interface MapEventOptions {
  config: ProgramsConfig;
  /** liveUserId -> display name, for the project's managers. */
  userNames?: Record<string, string>;
  /** Pins the event-type widget when a form words its headline differently. */
  sectionElementId?: string;
}

/**
 * Maps a project the caller already matched to `form` (by extendedBioId) into
 * an event, routing it to a section by its event-type answer. A project whose
 * event type is not answered (nothing to route on) is skipped.
 */
export const toProgramEvent = (
  project: RawProject,
  form: ProjectForm,
  { config, userNames = {}, sectionElementId }: MapEventOptions
): ProgramEvent | null => {
  // The caller matched this project to the form by extendedBioId, so the
  // answers are read straight off the project (a form switch can leave the
  // stored surveyId pointing elsewhere; extendedBioId is the current form).
  const bio = project.extendedBio ?? {};
  const answers = bio.answers ?? {};
  const language = bio.language;

  const sectionElement = findSectionElement(form.elements, sectionElementId);
  const sectionAnswer = sectionElement ? answers[sectionElement.id] : undefined;
  // The slug has to agree with buildSections, which slugifies the same labels.
  const section = slugify(`${sectionAnswer ?? ""}`);
  if (!section) return null;

  const levelElement = findLevelElement(form.elements);
  const level = LEVEL_BY_CHOICE[norm(levelElement ? answers[levelElement.id] : undefined)] ?? "rec";

  const start = isoDay(project.startDate) ?? isoDay(project.fixedTime);
  if (!start) return null;

  const endDay = isoDay(project.endDate);
  const end = endDay && endDay !== start ? endDay : undefined;

  // Age groups are whatever the form offers; the labels are shown as-is.
  const ageGroups = [...new Set(
    form.elements
      .filter((element) => element !== sectionElement && element !== levelElement)
      .filter((element) => /age/i.test(textOf(element.headline, language)))
      .flatMap((element) => answerScalars(answers[element.id]))
  )];

  const managers = (project.managerLiveUserIds ?? [])
    .map((id) => userNames[`${id}`])
    .filter(Boolean);

  const amount = project.payment?.info?.amount;

  return {
    id: project._id,
    section,
    surveyId: form.id,
    title: project.name?.trim() || "Untitled",
    description: project.description?.trim() || "",
    start,
    end,
    time: timeOf(project),
    location: addressOf(project),
    coach: managers.length ? managers.join(", ") : undefined,
    ageGroups,
    level,
    price: typeof amount === "number" ? amount : undefined,
    url: beamViteUrlFor(project.beamViteWebsiteName, config),
    answers,
  };
};

/** Every project that maps onto one of the organization's event forms. */
export const toProgramEvents = (
  projects: RawProject[],
  forms: ProjectForm[],
  options: MapEventOptions
): ProgramEvent[] => {
  // A project is an event when its extendedBioId equals one of the event
  // forms' objectId from aggregateBds (the form currently assigned to it).
  const byId = new Map(forms.map((form) => [form.id, form]));
  return projects
    .map((project) => {
      const form = byId.get(`${project.extendedBioId}`);
      return form ? toProgramEvent(project, form, options) : null;
    })
    .filter((event): event is ProgramEvent => event !== null);
};

/** Display name for a live-user row, falling back to the beamId. */
export const liveUserName = (row: {
  firstName?: string;
  lastName?: string;
  beamId?: string;
}): string => [row.firstName, row.lastName].filter(Boolean).join(" ").trim() || row.beamId || "";
