import React, { FC, useEffect, useState, useCallback, useRef } from "react";
import { Row, Col, Layout, Skeleton, Button } from "antd";
import DispatchPanel from "./DispatchPanel/index";
import MapPanel from "./MapPanel/index";
import { useDispatch, useSelector } from "react-redux";
import Autocomplete from "react-google-autocomplete";
import Geocode from "react-geocode";
import DashboardModal from "./Dashboard/DashboardModal";
import DriverModal from "./Dashboard/Driver/DriverModal";
import DispatcherModal from "./Dashboard/DispatcherModal";
import VehicleModal from "./Dashboard/Vehicle/VehicleModal";
import PricingModal from "./Dashboard/Pricing/PricingModal";
import LocationModal from "./Dashboard/Location/LocationModal";
import EquipmentModal from "./Dashboard/Equipment/EquipmentModal";
import ShiftModal from "./Dashboard/Shift/ShiftModal";
import SchedulerModal from "./Dashboard/Scheduler/SchedulerModal";
import RecurringModal from "./Dashboard/Recurring/RecurringModal";
import TimeoffModal from "./Dashboard/Timeoff/TimeoffModal";
import ClockInModal from "./Dashboard/ClockIn/ClockInModal";
import SideBar from "./SideBar";
import { generateUUID } from "utils/appUtil";
import { SCHOOL_BUS_MENU_ITEMS, PERMISSION_TYPES } from "utils/PageTypes";
import { useLocation } from "react-router-dom";
import { DECRYPT_TOKEN } from "reducers/reducer";
import { RootState } from "reducers/rootReducer";
import { SocketTopics, UserTopics, BioTopics } from "constants/enums";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { MenuOutlined } from "@ant-design/icons";

import Loader from "react-loader-spinner";
import {
  getProjectsRequestPublishTopic,
  getProjectsSubscriptionTopic,
  getAdminRolesTopic,
} from "hooks/MQTTConstants";
import useSocketActions from "../../../hooks/socketActions";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const SchoolBusWrapper: FC<{ socket: ISocket }> = ({ socket }) => {
  const dispatch = useDispatch();
  // const [screen, setScreen] = useState<any>(SCHOOL_BUS_MENU_ITEMS.Dashboard);
  const [screen, setScreenState] = useState<any>(undefined);
  const [adminRoles, setAdminRoles] = useState<any>();
  const [userRole, setUserRole] = useState<any>();
  const [dispatching, setDispatching] = useState<Boolean>(false);
  const { encrypted_token, projects } = useSelector(
    (state: RootState) => state.auth
  );
  const [componentUuids, setComponentUuid] = useState<any>({
    all: generateUUID(),
    driver: generateUUID(),
    vehicle: generateUUID(),
    dispatcher: generateUUID(),
    pricing: generateUUID(),
    equipment: generateUUID(),
    schedule: generateUUID(),
    timeoff: generateUUID(),
    timesheet: generateUUID(),
    shift: generateUUID(),
    recurring: generateUUID(),
    location: generateUUID(),
  });

  // Custom setScreen function that saves to localStorage
  const setScreen = (value: any) => {
    setScreenState(value);
    localStorage.setItem("medicalRideWrapperScreen", String(value));
  };

  const params: any = {
    screen,
    setScreen,
  };
  const { search } = useLocation();
  const { getUserRequestPayload } = useSocketActions();
  const [showMapPanel, setShowMapPanel] = useState(true);

  useEffect(() => {
    if (encrypted_token) {
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getProjectsSubscriptionTopic(encrypted_token?.connectionId)
      );

      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getProjectsRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          userId: encrypted_token?.userId,
          cudbServiceId:
            encrypted_token?.cudbServiceId || encrypted_token?.serviceId,
        })
      );
    }
  }, [encrypted_token]);

  const getAdminRoles = (adminUserId, cudbServiceId) => {
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(adminUserId, "$", "$..role"),
      getAdminRolesTopic(encrypted_token?.connectionId),
      cudbServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      getAdminRolesTopic(encrypted_token?.connectionId),
      (response) => {
        setAdminRoles(response.data?.[0]?.[0]);
      },
      componentUuids.all
    );
  };

  useEffect(() => {
    if (adminRoles) {
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.SearchInUser,
        getUserRequestPayload(encrypted_token.userId, "$", "$..roleId"),
        BioTopics.GetBio,
        projects?.userServiceId
      );
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        BioTopics.GetBio,
        (response) => {
          const role = adminRoles.find((x) => {
            return x?._id === response?.data?.[0]?.[0];
          });
          if (
            role?.permissions?.includes(PERMISSION_TYPES.Admin) ||
            role?.permissions?.includes(PERMISSION_TYPES.Cad)
          )
            setUserRole("admin");
          if (
            role?.permissions?.includes(PERMISSION_TYPES.OnMove) &&
            !role?.permissions?.includes(PERMISSION_TYPES.Admin)
          )
            setUserRole("driver");
          if (
            role?.permissions?.includes(PERMISSION_TYPES.Live) &&
            !role?.permissions?.includes(PERMISSION_TYPES.Admin)
          )
            setUserRole("student");
        }
      );
    }
  }, [adminRoles]);

  useEffect(() => {
    if (userRole) {
      // Try to get saved screen from localStorage, otherwise default to Dashboard
      const savedScreen = localStorage.getItem("medicalRideWrapperScreen");
      if (savedScreen) {
        setScreen(Number(savedScreen));
      } else {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Dashboard);
      }
    }
  }, [userRole]);

  useEffect(() => {
    if (projects?.adminUserId) {
      getAdminRoles(projects?.adminUserId, projects?.userServiceId);
    }
  }, [projects]);

  useEffect(() => {
    if (socket.client) {
      const query = new URLSearchParams(search);
      const userId = query.get("userId");
      const connectionId = query.get("connectionId");
      const token = query.get("token");
      if (token) {
        dispatch(
          DECRYPT_TOKEN({
            data: { payload: token },
            callback: (data) => {},
          })
        );
      } else {
        dispatch({
          type: "ADD_ENCRYPTED_TOKEN",
          payload: {
            connectionId,
            userId,
          },
        });
      }
    }
  }, [search, socket.client]);


  const [isModalVisible, setIsModalVisible] = useState<boolean>(false);
  const validateNavigationRef = useRef<((onConfirm: () => void) => void) | null>(null);
  const [validateNavigation, setValidateNavigation] = useState<((onConfirm: () => void) => void) | null>(null);

  useEffect(() => {
  }, [validateNavigation]);

  const handleNavigationAttempt = useCallback((validator: (onConfirm: () => void) => void) => {
    validateNavigationRef.current = validator;
    setValidateNavigation(validator);
  }, []);

  // Get validateNavigation from ref to ensure it persists across re-renders
  const getValidateNavigation = useCallback(() => {
    return validateNavigationRef.current || validateNavigation;
  }, [validateNavigation]);
  
  const handleCancel = () => {
    setIsModalVisible(false);
  };

  return (
    <Row
      className="main-layout"
      style={{
        transform: "scale(0.8)",
        transformOrigin: "0 0",
        width: "125vw",
        height: "100vh",
      }}
    >
      {screen !== undefined ? (
        // 
        <React.Fragment>
        <Button
        className="beam-btn mb-3"
      type="text"       // no border
      icon={<MenuOutlined />}
      onClick={() => setIsModalVisible(true)}
    />
        <SideBar socket={socket} params={params} userRole={userRole} isModalVisible={isModalVisible} handleCancel={handleCancel} validateNavigation={validateNavigationRef.current} />
        </React.Fragment>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: "16px" }}>
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
          <Skeleton.Button shape="square" style={{ width: 85, height: 85 }} />
        </div>
      )}

      {(screen === SCHOOL_BUS_MENU_ITEMS.Dashboard || screen === SCHOOL_BUS_MENU_ITEMS.Booking) && (
        <React.Fragment>
          {screen === SCHOOL_BUS_MENU_ITEMS.Booking && (
          <Col
            span={24}
            style={{
              height: "calc((100vh / 0.8) - 50px)",
              overflow: "scroll",
            }}
          >
            <DispatchPanel
              socket={socket}
              params={params}
              fullScreen={true}
              scale={true}
              toggleDispatch={() => {
                // setDispatching((prev) => !prev);
                setScreen(SCHOOL_BUS_MENU_ITEMS.Dashboard);
                document.title = "Ride Schedule | Beam";
              }}
              onNavigationAttempt={(validator) => {handleNavigationAttempt(validator);
              }}
            />
          </Col>
          )}
            <Col
              span={24}
            style={{
              height: "calc((100vh / 0.8) - 70px)",
              overflow: "scroll",
            }}
          >
            <Row>
              {showMapPanel && (
                <Col span={24} className={`ride-container`}>
                  <MapPanel socket={socket} params={params} />
                </Col>
              )}
              <Col span={24}>
                <div className="beam-modal analytics-summary-modal mr-4">
                  <Layout
                    className="main-layout exec-layout mt-3"
                    style={{ padding: 0 }}
                  >
                    <DashboardModal
                      socket={socket}
                      filter={true}
                      componentUuid={componentUuids.all}
                      toggleMap={() => setShowMapPanel((prev) => !prev)}
                      mapVisible={showMapPanel}
                      toggleDispatch={() => {
                        setScreen(SCHOOL_BUS_MENU_ITEMS.Booking);
                      }}
                    />
                  </Layout>
                </div>
              </Col>
              </Row>
            </Col>
        </React.Fragment>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Driver && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <DriverModal
                socket={socket}
                componentUuid={componentUuids.driver}
                userRole={userRole}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Dispatcher && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <DispatcherModal
                socket={socket}
                componentUuid={componentUuids.dispatcher}
                userRole={userRole}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Timeoff && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <TimeoffModal
                socket={socket}
                componentUuid={componentUuids.timeoff}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Timesheet && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <ClockInModal
                socket={socket}
                componentUuid={componentUuids.timesheet}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Scheduler && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <SchedulerModal
                socket={socket}
                componentUuid={componentUuids.schedule}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Recurring && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <RecurringModal
                socket={socket}
                componentUuid={componentUuids.recurring}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Vehicle && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <VehicleModal
                socket={socket}
                componentUuid={componentUuids.vehicle}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Pricing && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <PricingModal
                socket={socket}
                componentUuid={componentUuids.pricing}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Location && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <LocationModal
                socket={socket}
                componentUuid={componentUuids.location}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Equipment && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <EquipmentModal
                socket={socket}
                componentUuid={componentUuids.equipment}
              />
            </Layout>
          </div>
        </Col>
      )}

      {screen === SCHOOL_BUS_MENU_ITEMS.Shift && (
        <Col span={24}>
          <div className="beam-modal analytics-summary-modal mr-4">
            <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
              <ShiftModal
                socket={socket}
                componentUuid={componentUuids.shift}
              />
            </Layout>
          </div>
        </Col>
      )}

      <Autocomplete
        apiKey="AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M"
        style={{ display: "none" }}
        options={{
          types: ["(regions)"],
          componentRestrictions: { country: ["us", "ca", "uk"] },
        }}
      />
    </Row>
  );
};

export default SchoolBusWrapper;
