import React, { useEffect, useState } from "react";
import { Modal, Button, Input, Row, Col } from "antd";
import { LeftOutlined, RightOutlined } from "@ant-design/icons";
import { SocketTopics, UserTopics } from "constants/enums";
import {
    getPageUpdateRequestPublishTopic,
    getPageUpdateSubscriptionTopic
  } from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";

interface TextModalProps {
  inputArray: any[];
  visible: boolean;
  onSave: (updatedArray: string[]) => void;
  onCancel: () => void;
  defaultIndex?: number;
  socket?: any;
}

const TextModal: React.FC<TextModalProps> = ({
  inputArray,
  visible,
  onSave,
  onCancel,
  socket,
  defaultIndex = 0,
}) => {
  const [currentIndex, setCurrentIndex] = useState<number>();
  const [saving, setSaving] = useState<boolean>(false);
  const [textArray, setTextArray] = useState<any[]>([...inputArray]);
  const [currentText, setCurrentText] = useState<string>();
  const {
    encrypted_token,
  } = useSelector((state: RootState) => state.auth);

  useEffect(()=>{
    console.log('input array', inputArray);
    inputArray?.map((page: any, index)=>{
       if(page?.key === defaultIndex){
            setCurrentIndex(index);
            setCurrentText(page?.action?.page?.profile?.customMessages?.[0]?.attributes?.body);
       }
    })
    console.log('pageId', defaultIndex);

    socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getPageUpdateSubscriptionTopic(encrypted_token?.connectionId),
        (response) => {
          setSaving(false);
          pushNotification(
            "Custom message saved successfully",
            "success",
            "TOP_CENTER",
            1000
          );
        }
      );

  },[]);

  const handleNext = () => {
    if (currentIndex < textArray.length - 1) {
    //   saveCurrentText();
      const newIndex = currentIndex + 1;
      setCurrentIndex(newIndex);
      setCurrentText(textArray[newIndex]?.action?.page?.profile?.customMessages?.[0]?.attributes?.body || '');
    }
  };

  const handlePrevious = () => {
    if (currentIndex > 0) {
    //   saveCurrentText();
      const newIndex = currentIndex - 1;
      setCurrentIndex(newIndex);
      setCurrentText(textArray[newIndex]?.action?.page?.profile?.customMessages?.[0]?.attributes?.body || '');
    }
  };

  const saveCurrentText = () => {
    const updatedArray = [...textArray];
    updatedArray[currentIndex].action.page.profile.customMessages[0].attributes.body = currentText;
    setTextArray(updatedArray);
    setSaving(true);
    socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getPageUpdateRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({
          objectId: updatedArray[currentIndex].key.toString(),
          changes: [{
            "op": "replace",
            "path": "$..profile.customMessages[0]..body",
            "value": currentText
          }]
        })
      );
  };

  const handleSave = () => {
    saveCurrentText();
    // onSave(textArray);
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    setCurrentText(e.target.value);
  };

  return (
    <Modal
      title="Edit Notification Message"
      className="beam-modal"
      visible={visible}
      onCancel={onCancel}
      //   footer={[
      //     <Button key="cancel" className="beam-btn orange-btn bordered" onClick={onCancel}>
      //       Cancel
      //     </Button>,
      //     <Button key="save" type="primary" className="beam-btn green-btn" onClick={handleSave}>
      //       Save
      //     </Button>,
      //   ]}
    >
      <div style={{ marginBottom: 16 }}>
        <Input.TextArea
          value={currentText}
          onChange={handleTextChange}
          rows={4}
          autoSize={{ minRows: 4 }}
          placeholder="Edit custom message"
        />
      </div>
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <Button
          icon={<LeftOutlined />}
          onClick={handlePrevious}
          disabled={currentIndex === 0}
          className="beam-btn yellow-btn bordered"
        >
          Previous
        </Button>
        <Button
          icon={<RightOutlined />}
          onClick={handleNext}
          disabled={currentIndex === textArray.length - 1}
          className="beam-btn yellow-btn bordered"
        >
          Next
        </Button>
      </div>
      <Row className="action-grp mt-4">
        <Col span={12} xs={24} sm={12}>
          <Button
            className="beam-btn orange-btn bordered w-full"
            onClick={onCancel}
            // loading={saving}
          >
            Cancel
          </Button>
        </Col>
        <Col span={12} className="pl-2" xs={24} sm={12}>
          <Button
            className="beam-btn green-btn cover w-full"
            onClick={handleSave}
            loading={saving}
          >
            Save
          </Button>
        </Col>
      </Row>
    </Modal>
  );
};

export default TextModal;
