import React from "react";
import { Row, Col, Button } from "antd";
import { useDispatchPanel } from "../context";

const DispatchActions: React.FC = () => {
  const {
    ridePageId,
    webBooker,
    ridePageStatus,
    searching,
    blocked,
    estimatedFare,
    clearForm,
    setIsCancelModalVisible,
    submitPageId,
  } = useDispatchPanel();

  return (
    <Row className="action-grp ride-actions mt-3">
      <Col span={ridePageId ? (webBooker ? 8 : 6) : 12} className="px-2">
        <Button
          className="beam-btn yellow-btn bordered w-full w-full ride-btn ride-btn--secondary"
          onClick={() => {
            clearForm();
            localStorage.removeItem("lastRideId");
          }}
        >
          Clear
        </Button>
      </Col>

      {ridePageId && (
        <Col span={webBooker ? 8 : 6} className="px-2">
          <Button
            className="beam-btn orange-btn bordered w-full w-full ride-btn ride-btn--danger"
            onClick={() => {
              setIsCancelModalVisible(true);
            }}
            // The ride service rejects cancelling a completed ride
            // (INVALID_STATE); a cancelled one is already done.
            disabled={ridePageStatus === "black" || ridePageStatus === "green"}
          >
            Cancel
          </Button>
        </Col>
      )}

      <Col
        span={ridePageId ? (webBooker ? 8 : 6) : 12}
        className="pl-2 ride-actions__primary"
      >
        <Button
          className="beam-btn green-btn cover w-full ride-btn ride-btn--primary"
          htmlType="submit"
          loading={searching}
          disabled={
            blocked ||
            ridePageStatus === "green" ||
            (webBooker && !estimatedFare)
          }
          onClick={(e) => {
            // A second click while a submit is in flight must not flip the
            // Update/New target of the request already being built.
            if (searching) {
              e.preventDefault();
              return;
            }
            submitPageId.current = true;
          }}
        >
          {ridePageId ? "Update" : "Dispatch"}
        </Button>
      </Col>

      {ridePageId && !webBooker && (
        <Col span={6} className="pl-3">
          <Button
            className="beam-btn yellow-btn bordered w-full ride-btn ride-btn--secondary"
            htmlType="submit"
            loading={searching}
            disabled={blocked}
            onClick={(e) => {
              if (searching) {
                e.preventDefault();
                return;
              }
              submitPageId.current = false;
            }}
            title="Dispatch as a new ride"
          >
            New
          </Button>
        </Col>
      )}
    </Row>
  );
};

export default DispatchActions;
