import React from "react";
import { Button, Form } from "antd";
import { CompassOutlined } from "@ant-design/icons";
import LocationInput, { disabledStyle } from "common/LocationInput";
import { useDispatchPanel } from "../context";
import { getCurrentLocation, reverseGeocode } from "../utils";
import "./LocationSection.scss";

const LocationSection: React.FC = () => {
  const {
    form,
    webBooker,
    standLocations,
    screens,
    setScreens,
    addOtherLocation,
    getRideEstimation,
    getCouponByLocation,
    locationType,
    pickupReference,
  } = useDispatchPanel();
  // Booked from a location QR: the pickup is that place and can't be changed.
  const pickupLocked = !!pickupReference;

  return (
    <React.Fragment>
      {/* Flex rather than a 22/2 grid: on a phone the 2/24 column is too narrow
          for the locate button, which then overlaps the field's Map button. */}
      <div className="ride-loc-row mt-3">
        <div className="ride-loc-row__field">
          <Form.Item
            name="pickupLocation"
            rules={[{ required: true, message: "**Required Field" }]}
          >
            <LocationInput
              placeholder="Pick up location"
              disabled={pickupLocked}
              onChange={(location: any) => {
                addOtherLocation({ pickupLocation: location });
                setScreens({
                  ...screens,
                  map: true,
                });
                const dropoffLocation = form.getFieldValue("dropoffLocation");
                if (dropoffLocation?.value?.coordinates) {
                  getRideEstimation(location, dropoffLocation);
                }
                locationType.current = "pickup";
                getCouponByLocation(location);
              }}
            />
          </Form.Item>
          {pickupLocked && (
            <p className="mb-2">Pickup at {pickupReference.name}</p>
          )}
          {standLocations?.length > 0 && (
            <Form.Item>
              <p className="error">
                **Blocked Area. Please select nearest pickup point on the map
              </p>
            </Form.Item>
          )}
        </div>

        <Button
          className="beam-btn icon-btn ride-loc-row__locate"
          aria-label="Use my current location as pickup"
          disabled={pickupLocked}
          style={pickupLocked ? disabledStyle : undefined}
          onClick={async () => {
            const location = await getCurrentLocation();
            console.log("location", location);
            const address = await reverseGeocode(location);
            console.log("address", address);

            const pickupLocation = {
              type: "incident-location",
              label: address,
              value: {
                description: address,
                place_id: "",
                coordinates: location,
              },
            };
            form.setFieldsValue({
              pickupLocation,
            });

            addOtherLocation({ pickupLocation });
            setScreens({
              ...screens,
              map: true,
            });
            const dropoffLocation = form.getFieldValue("dropoffLocation");
            if (dropoffLocation?.value?.coordinates) {
              getRideEstimation(pickupLocation, dropoffLocation);
            }
            getCouponByLocation(pickupLocation);
            locationType.current = "pickup";
          }}
        >
          <CompassOutlined />
        </Button>
      </div>
      <div className="ride-loc-row mt-3">
        <div className="ride-loc-row__field">
          <Form.Item
            name="dropoffLocation"
            rules={
              webBooker ? [{ required: true, message: "**Required Field" }] : []
            }
          >
            <LocationInput
              placeholder="Drop off location"
              onChange={(location: any) => {
                addOtherLocation({ dropoffLocation: location });
                const pickupLocation = form.getFieldValue("pickupLocation");
                if (pickupLocation?.value?.coordinates) {
                  getRideEstimation(pickupLocation, location);
                }
                locationType.current = "dropoff";
              }}
            />
          </Form.Item>
        </div>
        <Button
          className="beam-btn icon-btn ride-loc-row__locate"
          aria-label="Use my current location as drop off"
          onClick={async () => {
            const location = await getCurrentLocation();
            console.log("location", location);
            const address = await reverseGeocode(location);
            console.log("address", address);

            const dropoffLocation = {
              type: "incident-location",
              label: address,
              value: {
                description: address,
                place_id: "",
                coordinates: location,
              },
            };
            form.setFieldsValue({
              dropoffLocation,
            });

            addOtherLocation({ dropoffLocation });
            setScreens({
              ...screens,
              map: true,
            });
            const pickupLocation = form.getFieldValue("pickupLocation");
            if (pickupLocation?.value?.coordinates) {
              getRideEstimation(pickupLocation, dropoffLocation);
            }
            locationType.current = "dropoff";
          }}
        >
          <CompassOutlined />
        </Button>
      </div>
    </React.Fragment>
  );
};

export default LocationSection;
