import React from "react";
import { useDispatchPanel } from "../context";

// Compact stat card with the trip estimate (distance, time, fare...).
const EstimationSummary: React.FC = () => {
  const { estimation } = useDispatchPanel();

  if (!estimation) return null;

  return (
    <div className="ride-estimate mt-3" aria-label="Trip estimate">
      <div className="ride-estimate__title">Trip estimate</div>
      <dl className="ride-estimate__grid">
        {estimation.map((item: any, i: number) => (
          <div className="ride-estimate__stat" key={i}>
            <dt>{item.label}</dt>
            <dd>{item.value}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
};

export default EstimationSummary;
