/**
 * Pure helpers shared by the ride summary (/ride-summary) and the incident
 * summary (/summary) reports: which GPS window to load, trip times, trip stats
 * from the GPS breadcrumbs and the static route map URL. Nothing here touches
 * `google`, the DOM or redux so it can be unit tested.
 */
import { downsample, parseTrack, summarizeTrack, Stop, TrackPoint } from "../Fleet/fleetUtils";

const polyline = require("google-polyline");

/* ------------------------------------------------------------- helpers */

/** Epoch ms from an epoch (s or ms), numeric string or date string. */
export const toMs = (value: any): number | undefined => {
  if (value === undefined || value === null || value === "") return undefined;
  const n =
    typeof value === "number"
      ? value
      : /^\d+(\.\d+)?$/.test(`${value}`)
      ? Number(value)
      : Date.parse(value);
  if (!Number.isFinite(n) || n <= 0) return undefined;
  return n < 1e12 ? n * 1000 : n;
};

export interface LatLng {
  lat: number;
  lng: number;
}

/**
 * `{lat, long}` / `{lat, lng}` or a location object wrapping them in
 * `coordinates` (the page stores both shapes) → LatLng, or undefined.
 */
export const toLatLng = (value: any): LatLng | undefined => {
  const c = value?.coordinates ?? value;
  const lat = Number(c?.lat);
  const lng = Number(c?.long ?? c?.lng);
  if (c?.lat === undefined || c?.lat === null || !Number.isFinite(lat) || !Number.isFinite(lng)) return undefined;
  if (c?.long === undefined && c?.lng === undefined) return undefined;
  return { lat, lng };
};

/* ---------------------------------------------------------- GPS window */

export interface GpsWindow {
  iotUdid?: string;
  iotUserId?: string;
  /** Sender of the GPS message (the driver / device owner). */
  userId?: string;
  from?: number;
  to?: number;
}

const byCreatedAt = (a: any, b: any) => (toMs(a?.createdAt) ?? 0) - (toMs(b?.createdAt) ?? 0);

/**
 * The GPS window of the page's (latest) trip, from the page messages:
 * 1. the newest `gps-report` (data.startIotAt / endIotAt);
 * 2. else the last `gps` start (data.startIotAt, or its createdAt) paired with
 *    the next `gps-stop` (data.endIotAt, or its createdAt);
 * 3. else that start left open: until the last message after it, or `now`.
 */
export const findGpsWindow = (messages: any[] | undefined, now = Date.now()): GpsWindow | undefined => {
  const sorted = (messages ?? []).filter(Boolean).slice().sort(byCreatedAt);
  const reports = sorted.filter((m) => m.messageType === "gps-report");
  const report = reports[reports.length - 1];
  if (report) {
    return {
      iotUdid: report.data?.iotUdid,
      iotUserId: report.data?.iotUserId,
      // The writer sets data.userId (the driver); sender is the fallback.
      userId: report.data?.userId ?? report.senderId,
      from: toMs(report.data?.startIotAt),
      to: toMs(report.data?.endIotAt),
    };
  }

  // Group start/stop pairs; repeated `gps` messages inside an open trip keep
  // the first one as the start.
  let trip: { start: any; stop?: any } | undefined;
  sorted.forEach((m) => {
    if (m.messageType === "gps") {
      if (!trip || trip.stop) trip = { start: m };
    } else if (m.messageType === "gps-stop" && trip && !trip.stop) {
      trip.stop = m;
    }
  });
  if (!trip) return undefined;

  const { start, stop } = trip;
  const from = toMs(start.data?.startIotAt) ?? toMs(start.createdAt);
  let to: number | undefined;
  if (stop) {
    to = toMs(stop.data?.endIotAt) ?? toMs(stop.createdAt);
  } else {
    const last = toMs(sorted[sorted.length - 1]?.createdAt);
    to = last !== undefined && from !== undefined && last > from ? last : now;
  }
  return {
    iotUdid: start.data?.iotUdid ?? stop?.data?.iotUdid,
    iotUserId: start.data?.iotUserId ?? stop?.data?.iotUserId,
    userId: start.data?.userId ?? stop?.data?.userId ?? start.senderId,
    from,
    to,
  };
};

export const gpsWindowKey = (w?: GpsWindow) =>
  w ? [w.iotUdid, w.iotUserId, w.userId, w.from, w.to].join("|") : "";

/**
 * `GET_HISTORICAL_GPS` requestData for the window (same shape the ride summary
 * always sent), or undefined when the window can't make a valid query.
 */
export const gpsHistoryRequest = (w: GpsWindow | undefined, ecosystem = process.env.REACT_APP_ECO_SYSTEM) => {
  if (!w || !w.iotUdid || w.from === undefined || w.to === undefined) return undefined;
  return {
    filter: `ecosystem=${ecosystem} iotUdid=${w.iotUdid} userId=${w.userId} iotUserId=${w.iotUserId} page=true`,
    fromTimestamp: w.from,
    toTimestamp: w.to,
    options: {
      withLabels: true,
    },
  };
};

/* ---------------------------------------------------------------- times */

export interface TripTimes {
  start?: number;
  end?: number;
  totalMs?: number;
}

/**
 * start: GPS window start → first GPS point → page metadata.createdAt.
 * end:   tripDetails.end.timestamp (profile, then meter) → GPS window end →
 *        last GPS point.
 */
export const tripTimes = ({
  page,
  window,
  points,
  waitMs,
}: {
  page?: any;
  window?: GpsWindow;
  points?: TrackPoint[];
  /** The meter's wait time: a trip can't be shorter than it. */
  waitMs?: number;
}): TripTimes => {
  const s = page?.persistent?.static;
  const first = points?.length ? points[0].t : undefined;
  const last = points?.length ? points[points.length - 1].t : undefined;
  const start = window?.from ?? first ?? toMs(s?.metadata?.createdAt);
  const end =
    toMs(s?.profile?.tripDetails?.end?.timestamp) ??
    toMs(s?.meter?.tripDetails?.end?.timestamp) ??
    window?.to ??
    last;
  const totalMs = start !== undefined && end !== undefined ? Math.max(0, end - start) : undefined;
  // The meter clock starts before the start message is stamped (e.g. a hail
  // ride sends Start only after creating its page), so a short trip can show
  // more wait than total time. Only then: end = start + wait.
  if (
    start !== undefined &&
    totalMs !== undefined &&
    waitMs !== undefined &&
    Number.isFinite(waitMs) &&
    waitMs > totalMs
  ) {
    return { start, end: start + waitMs, totalMs: waitMs };
  }
  return { start, end, totalMs };
};

/* ---------------------------------------------------------------- stats */

export type DistanceUnit = "km" | "mi";

/** meter.unit "imperial" → miles, anything else → km. */
export const distanceUnit = (meterUnit?: string): DistanceUnit => (meterUnit === "imperial" ? "mi" : "km");

export interface TripStats {
  /** Distance driven while moving, in `unit`. */
  distance: number;
  /** Every leg including idle jitter and signal gaps, in `unit`. */
  totalDistance: number;
  unit: DistanceUnit;
  movingMs: number;
  /** Idle time (speed ≤ 0.5 m/s), the GPS equivalent of the meter's wait. */
  waitMs: number;
  maxSpeed: number;
  stops: Stop[];
  track: TrackPoint[];
}

const metersTo = (m: number, unit: DistanceUnit) => (unit === "mi" ? m / 1609.344 : m / 1000);

/** Raw `/getRange` samples → trip stats, or undefined without a track. */
export const tripStats = (samples: any[] | undefined, meterUnit?: string): TripStats | undefined => {
  const track = parseTrack(samples);
  if (!track.length) return undefined;
  const unit = distanceUnit(meterUnit);
  const summary = summarizeTrack(track);
  // summarizeTrack only exposes the average moving speed; speed × time is
  // exactly the distance it accumulated while moving.
  const movingM = summary.avgMovingSpeed * (summary.movingMs / 1000);
  return {
    distance: metersTo(movingM, unit),
    totalDistance: metersTo(summary.distanceM, unit),
    unit,
    movingMs: summary.movingMs,
    waitMs: summary.idleMs,
    maxSpeed: summary.maxSpeed,
    stops: summary.stops,
    track,
  };
};

/* ----------------------------------------------------------- formatting */

const pad = (n: number) => `${n}`.padStart(2, "0");

/** "1h 05m 12s" / "5m 03s" / "42s" / "—". */
export const formatDuration = (ms?: number) => {
  if (ms === undefined || ms === null || !Number.isFinite(ms) || ms < 0) return "—";
  const total = Math.round(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  if (h) return `${h}h ${pad(m)}m ${pad(s)}s`;
  if (m) return `${m}m ${pad(s)}s`;
  return `${s}s`;
};

/** "+12m" / "+1h 05m" offset of an event from the timeline start. */
export const formatOffset = (ms?: number) => {
  if (ms === undefined || !Number.isFinite(ms)) return "";
  const mins = Math.max(0, Math.floor(ms / 60000));
  const h = Math.floor(mins / 60);
  return h ? `+${h}h ${pad(mins % 60)}m` : `+${mins}m`;
};

const EVENT_LABELS: Record<string, string> = {
  gps: "GPS start",
  "gps-stop": "GPS stop",
  "gps-report": "GPS report",
};
const ACRONYMS = new Set(["gps", "rsvp", "b2t", "iot", "ncic", "nfirs", "cad", "sos"]);

/** Message type → label ("gps-report" → "GPS report", "video-call" → "Video call"). */
export const humanizeEventType = (type?: string) => {
  if (!type) return "Event";
  const key = `${type}`.toLowerCase();
  if (EVENT_LABELS[key]) return EVENT_LABELS[key];
  return key
    .split(/[-_\s]+/)
    .filter(Boolean)
    .map((w, i) => (ACRONYMS.has(w) ? w.toUpperCase() : i === 0 ? w.charAt(0).toUpperCase() + w.slice(1) : w))
    .join(" ");
};

/** Local date + time, or "—". */
export const formatDateTime = (value: any) => {
  const ms = toMs(value);
  if (ms === undefined) return "—";
  const d = new Date(ms);
  return `${d.toLocaleDateString()} ${d.toLocaleTimeString()}`;
};

/* ------------------------------------------------------------------ map */

/** The key the ride summary has always used for Static Maps. */
export const STATIC_MAPS_KEY = process.env.REACT_APP_GOOGLE_STATIC_MAPS_KEY || "AIzaSyBPbm_leF-HO_IYt7_gp9noPOCem14bEtY";

export const MAX_STATIC_MAP_URL = 7000;

/**
 * Google Static Maps URL with the track as an encoded polyline, a green pickup
 * (A) and a red dropoff (B) marker. Pickup/dropoff default to the track ends.
 * The track is thinned until the URL fits `MAX_STATIC_MAP_URL`.
 */
export interface MapMarker extends LatLng {
  color: string;
  /** One character (Static Maps label). */
  label: string;
}

/**
 * A point `minM`–`maxM` metres from `center`, placed by a seed (e.g. the page
 * id) so the same page always gets the same point. Used for demo pins.
 */
export const pointNear = (center: LatLng, seed: string, minM = 300, maxM = 900): LatLng => {
  let h = 2166136261;
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  const r1 = ((h >>> 0) % 10000) / 10000;
  const r2 = (((h >>> 0) / 10000) % 10000) / 10000;
  const bearing = r1 * 2 * Math.PI;
  const dist = minM + r2 * (maxM - minM);
  const dLat = (dist * Math.cos(bearing)) / 111320;
  const dLng = (dist * Math.sin(bearing)) / (111320 * Math.cos((center.lat * Math.PI) / 180));
  return { lat: center.lat + dLat, lng: center.lng + dLng };
};

export const staticRouteMapUrl = ({
  track,
  pickup,
  dropoff,
  extraMarkers = [],
  apiKey = STATIC_MAPS_KEY,
  size = "640x400",
}: {
  track?: { lat: number; lng: number }[];
  pickup?: LatLng;
  dropoff?: LatLng;
  /** More pins, e.g. a store. `color` is a Static Maps colour (name or 0xRRGGBB). */
  extraMarkers?: MapMarker[];
  apiKey?: string;
  size?: string;
}): string | undefined => {
  const path = track ?? [];
  const a = pickup ?? path[0];
  const b = dropoff ?? (path.length > 1 ? path[path.length - 1] : undefined);
  if (!a && !b && path.length < 2 && extraMarkers.length === 0) return undefined;

  const ll = (p: LatLng) => `${p.lat.toFixed(6)},${p.lng.toFixed(6)}`;
  const base = `https://maps.googleapis.com/maps/api/staticmap?size=${size}&scale=2&maptype=roadmap`;
  const markers = [
    a ? `&markers=${encodeURIComponent(`color:green|label:A|${ll(a)}`)}` : "",
    b ? `&markers=${encodeURIComponent(`color:red|label:B|${ll(b)}`)}` : "",
    ...extraMarkers.map(
      (m) => `&markers=${encodeURIComponent(`color:${m.color}|label:${m.label}|${ll(m)}`)}`
    ),
  ].join("");
  const key = `&key=${apiKey}`;

  const build = (points: { lat: number; lng: number }[]) => {
    if (points.length < 2) return `${base}${markers}${key}`;
    const enc = polyline.encode(points.map((p) => [p.lat, p.lng]));
    return `${base}&path=${encodeURIComponent(`color:0x1c7a2bdd|weight:4|enc:${enc}`)}${markers}${key}`;
  };

  let max = path.length;
  let url = build(path);
  while (url.length > MAX_STATIC_MAP_URL && max > 2) {
    max = Math.max(2, Math.floor(max * 0.75));
    url = build(downsample(path, max));
  }
  return url;
};
