import { OrgRole } from "./beamTypes";
import { ProgramsConfig, signupOverride } from "./config";

/**
 * Which form the Recreational and Traveler sections embed.
 *
 * The form is not configured per deployment — it is resolved from the
 * organization's own roles, the way the admin console does it: a role carries
 * the `extendedBioId` of its registration form, so picking the role picks the
 * form. `org-beam-sport` has a "Recreational" role bound to form 229211 and a
 * "Travelling" role bound to 229635, and each section opens its own.
 *
 * An organization that has no such role falls back to the next candidate name
 * (a generic pending-registration role). If nothing matches, the section says
 * so instead of embedding another organization's form.
 */

/** Role names to try for each sign-up section, best first, case-insensitive. */
export const SIGNUP_ROLE_CANDIDATES: Record<string, string[]> = {
  recreational: ["recreational", "pending users", "non-beamer users"],
  traveler: ["travelling", "traveller", "traveler", "travel", "pending users"],
};

/**
 * A fully-specified sign-up form URL for a section, used when its registration
 * form lives in a different organization than the page's default — so the URL
 * cannot be built from this org's `serviceId`/`connectionId`. Travel
 * registration is hosted on `org-beam-sport` while the page runs on the
 * default org. An explicit env/query override (`signupOverride`) still wins.
 */
export const SIGNUP_URL_OVERRIDES: Record<string, string> = {
  recreational:
    "https://cpc.staging.beam.live/eb/229211?serviceId=org-beam-sport&roleId=0c1c18ab-fe5f-4d40-a944-c78888fd2235&connectionId=178541&adminUserId=120129",
  traveler:
    "https://cpc.staging.beam.live/eb/229635?serviceId=org-beam-sport&roleId=806397b8-e4be-4f3d-b7ef-83983ccc634d&connectionId=178507&adminUserId=120129",
};

export interface SignupTarget {
  /** BDS id of the `user:extendedBio` form. */
  formId: string;
  roleId: string;
  roleName: string;
  /** The CPC form URL, and the same URL in embed mode for the iframe. */
  url: string;
  embedUrl: string;
}

const norm = (value: string | undefined): string => (value ?? "").trim().toLowerCase();

const buildUrl = (formId: string, roleId: string, config: ProgramsConfig): string => {
  const params = new URLSearchParams({
    serviceId: config.serviceId,
    roleId,
    connectionId: config.connectionId,
  });
  return `${config.cpcAppUrl}/eb/${formId}?${params.toString()}`;
};

/** A sign-up target from a fully-specified form URL, reading its ids back out. */
const targetFromUrl = (url: string): SignupTarget => {
  const parsed = new URL(url);
  const formId = parsed.pathname.split("/").filter(Boolean).pop() ?? "";
  const roleId = parsed.searchParams.get("roleId") ?? "";
  return {
    formId,
    roleId,
    roleName: "",
    url,
    embedUrl: `${url}${url.includes("?") ? "&" : "?"}embed=true`,
  };
};

/**
 * The sign-up target for one section, or `null` when the organization has no
 * role for it. An explicit `formId`/`roleId` override always wins.
 */
export const resolveSignup = (
  sectionId: string,
  roles: OrgRole[],
  config: ProgramsConfig
): SignupTarget | null => {
  const override = signupOverride(sectionId);

  // A section pinned to another org's form uses that URL verbatim, unless a
  // deploy pins its own form/role through env/query.
  const fixed = SIGNUP_URL_OVERRIDES[sectionId];
  if (fixed && !override.formId && !override.roleId) {
    return targetFromUrl(fixed);
  }

  const byName = (name: string) => roles.find((role) => norm(role.name) === name);

  let formId = override.formId;
  let roleId = override.roleId;
  let roleName = "";

  if (!formId || !roleId) {
    const candidates = SIGNUP_ROLE_CANDIDATES[sectionId] ?? [sectionId];
    // Only a role that actually has a form bound can serve the section.
    const match = candidates.map(byName).find((role) => role?.extendedBioId);
    if (match) {
      formId = formId ?? String(match.extendedBioId);
      roleId = roleId ?? match._id;
      roleName = match.name ?? "";
    }
  }

  if (!formId || !roleId) return null;

  const url = buildUrl(formId, roleId, config);
  return { formId, roleId, roleName, url, embedUrl: `${url}&embed=true` };
};

/** Resolves every sign-up section in one pass, keyed by section slug. */
export const resolveSignups = (
  sectionIds: string[],
  roles: OrgRole[],
  config: ProgramsConfig
): Record<string, SignupTarget> => {
  const out: Record<string, SignupTarget> = {};
  sectionIds.forEach((id) => {
    const target = resolveSignup(id, roles, config);
    if (target) out[id] = target;
  });
  return out;
};
