import React, { useEffect, useRef } from "react";
import { Row, Col, Button, Select, Form } from "antd";
import { isValidPhoneNumber } from "react-phone-number-input";
import { SocketTopics } from "constants/enums";
import { getApplyCouponPublishTopic } from "hooks/MQTTConstants";
import { useDispatchPanel } from "../context";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { newClientRequestId } from "../../rideSync";

const CouponSection: React.FC = () => {
  const {
    fareType,
    form,
    coupons,
    socket,
    encrypted_token,
    projects,
    estimatedFare,
    couponResponse,
    setCouponResponse,
    getCouponByLocation,
    couponRequestRef,
  } = useDispatchPanel();

  // A coupon is quoted for one fare and pickup: when the fare type, fare or
  // pickup changes (including programmatic changes from an estimate or fixed
  // rate reply), the quote no longer holds.
  const watchedPickup = Form.useWatch("pickupLocation", form);
  const quoteKey = JSON.stringify([
    fareType?.value,
    fareType?.fare,
    estimatedFare,
    watchedPickup?.value?.coordinates?.lat,
    watchedPickup?.value?.coordinates?.long,
  ]);
  const lastQuoteKey = useRef<string>(quoteKey);
  useEffect(() => {
    if (lastQuoteKey.current === quoteKey) return;
    lastQuoteKey.current = quoteKey;
    if (couponRequestRef.current || couponResponse) {
      couponRequestRef.current = undefined;
      setCouponResponse(undefined);
      if (form.getFieldValue("coupon") !== undefined) {
        form.setFieldsValue({ coupon: undefined });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [quoteKey]);

  // The list depends on who the passenger is (private coupons), so fetch it
  // again once a complete, valid phone number is entered — not on every
  // keystroke — and only when it differs from the last one fetched for this
  // pickup. The email in the form is sent along at that moment.
  const watchedPhone = Form.useWatch("passengerPhoneNumber", form);
  const validPhone =
    watchedPhone && isValidPhoneNumber(watchedPhone) ? watchedPhone : undefined;
  const lastFetched = useRef<string>();
  useEffect(() => {
    const pickupLocation = form.getFieldValue("pickupLocation");
    const coordinates = pickupLocation?.value?.coordinates;
    if (!validPhone || !coordinates) return;
    const key = `${validPhone}|${coordinates.lat},${coordinates.long}`;
    if (lastFetched.current === key) return;
    lastFetched.current = key;
    getCouponByLocation(pickupLocation);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [validPhone]);

  if (!(fareType?.value === "fixed" || fareType?.value === "fixedEstimate")) {
    return null;
  }

  const passengerPhoneNumber = form.getFieldValue("passengerPhoneNumber");
  if (passengerPhoneNumber === undefined || passengerPhoneNumber === "") {
    return null;
  }

  const validCoupons = (coupons ?? []).filter(
    (c: { expiry?: number }) => c.expiry != null && c.expiry > Date.now()
  );

  const applyCoupon = (couponCode: string) => {
    const fareTypeVal = form.getFieldValue("fareType");
    const passengerEmail = form.getFieldValue("passengerEmail");
    const pickupLocation = form.getFieldValue("pickupLocation");
    const requestId = newClientRequestId();
    couponRequestRef.current = { code: couponCode, requestId };
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getApplyCouponPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        pickupLocation: {
          coordinates: pickupLocation?.value?.coordinates,
        },
        notificationChannels: {
          email: passengerEmail,
          phone: passengerPhoneNumber,
        },
        cudbServiceId: projects?.userServiceId,
        couponCode: couponCode,
        meterFare:
          fareTypeVal?.value === "fixed" ? fareTypeVal?.fare : estimatedFare,
      }, requestId)
    );
  };

  return (
    <React.Fragment>
      <label className="ant-form-item-required">Discount coupons</label>
      <Row>
        <Col span={couponResponse?.status === true ? 20 : 24} className="">
          <Form.Item name="coupon">
            <Select
              allowClear
              className="w-full"
              placeholder={
                validCoupons.length === 0
                  ? "No coupons available"
                  : "Select a coupon"
              }
              options={validCoupons.map(
                (c: { code: string; type?: string; value?: number }) => ({
                  value: c.code,
                  label:
                    c.type === "percentage"
                      ? `${c.code} - ${c.value}%`
                      : `${c.code} - ${c.value} off`,
                })
              )}
              onChange={(value) => {
                if (value == null) {
                  couponRequestRef.current = undefined;
                  setCouponResponse(undefined);
                  return;
                }
                setCouponResponse(undefined);
                applyCoupon(value);
              }}
            />
          </Form.Item>
        </Col>

        {couponResponse?.status === true && (
          <Col span={4}>
            <Button
              className="beam-btn icon-btn ml-2 w-100"
              onClick={() => {
                couponRequestRef.current = undefined;
                setCouponResponse(undefined);
                form.setFieldsValue({ coupon: undefined });
              }}
            >
              Remove
            </Button>
          </Col>
        )}

        {couponResponse && couponResponse?.status === false && (
          <Form.Item>
            <p className="error">{couponResponse?.data?.details}</p>
          </Form.Item>
        )}

        {couponResponse && couponResponse?.status === true && (
          <Form.Item>
            <p className="ride-success" style={{ marginTop: "10px" }}>
              Coupon applied successfully! Your discounted fare is{" "}
              {couponResponse?.data?.discountedMeterFare}{" "}
              {couponResponse?.data?.currency}
            </p>
          </Form.Item>
        )}
      </Row>
      <hr />
    </React.Fragment>
  );
};

export default CouponSection;
