/*global google*/
import React, { FC, useEffect, useRef, useState } from "react";
import { Circle, DirectionsRenderer, InfoWindow, Marker, Polygon } from "react-google-maps";
import { AreaShape, boundsCenter, LatLng, routeEnds, TripPin } from "./rideMapUtils";

export interface RideMapLayersProps {
  pins: TripPin[];
  /** Blocked area for the current pickup (red). */
  blockedArea?: AreaShape;
  /** The organisation's fleet zones (grey, named). */
  zones: AreaShape[];
  stands: { key: string; position: LatLng; raw: any; title?: string }[];
  assets: { key: string; position: LatLng; raw: any; color: string; title?: string; selected: boolean }[];
  myLocation?: LatLng;
  onStand: (stand: any) => void;
  onAsset: (asset: any) => void;
}

const PIN_LABEL: Record<TripPin["role"], string> = { pickup: "P", dropoff: "D", other: "" };
const PIN_NAME: Record<TripPin["role"], string> = { pickup: "Pickup", dropoff: "Drop-off", other: "Stop" };

const pinIcon = (color: string) => ({
  url: `/images/map-plain-icon-${color}.svg`,
  scaledSize: new google.maps.Size(26, 40),
  labelOrigin: new google.maps.Point(13, 14),
});

const areaOptions = (blocked: boolean) =>
  blocked
    ? { strokeColor: "#FF0000", fillColor: "#FF0000", fillOpacity: 0.15, strokeWeight: 2 }
    : { strokeColor: "#000000", fillColor: "#000000", fillOpacity: 0.12, strokeWeight: 1 };

/**
 * The dispatch layers the old Ride map drew, rendered on the Fleet map
 * instance (inside its GoogleMap): trip pins + driving route, blocked area,
 * stands, fleet zones, assets and the dispatcher's location.
 */
const RideMapLayers: FC<RideMapLayersProps> = ({
  pins,
  blockedArea,
  zones,
  stands,
  assets,
  myLocation,
  onStand,
  onAsset,
}) => {
  const [info, setInfo] = useState<{ key: string; position: LatLng; body: React.ReactNode }>();
  const [directions, setDirections] = useState<any>();
  const routeSeq = useRef(0);

  const ends = routeEnds(pins);
  const routeKey = ends ? JSON.stringify(ends.map((p) => [p.lat, p.lng])) : "";

  // Driving route between the trip pins, as the old map's DirectionsRenderer.
  useEffect(() => {
    const seq = ++routeSeq.current;
    if (!ends) {
      setDirections(undefined);
      return;
    }
    new google.maps.DirectionsService().route(
      {
        origin: new google.maps.LatLng(ends[0].lat, ends[0].lng),
        destination: new google.maps.LatLng(ends[1].lat, ends[1].lng),
        travelMode: google.maps.TravelMode.DRIVING,
      },
      (result: any, status: any) => {
        if (seq !== routeSeq.current) return;
        if (status === google.maps.DirectionsStatus.OK) setDirections(result);
        else {
          console.error(`error fetching directions ${status}`);
          setDirections(undefined);
        }
      }
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [routeKey]);

  const area = (shape: AreaShape, key: string, blocked: boolean) => {
    const onClick = () => {
      if (!shape.name) return;
      const position = shape.kind === "circle" ? shape.center : boundsCenter(shape.paths);
      if (position) setInfo({ key, position, body: <div className="flt-info">{shape.name}</div> });
    };
    return shape.kind === "polygon" ? (
      <Polygon key={key} path={shape.paths} options={{ ...areaOptions(blocked), zIndex: 1 }} onClick={onClick} />
    ) : (
      <Circle
        key={key}
        center={shape.center}
        radius={shape.radius}
        options={{ ...areaOptions(blocked), zIndex: 1 }}
        onClick={onClick}
      />
    );
  };

  return (
    <>
      {zones.map((z, i) => area(z, `zone-${z.id ?? i}`, false))}
      {blockedArea && area(blockedArea, "blocked-area", true)}

      {directions && (
        <DirectionsRenderer
          directions={directions}
          // Our own pins mark the ends; FleetView fits the view to them.
          options={{ suppressMarkers: true, preserveViewport: true }}
        />
      )}

      {stands.map((s) => (
        <Marker
          key={s.key}
          position={s.position}
          zIndex={60}
          title={s.title ? `${s.title} — set as pickup` : "Set as pickup"}
          icon={{ url: "/images/map-plain-icon-green.svg", scaledSize: new google.maps.Size(22, 34) }}
          onClick={() => onStand(s.raw)}
        />
      ))}

      {assets.map((a) => (
        <Marker
          key={a.key}
          position={a.position}
          zIndex={60}
          title={a.title}
          label={a.title ? { text: `${a.title}` } : undefined}
          icon={{
            url: `/images/map-plain-icon-${a.selected ? "green" : a.color}.svg`,
            scaledSize: new google.maps.Size(22, 34),
          }}
          onClick={() => onAsset(a.raw)}
        />
      ))}

      {pins.map((p) => (
        <Marker
          key={p.key}
          position={p}
          zIndex={70}
          title={p.title}
          label={PIN_LABEL[p.role] ? { text: PIN_LABEL[p.role], color: "#ffffff", fontSize: "11px", fontWeight: "700" } : undefined}
          icon={pinIcon("blue")}
          onClick={() =>
            setInfo({
              key: p.key,
              position: p,
              body: (
                <div className="flt-info">
                  <strong>{PIN_NAME[p.role]}</strong>
                  {p.title && <div>{p.title}</div>}
                </div>
              ),
            })
          }
        />
      ))}

      {myLocation && (
        <Marker
          position={myLocation}
          zIndex={65}
          title="Your location"
          icon={{
            path: google.maps.SymbolPath.CIRCLE,
            scale: 7,
            fillColor: "#4682f4",
            fillOpacity: 1,
            strokeColor: "#ffffff",
            strokeWeight: 2,
          }}
        />
      )}

      {info && (
        <InfoWindow position={info.position} onCloseClick={() => setInfo(undefined)}>
          {info.body}
        </InfoWindow>
      )}
    </>
  );
};

export default RideMapLayers;
