import { SocketTopics } from "constants/enums";
import {
  getRideEstimationPublishTopic,
  getCouponByLocationPublishTopic,
  getAggregateBdsPublishTopic,
} from "hooks/MQTTConstants";
import { GET_AGGREGATE } from "reducers/reducer";
import { formatForRedis } from "utils/appUtil";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import { getPageUpdatedAt } from "../../rideSync";

// Socket publish helpers that request ride data (estimation, coupons, admin
// users) and the customer lookup used to flag blocked passengers.
export const useRideSocketActions = (d: any) => {
  const getRideEstimation = (
    pickupLocation: any,
    dropoffLocation: any,
    vehicleType?: any
  ) => {
    const connectionId = d.encrypted_token?.connectionId;
    const userId = d.encrypted_token?.userId;
    d.setEstimation(undefined);
    d.setEstimatedFare(undefined);
    d.couponRequestRef.current = undefined;
    d.setCouponResponse(undefined);
    d.form.setFieldsValue({ coupon: undefined });
    const request = wrapRequestPayload({
      pickupLocation: {
        coordinates: pickupLocation?.value?.coordinates,
        place_id: pickupLocation?.value?.place_id,
      },
      dropoffLocation: {
        coordinates: dropoffLocation?.value?.coordinates,
        place_id: dropoffLocation?.value?.place_id,
      },
      userId,
      startTime: new Date().getTime(),
      cudbServiceId: d.projects?.userServiceId,
      vehicleType,
    });
    d.estimationRequestIdRef.current = request.id;
    d.socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getRideEstimationPublishTopic(connectionId),
      request
    );
  };

  const getCouponByLocation = (location: any) => {
    const connectionId = d.encrypted_token?.connectionId;
    // Private coupons are matched on the passenger's phone/email, so send them
    // like applyCoupon does (empty values are left out).
    const phone = d.form?.getFieldValue("passengerPhoneNumber");
    const email = d.form?.getFieldValue("passengerEmail");
    d.socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getCouponByLocationPublishTopic(connectionId),
      wrapRequestPayload({
        pickupLocation: {
          coordinates: location?.value?.coordinates,
        },
        ...(phone || email
          ? {
              notificationChannels: {
                ...(email ? { email } : {}),
                ...(phone ? { phone } : {}),
              },
            }
          : {}),
        cudbServiceId: d.projects?.userServiceId,
      })
    );
  };

  const getAdminUsers = () => {
    const connectionId = d.encrypted_token?.connectionId;
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(
            d.projects?.userServiceId
          )}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          firstName: "$..profile.firstName",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@firstName)`,
      },
      anyStatus: false,
    };

    d.socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getAggregateBdsPublishTopic(connectionId),
      wrapRequestPayload(userRequest, d.filterUserRequestId.current)
    );
  };

  const getPassenger = (email: any, phone: any) => {
    const customerRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:id`,
          searchQuery: `@partitions:{'org\\:${formatForRedis(
            d.projects?.userServiceId
          )}'}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          info: "$.info",
          email: "$..email",
          phone: "$..phone",
          objectId: "$.objectId",
        },
      },
      filter: {
        expression: `(exists(@email) && @email=='${email}') || (exists(@phone) && @phone=='${phone}')`,
      },
    };
    d.dispatch(
      GET_AGGREGATE({
        requestData: customerRequest,
        callback: (response: any) => {
          const customer = response?.[0];
          if (customer) {
            if (customer?.info?.blockedAt) {
              d.setBlocked(true);
            } else {
              d.setBlocked(false);
            }
          } else {
            d.setBlocked(false);
          }
        },
      })
    );
  };

  // Re-reads the ride loaded in the panel. Always refreshes its status; with
  // resetForm it also reloads the form (and the updatedAt sent as
  // expectedUpdatedAt). With notifyIfChanged, a newer server copy raises the
  // "changed by someone else" notice instead of overwriting the dispatcher's
  // edits.
  const reloadRide = (
    pageId: any,
    opts: { resetForm?: boolean; notifyIfChanged?: boolean } = {}
  ) => {
    const serviceId = d.projects?.userServiceId;
    const userId = d.encrypted_token?.userId;
    if (!pageId || !serviceId || !userId) return;
    d.dispatch(
      GET_AGGREGATE({
        silent: true,
        requestData: {
          select: {
            index: {
              searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:pageUpdatedAtIndex`,
              searchQuery: `@pageMembers:{'${userId}'}@partitions:{'org\\:${formatForRedis(
                serviceId
              )}'}`,
              searchOptions: "VERBATIM TIMEOUT 10000",
            },
            list: {
              objectIds: [pageId.toString()],
            },
            load: {
              persistent: "$.persistent",
              nonpersistent: "$.nonpersistent",
              pageId: "$.objectId",
            },
          },
          filter: {
            expression: "",
          },
        },
        callback: (response: any) => applyLoadedRide(pageId, response?.[0], opts),
      })
    );
  };

  // Applies a fresh copy of the ride loaded in the panel: a fetched page, or
  // the `row` a ridePageUpdated event carries (same shape). Options as for
  // reloadRide.
  const applyLoadedRide = (
    pageId: any,
    page: any,
    opts: { resetForm?: boolean; notifyIfChanged?: boolean } = {}
  ) => {
    // The panel may have moved on to another ride meanwhile.
    if (
      !page ||
      !pageId ||
      d.ridePageIdRef.current?.toString() !== pageId.toString()
    )
      return;
    const status = page?.nonpersistent?.static?.live?.status?.name;
    if (status) d.setPageStatus(status);
    const updatedAt = getPageUpdatedAt(page);
    if (opts.resetForm) {
      d.setFormValuesFromPage({
        ...page,
        persistent: {
          static: {
            profile: page?.persistent?.static?.ride,
          },
        },
      });
      d.loadedUpdatedAtRef.current = updatedAt;
      d.setRideNotice(undefined);
      return;
    }
    if (
      opts.notifyIfChanged &&
      !d.webBooker &&
      updatedAt &&
      (!d.loadedUpdatedAtRef.current ||
        updatedAt > d.loadedUpdatedAtRef.current)
    ) {
      d.setRideNotice({
        pageId: pageId.toString(),
        message: `This ride was changed by someone else${status ? ` (now ${status})` : ""}.`,
      });
    }
  };

  return {
    getRideEstimation,
    getCouponByLocation,
    getAdminUsers,
    getPassenger,
    reloadRide,
    applyLoadedRide,
  };
};
