import React from "react";
import { Empty, Table } from "antd";
import { useDashboard } from "../context";

const PagesTable: React.FC = () => {
  const {
    tableDataSource,
    tableColumns,
    dispatch,
    selectedPage,
    pendingRows,
    statusFilterLoading,
    projectFilterLoading,
    timeFilterLoading,
  } = useDashboard();
  // A booked ride's placeholder hides as soon as its real row is listed.
  const tableKeys = pendingRows?.length
    ? new Set((tableDataSource || []).map((row: any) => row.key?.toString()))
    : undefined;
  const placeholders = (pendingRows || []).filter(
    (row: any) => !row.pageId || !tableKeys?.has(row.pageId)
  );
  const rows = placeholders.length
    ? [...placeholders, ...(tableDataSource || [])]
    : tableDataSource;
  // Spinner while a filter change is fetching, or on first load. Background
  // polls never set these flags.
  const loading =
    !!statusFilterLoading ||
    (!(rows?.length > 0) && !!(projectFilterLoading || timeFilterLoading));

  return (
    <Table
      dataSource={rows}
      className={`ride-table ${rows?.length > 0 ? "" : "table-empty"}`}
      size="small"
      loading={loading}
      locale={{
        emptyText: (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description="No rides match this view"
          />
        ),
      }}
      onRow={(record: any) => {
        return {
          onDoubleClick: () => {
            // Optimistic rows have no ride page to open yet.
            if (record?.action?.pendingSubmission) return;
            dispatch({
              type: "SET_SELECTED_PAGE",
              payload: { page: record?.action?.page },
            });
          },
          onClick: () => {},
        };
      }}
      columns={tableColumns}
      scroll={{ x: "max-content", y: 520 }}
      onChange={(e) => {
        console.log("event here", e);
      }}
      rowClassName={(record: any, index) => {
        if (record?.action?.pendingSubmission)
          return record.action.failed ? "pending-row failed" : "pending-row";
        if (record?.key === selectedPage?.page?.pageId)
          return `row-selected ${record.pageStatus}-row`;
        return `${record.pageStatus}-row`;
      }}
    />
  );
};

export default PagesTable;
