import React, { FC, useState } from "react";
import { Button, Form, Input, Modal, Segmented } from "antd";
import { MailOutlined, PhoneOutlined } from "@ant-design/icons";
import PhoneInput, { isValidPhoneNumber } from "react-phone-number-input";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { pushNotification } from "utils/notifications";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import { shareDispatchUrlPublishTopic } from "hooks/MQTTConstants";
import "./ShareDispatchUrlModal.scss";

type Channel = "email" | "phone";

const ShareDispatchUrlModal: FC<{ onClose: () => void; socket?: ISocket }> = ({
  onClose,
  socket,
}) => {
  const [isModalVisible, setIsModalVisible] = useState(true);
  const [form] = Form.useForm();
  const [channel, setChannel] = useState<Channel>("email");
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);

  const close = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  const onSubmitHandler = (values: any) => {
    // Only the chosen channel is sent.
    const email = channel === "email" ? values.email : undefined;
    const phone = channel === "phone" ? values.phone : undefined;
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      shareDispatchUrlPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        notificationChannels: { email, phone },
        nickname: values.nickname,
        cudbServiceId: projects?.userServiceId,
      }),
      undefined,
      undefined,
      { retryOnAckTimeout: false }
    );
    close();
    pushNotification("Link shared successfully", "success", "TOP_CENTER", 1000);
  };

  return (
    <Modal
      title={null}
      visible={isModalVisible}
      onCancel={close}
      width={440}
      className="ride-modal"
      footer={null}
      destroyOnClose
    >
      <h2 className="ride-modal__title">Share dispatch link</h2>
      <p className="ride-modal__desc">
        Send a link that lets someone book rides with your fleet.
      </p>

      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        onFinish={onSubmitHandler}
      >
        <Form.Item label="Send by">
          <Segmented
            block
            value={channel}
            onChange={(value) => setChannel(value as Channel)}
            options={[
              { value: "email", label: "Email", icon: <MailOutlined /> },
              { value: "phone", label: "Phone", icon: <PhoneOutlined /> },
            ]}
          />
        </Form.Item>

        {channel === "email" ? (
          <Form.Item
            label="Email address"
            name="email"
            rules={[
              { required: true, message: "Enter an email address" },
              { type: "email", message: "Enter a valid email address" },
            ]}
          >
            <Input type="email" placeholder="name@example.com" autoFocus />
          </Form.Item>
        ) : (
          <Form.Item
            label="Phone number"
            name="phone"
            rules={[
              { required: true, message: "Enter a phone number" },
              {
                validator: async (_, value) => {
                  if (value && !isValidPhoneNumber(value)) {
                    throw new Error("Enter a valid phone number");
                  }
                },
              },
            ]}
          >
            {/* Form.Item injects value/onChange; the prop is required by the types. */}
            <PhoneInput defaultCountry="US" placeholder="Phone number" onChange={() => undefined} />
          </Form.Item>
        )}

        <div className="ride-modal__actions">
          <Button onClick={close}>Cancel</Button>
          <Button type="primary" htmlType="submit">
            Send invite
          </Button>
        </div>
      </Form>
    </Modal>
  );
};

export default ShareDispatchUrlModal;
