import { ProgramsConfig } from "./config";

/**
 * Thin POST helpers for the two Beam services the Programs page reads:
 * the organization's CUDB (projects) and BDS (the extended-bio forms).
 *
 * No `topic` header. The admin backend sends one, but the CPC form app —
 * the other browser client of these endpoints — does not, and a custom
 * header would turn every call into a CORS preflight. Both services accept
 * the call without it.
 */

export class ProgramsApiError extends Error {
  status: number;
  body?: unknown;

  constructor(message: string, status: number, body?: unknown) {
    super(message);
    this.name = "ProgramsApiError";
    this.status = status;
    this.body = body;
  }
}

/** `{ data, status, message }` — `status: false` is a rejected query, not a transport error. */
interface BeamEnvelope<T = unknown> {
  data?: T;
  status?: boolean;
  message?: string;
}

const post = async <T>(url: string, body: unknown, signal?: AbortSignal): Promise<BeamEnvelope<T>> => {
  const response = await fetch(url, {
    method: "POST",
    headers: { accept: "*/*", "Content-Type": "application/json" },
    body: JSON.stringify(body),
    signal,
  });

  const text = await response.text();
  let parsed: unknown = null;
  if (text) {
    try {
      parsed = JSON.parse(text);
    } catch {
      parsed = text;
    }
  }

  if (!response.ok) {
    const message =
      (parsed as { message?: string })?.message ?? `Beam request failed (${response.status})`;
    throw new ProgramsApiError(message, response.status, parsed);
  }

  const envelope = (parsed ?? {}) as BeamEnvelope<T>;
  if (envelope.status === false) {
    throw new ProgramsApiError(envelope.message || "Beam rejected the query", response.status, parsed);
  }
  return envelope;
};

export const postCudb = <T>(
  config: ProgramsConfig,
  action: "searchInUser",
  body: unknown,
  signal?: AbortSignal
): Promise<BeamEnvelope<T>> => post<T>(`${config.cudbApiUrl}/${action}`, body, signal);

export const postBds = <T>(
  config: ProgramsConfig,
  action: "aggregateBds" | "searchInQuery",
  body: unknown,
  signal?: AbortSignal
): Promise<BeamEnvelope<T>> => post<T>(`${config.bdsApiUrl}/${action}`, body, signal);

/**
 * `searchInUser` wraps the matched value in one array per path/object
 * (`data[0][0]` in practice). Drill through the single-element wrappers
 * until a non-array value is reached.
 */
export const unwrapValue = (data: unknown): unknown => {
  let current = data;
  while (Array.isArray(current)) {
    if (current.length === 0) return null;
    current = current[0];
  }
  return current ?? null;
};

/**
 * RediSearch tag values must escape punctuation, so `cudb-test` is written
 * `cudb\-test` inside a searchQuery.
 */
export const escapeTag = (value: string): string =>
  value.replace(/[,.<>{}[\]"':;!@#$%^&*()\-+=~|\\ ]/g, (char) => `\\${char}`);
