import React, { FC, KeyboardEvent, ReactNode, useState } from "react";
import { Layout } from "antd";
import {
  CalendarOutlined,
  EnvironmentOutlined,
  GatewayOutlined,
  SendOutlined,
} from "@ant-design/icons";
import DispatchPanel from "./DispatchPanel/index";
import FleetPanel from "./FleetPanel/index";
import { useDispatch } from "react-redux";
import { useHistory } from "react-router-dom";
import Autocomplete from "react-google-autocomplete";
import Geocode from "react-geocode";
import DashboardModal from "./Dashboard/DashboardModal";
import GeofenceModal from "./Dashboard/GeofenceModal";
import { generateUUID } from "utils/appUtil";
import { GOOGLE_MAPS_KEY } from "./rideSync";
import "./RideShell.scss";

Geocode.setApiKey(GOOGLE_MAPS_KEY);
Geocode.setLanguage("en");
Geocode.setRegion("us");

// Right-hand tabs, in display order. Keys are the `selected` values.
const TABS: { key: string; label: string; icon: ReactNode }[] = [
  // Vehicles and their drivers are paired, so the Fleet map also lists the
  // drivers (contact, status, ride progress); there is no separate Drivers tab.
  { key: "map", label: "Fleet", icon: <EnvironmentOutlined /> },
  { key: "advance", label: "Advance booking", icon: <CalendarOutlined /> },
  { key: "dispatch", label: "Dispatching", icon: <SendOutlined /> },
  { key: "geofence", label: "Zones", icon: <GatewayOutlined /> },
];

// Titled white card around a tab's content. The legacy beam-modal / Layout
// wrappers are kept inside so the embedded modules render as before.
// `plain` skips the legacy wrappers for content built on the ride theme.
const RideCard: FC<{
  title: string;
  id?: string;
  extra?: ReactNode;
  plain?: boolean;
}> = ({ title, id, extra, plain, children }) => (
  <section className="ride-card" aria-labelledby={id ? `${id}-title` : undefined}>
    <header className="ride-card__head">
      <h2 className="ride-card__title" id={id ? `${id}-title` : undefined}>
        {title}
      </h2>
      {extra}
    </header>
    <div className="ride-card__body">
      {plain ? (
        children
      ) : (
        <div className="beam-modal analytics-summary-modal">
          <Layout className="main-layout exec-layout" style={{ padding: 0 }}>
            {children}
          </Layout>
        </div>
      )}
    </div>
  </section>
);

const RideWrapper: FC<{ socket: ISocket }> = ({ socket }) => {
  const history = useHistory();
  const dispatch = useDispatch();
  const [screens, setScreens] = useState<any>({
    form: true,
    map: true,
  });
  const [selected, setSelected] = useState<string>("map");
  const [componentUuids, setComponentUuid] = useState<any>({
    driver: generateUUID(),
    advance: generateUUID(),
    dispatch: generateUUID(),
    all: generateUUID(),
  });
  const params: any = {
    screens,
    setScreens,
  };

  // Arrow keys move between tabs (WAI-ARIA tabs pattern).
  const onTabKeyDown = (e: KeyboardEvent<HTMLButtonElement>, index: number) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft") return;
    e.preventDefault();
    const step = e.key === "ArrowRight" ? 1 : -1;
    const next = TABS[(index + step + TABS.length) % TABS.length];
    setSelected(next.key);
    const el = document.getElementById(`ride-tab-${next.key}`);
    el?.focus();
  };

  const activeTab = TABS.find((tab) => tab.key === selected);

  return (
    <div className="ride-shell">
      <header className="ride-shell__header">
        <img src="/images/logo-icon.svg" alt="Beam" />
        <h1 className="ride-shell__title">Dispatch</h1>
      </header>

      <div
        className={`ride-shell__body ${
          screens.form && !screens.map ? "is-form-only" : ""
        } ${!screens.form ? "is-content-only" : ""}`}
      >
        {screens.form && (
          <aside
            className={`ride-shell__side ${
              screens.active === "form" ? "active-screen" : ""
            }`}
            aria-label="Ride booking form"
          >
            <DispatchPanel
              socket={socket}
              params={params}
              fullScreen={true}
              scale={true}
            />
          </aside>
        )}

        {screens.map && (
          <main className="ride-shell__main">
            <div
              className={`ride-shell__tabs ${
                screens.active === "map" ? "active-screen" : ""
              }`}
            >
              <div className="ride-tabs" role="tablist" aria-label="Dispatch views">
                {TABS.map((tab, index) => {
                  const active = selected === tab.key;
                  return (
                    <button
                      key={tab.key}
                      id={`ride-tab-${tab.key}`}
                      type="button"
                      role="tab"
                      aria-selected={active}
                      aria-controls="ride-tabpanel"
                      tabIndex={active ? 0 : -1}
                      className={`ride-tabs__tab ${active ? "is-active" : ""}`}
                      onClick={() => {
                        setSelected(tab.key);
                      }}
                      onKeyDown={(e) => onTabKeyDown(e, index)}
                    >
                      <span className="ride-tabs__icon" aria-hidden="true">
                        {tab.icon}
                      </span>
                      {tab.label}
                    </button>
                  );
                })}
              </div>
            </div>

            <div className="ride-shell__content">
              <div
                id="ride-tabpanel"
                role="tabpanel"
                aria-labelledby={activeTab ? `ride-tab-${activeTab.key}` : undefined}
                className="ride-tabpanel"
              >
                {selected === "map" && (
                  <div className="ride-map-frame">
                    <FleetPanel socket={socket} params={params} />
                  </div>
                )}
                {selected === "geofence" && (
                  <RideCard title="Zones & stands" id="ride-zones" plain>
                    <GeofenceModal
                      socket={socket}
                      componentUuid={componentUuids.driver}
                    />
                  </RideCard>
                )}


                {selected === "dispatch" && (
                  <RideCard title="Dispatching" id="ride-dispatching">
                    <DashboardModal
                      socket={socket}
                      filter={false}
                      selected={selected}
                      componentUuid={componentUuids.advance}
                    />
                  </RideCard>
                )}
                {selected === "advance" && (
                  <RideCard title="Advance bookings" id="ride-advance">
                    <DashboardModal
                      socket={socket}
                      filter={false}
                      selected={selected}
                      componentUuid={componentUuids.advance}
                    />
                  </RideCard>
                )}
              </div>

              <RideCard title="All rides" id="ride-all">
                <DashboardModal
                  socket={socket}
                  filter={true}
                  componentUuid={componentUuids.all}
                />
              </RideCard>
            </div>
          </main>
        )}
      </div>

      <Autocomplete
        apiKey={GOOGLE_MAPS_KEY}
        style={{ display: "none" }}
        options={{
          types: ["(regions)"],
          componentRestrictions: { country: ["us", "ca", "uk"] },
        }}
      />
    </div>
  );
};

export default RideWrapper;
