import React from "react";
import type { ColumnsType } from "antd/es/table";
import moment from "moment";
import { Pill, PillTone } from "../../Medical/common/ui";
import { CouponLifecycle, formatMoney } from "../couponRules";
import { CouponProduct, RedemptionRecord } from "../types";

export const PRODUCT_LABEL: Record<CouponProduct, string> = { retail: "Retail", ride: "Ride" };
export const NO_LOCATION = "No location";

/** Where a redemption happened: the ride's pickup location, else none. */
export const locationLabel = (r: RedemptionRecord) => r.info.locationName || NO_LOCATION;

export const LIFECYCLE_PILL: Record<CouponLifecycle, { label: string; tone: PillTone }> = {
  active: { label: "Active", tone: "green" },
  scheduled: { label: "Scheduled", tone: "blue" },
  paused: { label: "Paused", tone: "amber" },
  expired: { label: "Expired", tone: "gray" },
  exhausted: { label: "Limit reached", tone: "purple" },
  archived: { label: "Archived", tone: "gray" },
};

export const REDEMPTION_COLUMNS: ColumnsType<RedemptionRecord> = [
  {
    title: "When",
    key: "when",
    render: (_, r) => moment(r.info.redeemedAt).format("MMM D, h:mm A"),
  },
  {
    title: "Coupon",
    key: "coupon",
    render: (_, r) => (
      <div>
        <strong>{r.info.couponTitle || "Coupon"}</strong>
        <div className="cpn-muted">
          {[PRODUCT_LABEL[r.info.product || "retail"], r.info.recipientName || r.info.passengerPhone]
            .filter(Boolean)
            .join(" · ")}
        </div>
      </div>
    ),
  },
  {
    title: "Store / location",
    key: "vendor",
    render: (_, r) =>
      r.info.product === "ride" ? (
        <div>
          {locationLabel(r)}
          {r.info.pageId && <div className="cpn-muted">Ride {r.info.pageId}</div>}
        </div>
      ) : (
        r.info.vendorName
      ),
  },
  {
    title: "Bill / fare",
    key: "bill",
    align: "right",
    render: (_, r) => formatMoney(r.info.billAmount ?? null, r.info.currency),
  },
  {
    title: "Discount",
    key: "discount",
    align: "right",
    render: (_, r) => formatMoney(r.info.discountApplied ?? null, r.info.currency),
  },
  {
    title: "Result",
    key: "status",
    render: (_, r) =>
      r.info.status === "accepted" ? (
        <Pill tone="green">Accepted</Pill>
      ) : r.info.status === "cancelled" ? (
        <Pill tone="gray" title="The ride was cancelled; the coupon was given back">
          Ride cancelled
        </Pill>
      ) : (
        <Pill tone="red" title={r.info.rejectReason}>
          Declined
        </Pill>
      ),
  },
  { title: "Reference", key: "ref", render: (_, r) => <span className="cpn-mono">{r.info.reference}</span> },
];

