import React from "react";
import { STATUS_OPTIONS, statusColorMapping } from "../constants";
import "./filters/filters.scss";

interface Props {
  counts: Record<string, number>;
  selected?: string;
  onSelect: (color?: string) => void;
}

const TILES = [{ label: "All", color: undefined as string, countKey: "live" }].concat(
  STATUS_OPTIONS.map(({ label, color }) => ({ label, color, countKey: color }))
);

/** Ride counts per status; clicking a tile filters the table to it. */
const StatusSummary = ({ counts, selected, onSelect }: Props) => (
  <div className="mx-status-tiles" role="tablist" aria-label="Filter by status">
    {TILES.map(({ label, color, countKey }) => {
      const active = selected === color;
      const accent = color ? statusColorMapping[color] : "#0c2340";
      const count = counts[countKey] ?? 0;
      return (
        <button
          key={label}
          type="button"
          role="tab"
          aria-selected={active}
          className={`mx-status-tile ${active ? "mx-status-tile--active" : ""} ${
            count === 0 ? "mx-status-tile--empty" : ""
          }`}
          style={{ "--accent": accent } as React.CSSProperties}
          onClick={() => onSelect(active && color ? undefined : color)}
        >
          <span className="mx-status-tile__label">
            {color && <i className="mx-status-tile__dot" />}
            {label}
          </span>
          <span className="mx-status-tile__count">{count}</span>
        </button>
      );
    })}
  </div>
);

export default StatusSummary;
