/** A day range for a date filter; both bounds inclusive, `YYYY-MM-DD`. */
export interface DateRange {
  from?: string;
  to?: string;
}

/**
 * The filter bar's state, held by the page so a selection carries over between
 * sections. Both maps are keyed by extended-bio element id, because the
 * controls are generated from the event form's widgets (data.blocks[].elements[]),
 * not hard-coded: `answers` holds the choice filters (a picked label per
 * element), `dates` holds the date filters (a day range per element).
 */
export interface Filters {
  answers: Record<string, string>;
  dates: Record<string, DateRange>;
}

export const EMPTY_FILTERS: Filters = { answers: {}, dates: {} };
