import React, { FC, useMemo, useState } from "react";
import { useHistory, useLocation } from "react-router-dom";
import { Button, Drawer, Empty, Input, Segmented, Select, Tooltip } from "antd";
import {
  AppstoreOutlined,
  ArrowRightOutlined,
  BarsOutlined,
  CalendarOutlined,
  ClockCircleOutlined,
  DownloadOutlined,
  EnvironmentOutlined,
  ExportOutlined,
  HeartFilled,
  HeartOutlined,
  LinkOutlined,
  SearchOutlined,
} from "@ant-design/icons";
import moment from "moment";

import { ProgramEvent, SectionDef } from "./data";
import { EMPTY_FILTERS, Filters } from "./types";
import FilterBar, { PROFILE_LABEL } from "./FilterBar";
import { answerMatches, eventInDateRange, FilterDef } from "./api/mapEvents";
import {
  copyEventLink,
  downloadIcs,
  EventFacts,
  eventPath,
  formatDates,
  priceLabel,
  useSaved,
} from "./eventUtils";

type SortKey = "soonest" | "price-asc" | "price-desc";
type View = "grid" | "list";

interface Props {
  section: SectionDef;
  /** Every event of the organization; this section picks its own. */
  events: ProgramEvent[];
  filterDefs: FilterDef[];
  filters: Filters;
  onFiltersChange: (filters: Filters) => void;
}

/** Unpriced events sort after priced ones in both directions. */
const byPrice = (a: ProgramEvent, b: ProgramEvent, dir: 1 | -1) => {
  if (a.price === undefined && b.price === undefined) return 0;
  if (a.price === undefined) return 1;
  if (b.price === undefined) return -1;
  return (a.price - b.price) * dir;
};

const EventsSection: FC<Props> = ({ section, events: allEvents, filterDefs, filters, onFiltersChange }) => {
  const history = useHistory();
  const location = useLocation();
  const { saved, toggle } = useSaved();

  const [search, setSearch] = useState("");
  const [sort, setSort] = useState<SortKey>("soonest");
  const [view, setView] = useState<View>("grid");
  const [savedOnly, setSavedOnly] = useState(false);

  // ?event=<id> opens the drawer, so an event can be shared as a link.
  const openId = new URLSearchParams(location.search).get("event");
  const openEvent = allEvents.find((e) => e.id === openId && e.section === section.id);
  const setOpen = (id?: string) =>
    history.replace({ pathname: location.pathname, search: id ? `?event=${id}` : "" });

  // Every event of the section, regardless of date. A past date no longer
  // hides a matched event from the list.
  const sectionEvents = useMemo(
    () => allEvents.filter((e) => e.section === section.id),
    [allEvents, section.id]
  );

  const events = useMemo(() => {
    const q = search.trim().toLowerCase();
    const activeAnswers = Object.entries(filters.answers).filter(([, value]) => Boolean(value));
    const activeDates = Object.entries(filters.dates).filter(
      ([, range]) => range && (range.from || range.to)
    );

    const list = sectionEvents.filter((e) => {
      // Filters are whatever the form currently defines; a selection left over
      // from a filter the form no longer has is ignored, so removing a filter
      // from the form never traps the list in an unmatchable state.
      for (const [elementId, value] of activeAnswers) {
        const def = filterDefs.find((d) => d.id === elementId);
        if (!def) continue;
        if (def.surveyId !== e.surveyId) return false;
        if (!answerMatches(e.answers[elementId], value)) return false;
      }
      // Date filters read the event's own start/end, not a stored answer.
      for (const [elementId, range] of activeDates) {
        const def = filterDefs.find((d) => d.id === elementId);
        if (!def || def.kind !== "date") continue;
        if (def.surveyId !== e.surveyId) return false;
        if (!eventInDateRange(e, range)) return false;
      }
      if (savedOnly && !saved.includes(e.id)) return false;
      if (q && !`${e.title} ${e.location ?? ""} ${e.coach ?? ""}`.toLowerCase().includes(q)) {
        return false;
      }
      return true;
    });

    const by: Record<SortKey, (a: ProgramEvent, b: ProgramEvent) => number> = {
      soonest: (a, b) => a.start.localeCompare(b.start),
      "price-asc": (a, b) => byPrice(a, b, 1),
      "price-desc": (a, b) => byPrice(a, b, -1),
    };
    return [...list].sort(by[sort]);
  }, [sectionEvents, filters, filterDefs, savedOnly, saved, search, sort]);

  const clearLocal = () => {
    setSearch("");
    setSavedOnly(false);
  };

  /** The event's Beam Vite site when it has one, otherwise its page here. */
  const openEventPage = (event: ProgramEvent) => {
    if (event.url) {
      window.open(event.url, "_blank", "noopener,noreferrer");
    } else {
      history.push(eventPath(event));
    }
  };

  const savedInSection = sectionEvents.filter((e) => saved.includes(e.id)).length;

  const toolbar = (
    <>
      <Input
        allowClear
        size="large"
        className="programs-toolbar__search"
        prefix={<SearchOutlined />}
        placeholder={`Search ${section.label.toLowerCase()}, venues or coaches`}
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      <div className="programs-toolbar__right">
        <Tooltip title={savedOnly ? "Show all" : "Show saved only"}>
          <button
            type="button"
            className={`programs-saved-toggle${savedOnly ? " is-on" : ""}`}
            aria-pressed={savedOnly}
            onClick={() => setSavedOnly((v) => !v)}
          >
            {savedOnly ? <HeartFilled /> : <HeartOutlined />}
            <span>Saved</span>
            {savedInSection > 0 && <span className="programs-saved-toggle__count">{savedInSection}</span>}
          </button>
        </Tooltip>
        <Select<SortKey>
          size="large"
          value={sort}
          onChange={setSort}
          className="programs-toolbar__sort"
          options={[
            { value: "soonest", label: "Soonest first" },
            { value: "price-asc", label: "Price: low to high" },
            { value: "price-desc", label: "Price: high to low" },
          ]}
        />
        <Segmented
          size="large"
          value={view}
          onChange={(v) => setView(v as View)}
          options={[
            { value: "grid", icon: <AppstoreOutlined />, label: "" },
            { value: "list", icon: <BarsOutlined />, label: "" },
          ]}
          className="programs-toolbar__view"
        />
      </div>
    </>
  );

  return (
    <div className="programs-explorer programs-rise">
      <FilterBar
        filters={filters}
        onChange={onFiltersChange}
        filterDefs={filterDefs}
        toolbar={toolbar}
        onClear={clearLocal}
      />

      <div className="programs-results-head">
        <span>
          <strong>{events.length}</strong> {events.length === 1 ? "result" : "results"}
        </span>
      </div>

      {events.length === 0 ? (
        <div className="programs-card programs-empty">
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={
              savedOnly
                ? "You haven't saved any of these yet"
                : sectionEvents.length === 0
                ? `No ${section.label.toLowerCase()} are published yet`
                : `No ${section.label.toLowerCase()} match these filters`
            }
          >
            {sectionEvents.length > 0 && (
              <Button
                onClick={() => {
                  onFiltersChange(EMPTY_FILTERS);
                  clearLocal();
                }}
              >
                Clear filters
              </Button>
            )}
          </Empty>
        </div>
      ) : (
        <div className={`programs-events programs-events--${view}`}>
          {events.map((event, i) => (
            <EventCard
              key={event.id}
              event={event}
              index={i}
              saved={saved.includes(event.id)}
              onToggleSave={() => toggle(event.id)}
              onOpen={() => setOpen(event.id)}
            />
          ))}
        </div>
      )}

      <EventDrawer
        event={openEvent}
        saved={openEvent ? saved.includes(openEvent.id) : false}
        onClose={() => setOpen()}
        onToggleSave={() => openEvent && toggle(openEvent.id)}
        onOpenEvent={() => openEvent && openEventPage(openEvent)}
        onCopyLink={() => openEvent && copyEventLink(openEvent)}
      />
    </div>
  );
};

/** Level, then whatever age groups the event's answers carry. */
const EventTags: FC<{ event: ProgramEvent; light?: boolean }> = ({ event, light }) => {
  const extra = light ? " programs-tag--light" : "";
  return (
    <div className="programs-event__tags">
      <span className={light ? `programs-tag${extra}` : `programs-tag programs-tag--${event.level}`}>
        {PROFILE_LABEL[event.level]}
      </span>
      {event.ageGroups.length > 0 && (
        <span className={`programs-tag${extra}`}>{event.ageGroups.join(" · ")}</span>
      )}
    </div>
  );
};

const EventCard: FC<{
  event: ProgramEvent;
  index: number;
  saved: boolean;
  onToggleSave: () => void;
  onOpen: () => void;
}> = ({ event, index, saved, onToggleSave, onOpen }) => {
  const start = moment(event.start);
  const price = priceLabel(event.price);
  return (
    <article
      className={`programs-event programs-event--${event.level}`}
      style={{ animationDelay: `${Math.min(index, 8) * 50}ms` }}
    >
      <button type="button" className="programs-event__hit" onClick={onOpen} aria-label={`View ${event.title}`} />
      <div className="programs-event__top">
        <div className="programs-event__date">
          <span className="programs-event__month">{start.format("MMM")}</span>
          <span className="programs-event__day">{start.format("D")}</span>
          <span className="programs-event__weekday">{start.format("ddd")}</span>
        </div>
        <EventTags event={event} />
        <Tooltip title={saved ? "Remove from saved" : "Save"}>
          <button
            type="button"
            className={`programs-heart${saved ? " is-saved" : ""}`}
            aria-pressed={saved}
            aria-label={saved ? "Remove from saved" : "Save"}
            onClick={onToggleSave}
          >
            {saved ? <HeartFilled /> : <HeartOutlined />}
          </button>
        </Tooltip>
      </div>

      <div className="programs-event__body">
        <h3>{event.title}</h3>
        <ul className="programs-event__meta">
          <li>
            <CalendarOutlined /> {formatDates(event)}
          </li>
          {event.time && (
            <li>
              <ClockCircleOutlined /> {event.time}
            </li>
          )}
          {event.location && (
            <li>
              <EnvironmentOutlined /> {event.location}
            </li>
          )}
        </ul>
      </div>

      <div className="programs-event__foot">
        <div className="programs-event__price-row">
          <span className="programs-event__price">{price ?? ""}</span>
          <span className="programs-event__cta">
            Details <ArrowRightOutlined />
          </span>
        </div>
      </div>
    </article>
  );
};

const EventDrawer: FC<{
  event?: ProgramEvent;
  saved: boolean;
  onClose: () => void;
  onToggleSave: () => void;
  onOpenEvent: () => void;
  onCopyLink: () => void;
}> = ({ event, saved, onClose, onToggleSave, onOpenEvent, onCopyLink }) => (
  <Drawer
    open={Boolean(event)}
    onClose={onClose}
    width={Math.min(480, window.innerWidth)}
    className="programs-drawer"
    title={null}
    closable
    destroyOnClose
  >
    {event && (
      <>
        <div className={`programs-drawer__banner programs-drawer__banner--${event.level}`}>
          <EventTags event={event} light />
          <h2>{event.title}</h2>
          {priceLabel(event.price) && (
            <span className="programs-drawer__price">{priceLabel(event.price)}</span>
          )}
        </div>

        <div className="programs-drawer__body">
          {event.description && <p className="programs-drawer__desc">{event.description}</p>}
          <EventFacts event={event} className="programs-drawer__facts" />
        </div>

        <div className="programs-drawer__actions">
          <Button type="primary" size="large" block className="programs-btn" onClick={onOpenEvent}>
            Open event {event.url ? <ExportOutlined /> : <ArrowRightOutlined />}
          </Button>
          <div className="programs-drawer__secondary">
            <Button icon={saved ? <HeartFilled /> : <HeartOutlined />} onClick={onToggleSave}>
              {saved ? "Saved" : "Save"}
            </Button>
            <Button icon={<DownloadOutlined />} onClick={() => downloadIcs(event)}>
              Add to calendar
            </Button>
            <Button icon={<LinkOutlined />} onClick={onCopyLink}>
              Copy link
            </Button>
          </div>
        </div>
      </>
    )}
  </Drawer>
);

export default EventsSection;
