import React, { FC, useState } from "react";
import { Alert, Button, Modal, Tag } from "antd";

import { MemberRequest, PaymentRequestDraft, ProjectMember } from "../types";
import { computeAmountDue, money, validatePaymentConfig } from "../paymentConfig";
import PaymentConfigForm from "../PaymentConfigForm";
import AppliedStrip from "./AppliedStrip";
import { amountOf, seedMemberRequest } from "./draft";

interface Props {
  member: ProjectMember;
  draft: PaymentRequestDraft;
  onApply: (request: MemberRequest) => void;
  onClose: () => void;
}

/**
 * One member's own copy of the request: the complete configuration plus
 * the adjustments applied to them. Seeded from their existing override
 * or the group request; nothing is written until Apply.
 */
const MemberCustomiseModal: FC<Props> = ({ member, draft, onApply, onClose }) => {
  const [request, setRequest] = useState<MemberRequest>(() => seedMemberRequest(draft, member.id));
  const [errors, setErrors] = useState<string[]>([]);

  const groupAmount = amountOf({ config: draft.config, applied: draft.applied, note: "" });
  const breakdown = computeAmountDue(request.config, request.applied);
  const { currency } = request.config;

  const apply = () => {
    const problems = validatePaymentConfig(request.config);
    setErrors(problems);
    if (problems.length > 0) return;
    /* Store the award actually applied (capped by the rule), so the chips and the review agree. */
    const awardLine = breakdown.lines.find((line) => line.key === "scholarship");
    onApply({
      ...request,
      applied: { ...request.applied, scholarshipAward: awardLine ? Math.abs(awardLine.amount) : null },
    });
  };

  return (
    <Modal
      visible
      width={960}
      onCancel={onClose}
      className="beam-modal cfo-action-modal cfo-config-modal"
      bodyStyle={{ maxHeight: "70vh", overflow: "auto" }}
      title={
        <div className="cfo-action-modal__title">
          <span>Customise request</span>
          <Tag color="purple">{member.name}</Tag>
          <span className="cfo-action-modal__scope">
            {member.role}
            {member.household ? ` · household ${member.household}` : ""}
          </span>
        </div>
      }
      footer={[
        <div key="amount" className="cfo-customise-footer__amount">
          <span>Amount due</span>
          <strong className={breakdown.total !== groupAmount ? "cfo-amount--in" : undefined}>
            {money(breakdown.total, currency)}
          </strong>
          <span className="cfo-muted">group {money(groupAmount, currency)}</span>
        </div>,
        <Button key="cancel" className="beam-btn orange-btn bordered" onClick={onClose}>
          Cancel
        </Button>,
        <Button key="apply" className="beam-btn green-btn cover" onClick={apply}>
          Apply to {member.name.split(" ")[0]}
        </Button>,
      ]}
    >
      {errors.length > 0 && (
        <Alert
          className="cfo-modal-alert cfo-modal-alert--top"
          type="error"
          showIcon
          message="Please fix the highlighted sections"
          description={
            <ul className="cfo-error-list">
              {errors.map((message) => (
                <li key={message}>{message}</li>
              ))}
            </ul>
          }
        />
      )}

      <AppliedStrip
        scope="member"
        config={request.config}
        value={request.applied}
        note={request.note}
        onNoteChange={(note) => setRequest((current) => ({ ...current, note }))}
        onChange={(applied) => setRequest((current) => ({ ...current, applied }))}
      />

      <div className="cfo-breakdown">
        {breakdown.lines.map((line) => (
          <span key={line.key} className="cfo-breakdown__line">
            {line.label}
            <strong className={line.amount < 0 ? "cfo-amount--in" : undefined}>
              {line.amount < 0 ? "-" : ""}
              {money(Math.abs(line.amount), currency)}
            </strong>
          </span>
        ))}
      </div>

      <PaymentConfigForm
        value={request.config}
        errors={errors}
        onChange={(config) => setRequest((current) => ({ ...current, config }))}
      />
    </Modal>
  );
};

export default MemberCustomiseModal;
