import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Empty, Input, Segmented, Spin, Tooltip } from "antd";
import { RedoOutlined, SearchOutlined } from "@ant-design/icons";
import moment from "moment";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import {
  getRespondersRequestPublishTopic,
  getRespondersSubscriptionTopic,
} from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import useSocketActions from "../../../../hooks/socketActions";
import { Pill } from "../../Medical/common/ui";
import { statusMeta, toVehicle, TRIP_META } from "../../Fleet/fleetUtils";
import {
  AreaType,
  availableCount,
  buildAreas,
  queueFor,
  ZoneArea,
} from "./Zones/zoneQueue";
import "./Zones/Zones.scss";

const REFRESH_MS = 10000;
const SEARCH_SIZE_M = 300000;

/**
 * Zones & stands board: drivers inside each fleet zone, and each stand's
 * first-in-first-out queue (the order dispatch offers rides, see zoneQueue).
 */
const GeofenceModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket }) => {
  const { projects, encrypted_token, responders, vehicles } = useSelector(
    (state: RootState) => state.auth
  );
  const { getUserRequestPayload } = useSocketActions();

  const [fleetZones, setFleetZones] = useState<any>();
  const [loading, setLoading] = useState(false);
  const [locationError, setLocationError] = useState(false);
  const [updatedAt, setUpdatedAt] = useState<number>();
  const [, tick] = useState(0);
  const [view, setView] = useState<AreaType>("stand");
  const [search, setSearch] = useState("");
  const [selectedId, setSelectedId] = useState<string>();
  const centerRef = useRef<{ lat: number; long: number }>();
  const timerRef = useRef<any>();

  /* ------------------------------------------------------------- data */

  const getResponders = () => {
    if (!centerRef.current) return;
    setLoading(true);
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getRespondersRequestPublishTopic(encrypted_token?.connectionId),
      wrapRequestPayload({
        userId: encrypted_token?.userId,
        cudbServiceId: projects?.userServiceId,
        latLng: centerRef.current,
        height: SEARCH_SIZE_M,
        width: SEARCH_SIZE_M,
      })
    );
  };

  const getFleetZones = () => {
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(
        projects?.adminUserId,
        "$",
        "$..persistent.static.admin.fleetZones.items"
      ),
      ExtendedBioTopics.GetUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.GetUserBio,
      (resp) => {
        setFleetZones(resp?.data?.[0]?.[0]);
        getResponders();
      }
    );
  };

  const start = (center: { lat: number; long: number }) => {
    centerRef.current = center;
    getFleetZones();
    clearInterval(timerRef.current);
    timerRef.current = setInterval(() => {
      if (!document.hidden) getResponders();
    }, REFRESH_MS);
  };

  useEffect(() => {
    if (!encrypted_token || !projects?.userServiceId) return;
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getRespondersSubscriptionTopic(encrypted_token?.connectionId)
    );
    const fallback = encrypted_token?.location?.coordinates;
    const useFallback = () => {
      if (fallback?.lat !== undefined) {
        start({ lat: fallback.lat, long: fallback.long ?? fallback.lng });
      } else {
        setLocationError(true);
      }
    };
    if (!navigator.geolocation) {
      useFallback();
    } else {
      navigator.geolocation.getCurrentPosition(
        (position) =>
          start({ lat: position.coords.latitude, long: position.coords.longitude }),
        useFallback,
        { timeout: 8000 }
      );
    }
    return () => clearInterval(timerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [encrypted_token, projects?.userServiceId]);

  useEffect(() => {
    if (!responders) return;
    setLoading(false);
    setUpdatedAt(Date.now());
  }, [responders]);

  // Keeps "Updated 12s ago" and the waiting times current.
  useEffect(() => {
    const id = setInterval(() => tick((n) => n + 1), 15000);
    return () => clearInterval(id);
  }, []);

  /* ------------------------------------------------------------- view */

  const areas = useMemo(
    () => buildAreas(fleetZones, responders || []),
    [fleetZones, responders]
  );
  const counts = useMemo(
    () => ({
      stand: areas.filter((a) => a.type === "stand").length,
      zone: areas.filter((a) => a.type === "zone").length,
    }),
    [areas]
  );
  const listed = useMemo(() => {
    const q = search.trim().toLowerCase();
    return areas
      .filter((a) => a.type === view && (!q || a.name.toLowerCase().includes(q)))
      .sort(
        (a, b) =>
          availableCount(b) - availableCount(a) || a.name.localeCompare(b.name)
      );
  }, [areas, view, search]);

  // Keep a valid selection: the first area of the list when none is chosen.
  const selected: ZoneArea | undefined =
    listed.find((a) => a.id === selectedId) ?? listed[0];

  const ofView = areas.filter((a) => a.type === view);
  const totals = {
    areas: ofView.length,
    available: ofView.reduce((n, a) => n + availableCount(a), 0),
    busy: ofView.reduce((n, a) => n + a.users.length - availableCount(a), 0),
    empty: ofView.filter((a) => availableCount(a) === 0).length,
  };

  // The signed-in user's own place, when they are a driver waiting at a stand.
  const myPlace = useMemo(() => {
    const me = `${encrypted_token?.userId ?? ""}`;
    if (!me) return undefined;
    for (const area of areas) {
      if (area.type !== "stand") continue;
      const entry = queueFor(area).find((e) => `${e.user?.id}` === me);
      if (entry?.position) return { area, position: entry.position };
    }
    return undefined;
  }, [areas, encrypted_token?.userId]);

  const isStand = view === "stand";
  const ready = !!fleetZones;

  return (
    <div className="ride-zones">
      <div className="ride-zones__toolbar">
        <Segmented
          value={view}
          onChange={(value) => {
            setView(value as AreaType);
            setSelectedId(undefined);
          }}
          options={[
            { value: "stand", label: `Stands (${counts.stand})` },
            { value: "zone", label: `Zones (${counts.zone})` },
          ]}
        />
        <Input
          allowClear
          className="ride-zones__search"
          prefix={<SearchOutlined />}
          placeholder={isStand ? "Search stands" : "Search zones"}
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
        <div className="ride-zones__status">
          {locationError
            ? "Location unavailable"
            : updatedAt
            ? `Updated ${moment(updatedAt).fromNow()}`
            : "Loading…"}
        </div>
        <Button
          className="ride-refresh-btn"
          icon={<RedoOutlined spin={loading} />}
          disabled={loading || !centerRef.current}
          onClick={getResponders}
        >
          {loading ? "Refreshing…" : "Refresh"}
        </Button>
      </div>

      {myPlace && (
        <div className="ride-zones__mine" role="status">
          You are <strong>#{myPlace.position}</strong> in the queue at{" "}
          <strong>{myPlace.area.name}</strong>
        </div>
      )}

      <dl className="ride-zones__kpis">
        <div>
          <dt>{isStand ? "Stands" : "Zones"}</dt>
          <dd>{totals.areas}</dd>
        </div>
        <div>
          <dt>{isStand ? "Drivers queued" : "Available drivers"}</dt>
          <dd>{totals.available}</dd>
        </div>
        <div>
          <dt>Busy inside</dt>
          <dd>{totals.busy}</dd>
        </div>
        <div>
          <dt>{isStand ? "Empty stands" : "Empty zones"}</dt>
          <dd className={totals.empty ? "is-warn" : ""}>{totals.empty}</dd>
        </div>
      </dl>

      {!ready ? (
        <div className="ride-zones__state">
          {locationError ? (
            <Empty
              image={Empty.PRESENTED_IMAGE_SIMPLE}
              description="Allow location access to load nearby drivers"
            />
          ) : (
            <Spin />
          )}
        </div>
      ) : ofView.length === 0 ? (
        <div className="ride-zones__state">
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={isStand ? "No stands configured" : "No zones configured"}
          />
        </div>
      ) : (
        <div className="ride-zones__body">
          <ul className="ride-zones__list" aria-label={isStand ? "Stands" : "Zones"}>
            {listed.length === 0 && (
              <li className="ride-zones__none">No matches</li>
            )}
            {listed.map((area) => {
              const available = availableCount(area);
              const busy = area.users.length - available;
              const active = area.id === selected?.id;
              return (
                <li key={area.id}>
                  <button
                    type="button"
                    className={`ride-zones__area ${active ? "is-active" : ""}`}
                    aria-pressed={active}
                    onClick={() => setSelectedId(area.id)}
                  >
                    <span className="ride-zones__area-name">{area.name}</span>
                    <span className="ride-zones__area-meta">
                      {isStand ? `${available} in queue` : `${available} available`}
                      {busy > 0 && ` · ${busy} busy`}
                    </span>
                    <span
                      className={`ride-zones__badge ${available ? "" : "is-empty"}`}
                      aria-hidden
                    >
                      {available}
                    </span>
                  </button>
                </li>
              );
            })}
          </ul>

          <section className="ride-zones__detail" aria-live="polite">
            {selected && (
              <AreaDetail area={selected} vehicles={vehicles} />
            )}
          </section>
        </div>
      )}
    </div>
  );
};

const AreaDetail: FC<{ area: ZoneArea; vehicles: any[] }> = ({ area, vehicles }) => {
  const isStand = area.type === "stand";
  const entries = queueFor(area);
  const queued = entries.filter((e) => e.position).length;

  return (
    <>
      <header className="ride-zones__detail-head">
        <div>
          <h4>{area.name}</h4>
          <span className="ride-zones__muted">
            {isStand
              ? `${queued} in queue · first in, first out`
              : `${area.users.length} driver${area.users.length === 1 ? "" : "s"} inside`}
          </span>
        </div>
      </header>

      {entries.length === 0 ? (
        <Empty
          className="my-4"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description={isStand ? "No drivers waiting" : "No drivers in this zone"}
        />
      ) : (
        <table className="ride-zones__table">
          <thead>
            <tr>
              {isStand && <th className="is-num">#</th>}
              <th>Driver</th>
              <th>Vehicle</th>
              <th>Status</th>
              <th>{isStand ? "Waiting" : "Inside since"}</th>
              <th>Phone</th>
            </tr>
          </thead>
          <tbody>
            {entries.map(({ user, position, enteredAt }) => {
              const v = toVehicle(user, vehicles);
              const meta = statusMeta(v.status);
              const vehicleName = v.subtitle ? v.name : undefined;
              const driverName = v.driver?.name || user?.beamIds?.[0] || v.name;
              return (
                <tr key={user.id} className={position ? "" : "is-unqueued"}>
                  {isStand && (
                    <td className="is-num">
                      {position ? <span className="ride-zones__pos">{position}</span> : "—"}
                    </td>
                  )}
                  <td>
                    <div className="ride-zones__driver">{driverName}</div>
                    {user?.beamIds?.[0] && user.beamIds[0] !== driverName && (
                      <div className="ride-zones__muted">{user.beamIds[0]}</div>
                    )}
                  </td>
                  <td>{vehicleName || "—"}</td>
                  <td>
                    <span className="ride-zones__pills">
                      <Pill tone={meta.tone}>{meta.label}</Pill>
                      {v.trip && <Pill tone={TRIP_META[v.trip].tone}>{TRIP_META[v.trip].label}</Pill>}
                    </span>
                  </td>
                  <td>
                    {enteredAt ? (
                      <Tooltip title={moment(enteredAt).format("MMM D, h:mm A")}>
                        <span>{moment(enteredAt).fromNow(true)}</span>
                      </Tooltip>
                    ) : (
                      <span className="ride-zones__muted">—</span>
                    )}
                  </td>
                  <td>
                    {v.driver?.phone ? (
                      <a href={`tel:${v.driver.phone}`}>{v.driver.phone}</a>
                    ) : (
                      "—"
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </>
  );
};

export default GeofenceModal;
