import { useEffect, useRef } from "react";
import moment from "moment";
import { SocketTopics } from "constants/enums";
import {
  getUsersSubscriptionTopic,
  getAggregateBdsSubscriptionTopic,
} from "hooks/MQTTConstants";
import {
  getPageUpdatedAt,
  isSocketDebug,
  subscribeRidePageUpdated,
} from "../../../rideSync";
import { useRideOffersConnection } from "../../../rideOffers";
import { manualUserIds, rowPickupTime } from "./useDashboardQueries";

// The poll is a safety net behind the live events.
const POLL_INTERVAL_MS = 45000;
// Client-side mirror of the searchPage query predicates (time window, phone,
// project, user, area), so a real-time update can't insert a row the poll
// would exclude — those rows flickered in on each event and out on each poll.
const matchesActiveFilters = (d: any, pageUpdated: any, profile: any) => {
  // The advance/dispatch variants filter by ride status only (handled by the
  // selectedColor check in applyPageUpdate).
  if (d.selected === "advance" || d.selected === "dispatch") return true;

  const filters = d.activeFiltersRef.current;

  if (filters.phone) {
    // Phone search replaces the time window in searchPage, so match on the
    // number alone.
    const rowPhone = String(profile?.passengerPhoneNumber || "").replace(
      /\D/g,
      ""
    );
    return rowPhone !== "" && rowPhone === String(filters.phone).replace(/\D/g, "");
  }

  const createdAt = Number(pageUpdated?.persistent?.static?.metadata?.createdAt);
  if (d.startDate.current) {
    // Effective bounds computed by setTimePagePaths (end open when unset).
    if (!(createdAt >= d.startDate.current)) return false;
    if (d.endDate.current && !(createdAt <= d.endDate.current)) return false;
  } else {
    // Default view is "today" (same window searchPage applies).
    if (!(createdAt >= moment().startOf("day").valueOf())) return false;
  }

  if (
    filters.project &&
    pageUpdated?.persistent?.static?.iotAsset?.config?.iotAssetConfigId !==
      filters.project
  )
    return false;

  if (
    filters.user &&
    !pageUpdated?.persistent?.static?.metadata?.members?.users?.[filters.user]
  )
    return false;

  if (filters.area && profile?.[filters.area.field] !== filters.area.value)
    return false;

  return true;
};

// Applies one ridePageUpdated event to the table rows. Pure with respect to
// `pages` (returns a new array or the same reference when nothing changed) so
// it can run inside a functional setState updater without losing concurrent
// updates from polling.
const applyPageUpdate = (d: any, pages: any[], pageUpdated: any) => {
  const profile = {
    ...(pageUpdated?.persistent?.static?.profile || {}),
    ...(pageUpdated?.persistent?.static?.dashboard || {}),
    ...(pageUpdated?.persistent?.static?.ride || {}),
    ...(pageUpdated?.persistent?.dynamic?.ride || {}),
  };

  const status = pageUpdated?.nonpersistent?.static?.live?.status?.name;
  const rideType = pageUpdated?.persistent?.static?.profile?.type;
  const eventType = pageUpdated?.persistent?.static?.metadata?.type;
  // searchPage filters with !exists(@pageType), so any sub-typed ride page
  // (inspection etc.) is excluded from this table.
  if (pageUpdated?.persistent?.static?.ride?.rideRequestAttributes?.pageType)
    return pages;
  if ((!d.showHail.current && rideType === "hail") || eventType !== "event") {
    console.log("show hail false");
    return pages;
  }

  const index = pages.findIndex((page) => {
    return page.key?.toString() === pageUpdated.pageId?.toString();
  });

  // A fetch that lands after a newer copy (live or poll) must not roll the
  // row back.
  const incomingUpdatedAt = getPageUpdatedAt(pageUpdated);
  if (
    index !== -1 &&
    incomingUpdatedAt &&
    pages[index]?._updatedAt &&
    pages[index]._updatedAt > incomingUpdatedAt
  ) {
    return pages;
  }

  // A phone search spans every status, advance bookings included.
  const excluded =
    (d.selectedColor.current && d.selectedColor.current !== status) ||
    (!d.selectedColor.current &&
      status === "brown" &&
      !d.activeFiltersRef.current?.phone) ||
    !matchesActiveFilters(d, pageUpdated, profile);

  if (excluded) {
    if (index !== -1) {
      const removed = [...pages];
      removed.splice(index, 1);
      return removed;
    }
    return pages;
  }

  const source: any = {};
  Object.keys(profile).map((p) => {
    if (typeof profile[p] === "string") {
      source[p] = profile[p];
    }
  });

  const requestedBy =
    d.usersRef.current?.find((user: any) => {
      return (
        user.id === pageUpdated?.nonpersistent?.dynamic?.ride?.dispatchRequestBy
      );
    })?.beamId || "";


  let stripe;
  Object.keys(pageUpdated?.persistent?.static?.payment?.stripe || {})?.map(
    (key) => {
      if (
        pageUpdated?.persistent?.static?.payment?.stripe?.[key]?.object ===
          "payment_intent" &&
        pageUpdated?.persistent?.static?.payment?.stripe?.[key]?.status ===
          "succeeded"
      ) {
        stripe = pageUpdated?.persistent?.static?.payment?.stripe?.[key];
      }
    }
  );

  if (!stripe) {
    Object.keys(pageUpdated?.persistent?.static?.payment?.stripe || {})?.map(
      (key) => {
        if (
          pageUpdated?.persistent?.static?.payment?.stripe?.[key]?.object ===
            "payment_intent" &&
          pageUpdated?.persistent?.static?.payment?.stripe?.[key]?.status ===
            "requires_capture"
        ) {
          stripe = pageUpdated?.persistent?.static?.payment?.stripe?.[key];
        }
      }
    );
  }

  const sourceUpdatedData = {
    key: pageUpdated.pageId,
    pageStatus: pageUpdated?.nonpersistent?.static?.live?.status?.name,
    _updatedAt: incomingUpdatedAt,
    _createdAt:
      Number(pageUpdated?.persistent?.static?.metadata?.createdAt) || undefined,
    // Client time this row was refreshed live; a poll sent earlier keeps it.
    _liveAt: Date.now(),
    requestedBy,
    requestedAt: new Date(
      pageUpdated?.persistent?.static?.metadata?.createdAt
    ).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }),
    _manualUserIds: manualUserIds(
      pageUpdated?.nonpersistent?.dynamic?.ride?.manualUsers
    ),
    _driverUserId: profile?.driverUserId?.toString() || undefined,
    name: pageUpdated?.persistent?.static?.metadata?.title,
    action: {
      pageId: pageUpdated.pageId,
      page: {
        ...pageUpdated,
        profile,
      },
      summary: source.summary,
      cudbServiceId: d.projects?.userServiceId,
      stripe,
    },
    ...source,
    address:
      source?.address && source?.adress !== ""
        ? source?.address
        : profile?.pickupLocation?.attributes?.address,
    dropoffAddress:
      source?.dropoffAddress && source?.dropoffAddress !== ""
        ? source?.dropoffAddress
        : profile?.dropoffLocation?.attributes?.address,
  };

  if (isSocketDebug()) console.log("source updated", sourceUpdatedData);
  const next = [...pages];
  if (d.selected === "advance") {
    // Advance view is sorted by pickup time ASC: update in place, insert new
    // rows in order.
    if (index !== -1) {
      next[index] = sourceUpdatedData;
    } else {
      const at = rowPickupTime(sourceUpdatedData);
      const insertAt = next.findIndex((row) => rowPickupTime(row) > at);
      if (insertAt === -1) next.push(sourceUpdatedData);
      else next.splice(insertAt, 0, sourceUpdatedData);
    }
  } else {
    // A replace (existing row) updates in place so its position in the table
    // stays fixed — otherwise rows jump up and down on every update. Only a
    // brand-new row is placed at the top.
    if (index !== -1) {
      next[index] = sourceUpdatedData;
    } else {
      next.unshift(sourceUpdatedData);
    }
  }
  return next;
};

// All lifecycle effects: phone search sync, redraw ticks, incremental page
// updates, the encrypted-token bootstrap (subscribe + polling), project role
// setup, and user-request hydration. Ride invitations (the Driver column's
// live offers) come from the shared rideOffers store.
export const useDashboardSubscriptions = (d: any) => {
  const { socket } = d;

  // One shared, ref-counted subscription to the org's invitation topic for
  // every dashboard (and the Fleet tab).
  useRideOffersConnection(
    socket,
    d.projects?.userServiceId,
    d.encrypted_token?.userId
  );

  useEffect(() => {
    if (d.searchByPhone) {
      console.log("search by phone", d.searchByPhone);
      d.setPhonePagePaths(d.searchByPhone?.phone);
    }
  }, [d.searchByPhone]);

  useEffect(() => {
    if (d.statusCount) {
      d.setRedrawCount(d.redrawCount + 1);
    }
  }, [JSON.stringify(d.statusCount)]);

  // Drain every queued ridePageUpdated event in order inside a single
  // functional update, so simultaneous updates for different pages can't
  // overwrite each other and never clobber writes from polling/invitations.
  useEffect(() => {
    const events = d.pageUpdatedQueue;
    if (!events?.length) return;
    d.setPageUpdatedQueue([]);
    d.getPageStatusthrottleFunc();
    d.setTableDataSource((prev: any[]) => {
      let tempPages = [...(prev || [])];
      events.forEach((pageUpdated: any) => {
        tempPages = applyPageUpdate(d, tempPages, pageUpdated);
      });
      return tempPages;
    });
    // Replaces the optimistic placeholder of a just-booked ride (even when
    // the ride falls outside the current view).
    events.forEach((pageUpdated: any) => d.notePageRow?.(pageUpdated?.pageId));
  }, [d.pageUpdatedQueue]);

  // Gated on socket.client: subscribeToEvent silently drops the subscription
  // when the MQTT client doesn't exist yet, with no retry — if the token lands
  // in redux before the socket connects, real-time updates would never start.
  // All dashboards and the dispatch panel share one socket callback for this
  // topic (rideSync fan-out); the listener is removed on unmount.
  useEffect(() => {
    if (!(d.encrypted_token && socket.client)) return;
    d.encryptedTokenRef.current = d.encrypted_token;
    return subscribeRidePageUpdated(
      socket,
      d.encrypted_token?.userId,
      ({ pageId, meta, row: liveRow }) => {
        // Newer ride service: the event carries the row itself. It goes
        // through the same merge as a fetched page (newer updatedAt wins,
        // current filters/status view applied, a ride that no longer
        // matches is removed) without a round trip.
        if (liveRow) {
          d.setPageUpdatedQueue((prev: any[]) => [...prev, liveRow]);
          return;
        }
        const row = (d.tableDataSourceRef.current || []).find(
          (r: any) => r.key?.toString() === pageId
        );
        const metaUpdatedAt = Number(meta?.updatedAt);
        // The table already has this version (or newer).
        if (row && metaUpdatedAt && row._updatedAt && metaUpdatedAt <= row._updatedAt)
          return;
        // Not in the table and its status can't be shown in this view.
        if (!row && meta?.status) {
          const color = d.selectedColor.current;
          if (color && color !== meta.status) return;
          if (!color && meta.status === "brown" && !d.activeFiltersRef.current?.phone)
            return;
        }
        d.getPagethrottleFunc(pageId);
      }
    );
  }, [d.encrypted_token, socket.client]);

  // Resync once after a reconnect: events sent while the socket was down
  // are lost.
  const lastEpochRef = useRef<number>();
  useEffect(() => {
    const epoch = socket.connectionEpoch;
    if (epoch === undefined) return;
    const previous = lastEpochRef.current;
    lastEpochRef.current = epoch;
    if (previous === undefined || epoch <= previous) return;
    if (d.encryptedTokenRef.current && d.projectsRef.current?.userServiceId) {
      d.searchPageRef.current();
    }
  }, [socket.connectionEpoch]);

  // Page searches filter by org (projects.userServiceId), which arrives after
  // the token, so wait for it or the first queries go out unfiltered.
  useEffect(() => {
    if (d.encrypted_token && socket.client && d.projects?.userServiceId) {
      d.encryptedTokenRef.current = d.encrypted_token;

      d.setProjectFilterLoading(true);
      d.searchPageRef.current();

      if (d.timeoutRef.current) clearInterval(d.timeoutRef.current);
      d.timeoutRef.current = setInterval(() => {
        d.searchPageRef.current();
        d.prunePageThrottles();
      }, POLL_INTERVAL_MS);

      d.getPageAggregateBds("state");
      d.setTableHideList(
        JSON.parse(localStorage.getItem("tableHideList")) || []
      );
    }
  }, [d.encrypted_token, socket.client, d.projects?.userServiceId]);

  useEffect(() => {
    return () => {
      if (d.timeoutRef.current) {
        clearInterval(d.timeoutRef.current);
      }
      Object.keys(d.pageThrottleRef.current || {}).forEach((key) => {
        d.pageThrottleRef.current[key]?.fn?.cancel?.();
      });
      d.pageThrottleRef.current = {};
    };
  }, []);

  // Same socket.client gate as above: the users subscriptions are
  // dropped without retry if they run before the MQTT client is connected.
  useEffect(() => {
    if (d.projects && socket.client) {
      const options = [];
      d.projects?.projects?.map((project: any) => {
        options.push({ label: project.name, value: project.id });
      });
      d.setProjectFilterOptions(options);
      if (d.projects?.adminUserId) {
        d.getAdminRoles(d.projects?.adminUserId, d.projects?.userServiceId);
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getUsersSubscriptionTopic(
            d.encrypted_token?.connectionId,
            d.projects?.userServiceId
          )
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          getAggregateBdsSubscriptionTopic(d.encrypted_token?.connectionId)
        );
      }
    }
  }, [d.projects, socket.client]);

  useEffect(() => {
    if (d.userRequests && socket.client) {
      if (
        !d.usersRef.current &&
        d.userRequests?.[Object.keys(d.userRequests)?.[0]]
      ) {
        console.log(
          "user requests here",
          d.userRequests?.[Object.keys(d.userRequests)?.[0]]
        );
        d.usersRef.current = d.userRequests?.[Object.keys(d.userRequests)?.[0]];
        localStorage.setItem("rideUsers", JSON.stringify(d.usersRef.current));
      }

      if (d.userRequests?.[`${d.filterUserRequestId.current}:${d.projectFilter}`]) {
        d.setProjectFilterLoading(false);
        let options = [];
        d.userRequests?.[
          `${d.filterUserRequestId.current}:${d.projectFilter}`
        ]?.map((user: any) => {
          options.push({
            label: `${user.fullName}: ${user.email}`,
            value: user.id,
          });
        });
        d.setProjectFilterOptions(options);
      }
    }
  }, [d.userRequests, socket.client]);
};
