/**
 * CFO Dashboard — the people and organisations behind the sidebar tables.
 *
 * Players are generated from the project rosters so the individual
 * payment-request flow (which preselects a roster member by id) lines up
 * with what the table shows. Where a roster member also has a ledger
 * line, the table shows the ledger's figures; otherwise a deterministic
 * pattern gives every table a spread of paid / partial / overdue /
 * not-billed rows.
 *
 * Coaches, staff and vendors have no roster or ledger to derive from, so
 * they are written out here, reusing the names that already appear on
 * the payable side of the ledger.
 */
import {
  BillableEntity,
  BillingSnapshot,
  Domain,
  EntityKind,
  LedgerRow,
  ProjectRollup,
} from "./types";
import {
  DAY,
  LEDGER_ROWS,
  NOW,
  PROJECTS,
  PROJECT_MEMBERS,
  getProject,
} from "./mockData";
import { nextDueOf, projectGroupOf, summarizeProject } from "./selectors";

const round2 = (value: number) => Number(value.toFixed(2));

/** Deterministic contact details from a name, so the tables look filled in. */
const contact = (name: string, seed: number) => {
  const parts = name.toLowerCase().replace(/[^a-z ]/g, "").split(" ");
  const first = parts[0] || "user";
  const last = parts[parts.length - 1] || "beam";
  return {
    email: `${first}.${last}@example.com`,
    phone: `+1 (555) 0${String(100 + ((seed * 37) % 900)).padStart(3, "0")}-${String(
      (seed * 91) % 10000
    ).padStart(4, "0")}`,
  };
};

const snapshot = (
  currency: string,
  billed: number,
  collected: number,
  pastDue: number,
  nextDueAt: number | null,
  lastActivityAt: number | null
): BillingSnapshot => ({
  currency,
  billed: round2(billed),
  collected: round2(collected),
  outstanding: round2(Math.max(0, billed - collected - pastDue)),
  pastDue: round2(pastDue),
  nextDueAt,
  lastActivityAt,
});

const fromLedger = (row: LedgerRow): BillingSnapshot => ({
  currency: row.currency,
  billed: row.invoicedServiceFee,
  collected: row.collected,
  outstanding: row.outstanding,
  pastDue: row.pastDue,
  nextDueAt: nextDueOf(row),
  lastActivityAt: row.lastActivityAt,
});

/**
 * Roster members without a ledger line cycle through the four billing
 * states so a table of twenty players is not twenty identical rows.
 */
const patterned = (
  currency: string,
  amount: number,
  index: number
): BillingSnapshot => {
  const last = NOW - ((index * 5) % 40) * DAY;
  switch (index % 5) {
    case 0:
    case 1:
      return snapshot(currency, amount, amount, 0, null, last);
    case 2:
      return snapshot(currency, amount, amount / 2, 0, last + 30 * DAY, last);
    case 3:
      return snapshot(
        currency,
        amount,
        amount / 4,
        amount / 4,
        last + 30 * DAY,
        last
      );
    default:
      return snapshot(currency, 0, 0, 0, null, null);
  }
};

const buildPlayers = (domain: Domain): BillableEntity[] => {
  const rows = LEDGER_ROWS[domain];
  const players: BillableEntity[] = [];
  let seed = 0;

  PROJECTS.filter((project) => project.domain === domain).forEach((project) => {
    const roster = PROJECT_MEMBERS[project.id] || [];
    roster.forEach((member, index) => {
      seed += 1;
      const line = rows.find(
        (row) =>
          row.side === "ar" &&
          row.projectId === project.id &&
          row.entity === member.name
      );
      const billed = project.paymentConfigId ? project.totalAmount : 0;
      players.push({
        id: member.id,
        domain,
        kind: "player",
        side: "ar",
        name: member.name,
        role: member.role,
        household: member.household,
        projectIds: [project.id],
        paymentConfigId: project.paymentConfigId,
        billing: line
          ? fromLedger(line)
          : patterned(project.currency, billed, index),
        ...contact(member.name, seed),
      });
    });
  });

  return players;
};

interface PayeeSpec {
  id: string;
  name: string;
  role: string;
  projectIds: string[];
  paymentConfigId: string;
  contract: BillableEntity["contract"];
  category?: string;
  department?: string;
  fee: number;
  paid: number;
  pastDue?: number;
  nextDueInDays: number | null;
  lastActivityDaysAgo: number;
}

const payees = (
  domain: Domain,
  kind: "coach" | "staff" | "vendor",
  specs: PayeeSpec[]
): BillableEntity[] =>
  specs.map((spec, index) => ({
    id: spec.id,
    domain,
    kind,
    side: "ap",
    name: spec.name,
    role: spec.role,
    category: spec.category,
    department: spec.department,
    projectIds: spec.projectIds,
    paymentConfigId: spec.paymentConfigId,
    contract: spec.contract,
    billing: snapshot(
      "USD",
      spec.fee,
      spec.paid,
      spec.pastDue || 0,
      spec.nextDueInDays === null ? null : NOW + spec.nextDueInDays * DAY,
      NOW - spec.lastActivityDaysAgo * DAY
    ),
    ...contact(spec.name, 100 + index),
  }));

