export const PLAYERS: Record<Domain, BillableEntity[]> = {
  sport: buildPlayers("sport"),
  edu: buildPlayers("edu"),
};

export const COACHES: Record<Domain, BillableEntity[]> = {
  sport: payees("sport", "coach", SPORT_COACHES),
  edu: payees("edu", "coach", EDU_TEACHERS),
};

export const STAFF: Record<Domain, BillableEntity[]> = {
  sport: payees("sport", "staff", SPORT_STAFF),
  edu: payees("edu", "staff", EDU_STAFF),
};

export const VENDORS: Record<Domain, BillableEntity[]> = {
  sport: payees("sport", "vendor", SPORT_VENDORS),
  edu: payees("edu", "vendor", EDU_VENDORS),
};

/** Teams (or classes) and events, rolled up from the ledger. */
export const projectRollups = (
  domain: Domain,
  group: "team" | "event"
): ProjectRollup[] =>
  PROJECTS.filter(
    (project) =>
      project.domain === domain && projectGroupOf(project.kind) === group
  ).map((project) => summarizeProject(project, LEDGER_ROWS[domain]));

export const peopleFor = (
  kind: Exclude<EntityKind, "teams" | "events">,
  domain: Domain
): BillableEntity[] => {
  switch (kind) {
    case "players":
      return PLAYERS[domain];
    case "coaches":
      return COACHES[domain];
    case "staff":
      return STAFF[domain];
    case "vendors":
    default:
      return VENDORS[domain];
  }
};

/** Display name of the first project an entity belongs to. */
export const primaryProjectName = (entity: BillableEntity): string => {
  const project = entity.projectIds[0] ? getProject(entity.projectIds[0]) : null;
  return project ? project.name : "-";
};

export const projectNames = (entity: BillableEntity): string[] =>
  entity.projectIds
    .map((id) => getProject(id))
    .filter((project) => !!project)
    .map((project) => (project as { name: string }).name);
