import React, { useEffect, useState } from "react";
import { Tooltip } from "antd";
import { RideOffer, isOfferingStatus, useRidePageOffers } from "../../../rideOffers";
import { RIDE_STATUS_LABELS } from "../constants";

// "Driver" column of the rides tables: who has this ride right now. Driven by
// the row's status, the live offers (rideOffers store) and the drivers the
// dispatcher hand-picked (manualUsers).

// Statuses in which a driver has accepted the ride.
const ACCEPTED_STATUSES = new Set(["amber", "aqua", "blue", "green"]);

let cachedUsersJson: string | null = null;
let cachedUsers: any[] = [];
const storedUsers = (): any[] => {
  try {
    const json = localStorage.getItem("rideUsers");
    if (json !== cachedUsersJson) {
      cachedUsersJson = json;
      cachedUsers = JSON.parse(json || "[]") || [];
    }
  } catch (e) {
    cachedUsers = [];
  }
  return Array.isArray(cachedUsers) ? cachedUsers : [];
};

/** Driver id -> beam id (dashboard user list, else the cached list). */
export const driverDisplayName = (id: any, users?: any[]): string => {
  const key = id?.toString();
  if (!key) return "";
  const list = users?.length ? users : storedUsers();
  return list.find((u: any) => u?.id?.toString() === key)?.beamId || `Driver #${key}`;
};

/** Seconds left until `expiresAt`, ticking on its own 1s timer. */
export const OfferCountdown: React.FC<{ expiresAt: number; className?: string }> = ({
  expiresAt,
  className,
}) => {
  const secondsLeft = () => Math.max(0, Math.ceil((expiresAt - Date.now()) / 1000));
  const [left, setLeft] = useState(secondsLeft);
  useEffect(() => {
    setLeft(secondsLeft());
    const id = setInterval(() => {
      const next = secondsLeft();
      setLeft(next);
      if (next <= 0) clearInterval(id);
    }, 1000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expiresAt]);
  return (
    <span className={`ride-countdown ${className || ""}`} aria-label={`${left} seconds left`}>
      {left}s
    </span>
  );
};

const OfferingText: React.FC<{ offers: RideOffer[]; users?: any[] }> = ({ offers, users }) => {
  const latest = offers.reduce((a, b) => (b.expiresAt > a.expiresAt ? b : a), offers[0]);
  if (offers.length === 1) {
    return (
      <span className="ride-driver__offer">
        <span className="ride-driver__pulse" aria-hidden="true" />
        Offering to <strong>{driverDisplayName(latest.driverUserId, users)}</strong>
        <OfferCountdown expiresAt={latest.expiresAt} />
      </span>
    );
  }
  return (
    <Tooltip
      title={
        <ul className="ride-driver__list">
          {offers.map((o) => (
            <li key={o.driverUserId}>
              {driverDisplayName(o.driverUserId, users)} <OfferCountdown expiresAt={o.expiresAt} />
            </li>
          ))}
        </ul>
      }
    >
      <span className="ride-driver__offer" tabIndex={0}>
        <span className="ride-driver__pulse" aria-hidden="true" />
        Offering to <strong>{offers.length} drivers</strong>
        <OfferCountdown expiresAt={latest.expiresAt} />
      </span>
    </Tooltip>
  );
};

const ManualTag: React.FC<{ ids: string[]; users?: any[] }> = ({ ids, users }) => (
  <Tooltip title={`Hand-picked: ${ids.map((id) => driverDisplayName(id, users)).join(", ")}`}>
    <span className="ride-driver__tag" tabIndex={0}>
      Manual
    </span>
  </Tooltip>
);

export const DriverCell: React.FC<{ record: any; usersRef?: { current?: any } }> = ({
  record,
  usersRef,
}) => {
  const pageId = record?.action?.pendingSubmission ? undefined : record?.key?.toString();
  const offers = useRidePageOffers(pageId);
  if (!pageId) return null;

  const users = usersRef?.current;
  const status: string | undefined = record?.pageStatus;
  const manualIds: string[] = record?._manualUserIds || [];
  const driverName =
    record?.driverName ||
    (record?._driverUserId ? driverDisplayName(record._driverUserId, users) : "");
  const liveOffers = isOfferingStatus(status) ? offers : [];

  let main: React.ReactNode;
  if (liveOffers.length) {
    main = <OfferingText offers={liveOffers} users={users} />;
  } else if (status && ACCEPTED_STATUSES.has(status)) {
    main = (
      <span className="ride-driver__accepted">
        <span className="ride-driver__name">{driverName || "—"}</span>
        <span className={`ride-driver__stage ride-driver__stage--${status}`}>
          {RIDE_STATUS_LABELS[status]}
        </span>
      </span>
    );
  } else if (status === "purple") {
    main = <span className="ride-driver__muted">Searching…</span>;
  } else if (status === "red") {
    main = <span className="ride-driver__none">No driver accepted</span>;
  } else {
    // Scheduled, cancelled, processed: the driver if one was assigned.
    main = driverName ? (
      <span className="ride-driver__name">{driverName}</span>
    ) : (
      <span className="ride-driver__muted">—</span>
    );
  }

  return (
    <span className="ride-driver">
      {main}
      {manualIds.length > 0 && <ManualTag ids={manualIds} users={users} />}
    </span>
  );
};

export default DriverCell;
