import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Spin, Tooltip } from "antd";
import { EnvironmentOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import { RootState } from "reducers/rootReducer";
import { SET_SELECTED_ASSETS, SET_SELECTED_PICKUP, SET_SELECTED_RESPONDER } from "reducers/reducer";
import { ExtendedBioTopics, SocketTopics, UserTopics } from "constants/enums";
import { ensureActiveCountry, getActiveCountry, primeActiveCountry } from "utils/placeName";
import { pushNotification } from "utils/notifications";
import useSocketActions from "../../../../hooks/socketActions";
import FleetView, { FleetOverlay } from "../../Fleet/FleetView";
import { FleetVehicle, VehicleOffers } from "../../Fleet/fleetUtils";
import { GOOGLE_MAPS_KEY } from "../rideSync";
import { useRideOffers } from "../rideOffers";
import RideMapLayers from "./RideMapLayers";
import {
  AreaShape,
  canAssign,
  centerFromQuery,
  fleetZoneShapes,
  geofenceShape,
  LatLng,
  pickedVehicleIds,
  standPosition,
  toAssetMarker,
  toDispatchResponder,
  tripPins,
} from "./rideMapUtils";

const locate = (): Promise<LatLng | undefined> =>
  new Promise((resolve) => {
    if (!navigator.geolocation) return resolve(undefined);
    navigator.geolocation.getCurrentPosition(
      (pos) => resolve({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => resolve(undefined),
      { timeout: 5000 }
    );
  });

/**
 * Ride "Map" tab: the Fleet dashboard (live vehicles, filters, GPS history,
 * playback) plus everything the old Ride MapPanel did for dispatching — trip
 * pins and route, blocked area, stands, fleet zones, assets and picking
 * drivers for the dispatch. Same props as MapPanel so the two swap 1:1.
 *
 * Live positions come only from FleetView's getResponders poll; its replies
 * also reach redux `responders` through the app's socket handler, as the old
 * map's one-off request did.
 */
// `params` (screens/setScreens) is kept for MapPanel parity; nothing here needs it.
const FleetPanel: FC<{ socket: ISocket; params: any }> = ({ socket }) => {
  const dispatch = useDispatch();
  const { search } = useLocation();
  const {
    vehicles,
    project,
    projects,
    otherLocations,
    assets,
    geofenceLocation,
    standLocations,
    selectedResponders,
    selectedAssets,
    encrypted_token,
  } = useSelector((state: RootState) => state.auth);
  const { getUserRequestPayload } = useSocketActions();

  /* ------------------------------------------------------------- centre */

  // As the old map: URL lat/lng (web booker), else the browser location. If
  // neither, FleetView falls back to its own (last searched place, default).
  const [start, setStart] = useState<{ done: boolean; center?: LatLng }>(() => {
    const fromUrl = centerFromQuery(search);
    return fromUrl ? { done: true, center: fromUrl } : { done: false };
  });
  const [myLocation, setMyLocation] = useState<LatLng | undefined>(start.center);
  const [focus, setFocus] = useState<FleetOverlay["focus"]>();

  useEffect(() => {
    if (start.done) return;
    let cancelled = false;
    locate().then((center) => {
      if (cancelled) return;
      setMyLocation(center);
      setStart({ done: true, center });
    });
    return () => {
      cancelled = true;
    };
  }, [start.done]);

  const goToMyLocation = async () => {
    const here = centerFromQuery(search) || (await locate());
    if (!here) {
      pushNotification("Couldn't get your location", "error", "TOP_CENTER", 2000);
      return;
    }
    setMyLocation(here);
    setFocus({ ...here, key: Date.now() });
  };

  // Country to scope the place search to, as the old map did.
  const [searchCountry, setSearchCountry] = useState(getActiveCountry());
  useEffect(() => {
    let cancelled = false;
    const resolve = myLocation
      ? primeActiveCountry({ lat: myLocation.lat, long: myLocation.lng })
      : ensureActiveCountry();
    resolve
      .then((code) => {
        if (!cancelled && code) setSearchCountry(code);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [myLocation?.lat, myLocation?.lng]); // eslint-disable-line react-hooks/exhaustive-deps

  /* ------------------------------------------------------- fleet zones */

  const [zones, setZones] = useState<AreaShape[]>([]);
  useEffect(() => {
    if (!projects?.adminUserId) return;
    socket.subscribeToSurvey(SocketTopics.SurveyTopics, ExtendedBioTopics.GetUserBio, (resp: any) => {
      setZones(fleetZoneShapes(resp?.data?.[0]?.[0]));
    });
    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.SearchInUser,
      getUserRequestPayload(projects?.adminUserId, "$", "$..persistent.static.admin.fleetZones.items"),
      ExtendedBioTopics.GetUserBio,
      projects?.userServiceId
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId]);

  /* ------------------------------------------------------ dispatch data */

  const pins = useMemo(() => tripPins(otherLocations), [otherLocations]);
  const blockedArea = useMemo(() => geofenceShape(geofenceLocation, true), [geofenceLocation]);
  const stands = useMemo(
    () =>
      (standLocations ?? [])
        .map((s: any, i: number) => {
          const position = standPosition(s);
          return position
            ? { key: `stand-${s?.id ?? s?._id ?? i}`, position, raw: s, title: s?.location?.attributes?.address }
            : undefined;
        })
        .filter(Boolean) as { key: string; position: LatLng; raw: any; title?: string }[],
    [standLocations]
  );

  // `selectedResponders` / `selectedAssets` are mutated in place by the
  // reducer, so derive from them on every render rather than memoising.
  const pickedIds = pickedVehicleIds(selectedResponders);
  const selectedAssetIds = (selectedAssets ?? []).map((a: any) => `${a?.id}`);
  const assetMarkers = (assets ?? [])
    .map((item: any, i: number) => {
      const m = toAssetMarker(item);
      return m
        ? {
            key: `asset-${m.id ?? i}`,
            position: { lat: m.lat, lng: m.lng },
            raw: m,
            color: m.color,
            title: m.title,
            selected: selectedAssetIds.includes(`${m.id}`),
          }
        : undefined;
    })
    .filter(Boolean) as any[];

  const fitPoints = useMemo<LatLng[]>(
    () => [...pins.map(({ lat, lng }) => ({ lat, lng })), ...stands.map((s) => s.position)],
    [pins, stands]
  );

  /* -------------------------------------------------- pending offers */

  // Rides currently ringing on drivers' phones (vehicle id = responder id =
  // the offer's driverUserId).
  const { byDriver } = useRideOffers(socket, projects?.userServiceId, encrypted_token?.userId);
  const offers = useMemo<VehicleOffers>(() => {
    const out: VehicleOffers = {};
    Object.keys(byDriver).forEach((driverId) => {
      const o = byDriver[driverId];
      out[driverId] = {
        pageId: o.pageId,
        expiresAt: o.expiresAt,
        label: o.pickup ? `Ride #${o.pageId} · pickup ${o.pickup}` : `Ride #${o.pageId}`,
      };
    });
    return out;
  }, [byDriver]);

  /* ---------------------------------------------------- driver picking */

  const toggleDriver = (vehicle: FleetVehicle) => {
    const existing = (selectedResponders ?? []).find((r: any) => `${r?.id}` === vehicle.id);
    if (existing) {
      // The reducer toggles by id: passing the stored entry removes it.
      dispatch({ type: SET_SELECTED_RESPONDER, payload: existing });
      return;
    }
    if (!canAssign(vehicle, false)) {
      pushNotification("Only available drivers can be assigned", "error", "TOP_CENTER", 2000);
      return;
    }
    dispatch({ type: SET_SELECTED_RESPONDER, payload: toDispatchResponder(vehicle.raw, vehicles) });
  };

  const overlay: FleetOverlay = {
    fitPoints,
    fitKey: JSON.stringify(fitPoints),
    focus,
    layers: (
      <RideMapLayers
        pins={pins}
        blockedArea={blockedArea}
        zones={zones}
        stands={stands}
        assets={assetMarkers}
        myLocation={myLocation}
        onStand={(stand) => dispatch({ type: SET_SELECTED_PICKUP, payload: stand })}
        onAsset={(asset) => dispatch({ type: SET_SELECTED_ASSETS, payload: asset })}
      />
    ),
    tools: (
      <Tooltip title="My location" placement="left">
        <Button icon={<EnvironmentOutlined />} onClick={goToMyLocation} />
      </Tooltip>
    ),
  };

  return (
    <div className="flt-ride-panel">
      {start.done ? (
        <FleetView
          socket={socket}
          embedded
          projectId={project || undefined}
          initialCenter={start.center}
          searchCountry={searchCountry}
          googleApiKey={GOOGLE_MAPS_KEY || undefined}
          overlay={overlay}
          selectedVehicleIds={pickedIds}
          offers={offers}
          onVehicleAction={toggleDriver}
          vehicleAction={(v, picked) => ({
            label: picked ? "Assigned" : "Assign",
            active: picked,
            disabled: !canAssign(v, picked),
            tooltip: picked
              ? "Remove from this dispatch"
              : canAssign(v, picked)
              ? "Add to this dispatch"
              : "Only available drivers can be assigned",
          })}
        />
      ) : (
        <div className="flt-shell flt-shell--embedded">
          <div className="flt-shell__loading">
            <Spin />
            <span>Finding your location…</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default FleetPanel;
