import React, { FC, useEffect, useMemo, useState } from "react";
import { Alert, Button, Empty, InputNumber, Popconfirm, Select, Table, Tag } from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import {
  getDistanceMatrix,
  putDistanceMatrix,
} from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { DistanceEntry } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";

interface RowEntry extends DistanceEntry {
  _rowId: number;
}

const pairKey = (a: string, b: string) => [a, b].sort().join("→");

const DistanceMatrixEditor: FC<{
  orgId: string;
  knownLocations: string[];
}> = ({ orgId, knownLocations }) => {
  const [rows, setRows] = useState<RowEntry[]>([]);
  const [savedRows, setSavedRows] = useState<RowEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const nextIdRef = React.useRef(1);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const entries = await getDistanceMatrix(orgId);
        if (!cancelled) {
          const loaded = (entries || []).map((e) => ({
            ...e,
            _rowId: nextIdRef.current++,
          }));
          setRows(loaded);
          setSavedRows(loaded);
        }
      } catch (e) {
        if (!cancelled) {
          pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [orgId]);

  const locationOptions = Array.from(
    new Set([...knownLocations, ...rows.flatMap((r) => [r.fromLocation, r.toLocation])])
  )
    .filter(Boolean)
    .map((l) => ({ label: l, value: l }));

  const duplicates = useMemo(() => {
    const seen = new Set<string>();
    const dupes = new Set<string>();
    rows.forEach((r) => {
      if (!r.fromLocation || !r.toLocation) return;
      const key = pairKey(r.fromLocation, r.toLocation);
      if (seen.has(key)) dupes.add(key);
      seen.add(key);
    });
    return dupes;
  }, [rows]);

  const coveredPairs = useMemo(() => {
    const set = new Set<string>();
    rows.forEach((r) => {
      if (r.fromLocation && r.toLocation) set.add(pairKey(r.fromLocation, r.toLocation));
    });
    return set;
  }, [rows]);

  // Building pairs from resource locations that have no distance yet.
  const missingPairs = useMemo(() => {
    const pairs: [string, string][] = [];
    for (let i = 0; i < knownLocations.length; i++) {
      for (let j = i + 1; j < knownLocations.length; j++) {
        if (!coveredPairs.has(pairKey(knownLocations[i], knownLocations[j]))) {
          pairs.push([knownLocations[i], knownLocations[j]]);
        }
      }
    }
    return pairs;
  }, [knownLocations, coveredPairs]);

  const unsaved = useMemo(() => {
    const strip = (list: RowEntry[]) =>
      JSON.stringify(
        list.map(({ fromLocation, toLocation, minutes }) => ({
          fromLocation,
          toLocation,
          minutes,
        }))
      );
    return strip(rows) !== strip(savedRows);
  }, [rows, savedRows]);

  const updateRow = (rowId: number, patch: Partial<DistanceEntry>) => {
    setRows((prev) => prev.map((r) => (r._rowId === rowId ? { ...r, ...patch } : r)));
  };

  const addRow = (from = "", to = "") => {
    setRows((prev) => [
      ...prev,
      { fromLocation: from, toLocation: to, minutes: 5, _rowId: nextIdRef.current++ },
    ]);
  };

  const handleSave = async () => {
    const complete = rows.filter((r) => r.fromLocation && r.toLocation && r.minutes >= 0);
    if (complete.length !== rows.length) {
      pushNotification("Complete or remove empty rows first", "error", "TOP_CENTER", 3000);
      return;
    }
    if (duplicates.size) {
      pushNotification("Remove duplicate pairs first", "error", "TOP_CENTER", 3000);
      return;
    }
    setSaving(true);
    try {
      await putDistanceMatrix(
        orgId,
        complete.map(({ fromLocation, toLocation, minutes }) => ({
          fromLocation,
          toLocation,
          minutes,
        }))
      );
      setSavedRows(rows);
      pushNotification("Distance matrix saved", "success", "TOP_CENTER", 2000);
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setSaving(false);
    }
  };

  const singleLocationSelect = (
    rowId: number,
    field: "fromLocation" | "toLocation",
    value: string
  ) => (
    <Select
      mode="tags"
      size="small"
      style={{ minWidth: 150 }}
      value={value ? [value] : []}
      options={locationOptions}
      onChange={(v: string[]) =>
        updateRow(rowId, { [field]: v.length ? v[v.length - 1] : "" } as any)
      }
      placeholder="Building"
    />
  );

  const columns = [
    {
      title: "From",
      key: "from",
      render: (_: any, r: RowEntry) => singleLocationSelect(r._rowId, "fromLocation", r.fromLocation),
    },
    {
      title: "To",
      key: "to",
      render: (_: any, r: RowEntry) => singleLocationSelect(r._rowId, "toLocation", r.toLocation),
    },
    {
      title: "Walking minutes",
      key: "minutes",
      render: (_: any, r: RowEntry) => (
        <InputNumber
          size="small"
          min={0}
          value={r.minutes}
          onChange={(v) => updateRow(r._rowId, { minutes: v ?? 0 })}
        />
      ),
    },
    {
      title: "",
      key: "status",
      render: (_: any, r: RowEntry) =>
        r.fromLocation &&
        r.toLocation &&
        duplicates.has(pairKey(r.fromLocation, r.toLocation)) ? (
          <Tag color="red">duplicate</Tag>
        ) : null,
    },
    {
      title: "",
      key: "actions",
      render: (_: any, r: RowEntry) => (
        <Popconfirm
          title="Remove this pair?"
          onConfirm={() => setRows((prev) => prev.filter((x) => x._rowId !== r._rowId))}
        >
          <Button type="text" icon={<DeleteOutlined />} />
        </Popconfirm>
      ),
    },
  ];

  return (
    <div className="distance-matrix-editor scheduler-card">
      {!knownLocations.length && !rows.length && !loading && (
        <Alert
          className="mb-3"
          type="info"
          showIcon
          message="No buildings yet"
          description="Set the Location field on your rooms and teachers first — those buildings appear here to connect."
        />
      )}

      {missingPairs.length > 0 && (
        <div className="missing-pairs mb-3">
          <span style={{ fontSize: 12, color: "#566477", marginRight: 8 }}>
            Not connected yet:
          </span>
          {missingPairs.slice(0, 6).map(([a, b]) => (
            <Tag
              key={`${a}-${b}`}
              style={{ cursor: "pointer" }}
              onClick={() => addRow(a, b)}
            >
              + {a} ↔ {b}
            </Tag>
          ))}
          {missingPairs.length > 6 && (
            <span style={{ fontSize: 12, color: "#91a5c6" }}>
              +{missingPairs.length - 6} more
            </span>
          )}
        </div>
      )}

      <Table
        rowKey="_rowId"
        size="small"
        loading={loading}
        dataSource={rows}
        columns={columns as any}
        pagination={false}
        locale={{
          emptyText: (
            <Empty
              image={Empty.PRESENTED_IMAGE_SIMPLE}
              description="No pairs yet — add the walking time between two buildings"
            />
          ),
        }}
      />
      <div style={{ display: "flex", gap: 8, marginTop: 12, alignItems: "center" }}>
        <Button type="dashed" icon={<PlusOutlined />} onClick={() => addRow()}>
          Add pair
        </Button>
        <Button
          loading={saving}
          disabled={!unsaved}
          className="beam-btn green-btn cover"
          onClick={handleSave}
        >
          Save matrix
        </Button>
        {unsaved && <Tag color="gold">unsaved changes</Tag>}
      </div>
    </div>
  );
};

export default DistanceMatrixEditor;
