const patchUser = (state: any, action: any): any => {
  console.log('patch users')
  let users = state.users || [];
  const userIdx = users.findIndex((user) => {
    return user.id === action.payload.userId;
  });
  // console.log("patch user", userIdx, action.payload);
  if (userIdx !== -1) {
    const output = {};
    let current;
    for (let op of action.payload.user) {
      current = output;
      let segments = op.path.split("/");
      segments.map((segment, index) => {
        if (segment !== "") {
          if (!(segment in current)) {
            if (index + 1 === segments.length) {
              current[segment] = op.value;
            } else {
              current[segment] = {};
            }
          }
          current = current[segment];
        }
      });
    }
    users[userIdx] = _.merge(users[userIdx], output);
  }
  return {
    ...state,
    users: [...users],
  };
};

const patchUserStatus = (state: any, action: any): any => {
  console.log("patch user status", action);
  let users = state.users || [];
  const userIdx = users.findIndex((user) => {
    return user.id === action.payload.userId;
  });
  if (userIdx !== -1) {
    users[userIdx].nonpersistent.static.live.status = {
      name: action.payload.status,
      color: action.payload.status,
    };
  }
  return {
    ...state,
    users: [...users],
  };
};

