const processMessage = (
  updatedMessages: Array<any>,
  payload: any
): Array<object> => {
  // const flag = payload.data?.flag;
  const flag = payload.refMessage?.referenceType;
  const originalPageMessageId = payload?.originalPageMessageId;
  if (flag === "update" && !payload.status) {
    let index = updatedMessages.findIndex((x) => {
      return (
        x.id === originalPageMessageId ||
        x.originalPageMessageId === originalPageMessageId
      );
    });
    updatedMessages[index] = payload;
  } else if (flag === "remove" && !payload.status) {
    let index = updatedMessages.findIndex((x) => {
      return (
        x.id === originalPageMessageId ||
        x.originalPageMessageId === originalPageMessageId
      );
    });
    updatedMessages.splice(index, 1);
  } else updatedMessages.push(payload);
  return updatedMessages;
};

const setMessages = (state: any, action: any): any => {
  let processedMessages = [];
  let allMessages = action.payload;
  allMessages.sort((a, b) =>
    parseInt(a.id) > parseInt(b.id)
      ? 1
      : parseInt(b.id) > parseInt(a.id)
      ? -1
      : 0
  );
  allMessages?.map((message) => {
    processedMessages = processMessage(processedMessages, message);
  });
  return {
    ...state,
    messages: processedMessages,
  };
};

