const appendMessage = (state: any, action: any): any => {
  const updatedMessages = state.messages || [];
  const flag = action.payload.refMessage?.referenceType;
  const originalPageMessageId = action.payload?.originalPageMessageId;
  if (flag === "update" && !action.payload.status) {
    let index = updatedMessages.findIndex((x: any) => {
      return (
        x.id === originalPageMessageId ||
        x.originalPageMessageId === originalPageMessageId
      );
    });
    updatedMessages[index] = action.payload;
  } else if (flag === "remove" && !action.payload.status) {
    let index = updatedMessages.findIndex((x: any) => {
      return (
        x.id === originalPageMessageId ||
        x.originalPageMessageId === originalPageMessageId
      );
    });
    updatedMessages.splice(index, 1);
  } else updatedMessages.push(action.payload);
  return {
    ...state,
    messages: [...updatedMessages],
  };
};

