const patchPage = (state: any, action: any): any => {
  let page = state.page || {};
  console.log("patch page");
  if (page) {
    const output = {};
    let current;
    if (action.payload.length === 0) {
      return {
        ...state,
      };
    }
    for (let op of action.payload) {
      current = output;
      let segments = op.path.split("/");
      segments.map((segment, index) => {
        if (segment !== "") {
          if (!(segment in current)) {
            if (index + 1 === segments.length) {
              current[segment] = op.value;
            } else {
              current[segment] = {};
            }
          }
          current = current[segment];
        }
      });
    }
    console.log("output", output);
    page = _.merge(page, output);
  }
  return {
    ...state,
    page: { ...page },
  };
};

