const authReducer = (
  state: AuthState = initialState,
  action: { payload: any; type: any }
): AuthState => {
  switch (action.type) {
    case GET_PROJECT_SURVEY_ID:
      return {
        ...state,
        surveyId: action.payload,
      };
    case GET_SECTION_LIST:
      return getSectionList(state, action);
    case GET_BIO:
      return getBio(state, action);
    case GET_SURVEY:
      return getSurvey(state, action);
    case ADD_SURVEY:
      return addSurvey(state, action);
    case SET_NO_FOUND:
      return setNoFound(state, action);
    case SET_CATEGORIES:
      return setCategories(state, action);
    case SET_COACHES:
        return setCoaches(state, action);
    case GET_SURVEY_LIST:
      return getSurveyList(state, action);
      case RESET_REDIRECT_STATE:
        return resetRedirectState(state);
    // case GET_SURVEY_ANSWER:
    //     return getAnswer(state, action);
    case GET_ROLE_LIST:
      return getRoleList(state, action);
    case "ADD_FILE":
      return getFileToSend(state, action);
    case "ADD_CSV":
      return getCSVToSend(state, action);
    case GET_PROJECT_LIST:
      return getProjectList(state, action);
    case GET_ACCOUNT_LIST:
      return getAccountList(state, action);
    case GET_RESPONDER_LIST:
      return getResponderList(state, action);
    case GET_ASSETS_LIST:
      return getAssetsList(state, action);
    case SET_SELECTED_RESPONDER:
      return setSelectedResponder(state, action);
    case SET_SELECTED_ASSETS:
      return setSelectedAssets(state, action);
      case SET_SELECTED_PICKUP:
      return setSelectedPickup(state, action);
    case SET_CURRENT_LOCATION:
      return setCurrentLocation(state, action);
    case SET_CURRENT_PROJECT:
      return setCurrentProject(state, action);
    case SET_SUBMITTED:
      return setSubmitted(state, action);
    case 'SET_ONLY_SUBMITTED':
      return setOnlySubmitted(state, action);  
    case SET_URL_PARAMS:
      return setUrlParams(state, action);
    case ADD_OTHER_LOCATION:
      return addOtherLocation(state, action);
    case ADD_EVENT_LOCATION:
      return addEventLocation(state, action);
      case CLEAR_OTHER_LOCATION:
        return clearOtherLocation(state, action);  
    case ADD_GEOFENCE_LOCATION:
      return addGeofenceLocation(state, action);
    case ADD_STAND_LOCATION:
      return addStandLocations(state, action);
    case REMOVE_OTHER_LOCATION:
      return removeOtherLocation(state, action);
    case SET_PAGE:
      return setPage(state, action);
    case PATCH_PAGE:
      return patchPage(state, action);
    case PATCH_USER:
      return patchUser(state, action);
    case PATCH_USER_STATUS:
      return patchUserStatus(state, action);
    case SET_USERS:
      return setUsers(state, action);
    case "SET_USERS_REQUEST_ID":
      return setUsersRequest(state, action);
    case "SET_SELECTED_PAGE":
      return setSelectedPage(state, action);
    case "SEARCH_PAGES_BY_PHONE":
      return setSelectedPhone(state, action);  
    case SET_MESSAGES:
      return setMessages(state, action);
    case APPEND_MESSAGE:
      return appendMessage(state, action);
    case SET_CURRENT_MESSAGE:
      return setCurrentMessage(state, action);
    case CLEAR_SUMMARY:
      return clearSummary(state, action);
    case "USER_BDS":
      return setUserBds(state, action);
    case "AGGREGATE_BDS":
      return setAggregateBds(state, action);
    case "LOGIN_SUCCESSFUL":
        return setLoginSuccessful(state, true);
    case "ADMIN_ROLES":
      return setAdminRoles(state, action);  
    case "SET_PAGE_RESULT":
      return setPageResult(state, action);
    case "SET_VISIT":
      return setVisitResult(state, action);
    case "SET_STAFF":
      return setStaffResult(state, action);
    case "ADD_MAP_ASSET_FILTER":
      return setMapAssetsFilter(state, action);
    case "ADD_MAP_USER_FILTER":
      return setMapUsersFilter(state, action);
    case SET_DRIVER_FILTER:
      return setDriverFilter(state, action);
    case "ADD_ENCRYPTED_TOKEN":
      return setEncryptedToken(state, action);
    case "SET_VEHICLES":
      return setVehicles(state, action);  
    case "SET_VEHICLE_TYPES":
      return setVehicleType(state, action);    
    case "ADD_GPS":
      return setHistoricalGPS(state, action);
    case "SET_GPS_REPORT_MARKERS":
      return {
        ...state,
        gpsReportMarkers: action.payload,
      };
    case "SET_SELECTED_RESPONDER":
      return setResponder(state, action);
    case "SET_SELECTED_PHONE":
      return setPrimaryPhone(state, action);  
    case "SET_SELECTED_EMAIL":
      return setPrimaryEmail(state, action);    
    case "FILTER_SUB_CATEGORIES":
      return setFilterSubCategories(state, action);    
      case "loginUser":
      return {
        ...state,
        registrationSuccess: false,
      };
      case "ADD_DECRYPTED_TOKEN":
        return setDecryptedToken(state, action);
      case "registerNonBeamerUser":
        return setLoginSuccessful(state, false);
      case SHOW_PROGRESS:
        return setShowProgress(state);
      case HIDE_PROGRESS:
        return setHideProgress(state);
        case LOGIN_SUCCESS:
          return getLoginSuccess(state);
      case RESET_REGISTRATION_SUCCESS:
          return resetRegistrationSuccess(state);
      case OPEN_LOGIN_MODAL:
          return openLoginModal(state, true);
      case CLOSE_LOGIN_MODAL:
          return openLoginModal(state, false);
      case OPEN_REGISTER_MODAL:
          return openRegisterModal(state, true);
      case CLOSE_REGISTER_MODAL:
          return openRegisterModal(state, false);
      case OPEN_VERIFY_MODAL:
          return openVerifyModal(state, true);
      case CLOSE_VERIFY_MODAL:
            return openVerifyModal(state, false);
      case REGISTRATION_SUCCESS:
          return setRegistrationSuccess(state, action);
      case SET_USER_INFO:
            return setUserInfo(state, action);
      case LOGOUT_USER:
            return getLogout(state);
      case UPDATE_USER_INFO:
            return setUserInfo(state, action);
      case VERIFICATION_CODE_SENT:
            return handleVerificationCodeSent(state);
      case "VERIFICATION_FAILED":
            return handleVerificationFailure(state);
      case "AUTHENTICATION_SUCCESSFULL":
            return handleAuthenticationSuccess(state);
      case "AUTHENTICATION_FAILED":
            return handleAuthenticationFailure(state);
    default:
      return state;
  }
};

export default authReducer;
