import { useRef } from "react";
import _ from "lodash";
import { SocketTopics } from "constants/enums";
import { getVerifyCustomerPublishTopic } from "hooks/MQTTConstants";
import {
  SET_SUBMITTED,
  CREATE_RIDE,
  GET_PAYSTACK_TOKEN,
} from "reducers/reducer";
import { pushNotification } from "utils/notifications";
import { formatObject } from "utils/appUtil";
import {
  buildRideRequests,
  RideRequestValidationError,
} from "../buildRideRequests";
import { notifyNativeBridge } from "../utils";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";
import {
  getFleetTimezone,
  legLabel,
  newClientRequestId,
  parseRideResponse,
  RETURN_LEG_SUFFIX,
  RideErrorCode,
  emitRideSubmission,
} from "../../rideSync";

const STORED_REQUESTS_KEY = "rideRequests";

// Placeholder id for the dashboard's optimistic row; only new rides get one
// (an update already has its row).
const placeholderId = (request: any) =>
  !request?.pageId && request?.clientRequestId
    ? request.clientRequestId
    : undefined;

const placeholderSummary = (request: any) => {
  const attrs = request?.rideRequestAttributes || {};
  return {
    pickup: attrs.pickupAddress,
    dropoff: attrs.dropoffAddress,
    passengerName: attrs.passengerName,
    passengerPhoneNumber: attrs.passengerPhoneNumber,
    leg: legLabel(request?.clientRequestId),
  };
};
// Paystack token requests have no timeout of their own; never leave the
// submit button spinning forever if the saga never calls back.
const PAYSTACK_SAFETY_MS = 45000;

const readStoredRequests = (): any[] => {
  try {
    const stored = JSON.parse(localStorage.getItem(STORED_REQUESTS_KEY));
    return Array.isArray(stored) ? stored : [];
  } catch (e) {
    return [];
  }
};

const writeStoredRequests = (requests: any[]) => {
  try {
    if (requests.length) {
      localStorage.setItem(STORED_REQUESTS_KEY, JSON.stringify(requests));
    } else {
      localStorage.removeItem(STORED_REQUESTS_KEY);
    }
  } catch (e) {}
};

// Drops one leg from the stored Paystack requests once it has been created.
const removeStoredRequest = (request: any) => {
  const key = request?.clientRequestId;
  writeStoredRequests(
    readStoredRequests().filter((stored) =>
      key
        ? stored?.clientRequestId !== key
        : JSON.stringify(stored) !== JSON.stringify(request)
    )
  );
};

// Fare the passenger pays for one leg (the coupon-discounted fare when the
// leg carries a coupon).
const payableFare = (request: any) => {
  const attrs = request?.rideRequestAttributes || {};
  const fare = parseFloat(
    request?.couponId && attrs.discountedFare != null
      ? attrs.discountedFare
      : attrs.fixedFare ?? 0
  );
  return Number.isFinite(fare) ? fare : 0;
};

// Owns the submit pipeline: dispatching ride-create requests, and the full
// onSubmitHandler that resolves form values into one or more requests,
// handles OTP verification and the Paystack redirect flow.
export const useDispatchSubmit = (d: any) => {
  // Synchronous double-submit guard: set before any await, released on every
  // exit path. `searching` state alone is too late (it lands a render later).
  const inFlightRef = useRef(false);
  const safetyTimerRef = useRef<any>();
  // Legs (`:out` / `:ret`) already created for the current booking, so a
  // retry after a partial round-trip failure only sends the failed leg — even
  // against a ride service that doesn't dedupe on clientRequestId.
  const succeededLegsRef = useRef<{ [leg: string]: string }>({});

  const acquire = () => {
    if (inFlightRef.current) return false;
    inFlightRef.current = true;
    d.setSearching(true);
    return true;
  };

  const release = () => {
    inFlightRef.current = false;
    clearTimeout(safetyTimerRef.current);
    d.setSearching(false);
  };

  // One clientRequestId per form submission attempt: reused while the form
  // content is unchanged (a retry dedupes server-side), regenerated after a
  // success / form clear. A partially-booked round trip keeps its id.
  const getClientRequestId = (fingerprint: string) => {
    const current = d.clientRequestRef.current;
    if (
      current &&
      (current.fingerprint === fingerprint ||
        Object.keys(succeededLegsRef.current).length > 0)
    ) {
      current.fingerprint = fingerprint;
      return current.id;
    }
    const id = newClientRequestId();
    d.clientRequestRef.current = { id, fingerprint };
    return id;
  };

  const resetBooking = () => {
    d.clientRequestRef.current = undefined;
    succeededLegsRef.current = {};
  };

  const legKey = (request: any) =>
    request?.clientRequestId?.endsWith(RETURN_LEG_SUFFIX) ? "ret" : "out";

  // Sends one leg; always resolves with the parsed outcome.
  const sendRideRequest = (request: any, paymentRef: any) =>
    new Promise<any>((resolve) => {
      d.dispatch(
        CREATE_RIDE({
          requestData: { ...request, paymentRef },
          callback: (data: any, meta: any) => {
            const parsed = parseRideResponse(data, meta, { preferDetails: true });
            resolve({
              ok: parsed.ok && !!data?.pageId,
              pageId: data?.pageId,
              url: data?.url,
              code: parsed.code,
              message: parsed.message || "Ride request failed",
              request,
            });
          },
        })
      );
    });

  // Submits every leg, then reports one combined outcome. `stored` marks a
  // Paystack resume whose requests live in localStorage until created.
  const submitRequests = async (
    requests: any[],
    paymentRef: any,
    opts: { stored?: boolean; errorDuration?: number } = {}
  ) => {
    const isRoundTrip = requests.length > 1;
    const pending = requests.filter(
      (request) => !(isRoundTrip && succeededLegsRef.current[legKey(request)])
    );
    pending.forEach((request) => {
      const id = placeholderId(request);
      if (id) {
        emitRideSubmission({
          id,
          state: "pending",
          summary: placeholderSummary(request),
        });
      }
    });
    const results = await Promise.all(
      pending.map((request) => sendRideRequest(request, paymentRef))
    );
    results.forEach((result) => {
      const id = placeholderId(result.request);
      if (id) {
        emitRideSubmission(
          result.ok
            ? { id, state: "done", pageId: result.pageId?.toString() }
            : {
              id,
              state: "failed",
              summary: placeholderSummary(result.request),
              message: result.message,
              retry: () => retryRequests(requests, paymentRef, opts),
            }
        );
      }
      if (!result.ok) return;
      if (isRoundTrip) succeededLegsRef.current[legKey(result.request)] = result.pageId;
      if (opts.stored) removeStoredRequest(result.request);
    });
    const failed = results.filter((result) => !result.ok);
    const succeeded = results.filter((result) => result.ok);
    release();

    if (!failed.length) {
      pushNotification("Ride request submitted", "success", "TOP_CENTER", 1000);
      resetBooking();
      d.setSubmitIssue(undefined);
      if (opts.stored) {
        writeStoredRequests([]);
        const query = new URLSearchParams(window.location.search);
        if (query.has("reference")) {
          query.delete("reference");
          d.history.replace({ search: query.toString() });
        }
      }
      d.dispatch({ type: SET_SUBMITTED, payload: false });
      d.clearForm();
      d.setVerifyModal(undefined);
      const first = succeeded[0] || {};
      if (first.pageId) {
        setTimeout(() => notifyNativeBridge(first.pageId), 2000);
      }
      // Web booker: take the passenger straight to their ride page (the
      // same link they are sent). A return trip books twice; the first
      // reply redirects.
      if (d.webBooker && first.url) {
        setTimeout(() => window.location.assign(first.url), 1000);
      }
      return;
    }

    // Failure: keep the form, selected drivers and map pins as they are.
    d.dispatch({ type: "SET_ONLY_SUBMITTED", payload: false });

    if (failed.every((result) => result.code === RideErrorCode.DuplicateInProgress)) {
      pushNotification("Already submitting…", "info", "TOP_CENTER", 3000);
      return;
    }

    const stale = failed.find(
      (result) =>
        result.code === RideErrorCode.StaleUpdate ||
        result.code === RideErrorCode.InvalidState
    );
    if (stale?.request?.pageId) {
      d.reloadRide?.(stale.request.pageId, {
        resetForm: stale.code === RideErrorCode.StaleUpdate,
      });
    }

    const message = isRoundTrip
      ? [
        ...succeeded.map(
          (result) => `${legLabel(result.request?.clientRequestId)} was booked.`
        ),
        ...failed.map(
          (result) =>
            `${legLabel(result.request?.clientRequestId)} failed: ${result.message}`
        ),
      ].join(" ")
      : failed[0].message;

    const partial = isRoundTrip && Object.keys(succeededLegsRef.current).length > 0;
    const timedOut = failed.some((result) => result.code === RideErrorCode.Timeout);
    if (opts.stored || partial || timedOut) {
      // Persistent, with a Retry that resends only the failed legs under the
      // same clientRequestIds.
      d.setSubmitIssue({
        kind: opts.stored ? "payment" : "submit",
        message: partial
          ? `${message} Fix the form if needed and retry — the booked leg is not sent again.`
          : message,
        retry: () => retryRequests(requests, paymentRef, opts),
        dismiss: opts.stored
          ? () => {
            writeStoredRequests([]);
            const query = new URLSearchParams(window.location.search);
            query.delete("reference");
            d.history.replace({ search: query.toString() });
            d.setSubmitIssue(undefined);
          }
          : () => d.setSubmitIssue(undefined),
      });
    } else if (!stale || stale.code !== RideErrorCode.StaleUpdate) {
      pushNotification(message, "error", "TOP_CENTER", opts.errorDuration || 3000);
    } else {
      pushNotification(message, "warning", "TOP_CENTER", 6000);
    }
  };

  const retryRequests = (requests: any[], paymentRef: any, opts: any = {}) => {
    if (!acquire()) return;
    d.setSubmitIssue(undefined);
    submitRequests(requests, paymentRef, opts).catch((e) => {
      console.error("ride submit failed", e);
      release();
    });
  };

  // Paystack return: create the rides stored before the redirect. They stay
  // stored (per leg) until created, so a failure can be retried or survive a
  // reload; the same clientRequestIds are reused.
  const submitStoredRequests = (reference: string) => {
    const stored = readStoredRequests();
    if (!stored.length) return false;
    retryRequests(stored, reference, { stored: true, errorDuration: 5000 });
    return true;
  };

  // Kept for callers that submit a single prepared request.
  const submitRideRequest = (request: any, paymentRef: any, errorDuration = 3000) => {
    retryRequests([request], paymentRef, { errorDuration });
  };

  const onSubmitHandler = async (values: any, bookingOtp?: string) => {
    if (!acquire()) return;
    try {
      await runSubmit(values, bookingOtp);
    } catch (e: any) {
      release();
      if (e instanceof RideRequestValidationError) {
        pushNotification(e.message, "error", "TOP_CENTER", 4000);
      } else {
        console.error("ride submit failed", e);
        pushNotification(
          "Something went wrong. please refresh",
          "error",
          "TOP_CENTER",
          3000
        );
      }
    }
  };

  const runSubmit = async (values: any, bookingOtp?: string) => {
    if (d.standLocations?.length > 0) {
      release();
      return;
    }

    // Already verified to load the card on file: book with that code instead
    // of sending another one.
    if (!bookingOtp && d.webBooker) {
      bookingOtp = d.verifiedOtp;
    }

    const userId = d.encrypted_token?.userId;
    const pageId = d.ridePageId;
    const connectionId = d.encrypted_token?.connectionId;
    let responders = d.selectedResponders.map((responder: any) => {
      return {
        id: responder.id,
        beamId: responder.title,
      };
    });
    if (values["undefined"]) {
      values = values["undefined"];
    }
    values.pickupLocation.type = "incident-location";
    if (values.dropoffLocation) {
      values.dropoffLocation.type = "incident-location";
    }
    const extendedAttributes: any = {};
    Object.keys(values).map((key) => {
      const formattedObj = formatObject(key, key, values[key], [], {});

      if (Array.isArray(formattedObj)) {
        formattedObj?.map((obj) => {
          _.merge(extendedAttributes, obj);
        });
      } else {
        _.merge(extendedAttributes, formattedObj);
      }
    });

    const fareTypeValue = extendedAttributes?.fareType?.value;
    // Coupons are only offered on fixed fares; a stale reply from an earlier
    // fare type must not ride along on a meter / bid ride.
    const couponApplies =
      d.couponResponse?.status === true &&
      !!d.couponResponse?.data?.couponId &&
      (fareTypeValue === "fixed" || fareTypeValue === "fixedEstimate");
    const couponResponse = couponApplies ? d.couponResponse : undefined;

    const sortedAttributes: any = {
      ...extendedAttributes,
      accountName: d.accounts?.find((x: any) => {
        return x?.objectId?.toString() === extendedAttributes?.account;
      })?.info?.name,
      fixedFare:
        fareTypeValue === "fixed" || fareTypeValue === "bid"
          ? extendedAttributes?.fareType?.fare?.toString()
          : d.estimatedFare
            ? d.estimatedFare
            : undefined,
      // Display hint only; the ride service recomputes it from couponId.
      ...(couponApplies
        ? { discountedFare: couponResponse?.data?.discountedMeterFare }
        : {}),
      estimatedFare: fareTypeValue === "bid" ? d.estimatedFare : undefined,
      fareType:
        d.estimatedFare && fareTypeValue === "fixedEstimate"
          ? "fixed"
          : fareTypeValue,
      payType: extendedAttributes?.payType?.value ?? undefined,
      sharePassengerLink: values.sharePassengerLink,
      ...(d.webBooker
        ? {
          sharePassengerLink: true,
          ...(!d.projects?.webSettings?.webBookerMeterPayment
            ? {
              payType: "now",
            }
            : {}),
          verifyCustomer: true,
          bookingOtp,
        }
        : {}),
    };

    if (sortedAttributes?.payType === "now") {
      sortedAttributes["payWith"] = d.payWith;
    }

    // Keep which place (hotel etc.) the ride was booked from, on the ride and
    // in the saved form values.
    if (d.pickupReferenceRef.current) {
      sortedAttributes["pickupReference"] = d.pickupReferenceRef.current;
      values.pickupReference = d.pickupReferenceRef.current;
    }

    if (d.webBooker && !bookingOtp) {
      d.setVerifyModal(values);
      d.socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getVerifyCustomerPublishTopic(connectionId),
        wrapRequestPayload({
          notificationChannels: {
            phone: values?.passengerPhoneNumber,
            email: values?.passengerEmail,
          },
          userServiceId: d.projects?.userServiceId,
        }),
      undefined,
      undefined,
      { retryOnAckTimeout: false }
      );
      pushNotification(
        "Verification code sent on notification channels",
        "success",
        "TOP_CENTER",
        3000
      );
      release();
      return;
    }
    let vehicleDriver;
    Object.keys(sortedAttributes).map((key) => {
      if (sortedAttributes?.[key]?.type === "vehicle") {
        vehicleDriver = sortedAttributes?.[key]?.value;
      }
    });
    if (vehicleDriver) {
      responders.push({
        id: vehicleDriver,
        beamId: "",
      });
    }

    let fingerprint: string;
    try {
      fingerprint = JSON.stringify({
        values,
        pageId,
        update: d.submitPageId.current,
        responders,
        payWith: d.payWith,
        couponId: couponResponse?.data?.couponId,
      });
    } catch (e) {
      fingerprint = newClientRequestId();
    }
    const clientRequestId = getClientRequestId(fingerprint);

    const notices: string[] = [];
    const eventRequests = await buildRideRequests(sortedAttributes, values, {
      userId,
      connectionId,
      responders,
      pageId,
      submitPageId: d.submitPageId,
      webBooker: d.webBooker,
      encrypted_token: d.encrypted_token,
      projects: d.projects,
      locationTypeFare: d.locationTypeFare,
      couponResponse,
      bookingOtp,
      clientRequestId,
      expectedUpdatedAt: d.loadedUpdatedAtRef.current,
      timezone: getFleetTimezone(d.projects),
      onNotice: (message) => notices.push(message),
    });
    notices.forEach((message) =>
      pushNotification(message, "warning", "TOP_CENTER", 6000)
    );

    if (eventRequests.length > 0) {
      d.setError(undefined);
    } else {
      pushNotification(
        "Something went wrong. please refresh",
        "error",
        "TOP_CENTER",
        3000
      );
      release();
      return;
    }

    if (
      sortedAttributes?.payType === "now" &&
      d.payWith === "paystack" &&
      (!d.submitPageId.current ||
        !d.ridePageId ||
        (d.ridePageId &&
          d.selectedPage?.page?.paystack?.status !== "authorized"))
    ) {
      // One authorization covers every leg of the booking.
      const total = eventRequests.reduce(
        (sum, request) => sum + payableFare(request),
        0
      );
      if (!(total > 0)) {
        pushNotification("Unable to determine the fare to charge", "error", "TOP_CENTER", 4000);
        release();
        return;
      }
      const amount = Math.round(total * 100).toString();

      const request = {
        email: values?.passengerEmail,
        phone: values?.passengerPhoneNumber,
        amount,
        callback_url: window.location.href,
        validateCustomer: bookingOtp ? true : false,
        otp: bookingOtp,
        userServiceId: d.projects?.userServiceId,
      };

      // Stored before the redirect; each leg is removed once created.
      writeStoredRequests(eventRequests);
      safetyTimerRef.current = setTimeout(release, PAYSTACK_SAFETY_MS);

      d.dispatch(
        GET_PAYSTACK_TOKEN({
          request,
          onError: () => release(),
          callback: (resp: any) => {
            if (resp?.data?.status) {
              // Leaving the page: stay busy so nothing is submitted twice
              // (the safety timer still releases if navigation stalls).
              if (resp?.data?.data?.authorization_url) {
                window.location.href = resp?.data?.data?.authorization_url;
                return;
              }
              if (resp?.data?.data?.status === "authorized") {
                const url = new URL(window.location.href);
                url.searchParams.set("reference", resp?.data?.data?.reference);
                window.location.href = url.toString();
                return;
              }
              release();
              pushNotification("Payment failed", "error", "TOP_CENTER", 3000);
            } else {
              release();
              pushNotification(
                resp?.data?.details || "Payment failed",
                "error",
                "TOP_CENTER",
                3000
              );
            }
          },
        })
      );
      return;
    }

    await submitRequests(eventRequests, d.selectedPage?.page?.paystack?.reference);
  };

  return {
    onSubmitHandler,
    submitRideRequest,
    submitStoredRequests,
    inFlightRef,
    resetBooking,
  };
};
