import React, { FC, useEffect } from "react";
import { Link } from "react-router-dom";
import { Button } from "antd";
import {
  ArrowLeftOutlined,
  ArrowRightOutlined,
  CalendarOutlined,
  DownloadOutlined,
  EnvironmentOutlined,
  ExportOutlined,
  HeartFilled,
  HeartOutlined,
  LinkOutlined,
} from "@ant-design/icons";
import moment from "moment";

import { ProgramEvent, SectionDef } from "./data";
import { PROFILE_LABEL } from "./FilterBar";
import {
  copyEventLink,
  downloadIcs,
  EventFacts,
  eventPath,
  formatDates,
  priceLabel,
  useSaved,
} from "./eventUtils";

/**
 * One event's own page, at /programs/:section/:eventId. Visit opens the
 * event's Beam Vite site when the project names one.
 */
const EventPage: FC<{
  event: ProgramEvent;
  events: ProgramEvent[];
  sections: SectionDef[];
}> = ({ event, events, sections }) => {
  const { saved, toggle } = useSaved();
  const section = sections.find((s) => s.id === event.section);
  const isSaved = saved.includes(event.id);
  const start = moment(event.start);
  const price = priceLabel(event.price);
  const label = section?.label ?? "events";
  // "Clinics" -> "clinic"; a section named "Events" reads better as "event".
  const singular = label.toLowerCase().replace(/s$/, "") || "event";

  useEffect(() => {
    document.title = `${event.title} | Beam`;
  }, [event]);

  const more = events
    .filter((e) => e.section === event.section && e.id !== event.id)
    .sort((a, b) => a.start.localeCompare(b.start))
    .slice(0, 3);

  return (
    <div className="programs-eventpage programs-rise">
      <Link to={`/programs/${event.section}`} className="programs-back">
        <ArrowLeftOutlined /> All {label.toLowerCase()}
      </Link>

      <section className={`programs-eventpage__hero programs-eventpage__hero--${event.level}`}>
        <div className="programs-eventpage__date">
          <span>{start.format("MMM")}</span>
          <strong>{start.format("D")}</strong>
          <small>{start.format("ddd")}</small>
        </div>
        <div className="programs-eventpage__headline">
          <div className="programs-event__tags">
            <span className="programs-tag programs-tag--light">{PROFILE_LABEL[event.level]}</span>
            {event.ageGroups.length > 0 && (
              <span className="programs-tag programs-tag--light">{event.ageGroups.join(" · ")}</span>
            )}
          </div>
          <h1>{event.title}</h1>
          <p>
            <CalendarOutlined /> {formatDates(event)}
            {event.location && (
              <>
                <span className="programs-eventpage__sep" />
                <EnvironmentOutlined /> {event.location}
              </>
            )}
          </p>
        </div>
      </section>

      <div className="programs-eventpage__grid">
        <div className="programs-eventpage__main">
          <div className="programs-card programs-eventpage__block">
            <h2>About this {singular}</h2>
            {event.description && <p className="programs-eventpage__desc">{event.description}</p>}
            <EventFacts event={event} />
          </div>
        </div>

        <aside className="programs-card programs-eventpage__aside">
          {price && (
            <>
              <span className="programs-eventpage__price">{price}</span>
              <span className="programs-eventpage__per">per player</span>
            </>
          )}
          {event.url ? (
            <Button
              type="primary"
              size="large"
              block
              className="programs-btn"
              href={event.url}
              target="_blank"
              rel="noopener noreferrer"
            >
              Visit <ExportOutlined />
            </Button>
          ) : null}
          <div className="programs-eventpage__tools">
            <Button icon={isSaved ? <HeartFilled /> : <HeartOutlined />} onClick={() => toggle(event.id)}>
              {isSaved ? "Saved" : "Save"}
            </Button>
            <Button icon={<DownloadOutlined />} onClick={() => downloadIcs(event)}>
              Calendar
            </Button>
            <Button icon={<LinkOutlined />} onClick={() => copyEventLink(event)}>
              Share
            </Button>
          </div>
        </aside>
      </div>

      {more.length > 0 && (
        <section className="programs-eventpage__more">
          <h2>More {label.toLowerCase()}</h2>
          <div className="programs-more">
            {more.map((e) => (
              <Link key={e.id} to={eventPath(e)} className={`programs-more__item programs-more__item--${e.level}`}>
                <span className="programs-more__date">{moment(e.start).format("MMM D")}</span>
                <strong>{e.title}</strong>
                <span className="programs-more__meta">
                  {[PROFILE_LABEL[e.level], e.ageGroups.join(", ")].filter(Boolean).join(" · ")}
                </span>
                <span className="programs-more__price">
                  {priceLabel(e.price) ?? "Details"} <ArrowRightOutlined />
                </span>
              </Link>
            ))}
          </div>
        </section>
      )}
    </div>
  );
};

export default EventPage;
