// Zones and stands from the admin's fleetZones, with the drivers inside each.
//
// Stands have a first-in-first-out queue. dps-service records when a driver
// enters a geofence (`live.geofence.geofenceEnterAt`, returned on each
// responder as `geofence`), and the ride service dispatches a stand in that
// order (ride-dps-service candidate-finder, zone/geofence rings). queueFor
// reproduces that order so the board shows who dispatch will offer next.

export type AreaType = "stand" | "zone";

export interface ZoneArea {
  id: string;
  /** The geofence's own id, as recorded on the driver at entry. */
  geofenceId: string;
  name: string;
  type: AreaType;
  /** Responders whose live location is inside the area. */
  users: any[];
}

export interface QueueEntry {
  user: any;
  /** 1-based place in the stand queue; unset for drivers not queued. */
  position?: number;
  /** When the driver entered this stand, if dps-service recorded it. */
  enteredAt?: number;
}

const EARTH_RADIUS_M = 6371000;
const toRadians = (deg: number) => deg * (Math.PI / 180);

const insidePolygon = (lat: number, lng: number, polygon: number[][][]) => {
  const ring = polygon?.[0] ?? [];
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
};

const insideCircle = (lat: number, lng: number, center: number[], radius: number) => {
  const [cLng, cLat] = center;
  const dLat = toRadians(lat - cLat);
  const dLng = toRadians(lng - cLng);
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRadians(cLat)) * Math.cos(toRadians(lat)) * Math.sin(dLng / 2) ** 2;
  return EARTH_RADIUS_M * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)) <= radius;
};

export const isInsideGeofence = (lat: number, lng: number, geofence: any): boolean => {
  const location = geofence?.location;
  if (location?.type === "Polygon") return insidePolygon(lat, lng, location.coordinates);
  if (location?.type === "Point") {
    return insideCircle(lat, lng, location.coordinates, Number(geofence.radius) || 0);
  }
  return false;
};

const userPosition = (user: any): { lat: number; lng: number } | undefined => {
  const coords = user?.location?.geoJson?.features?.[0]?.geometry?.coordinates;
  if (typeof coords?.[0] !== "number" || typeof coords?.[1] !== "number") return undefined;
  return { lat: coords[1], lng: coords[0] };
};

/** Available and not held back, as the ride service decides who to offer. */
export const isQueueEligible = (user: any) =>
  user?.status === "green" &&
  user?.isBlocked !== true &&
  user?.isBlocked !== 1 &&
  user?.dispatchReserved !== true &&
  user?.dispatchReserved !== 1;

/** One area per distinct zone / stand geofence, with the responders inside. */
export const buildAreas = (fleetZones: any, responders: any[] = []): ZoneArea[] => {
  const areas = new Map<string, ZoneArea & { geofence: any }>();
  Object.values(fleetZones || {}).forEach((item: any) => {
    (
      [
        ["zone", item?.zoneGeofenceId],
        ["stand", item?.standGeofenceId],
      ] as [AreaType, any][]
    ).forEach(([type, geofence]) => {
      if (!geofence?.name) return;
      const geofenceId = `${geofence._id ?? geofence.name}`;
      const id = `${type}:${geofenceId}`;
      if (!areas.has(id)) {
        areas.set(id, { id, geofenceId, name: geofence.name, type, users: [], geofence });
      }
    });
  });
  areas.forEach((area) => {
    area.users = responders.filter((user) => {
      const at = userPosition(user);
      return !!at && isInsideGeofence(at.lat, at.lng, area.geofence);
    });
  });
  return Array.from(areas.values()).map(({ geofence, ...area }) => area);
};

/** When the driver entered this area, if that is the geofence on record. */
export const enteredAt = (user: any, area: ZoneArea): number | undefined => {
  const g = user?.geofence;
  const t = Number(g?.geofenceEnterAt);
  return `${g?.geofenceId ?? ""}` === area.geofenceId && Number.isFinite(t) ? t : undefined;
};

/**
 * Stand queue: eligible drivers by entry time (no recorded entry = back of
 * the queue, service order kept), then everyone else in the stand unnumbered.
 * Zones have no queue: every driver is listed unnumbered.
 */
export const queueFor = (area: ZoneArea): QueueEntry[] => {
  if (area.type !== "stand") {
    return area.users.map((user) => ({ user, enteredAt: enteredAt(user, area) }));
  }
  const queued = area.users
    .map((user, index) => ({ user, index, at: enteredAt(user, area) }))
    .filter(({ user }) => isQueueEligible(user))
    .sort((a, b) => (a.at ?? Infinity) - (b.at ?? Infinity) || a.index - b.index)
    .map(({ user, at }, i) => ({ user, enteredAt: at, position: i + 1 }));
  const others = area.users
    .filter((user) => !isQueueEligible(user))
    .map((user) => ({ user, enteredAt: enteredAt(user, area) }));
  return [...queued, ...others];
};

/** Drivers in the stand queue (zones: available drivers inside). */
export const availableCount = (area: ZoneArea) => area.users.filter(isQueueEligible).length;
