import React, { FC, useMemo, useState } from "react";
import {
  Alert,
  Checkbox,
  DatePicker,
  Form,
  Input,
  InputNumber,
  List,
  Modal,
  Radio,
  Select,
  Switch,
  Table,
  Tag,
  Tooltip,
} from "antd";

import { LedgerAction, LedgerRow } from "./types";
import { FLAG_COLORS, FLAG_LABELS, formatMoney } from "./selectors";

const { TextArea } = Input;
const { Option } = Select;

/**
 * What an executive action is aimed at. The spec requires every action
 * to work at the macro project level and the micro individual level;
 * both arrive here as a list of affected ledger rows.
 */
export interface ActionTarget {
  level: "project" | "individual";
  label: string;
  rows: LedgerRow[];
}

const TITLES: Record<LedgerAction, string> = {
  flags: "Account Flags",
  refund: "Issue Refund",
  schedule: "Reschedule (CFO Override)",
  discount: "Apply Discount / Aid",
  cancel: "Cancel Registration",
  notify: "Send Notification",
};

interface Props {
  action: LedgerAction | null;
  target: ActionTarget | null;
  currency: string;
  onClose: () => void;
}

/**
 * The executive action engine.
 *
 * Every modal carries the real input set the action needs, but nothing
 * is submitted: no write endpoint exists for CFO overrides yet, so the
 * confirm button stays disabled and says why.
 */
const ActionModals: FC<Props> = ({ action, target, currency, onClose }) => {
  const [refundMode, setRefundMode] = useState<"full" | "prorated" | "credit">(
    "full"
  );
  const [retainFee, setRetainFee] = useState(true);
  const [scheduleMode, setScheduleMode] = useState<"move" | "grace" | "plan">(
    "move"
  );
  const [aidKind, setAidKind] = useState<"discount" | "scholarship">("discount");
  const [amountType, setAmountType] = useState<"fixed" | "percentage">("fixed");
  const [channels, setChannels] = useState<string[]>(["email"]);

  const money = (value: number) => formatMoney(value, currency);

  const totals = useMemo(() => {
    const rows = target ? target.rows : [];
    return rows.reduce(
      (acc, row) => ({
        collected: acc.collected + row.collected,
        outstanding: acc.outstanding + row.outstanding,
        pastDue: acc.pastDue + row.pastDue,
      }),
      { collected: 0, outstanding: 0, pastDue: 0 }
    );
  }, [target]);

  if (!action || !target) return null;

  const rowCount = target.rows.length;
  const scopeNote =
    target.level === "project"
      ? `${rowCount} account${rowCount === 1 ? "" : "s"} in ${target.label}`
      : target.label;

  const body = () => {
    switch (action) {
      case "flags": {
        const flagged = target.rows.filter((row) => row.flags.length > 0);
        if (flagged.length === 0) {
          return <Alert type="success" message="No open flags on this selection." />;
        }
        return (
          <List
            dataSource={flagged}
            renderItem={(row) => (
              <List.Item>
                <List.Item.Meta
                  title={
                    <span>
                      {row.entity}
                      <span className="cfo-muted"> - {row.project}</span>
                    </span>
                  }
                  description={
                    <div className="cfo-flag-list">
                      {row.flags.map((flag) => (
                        <div key={flag.kind} className="cfo-flag-list__item">
                          <Tag color={FLAG_COLORS[flag.kind]}>
                            {FLAG_LABELS[flag.kind]}
                          </Tag>
                          <span>{flag.note}</span>
                        </div>
                      ))}
                    </div>
                  }
                />
                <div className="cfo-flag-list__amount">
                  {row.pastDue > 0 ? money(row.pastDue) : money(row.outstanding)}
                </div>
              </List.Item>
            )}
          />
        );
      }

      case "refund":
        return (
          <Form layout="vertical">
            <Form.Item label="Refund type">
              <Radio.Group
                value={refundMode}
                onChange={(e) => setRefundMode(e.target.value)}
              >
                <Radio.Button value="full">Full reversal</Radio.Button>
                <Radio.Button value="prorated">Prorated mid-term</Radio.Button>
                <Radio.Button value="credit">Household credit</Radio.Button>
              </Radio.Group>
            </Form.Item>
            <Form.Item label={`Amount (${currency})`}>
              <InputNumber
                style={{ width: "100%" }}
                min={0}
                defaultValue={totals.collected}
                disabled={refundMode === "full"}
              />
            </Form.Item>
            <Form.Item label="Reason (audit trail)">
              <Select defaultValue="withdrawal">
                <Option value="injury">Season-ending injury</Option>
                <Option value="relocation">Relocation</Option>
                <Option value="cancellation">Program cancellation</Option>
                <Option value="withdrawal">Withdrawal</Option>
              </Select>
            </Form.Item>
            <Form.Item label="Retain non-refundable processing fee">
              <Switch checked={retainFee} onChange={setRetainFee} />
              {retainFee && (
                <InputNumber
                  className="cfo-inline-number"
                  min={0}
                  defaultValue={45}
                  addonBefore="Fee"
                />
              )}
            </Form.Item>
            <Form.Item label="Internal note">
              <TextArea rows={2} placeholder="Visible to finance staff only" />
            </Form.Item>
          </Form>
        );

      case "schedule":
        return (
          <Form layout="vertical">
            <Form.Item label="Override">
              <Radio.Group
                value={scheduleMode}
                onChange={(e) => setScheduleMode(e.target.value)}
              >
                <Radio.Button value="move">Move due date</Radio.Button>
                <Radio.Button value="grace">Extend grace hours</Radio.Button>
                <Radio.Button value="plan">Hardship plan</Radio.Button>
              </Radio.Group>
            </Form.Item>

            {scheduleMode === "move" && (
              <Form.Item label="New milestone due date">
                <DatePicker style={{ width: "100%" }} />
              </Form.Item>
            )}

            {scheduleMode === "grace" && (
              <Form.Item
                label="Extend grace period"
                extra="Counted in hours, matching the dunning benchmarks (24h / 120h / 240h / 336h)."
              >
                <InputNumber
                  style={{ width: "100%" }}
                  min={0}
                  step={24}
                  defaultValue={72}
                  addonAfter="hours"
                />
              </Form.Item>
            )}

            {scheduleMode === "plan" && (
              <>
                <Form.Item label="Split remaining balance into">
                  <InputNumber
                    style={{ width: "100%" }}
                    min={2}
                    max={12}
                    defaultValue={3}
                    addonAfter="installments"
                  />
                </Form.Item>
                <Form.Item label="First installment due">
                  <DatePicker style={{ width: "100%" }} />
                </Form.Item>
              </>
            )}

            <Alert
              type="info"
              showIcon
              message={`Remaining balance in scope: ${money(
                totals.outstanding + totals.pastDue
              )}`}
            />
          </Form>
        );

      case "discount":
        return (
          <Form layout="vertical">
            <Form.Item label="Grant as">
              <Radio.Group
                value={aidKind}
                onChange={(e) => setAidKind(e.target.value)}
              >
                <Radio.Button value="discount">Discount voucher</Radio.Button>
                <Radio.Button value="scholarship">
                  Scholarship / financial aid
                </Radio.Button>
              </Radio.Group>
            </Form.Item>
            <Form.Item label="Amount type">
              <Radio.Group
                value={amountType}
                onChange={(e) => setAmountType(e.target.value)}
              >
                <Radio.Button value="fixed">Fixed</Radio.Button>
                <Radio.Button value="percentage">Percentage</Radio.Button>
              </Radio.Group>
            </Form.Item>
            <Form.Item
              label="Value"
              extra={
                amountType === "percentage"
                  ? "0-100% of the running total. 100% clears the balance without a gateway fee."
                  : `Fixed amount in ${currency}.`
              }
            >
              <InputNumber
                style={{ width: "100%" }}
                min={0}
                max={amountType === "percentage" ? 100 : undefined}
                defaultValue={amountType === "percentage" ? 50 : 100}
                addonAfter={amountType === "percentage" ? "%" : currency}
              />
            </Form.Item>
            {aidKind === "discount" && (
              <Form.Item label="Voucher code (optional)">
                <Input placeholder="e.g. CFO-HARDSHIP-26" />
              </Form.Item>
            )}
            {aidKind === "scholarship" && (
              <Form.Item label="Award conditions">
                <Checkbox defaultChecked>Requires admin approval</Checkbox>
                <Checkbox>Requires proof documents</Checkbox>
              </Form.Item>
            )}
            <Form.Item label="Note shown to the payer">
              <TextArea rows={2} />
            </Form.Item>
          </Form>
        );

      case "cancel":
        return (
          <Form layout="vertical">
            <Alert
              type="warning"
              showIcon
              className="cfo-modal-alert"
              message={`This terminates ${scopeNote}.`}
              description="Future milestone draws are cancelled and operational credentials are updated."
            />
            <Form.Item label="Effective date">
              <DatePicker style={{ width: "100%" }} />
            </Form.Item>
            <Form.Item label="Set credential status to">
              <Select defaultValue="CANCELLED">
                <Option value="CANCELLED">CANCELLED</Option>
                <Option value="WITHDRAWN">WITHDRAWN</Option>
              </Select>
            </Form.Item>
            <Form.Item label="Reason">
              <Select defaultValue="withdrawal">
                <Option value="injury">Season-ending injury</Option>
                <Option value="relocation">Relocation</Option>
                <Option value="cancellation">Program cancellation</Option>
                <Option value="withdrawal">Voluntary withdrawal</Option>
              </Select>
            </Form.Item>
            <Form.Item>
              <Checkbox defaultChecked>
                Cancel all future installment draws
              </Checkbox>
              <br />
              <Checkbox>
                Refund the collected balance ({money(totals.collected)})
              </Checkbox>
            </Form.Item>
          </Form>
        );

      case "notify":
      default:
        return (
          <Form layout="vertical">
            <Form.Item label="Channels">
              <Checkbox.Group
                value={channels}
                onChange={(values) => setChannels(values as string[])}
                options={[
                  { label: "Email", value: "email" },
                  { label: "SMS", value: "sms" },
                  { label: "BeamLive Page Push", value: "push" },
                ]}
              />
            </Form.Item>
            <Form.Item label="Template">
              <Select defaultValue="past-due">
                <Option value="pre-due">Pre-due reminder</Option>
                <Option value="due-today">Due today</Option>
                <Option value="past-due">Past-due escalation</Option>
                <Option value="suspension">Suspension warning</Option>
                <Option value="aid-docs">Missing aid documents</Option>
              </Select>
            </Form.Item>
            <Form.Item
              label="Message"
              extra="Variables: {{amount}} {{player}} {{dueDate}} {{invoiceId}} {{org}} {{daysPastDue}}"
            >
              <TextArea
                rows={4}
                defaultValue={
                  "Hi {{player}}, your balance of {{amount}} for {{org}} was due on {{dueDate}}. Invoice {{invoiceId}}."
                }
              />
            </Form.Item>
            <Alert
              type="info"
              showIcon
              message={`Will be sent to ${rowCount} recipient${
                rowCount === 1 ? "" : "s"
              } on ${channels.length} channel${
                channels.length === 1 ? "" : "s"
              }.`}
            />
          </Form>
        );
    }
  };

  return (
    <Modal
      visible
      title={
        <div className="cfo-action-modal__title">
          <span>{TITLES[action]}</span>
          <Tag color={target.level === "project" ? "geekblue" : "purple"}>
            {target.level === "project" ? "Project level" : "Individual"}
          </Tag>
          <span className="cfo-action-modal__scope">{scopeNote}</span>
        </div>
      }
      onCancel={onClose}
      width={action === "flags" ? 720 : 560}
      okText={action === "flags" ? "Close" : "Confirm"}
      onOk={onClose}
      okButtonProps={
        action === "flags"
          ? undefined
          : { disabled: true, title: "No write endpoint yet" }
      }
      cancelButtonProps={action === "flags" ? { style: { display: "none" } } : undefined}
      footer={
        action === "flags"
          ? undefined
          : [
              <button
                key="cancel"
                type="button"
                className="ant-btn"
                onClick={onClose}
              >
                Cancel
              </button>,
              <Tooltip
                key="confirm"
                title="Read-only preview - CFO override endpoints are not built yet."
              >
                <span>
                  <button type="button" className="ant-btn ant-btn-primary" disabled>
                    Confirm
                  </button>
                </span>
              </Tooltip>,
            ]
      }
    >
      {target.rows.length > 1 && action !== "flags" && (
        <Table
          className="cfo-action-scope"
          size="small"
          rowKey="key"
          pagination={false}
          scroll={{ y: 140 }}
          dataSource={target.rows}
          columns={[
            { title: "Entity", dataIndex: "entity", key: "entity" },
            {
              title: "Balance",
              key: "balance",
              align: "right",
              render: (_: unknown, row: LedgerRow) =>
                money(row.outstanding + row.pastDue),
            },
          ]}
        />
      )}
      {body()}
    </Modal>
  );
};

export default ActionModals;
