/**
 * The send-payment-request draft: how it is created from a target and
 * how a recipient's effective request and amount are resolved.
 */
import {
  AppliedAdjustments,
  MemberRequest,
  PaymentRequestDraft,
  PaymentRequestTarget,
  ProjectMember,
} from "../types";
import { getPaymentConfig, getProjectMembers } from "../mockData";
import { EMPTY_APPLIED, cloneConfig, computeAmountDue, round2 } from "../paymentConfig";

/** Which flavour of request the wizard is running. */
export type WizardMode = "project" | "individual" | "payee";

export const wizardModeOf = (target: PaymentRequestTarget | null): WizardMode => {
  if (!target) return "project";
  if (target.payee) return "payee";
  return target.focusMemberIds && target.focusMemberIds.length > 0 ? "individual" : "project";
};

/** The recipients listed in step 2: the roster, or the payee alone. */
export const membersFor = (target: PaymentRequestTarget | null): ProjectMember[] => {
  if (!target) return [];
  if (target.payee) {
    const p = target.payee;
    return [{ id: p.id, name: p.name, role: p.role, household: p.category || p.department || "" }];
  }
  if (!target.project) return [];
  const focus = target.focusMemberIds || [];
  const roster = getProjectMembers(target.project.id).slice();
  /* The member the CFO clicked on sits at the top. */
  roster.sort((a, b) => {
    const af = focus.indexOf(a.id) !== -1 ? 0 : 1;
    const bf = focus.indexOf(b.id) !== -1 ? 0 : 1;
    return af - bf;
  });
  return roster;
};

/**
 * A fresh draft: a deep clone of the stored configuration (or payout
 * terms), everyone preselected unless the target focuses on one member.
 * Null when nothing is attached to bill against.
 */
export const createDraft = (target: PaymentRequestTarget | null): PaymentRequestDraft | null => {
  if (!target) return null;

  if (target.payee) {
    const stored = getPaymentConfig(target.payee.paymentConfigId);
    if (!stored) return null;
    const config = cloneConfig(stored);
    const owed = target.payee.billing.outstanding + target.payee.billing.pastDue;
    /* Payout terms describe cadence, not a per-payee figure: bill what is owed. */
    config.totalAmount = round2(owed > 0 ? owed : target.payee.billing.billed);
    return {
      mode: "same",
      config,
      applied: { ...EMPTY_APPLIED },
      overrides: {},
      recipientIds: [target.payee.id],
      saveToProject: false,
    };
  }

  if (!target.project) return null;
  const stored = getPaymentConfig(target.project.paymentConfigId);
  if (!stored) return null;
  const focus = target.focusMemberIds || [];
  const members = membersFor(target);
  return {
    mode: focus.length > 0 ? "custom" : "same",
    config: cloneConfig(stored),
    applied: { ...EMPTY_APPLIED },
    overrides: {},
    recipientIds: focus.length > 0 ? focus : members.map((m) => m.id),
    saveToProject: false,
  };
};

export const groupRequest = (draft: PaymentRequestDraft): MemberRequest => ({
  config: draft.config,
  applied: draft.applied,
  note: "",
});

/** What one recipient actually gets: their override, or the group request. */
export const effectiveRequest = (draft: PaymentRequestDraft, memberId: string): MemberRequest =>
  (draft.mode === "custom" && draft.overrides[memberId]) || groupRequest(draft);

export const amountOf = (request: MemberRequest, registeredAt?: number): number =>
  computeAmountDue(request.config, request.applied, registeredAt).total;

export const amountFor = (draft: PaymentRequestDraft, memberId: string): number =>
  amountOf(effectiveRequest(draft, memberId));

export const requestTotal = (draft: PaymentRequestDraft): number =>
  round2(draft.recipientIds.reduce((acc, id) => acc + amountFor(draft, id), 0));

/** Seed for the per-member customise modal. */
export const seedMemberRequest = (draft: PaymentRequestDraft, memberId: string): MemberRequest => {
  const existing = draft.overrides[memberId];
  if (existing) {
    return { config: cloneConfig(existing.config), applied: { ...existing.applied }, note: existing.note };
  }
  return { config: cloneConfig(draft.config), applied: { ...draft.applied }, note: "" };
};

export const withApplied = (
  applied: AppliedAdjustments,
  changes: Partial<AppliedAdjustments>
): AppliedAdjustments => ({ ...applied, ...changes });
