import { useCallback, useEffect, useRef } from "react";
import { useDispatch } from "react-redux";
import moment from "moment-timezone";
import type { PillTone } from "../../common/ui";
import {
  CREATE_SCHEDULE,
  DELETE_SCHEDULE,
  UPDATE_SCHEDULE,
} from "../../../../../reducers/reducer";

// Driver reminder notifications, stored in the scheduler service with
// partitions `org:<id>` and `type:notification`. `data` is what the scheduler
// publishes to dps `sendReminderNotification` on every cron tick.

export const SCHEDULE_TIME_FORMAT = "MM/DD/YYYY HH:mm";
const REQUEST_TIMEOUT_MS = 20000;

/** Stored as full day names, in this order. `cron` is the cron day-of-week (Sun = 0). */
export const DAYS = [
  { name: "Monday", short: "Mon", cron: 1 },
  { name: "Tuesday", short: "Tue", cron: 2 },
  { name: "Wednesday", short: "Wed", cron: 3 },
  { name: "Thursday", short: "Thu", cron: 4 },
  { name: "Friday", short: "Fri", cron: 5 },
  { name: "Saturday", short: "Sat", cron: 6 },
  { name: "Sunday", short: "Sun", cron: 0 },
];
const WEEKDAYS = DAYS.slice(0, 5).map((d) => d.name);
const WEEKEND = DAYS.slice(5).map((d) => d.name);

export type Channel = "push" | "email" | "sms";

export const CHANNELS: Record<Channel, { label: string; tone: PillTone; noun: string }> = {
  push: { label: "Push", tone: "blue", noun: "Push notification" },
  email: { label: "Email", tone: "purple", noun: "Email" },
  sms: { label: "SMS", tone: "green", noun: "SMS" },
};

export interface NotificationData {
  name?: string;
  daysOfTheWeek?: string[];
  scheduleTime?: string;
  notificationType?: Channel;
  drivers?: Record<string, { userId: string; beamId?: string }>;
  timezone?: string;
  cudbServiceId?: string;
}

/** A list row as the list and the editor pass it around (legacy `student` prop shape). */
export interface NotificationRecord {
  scheduleId: string;
  data: NotificationData;
}

/** Selected days in Monday-first order, dropping anything unknown. */
export const sortDays = (days?: string[]) =>
  DAYS.filter((d) => (days || []).includes(d.name)).map((d) => d.name);

const sameDays = (a: string[], b: string[]) =>
  a.length === b.length && a.every((d) => b.includes(d));

const joinAnd = (parts: string[]) =>
  parts.length < 2 ? parts.join("") : `${parts.slice(0, -1).join(", ")} & ${parts[parts.length - 1]}`;

/** "Every day", "Weekdays", "Weekends" or "Mon, Wed". */
export const describeDays = (days?: string[]) => {
  const sorted = sortDays(days);
  if (!sorted.length) return "No days";
  if (sorted.length === 7) return "Every day";
  if (sameDays(sorted, WEEKDAYS)) return "Weekdays";
  if (sameDays(sorted, WEEKEND)) return "Weekends";
  return sorted.map((d) => DAYS.find((x) => x.name === d)!.short).join(", ");
};

/** Phrase for the preview sentence: "every day", "every Mon & Wed". */
const daysPhrase = (days: string[]) => {
  const sorted = sortDays(days);
  if (sorted.length === 7) return "every day";
  if (sameDays(sorted, WEEKDAYS)) return "every weekday";
  if (sameDays(sorted, WEEKEND)) return "every Sat & Sun";
  return `every ${joinAnd(sorted.map((d) => DAYS.find((x) => x.name === d)!.short))}`;
};

/** Parses the stored local "MM/DD/YYYY HH:mm" time (older rows may use other formats). */
export const parseScheduleTime = (value?: string) => {
  if (!value) return undefined;
  const strict = moment(value, SCHEDULE_TIME_FORMAT, true);
  if (strict.isValid()) return strict;
  const loose = moment(new Date(value));
  return loose.isValid() ? loose : undefined;
};

export const formatScheduleTime = (value?: string) =>
  parseScheduleTime(value)?.format("HH:mm");

/** "Mon, Wed at 09:30" */
export const describeSchedule = (data?: NotificationData) => {
  const time = formatScheduleTime(data?.scheduleTime);
  const days = describeDays(data?.daysOfTheWeek);
  return time ? `${days} at ${time}` : days;
};

/** "Push notification every Mon & Wed at 09:30 to 3 drivers", or undefined while incomplete. */
export const previewSentence = (
  channel?: Channel,
  days?: string[],
  scheduleTime?: string,
  driverCount = 0
) => {
  const time = formatScheduleTime(scheduleTime);
  if (!channel || !days?.length || !time) return undefined;
  const who = driverCount
    ? ` to ${driverCount} ${driverCount === 1 ? "driver" : "drivers"}`
    : "";
  return `${CHANNELS[channel]?.noun || "Notification"} ${daysPhrase(days)} at ${time}${who}`;
};

/**
 * Cron for the scheduler service (npm `cron`, UTC server clock): minute and
 * hour of the local time converted to UTC, and the selected days as cron
 * day-of-week numbers (0-6, Sun = 0).
 *
 * Days are not shifted when the UTC conversion crosses midnight on purpose:
 * dps `sendReminderNotification` re-checks `daysOfTheWeek` against the server's
 * (UTC) weekday, so a shifted cron would never pass that check.
 */
export const buildCron = (scheduleTime: string, days: string[], timezone: string) => {
  const time = parseScheduleTime(scheduleTime)?.format("HH:mm") || "00:00";
  // Today's offset, so re-saving picks up daylight-saving changes.
  const today = moment.tz(timezone).format("MM/DD/YYYY");
  const utc = moment.tz(`${today} ${time}`, SCHEDULE_TIME_FORMAT, timezone).utc();
  const selected = DAYS.filter((d) => days.includes(d.name));
  const dayOfWeek =
    selected.length && selected.length < 7
      ? selected
          .map((d) => d.cron)
          .sort((a, b) => a - b)
          .join(",")
      : "*";
  return `${utc.minutes()} ${utc.hours()} * * ${dayOfWeek}`;
};

type Outcome = { ok: true; response: any } | { ok: false };

/**
 * CREATE/UPDATE/DELETE_SCHEDULE as promises. The sagas never call back on
 * failure (they show their own error toast), so each call settles with
 * `{ ok: false }` after a timeout and saving spinners always reset.
 */
export const useScheduleApi = () => {
  const dispatch = useDispatch();
  const timers = useRef<any[]>([]);

  useEffect(
    () => () => {
      timers.current.forEach(clearTimeout);
      timers.current = [];
    },
    []
  );

  const run = useCallback(
    (action: any, request: any) =>
      new Promise<Outcome>((resolve) => {
        let settled = false;
        const timer = setTimeout(() => {
          if (settled) return;
          settled = true;
          resolve({ ok: false });
        }, REQUEST_TIMEOUT_MS);
        timers.current.push(timer);
        dispatch(
          action({
            request,
            callback: (response: any) => {
              if (settled) return;
              settled = true;
              clearTimeout(timer);
              resolve({ ok: true, response });
            },
          })
        );
      }),
    [dispatch]
  );

  return {
    createSchedule: useCallback((request: any) => run(CREATE_SCHEDULE, request), [run]),
    updateSchedule: useCallback((request: any) => run(UPDATE_SCHEDULE, request), [run]),
    deleteSchedule: useCallback((request: any) => run(DELETE_SCHEDULE, request), [run]),
  };
};
