import { getDecryptedPayload } from "../../../../services/apis/collections/oAuthApis";

/**
 * The organization ids a `?token=` carries once decrypted. The decrypt service
 * answers an org token with `{ userId, connectionId, cudbServiceId | serviceId }`
 * — the CUDB org id (the `{org}-api.staging.beam.live` subdomain) and the config
 * user the page reads projects from. `serviceId` holds that CUDB org id after
 * mapping, see `decryptProgramsToken`.
 */
export interface DecodedToken {
  serviceId?: string;
  userId?: string;
  connectionId?: string;
}

/**
 * Decrypts the `?token=` into its organization ids, reusing the app's existing
 * decrypt service (POST /decryptPayloadTopic via `getDecryptedPayload`).
 *
 * Returns `null` for a missing, invalid or undecryptable token so the caller
 * can fall back to its defaults instead of breaking: the service answers a bad
 * token with `status:false` and no `decryptedPayload`, and any transport error
 * is swallowed here.
 */
export const decryptProgramsToken = async (token: string): Promise<DecodedToken | null> => {
  const value = token.trim();
  if (!value) return null;

  try {
    // getDecryptedPayload posts the body as-is and returns the parsed envelope
    // `{ data: { decryptedPayload }, status, message }`.
    const response: any = await getDecryptedPayload({ payload: value } as any);
    const raw = response?.data?.decryptedPayload;
    if (typeof raw !== "string") return null;

    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return null;

    console.log("Programs: decrypted token payload", parsed);

    return {
      // The CUDB org that becomes the `{org}-api.staging.beam.live` subdomain.
      // Same precedence the School module uses: `cudbServiceId`, then `serviceId`.
      serviceId: parsed.cudbServiceId ?? parsed.serviceId,
      userId: parsed.userId,
      connectionId: parsed.connectionId,
    };
  } catch {
    // A network failure or malformed payload is treated as "no token".
    return null;
  }
};
