import React, { FC } from "react";

import { BridgeStep, formatMoneyShort, formatSigned } from "../selectors";
import { ChartApi } from "./ChartFrame";
import { barPath, linearScale, niceTicks, tickText, useElementWidth } from "./scale";
import { CHART_COLORS, MARK } from "./theme";

interface Props {
  steps: BridgeStep[];
  currency: string;
  api: ChartApi;
  height?: number;
}

const MARGIN = { top: 26, right: 12, bottom: 26, left: 56 };

/**
 * Revenue bridge: totals rise above the zero line, deductions and
 * refunds drop below it. Six headline figures, so every column is
 * labelled at its data end.
 */
const WaterfallChart: FC<Props> = ({ steps, currency, api, height = 260 }) => {
  const [ref, width] = useElementWidth();
  const plotW = Math.max(0, width - MARGIN.left - MARGIN.right);
  const plotH = height - MARGIN.top - MARGIN.bottom;

  const maxUp = Math.max(...steps.filter((s) => s.signed >= 0).map((s) => s.signed), 0);
  const maxDown = Math.max(...steps.filter((s) => s.signed < 0).map((s) => -s.signed), 0);
  const upTicks = niceTicks(maxUp, 4);
  const downTicks = maxDown > 0 ? niceTicks(maxDown, 1) : [0];
  const top = upTicks[upTicks.length - 1];
  const bottom = -downTicks[downTicks.length - 1];
  const ticks = downTicks.slice(1).map((t) => -t).reverse().concat(upTicks);

  const y = linearScale([bottom, top], [MARGIN.top + plotH, MARGIN.top]);
  const band = steps.length > 0 ? plotW / steps.length : 0;
  const barW = Math.min(MARK.barMax, band * 0.5);
  const xOf = (i: number) => MARGIN.left + band * i + (band - barW) / 2;
  const zero = y(0);

  return (
    <div ref={ref} className="cfo-chart__svg-wrap">
      {width > 0 && (
        <svg width={width} height={height} className="cfo-chart__svg">
          {ticks.map((tick) => (
            <g key={tick}>
              <line
                x1={MARGIN.left}
                x2={width - MARGIN.right}
                y1={y(tick)}
                y2={y(tick)}
                className={tick === 0 ? "cfo-chart__baseline" : "cfo-chart__grid"}
              />
              <text x={MARGIN.left - 8} y={y(tick)} dy="0.35em" textAnchor="end" className="cfo-chart__tick">
                {tick < 0 ? "-" : ""}
                {tickText(Math.abs(tick), currency)}
              </text>
            </g>
          ))}

          {steps.map((step, i) => {
            const negative = step.signed < 0;
            const barTop = negative ? zero : y(step.signed);
            const h = Math.max(0, Math.abs(y(step.signed) - zero));
            const color = negative ? CHART_COLORS.orange : CHART_COLORS.purple;
            const labelY = negative ? zero + h + 14 : barTop - 6;
            const rows = [
              { label: negative ? "Deducted" : "Amount", value: formatSigned(step.signed, currency) },
              { label: "Previous period", value: formatSigned(step.signedPrevious, currency) },
              {
                label: "Change",
                value: `${step.change >= 0 ? "+" : ""}${formatSigned(step.change, currency)}${
                  step.changePct === null ? "" : ` (${step.changePct >= 0 ? "+" : ""}${step.changePct}%)`
                }`,
              },
            ];
            const show = () => api.show({ x: xOf(i) + barW / 2, y: Math.min(barTop, zero) - 6, title: step.label, rows });
            return (
              <g key={step.key}>
                <path d={barPath(xOf(i), barTop, barW, h, MARK.radius, negative ? "bottom" : "top")} fill={color} />
                <text x={xOf(i) + barW / 2} y={labelY} textAnchor="middle" className="cfo-chart__value">
                  {negative ? "-" : ""}
                  {formatMoneyShort(step.value, currency)}
                </text>
                <text x={MARGIN.left + band * i + band / 2} y={height - 8} textAnchor="middle" className="cfo-chart__label">
                  {step.label}
                </text>
                <rect
                  x={MARGIN.left + band * i}
                  y={MARGIN.top - 16}
                  width={band}
                  height={plotH + 16}
                  fill="transparent"
                  tabIndex={0}
                  aria-label={`${step.label} ${formatSigned(step.signed, currency)}`}
                  onMouseEnter={show}
                  onFocus={show}
                  onMouseLeave={api.hide}
                  onBlur={api.hide}
                />
              </g>
            );
          })}
        </svg>
      )}
    </div>
  );
};

export default WaterfallChart;
