import React, { FC, useEffect, useMemo, useState } from "react";
import { Button, Form, Input } from "antd";
import type { ColumnsType } from "antd/es/table";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import EditPricingModal from "./EditPricingModal";
import { PLAN_NAME_MAX } from "./PricingTables";
import {
  collectionPath,
  itemPath,
  nameKey,
  useAdminItems,
  useAdminUserUpdate,
} from "./adminCollection";
import {
  DataTableCard,
  EmptyState,
  FormModal,
  PageHeader,
  Pill,
  RowActions,
  matchesSearch,
} from "../../common/ui";
import "../Dashboard.scss";

export interface PricingPlan {
  _id: string;
  name: string;
  locations?: any[];
  rates?: any[];
}

// GetUserBio replies for the equipment collection must not be taken as pricing plans.
const isEquipmentItem = (x: any) =>
  Array.isArray(x?.equipments) && !("rates" in x) && !("locations" in x);

const serviceNames = (plan: PricingPlan) =>
  Array.from(new Set((plan.rates || []).map((r) => r?.service).filter(Boolean)));

const PricingModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { items, loading, status, reload, needsContainer, markContainerCreated } =
    useAdminItems<PricingPlan>(socket, "pricingManagement", isEquipmentItem, componentUuid);
  const updateAdmin = useAdminUserUpdate(socket, componentUuid);
  const [search, setSearch] = useState("");
  const [editing, setEditing] = useState<PricingPlan | undefined>(undefined);
  const [creating, setCreating] = useState(false);
  const [saving, setSaving] = useState(false);
  const [createForm] = Form.useForm();

  useEffect(() => {
    document.title = "Pricing | Beam";
  }, []);

  useEffect(() => {
    reload();
  }, [reload]);

  const filtered = useMemo(
    () =>
      items.filter((p) =>
        matchesSearch(
          search,
          p.name,
          ...(p.locations || []).map((l) => l?.name),
          ...serviceNames(p)
        )
      ),
    [items, search]
  );

  const openCreate = () => {
    if (status !== "ok") {
      pushNotification("Pricing plans are still loading, please try again", "error", "TOP_CENTER", 2000);
      return;
    }
    createForm.resetFields();
    setCreating(true);
  };

  const createPlan = async ({ name }: { name: string }) => {
    const id = generateUUID();
    const changes: any[] = [];
    const addContainer = needsContainer();
    if (addContainer) {
      changes.push({ op: "add", path: collectionPath("pricingManagement"), value: { items: {} } });
    }
    const plan: PricingPlan = { _id: id, name: name.trim(), locations: [], rates: [] };
    changes.push({ op: "add", path: itemPath("pricingManagement", id), value: plan });
    setSaving(true);
    try {
      const ok = await updateAdmin(changes);
      if (!ok) {
        pushNotification("Couldn't create the pricing plan, please try again", "error", "TOP_CENTER", 3000);
        return;
      }
      if (addContainer) markContainerCreated();
      pushNotification("Pricing plan created — now add its locations and rates", "success", "TOP_CENTER", 2000);
      setCreating(false);
      reload();
      setEditing(plan);
    } finally {
      setSaving(false);
    }
  };

  const deletePlan = async (plan: PricingPlan) => {
    const ok = await updateAdmin([{ op: "remove", path: itemPath("pricingManagement", plan._id) }]);
    if (ok) {
      pushNotification(`"${plan.name}" deleted`, "success", "TOP_CENTER", 2000);
      reload();
    } else {
      pushNotification("Couldn't delete the pricing plan, please try again", "error", "TOP_CENTER", 3000);
    }
  };

  const columns: ColumnsType<PricingPlan> = useMemo(
    () => [
      {
        title: "Name",
        dataIndex: "name",
        key: "name",
        sorter: (a, b) => `${a.name || ""}`.localeCompare(`${b.name || ""}`),
        render: (name) => <strong>{name || "Untitled plan"}</strong>,
      },
      {
        title: "Locations",
        key: "locations",
        render: (_, plan) => {
          const locations = plan.locations || [];
          if (!locations.length) return <Pill tone="amber">No locations</Pill>;
          return (
            <span title={locations.map((l) => l?.name).join(", ")}>
              {locations.length} · {locations.slice(0, 3).map((l) => l?.name).join(", ")}
              {locations.length > 3 ? "…" : ""}
            </span>
          );
        },
      },
      {
        title: "Services",
        key: "services",
        render: (_, plan) => {
          const services = serviceNames(plan);
          return services.length ? (
            <Pill tone="blue" plain>
              {services.length} {services.length === 1 ? "service" : "services"}
            </Pill>
          ) : (
            <Pill tone="gray">Not priced yet</Pill>
          );
        },
      },
      {
        title: "",
        key: "actions",
        align: "right",
        width: 110,
        render: (_, plan) => (
          <RowActions
            onEdit={() => setEditing(plan)}
            onDelete={() => deletePlan(plan)}
            deleteConfirm={`Delete "${plan.name}"? Bookings can no longer use its rates.`}
          />
        ),
      },
    ],
    // deletePlan only closes over these
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [updateAdmin, reload]
  );

  const emptyState =
    status === "error" ? (
      <EmptyState
        title="Couldn't load pricing plans"
        description={
          <Button className="mx-btn-secondary mt-2" onClick={reload}>
            Try again
          </Button>
        }
      />
    ) : search ? (
      <EmptyState title="No matching pricing plans" description="Try a different name, location or service." />
    ) : (
      <EmptyState
        title="No pricing plans yet"
        description="Create a plan, add its locations, then set rates per service."
        action={{ label: "Add pricing plan", onClick: openCreate }}
      />
    );

  return (
    <React.Fragment>
      <PageHeader
        title="Pricing"
        subtitle="Rate cards used to quote trips, per service and base location"
        search={{ value: search, onChange: setSearch, placeholder: "Search plans, locations or services" }}
        primaryAction={{ label: "Add pricing plan", onClick: openCreate }}
      />

      <DataTableCard<PricingPlan>
        rowKey="_id"
        loading={loading}
        clickable
        caption={
          search
            ? `${filtered.length} of ${items.length} plans`
            : `${items.length} ${items.length === 1 ? "plan" : "plans"}`
        }
        columns={columns}
        dataSource={filtered}
        empty={emptyState}
        scroll={{ x: true }}
        onRow={(plan) => ({ onClick: () => setEditing(plan) })}
      />

      {editing && (
        <EditPricingModal
          socket={socket}
          student={editing}
          existingNames={items.filter((p) => p._id !== editing._id).map((p) => p.name)}
          onClose={() => setEditing(undefined)}
          onAdd={() => {
            setEditing(undefined);
            reload();
          }}
        />
      )}

      <FormModal
        open={creating}
        title="New pricing plan"
        subtitle="Give the plan a name. You'll add locations and rates next."
        onCancel={() => setCreating(false)}
        onSubmit={createForm.submit}
        saving={saving}
        okText="Create plan"
      >
        <Form form={createForm} layout="vertical" onFinish={createPlan} requiredMark={false}>
          <Form.Item
            label="Plan name"
            name="name"
            validateFirst
            rules={[
              { required: true, whitespace: true, message: "Enter a plan name" },
              { max: PLAN_NAME_MAX, message: `Keep it under ${PLAN_NAME_MAX} characters` },
              {
                validator: (_, value) =>
                  items.some((p) => nameKey(p.name) === nameKey(value))
                    ? Promise.reject(new Error("A pricing plan with this name already exists"))
                    : Promise.resolve(),
              },
            ]}
          >
            <Input placeholder="e.g. Hospital-Paid (Contract)" autoFocus />
          </Form.Item>
        </Form>
      </FormModal>
    </React.Fragment>
  );
};

export default PricingModal;
