import React, { FC, useState, useEffect } from "react";
import { ReactSVG } from "react-svg";
import { SCHOOL_BUS_MENU_ITEMS } from "utils/PageTypes";

const SideBar: FC<{ socket?: ISocket; params: any; userRole?: any }> = ({
  socket,
  params,
  userRole,
}) => {
  const { screen, setScreen } = params;
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  const MENU_ITEMS: MenuItems[] = [
    {
      id: SCHOOL_BUS_MENU_ITEMS.Student,
      key: "student",
      name: "Student",
      src: "/images/community-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Student);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Driver,
      key: "driver",
      name: "Driver",
      src: "/images/user1-icon.svg",
      // cssClass: "settings-icon",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Driver);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Vehicle,
      key: "vehicle",
      name: "Vehicle",
      src: "/images/ride-dispatch-icon.svg",
      cssClass: "settings-icon",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Vehicle);
      },
    },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Scheduler,
      key: "schedule",
      name: "Scheduler",
      src: "/images/setting-icon.svg",
      cssClass: "settings-icon",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Scheduler);
      },
    },
    // {
    //   id: SCHOOL_BUS_MENU_ITEMS.Queue,
    //   key: "queue",
    //   name: "Queue",
    //   src: "/images/menu-icon.svg",
    //   cssClass: "settings-icon",
    //   onClick: () => {
    //     setScreen(SCHOOL_BUS_MENU_ITEMS.Queue);
    //   },
    // },
    {
      id: SCHOOL_BUS_MENU_ITEMS.Dashboard,
      key: "dashboard",
      name: "Dashboard",
      src: "/images/desktop-icon.svg",
      onClick: () => {
        setScreen(SCHOOL_BUS_MENU_ITEMS.Dashboard);
      },
    },
  ];

  useEffect(() => {
    const mediaQuery = window.matchMedia('(max-width: 768px)');
    const handleChange = (e) => setIsMobile(e.matches);

    // Add listener for changes
    mediaQuery.addEventListener('change', handleChange);

    // Cleanup listener on unmount
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  return (
    <div
      className="main-column search-panel mr-4"
      style={{
        width: isMobile ? 90: 110,
        position: "fixed",
        top: 75,
        left: 0,
        height: "122vh",
      }}
    >
      <div className="sidebar" style={{borderRadius: 0}}>
        <ul>
          {MENU_ITEMS?.filter((x) => {
            if (userRole === "admin" || x.key === "dashboard") return true;
            if (userRole === x?.key) return true;
            return false;
          })?.map((item) => (
            <li
              key={"selected-" + item.id}
              className={screen === item.id && "selected"}
              onClick={() => {
                const tempItem = MENU_ITEMS.find((x) => {
                  return x.id === item.id;
                });
                tempItem?.onClick();
              }}
            >
              <div>
                <div>
                  <ReactSVG className={item.cssClass} src={item.src} />
                  <p>{item.name}</p>
                </div>
              </div>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
};

export default SideBar;
