import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, DatePicker, Select } from "antd";
import type { ColumnsType } from "antd/es/table";
import moment, { Moment } from "moment";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { getCustomUpdateSubscriptionTopic } from "hooks/MQTTConstants";
import { formatForRedis, generateUUID } from "utils/appUtil";
import { PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { DataTableCard, EmptyState, PageHeader, Pill } from "../../common/ui";
import {
  STATUS,
  TimesheetRow,
  formatDay,
  formatDuration,
  toTimesheetRow,
} from "./timesheetUtils";
import "../Dashboard.scss";
import "./ClockIn.scss";

const { RangePicker } = DatePicker;

// GET_AGGREGATE's saga never calls back on failure.
const LOAD_TIMEOUT_MS = 15000;
const RANGE_FORMAT = "MMM D, YYYY";

type Range = [Moment, Moment];

/** Built per mount so "Today" doesn't go stale in a long-lived tab. */
const buildPresets = (): Record<string, Range> => ({
  Today: [moment().startOf("day"), moment().endOf("day")],
  Yesterday: [moment().subtract(1, "day").startOf("day"), moment().subtract(1, "day").endOf("day")],
  "This week": [moment().startOf("week"), moment().endOf("week")],
  "Last week": [
    moment().subtract(1, "week").startOf("week"),
    moment().subtract(1, "week").endOf("week"),
  ],
  "This month": [moment().startOf("month"), moment().endOf("month")],
  "Last month": [
    moment().subtract(1, "month").startOf("month"),
    moment().subtract(1, "month").endOf("month"),
  ],
});

// Responders: can take jobs (OnMove) and are not admins.
const isResponderRole = (role: any) => {
  const p: string[] = role?.permissions || [];
  return p.includes(PERMISSION_TYPES.OnMove) && !p.includes(PERMISSION_TYPES.Admin);
};

const time = (m?: Moment) => (m ? m.format("HH:mm") : undefined);

const COLUMNS: ColumnsType<TimesheetRow> = [
  {
    title: "Driver",
    dataIndex: "driverName",
    key: "driver",
    sorter: (a, b) => a.driverName.localeCompare(b.driverName),
    render: (name: string, r) => (
      <div>
        <strong>{name}</strong>
        {r.sessions.length > 1 && (
          <div className="mx-timesheet__sub">{r.sessions.length} sessions</div>
        )}
      </div>
    ),
  },
  {
    title: "Date",
    dataIndex: "date",
    key: "date",
    sorter: (a, b) => a.date.localeCompare(b.date),
    render: (date: string) => formatDay(date),
  },
  {
    title: "Clock in",
    key: "clockIn",
    render: (_, r) => time(r.clockIn) || "—",
  },
  {
    title: "Clock out",
    key: "clockOut",
    render: (_, r) =>
      r.clockOut ? (
        // Overnight shifts end on a later day.
        r.clockIn && !r.clockOut.isSame(r.clockIn, "day") ? (
          `${time(r.clockOut)} (${r.clockOut.format("MMM D")})`
        ) : (
          time(r.clockOut)
        )
      ) : (
        <span className="mx-timesheet__muted">—</span>
      ),
  },
  {
    title: "Break",
    dataIndex: "breakMinutes",
    key: "break",
    align: "right",
    render: (m: number) => (m ? formatDuration(m) : <span className="mx-timesheet__muted">—</span>),
  },
  {
    title: "Total hours",
    dataIndex: "workedMinutes",
    key: "worked",
    align: "right",
    sorter: (a, b) => a.workedMinutes - b.workedMinutes,
    render: (m: number) => <strong>{formatDuration(m)}</strong>,
  },
  {
    title: "Status",
    dataIndex: "status",
    key: "status",
    render: (status: TimesheetRow["status"]) => (
      <Pill tone={STATUS[status].tone}>{STATUS[status].label}</Pill>
    ),
  },
];

const SessionList = ({ row }: { row: TimesheetRow }) => (
  <ul className="mx-timesheet__sessions">
    {row.sessions.map((s, i) => (
      <li key={i}>
        <span>Session {i + 1}</span>
        <span>
          {time(s.start)} – {s.end ? time(s.end) : "still clocked in"}
        </span>
        {s.breakSeconds >= 60 && (
          <span className="mx-timesheet__muted">
            {formatDuration(s.breakSeconds / 60)} break
          </span>
        )}
      </li>
    ))}
  </ul>
);

/** "Timesheet" in the sidebar: drivers' clock-in / clock-out records. */
const ClockInModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
}> = ({ socket, componentUuid }) => {
  const { encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const uuid = useRef(componentUuid || generateUUID()).current;

  const [drivers, setDrivers] = useState<{ id: string; name: string }[]>([]);
  const [records, setRecords] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [loadFailed, setLoadFailed] = useState(false);
  const [driverId, setDriverId] = useState<string | undefined>(undefined);
  const presets = useMemo(buildPresets, []);
  const [range, setRange] = useState<Range>(presets.Today);

  const mounted = useRef(true);
  const requestSeq = useRef(0);
  const loadTimer = useRef<any>();
  // The socket callback is registered once; it reads the current filters here.
  const filters = useRef({ driverId, range });
  filters.current = { driverId, range };

  useEffect(() => {
    document.title = "Timesheet | Beam";
    mounted.current = true;
    return () => {
      mounted.current = false;
      clearTimeout(loadTimer.current);
    };
  }, []);

  const loadTimesheets = useCallback(
    (silent = false) => {
      const { driverId: user, range: [from, to] } = filters.current;
      const seq = ++requestSeq.current;
      const request: any = {
        select: {
          index: {
            searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
            searchQuery: `@partitions:{'org\\:${formatForRedis(
              projects?.userServiceId
            )}'}@partitions:{type\\:timesheet}@createdAt:[${from
              .clone()
              .startOf("day")
              .valueOf()},+inf]@createdAt:[-inf, ${to.clone().endOf("day").valueOf()}]${
              user ? `@partitions:{user\\:${user}}` : ""
            }`,
            searchOptions: "VERBATIM TIMEOUT 10000",
          },
          load: {
            info: "$.info",
            objectId: "$.objectId",
            partitions: "$.partitions",
            status: "$..status",
          },
        },
        filter: { expression: "" },
      };
      if (!silent) setLoading(true);
      clearTimeout(loadTimer.current);
      loadTimer.current = setTimeout(() => {
        if (!mounted.current || seq !== requestSeq.current) return;
        setLoading(false);
        setLoadFailed(true);
      }, LOAD_TIMEOUT_MS);
      dispatch(
        GET_AGGREGATE({
          requestData: request,
          callback: (response) => {
            // Filters may have changed while this was in flight.
            if (!mounted.current || seq !== requestSeq.current) return;
            clearTimeout(loadTimer.current);
            setRecords(Array.isArray(response) ? response : []);
            setLoadFailed(false);
            setLoading(false);
          },
        })
      );
    },
    [dispatch, projects?.userServiceId]
  );

  const loadDrivers = useCallback(
    (roles: any[]) => {
      const rolesQuery = (roles || [])
        .filter(isResponderRole)
        .map((y: any) => `@roleId === '${y._id}'`);
      if (!rolesQuery.length) return;
      dispatch(
        GET_AGGREGATE({
          requestData: {
            select: {
              index: {
                searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
                searchQuery: `@serviceId:{'${formatForRedis(projects?.userServiceId)}'}`,
                searchOptions: "TIMEOUT 5000",
              },
              list: { objectIds: undefined },
              load: {
                id: "$.objectId",
                status: "$.nonpersistent.static.live.status",
                live: "$.persistent.static.live",
                roleId: "$..admin.profile.roleId",
              },
            },
            apply: { expression: "", name: "" },
            result: {},
            filter: { expression: `exists(@roleId) && (${rolesQuery.join("||")})` },
            anyStatus: false,
          },
          callback: (response) => {
            if (!mounted.current) return;
            setDrivers(
              (Array.isArray(response) ? response : [])
                .map((x) => {
                  const { firstName, lastName } = x?.live?.profile || {};
                  return {
                    id: `${x?.id}`,
                    name: [firstName, lastName].filter(Boolean).join(" ") || "Unnamed driver",
                  };
                })
                .sort((a, b) => a.name.localeCompare(b.name))
            );
          },
        })
      );
    },
    [dispatch, projects?.userServiceId]
  );

  useEffect(() => {
    if (!projects?.adminUserId) return;
    loadTimesheets();
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      getCustomUpdateSubscriptionTopic(encrypted_token?.connectionId),
      () => {
        if (mounted.current) loadTimesheets(true);
      },
      uuid
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [projects?.adminUserId]);

  useEffect(() => {
    if (projects?.adminUserId && adminUserRoles) loadDrivers(adminUserRoles);
  }, [projects?.adminUserId, adminUserRoles, loadDrivers]);

  // Reload whenever a filter changes (after the first load above).
  const firstFilterRun = useRef(true);
  useEffect(() => {
    if (firstFilterRun.current) {
      firstFilterRun.current = false;
      return;
    }
    if (projects?.adminUserId) loadTimesheets();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [driverId, range]);

  const rows: TimesheetRow[] = useMemo(() => {
    const names = new Map(drivers.map((d) => [d.id, d.name]));
    const now = moment();
    return records
      .map((x) =>
        toTimesheetRow(x, (userId) => (userId && names.get(userId)) || "Unknown driver", now)
      )
      .filter((r): r is TimesheetRow => !!r)
      .sort((a, b) => b.date.localeCompare(a.date) || a.driverName.localeCompare(b.driverName));
  }, [records, drivers]);

  const summary = useMemo(() => {
    const byDriver = new Map<string, { name: string; minutes: number; days: number }>();
    rows.forEach((r) => {
      const id = r.userId || r.key;
      const entry = byDriver.get(id) || { name: r.driverName, minutes: 0, days: 0 };
      entry.minutes += r.workedMinutes;
      entry.days += 1;
      byDriver.set(id, entry);
    });
    return {
      worked: rows.reduce((sum, r) => sum + r.workedMinutes, 0),
      breaks: rows.reduce((sum, r) => sum + r.breakMinutes, 0),
      onShift: rows.filter((r) => r.status === "onShift" || r.status === "onBreak").length,
      missing: rows.filter((r) => r.status === "missingClockOut").length,
      byDriver: Array.from(byDriver.values()).sort((a, b) => b.minutes - a.minutes),
    };
  }, [rows]);

  const preset = Object.keys(presets).find(
    (k) => presets[k][0].isSame(range[0], "day") && presets[k][1].isSame(range[1], "day")
  );
  const rangeLabel = preset || `${range[0].format(RANGE_FORMAT)} – ${range[1].format(RANGE_FORMAT)}`;

  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load timesheets"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => loadTimesheets()}>
          Try again
        </Button>
      }
    />
  ) : (
    <EmptyState
      title="No clock-ins found"
      description={`${driverId ? "This driver hasn't" : "No driver has"} clocked in ${
        preset ? preset.toLowerCase() : `between ${rangeLabel}`
      }. Try a wider date range.`}
    />
  );

  return (
    <div className="mx-timesheet">
      <PageHeader
        title="Timesheet"
        subtitle="Driver clock-in and clock-out records with hours worked"
      />

      <div className="mx-card mx-timesheet__filters">
        <label>
          <span>Driver</span>
          <Select
            allowClear
            showSearch
            placeholder="All drivers"
            optionFilterProp="label"
            value={driverId}
            onChange={(v) => setDriverId(v || undefined)}
            options={drivers.map((d) => ({ label: d.name, value: d.id }))}
            notFoundContent={adminUserRoles ? "No drivers found" : "Loading drivers…"}
          />
        </label>
        <label>
          <span>Dates</span>
          <RangePicker
            allowClear={false}
            format={RANGE_FORMAT}
            value={range}
            ranges={presets as any}
            onChange={(values) => {
              if (values?.[0] && values?.[1]) {
                setRange([values[0].clone().startOf("day"), values[1].clone().endOf("day")]);
              }
            }}
          />
        </label>
      </div>

      <div className="mx-timesheet__stats">
        <div className="mx-card mx-timesheet__stat">
          <span>Hours worked</span>
          <strong>{formatDuration(summary.worked)}</strong>
        </div>
        <div className="mx-card mx-timesheet__stat">
          <span>Break time</span>
          <strong>{formatDuration(summary.breaks)}</strong>
        </div>
        <div className="mx-card mx-timesheet__stat">
          <span>On shift now</span>
          <strong>{summary.onShift}</strong>
        </div>
        <div
          className={`mx-card mx-timesheet__stat ${
            summary.missing ? "mx-timesheet__stat--alert" : ""
          }`}
        >
          <span>Missing clock-outs</span>
          <strong>{summary.missing}</strong>
        </div>
      </div>

      <DataTableCard<TimesheetRow>
        rowKey="key"
        loading={loading}
        caption={`${rows.length} ${rows.length === 1 ? "record" : "records"} · ${rangeLabel}`}
        columns={COLUMNS}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
        expandable={{
          expandedRowRender: (r) => <SessionList row={r} />,
          rowExpandable: (r) => r.sessions.length > 1,
        }}
      />

      {!driverId && summary.byDriver.length > 1 && (
        <div className="mx-card mx-timesheet__by-driver">
          <h4>Hours by driver</h4>
          <ul>
            {summary.byDriver.map((d, i) => (
              <li key={i}>
                <span>{d.name}</span>
                <span className="mx-timesheet__muted">
                  {d.days} {d.days === 1 ? "day" : "days"}
                </span>
                <strong>{formatDuration(d.minutes)}</strong>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export default ClockInModal;
