import moment from "moment";
import { formatForRedis } from "utils/appUtil";
import { DashboardFilters, QueryContext } from "../types";

const ECO = process.env.REACT_APP_ECO_SYSTEM;

const FORCED_VIEW_STATUS: Record<string, string> = {
  advance: "brown",
  dispatch: "purple",
};

export const getForcedStatus = (forcedView?: string) =>
  forcedView ? FORCED_VIEW_STATUS[forcedView] : undefined;

const timeIndex = (filters: DashboardFilters) => {
  const { startTimestamp, endTimestamp } = filters.timeRange;
  const start = startTimestamp ?? moment().startOf("day").valueOf();
  const end = endTimestamp ?? moment().endOf("day").valueOf();
  return `@createdAt:[${start},+inf]@createdAt:[-inf, ${end}]`;
};

const splitName = (fullName: string) => {
  const parts = fullName.trim().replace(/\s+/g, " ").split(" ");
  return { firstName: parts[0] || "", lastName: parts.slice(1).join(" ") };
};

/** Extra fields the active filters reference in their expressions. */
const filterLoad = ({ entityType, entityValue, areaType, areaValue }: DashboardFilters) => ({
  ...(areaValue ? { [areaType]: `$..profile.${areaType}` } : {}),
  ...(entityValue && (entityType === "responder" || entityType === "dispatcher")
    ? { user: `$.persistent.static.metadata.members.users.${entityValue}` }
    : {}),
});

/** Filter expressions shared by the table query and the status-count query. */
const filterExpressions = (filters: DashboardFilters) => {
  const expressions: string[] = [];
  const { entityType, entityValue, areaType, areaValue, phone, name } = filters;

  if (entityValue) {
    if (entityType === "project") {
      expressions.push(`exists(@accountId) && @accountId === '${entityValue}'`);
    } else if (entityType === "vehicle") {
      expressions.push(`exists(@vehicleProjectId) && @vehicleProjectId === '${entityValue}'`);
    } else {
      expressions.push(`exists(@user)`);
    }
  }
  if (areaValue) {
    expressions.push(`exists(@${areaType}) && @${areaType} === '${areaValue}'`);
  }
  if (phone) {
    expressions.push(
      `exists(@patientPhoneNumber) && contains(@patientPhoneNumber, '${phone}')`
    );
  }
  if (name) {
    const lower = name.toLowerCase();
    const { firstName, lastName } = splitName(lower);
    expressions.push(
      `(exists(@patientFullName) && contains(@patientFullName, '${lower}')) || (exists(@patientFirstName) && contains(lower(@patientFirstName), '${firstName}') && exists(@patientLastName) && contains(lower(@patientLastName), '${lastName}'))`
    );
  }
  return expressions;
};

const baseSearchQuery = (ctx: QueryContext) =>
  `@pageMembers:{${ctx.userId}|${ctx.adminUserId}}(-@rideType:{hail})@pageType:{event}`;

const wrapOr = (expressions: string[]) =>
  expressions.map((e) => (expressions.length > 1 && e.includes("||") ? `(${e})` : e));

export const buildPagesRequest = (ctx: QueryContext, filters: DashboardFilters) => {
  const forcedStatus = getForcedStatus(ctx.forcedView);
  let expressions: string[];
  let time = "";

  if (forcedStatus) {
    expressions = [`exists(@status) && @status === '${forcedStatus}'`];
  } else {
    expressions = filterExpressions(filters);
    time = timeIndex(filters);
    if (filters.status) {
      expressions.push(`exists(@status) && @status === '${filters.status}'`);
    }
  }

  return {
    select: {
      index: {
        searchIndex: `${ECO}:page:ride`,
        searchQuery: `${baseSearchQuery(ctx)}${time}`,
        searchOptions: "VERBATIM TIMEOUT 10000",
      },
      load: {
        profile: "$..profile",
        ride: "$.persistent.static.ride",
        type: "$..persistent.static.metadata.type",
        pageId: "$.objectId",
        iotAssetConfigId: "$.persistent.static.iotAsset.config.iotAssetConfigId",
        createdAt: "$.persistent.static.metadata.createdAt",
        updatedAt: "$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt",
        status: "$.nonpersistent.static.live.status.name",
        rideType: "$..profile.type",
        phone: "$..profile.studentPhone",
        patientFullName: "$..profile.patientFullName",
        patientFirstName: "$..profile.patientFirstName",
        patientLastName: "$..profile.patientLastName",
        patientPhoneNumber: "$..profile.patientPhoneNumber",
        vehicleProjectId: "$..profile.vehicle..projectId",
        accountId: "$..profile.billingInstitute",
        lastSent: "$.nonpersistent.dynamic.metadata.lastSent.members",
        lastRead: "$.nonpersistent.dynamic.metadata.lastReadUser",
        changelog: "$.nonpersistent.static.changelog",
        ...filterLoad(filters),
      },
    },
    filter: { expression: wrapOr(expressions).join("&&") },
    sortBy: {
      properties: [
        ctx.forcedView === "advance"
          ? { field: "@createdAt", order: "ASC" }
          : { field: "@updatedAt", order: "DESC" },
      ],
      max: 1000,
    },
    result: {},
  };
};

/** Same filters as the table minus the status filter, grouped by status. */
export const buildStatusCountRequest = (ctx: QueryContext, filters: DashboardFilters) => ({
  select: {
    index: {
      searchIndex: `${ECO}:page:ride`,
      searchQuery: `${baseSearchQuery(ctx)}${timeIndex(filters)}`,
      searchOptions: "VERBATIM TIMEOUT 10000",
    },
    load: {
      profile: "$..profile",
      rideType: "$..profile.type",
      persistent: "$.persistent",
      nonpersistent: "$.nonpersistent",
      pageId: "$.objectId",
      iotAssetConfigId: "$.persistent.static.iotAsset.config.iotAssetConfigId",
      createdAt: "$.persistent.static.metadata.createdAt",
      status: "$.nonpersistent.static.live.status.name",
      vehicleProjectId: "$..profile.vehicle..projectId",
      patientFullName: "$..profile.patientFullName",
      patientFirstName: "$..profile.patientFirstName",
      patientLastName: "$..profile.patientLastName",
      patientPhoneNumber: "$..profile.patientPhoneNumber",
      accountId: "$..profile.billingInstitute",
      ...filterLoad(filters),
    },
  },
  groupBy: {
    properties: ["@status"],
    reducers: [{ func: "COUNT", arguments: [], name: "count" }],
  },
  filter: { expression: wrapOr(filterExpressions(filters)).join("&&") },
});

export const buildPageByIdRequest = (pageId: string) => ({
  select: {
    index: {
      searchIndex: `${ECO}:pageUpdatedAtIndex`,
      searchQuery: `*`,
      searchOptions: "VERBATIM TIMEOUT 10000",
    },
    list: { objectIds: [pageId] },
    load: {
      persistent: "$.persistent",
      nonpersistent: "$.nonpersistent",
      pageId: "$.objectId",
      objectStatus: "$.objectStatus",
      lastSent: "$.nonpersistent.dynamic.metadata.lastSent.members",
      lastRead: "$.nonpersistent.dynamic.metadata.lastReadUser",
      createdAt: "$.persistent.static.metadata.createdAt",
    },
  },
  filter: { expression: "" },
});

export const buildAreaOptionsRequest = (ctx: QueryContext, areaType: string) => ({
  select: {
    index: {
      searchIndex: `${ECO}:pageUpdatedAtIndex`,
      searchQuery: `@pageMembers:{${ctx.userId}|${ctx.adminUserId}}`,
      searchOptions: "VERBATIM TIMEOUT 10000",
    },
    load: { [areaType]: `$.persistent.static.profile.${areaType}` },
  },
  groupBy: {
    properties: [`@${areaType}`],
    reducers: [{ func: "COUNT", arguments: [], name: "count" }],
  },
  filter: { expression: "" },
});

type RoleType = "dispatcher" | "responder" | "manager";

const ROLE_PREDICATES: Record<RoleType, (p: string[]) => boolean> = {
  dispatcher: (p) => p.includes("cad") && !p.includes("admin"),
  responder: (p) => p.includes("onMove") && !p.includes("admin"),
  manager: (p) => p.includes("cad") && p.includes("onMove") && !p.includes("admin"),
};

export const buildUsersByRoleRequest = (
  ctx: QueryContext,
  adminUserRoles: any[],
  type: RoleType
) => {
  const rolesQuery = (adminUserRoles || [])
    .filter((role: any) => ROLE_PREDICATES[type](role.permissions || []))
    .map((role: any) => `@roleId === '${role._id}'`);

  return {
    select: {
      index: {
        searchIndex: `${ECO}:userNameIndex`,
        searchQuery: `@serviceId:{'${formatForRedis(ctx.userServiceId)}'}`,
        searchOptions: "TIMEOUT 5000",
      },
      load: {
        id: "$.objectId",
        status: "$.nonpersistent.static.live.status",
        live: "$.persistent.static.live",
        roleId: "$..admin.profile.roleId",
      },
    },
    apply: { expression: "", name: "" },
    result: {},
    filter: { expression: `exists(@roleId) && (${rolesQuery.join("||")})` },
    anyStatus: false,
  };
};

export const buildShiftRequest = (ctx: QueryContext, day: number) => {
  const start = moment(day).startOf("day").valueOf();
  const end = moment(day).endOf("day").valueOf();
  return {
    select: {
      index: {
        searchIndex: `${ECO}:custom:createdAt`,
        searchQuery: `@partitions:{'org\\:${formatForRedis(
          ctx.userServiceId
        )}'}@partitions:{type\\:shift}`,
        searchOptions: "VERBATIM TIMEOUT 10000",
      },
      load: {
        info: "$.info",
        objectId: "$.objectId",
        partitions: "$.partitions",
        status: "$..status",
        startTimestamp: "$..startTimestamp",
        endTimestamp: "$..endTimestamp",
      },
    },
    filter: {
      expression: `exists(@startTimestamp) && exists(@endTimestamp) && @startTimestamp < ${end} && @endTimestamp > ${start}`,
    },
  };
};
