import React, { FC, useCallback, useState } from "react";
import { message } from "antd";
import {
  CalendarOutlined,
  ClockCircleOutlined,
  EnvironmentOutlined,
  UserOutlined,
} from "@ant-design/icons";
import moment from "moment";

import { ProgramEvent } from "./data";

/** Shared by the event card, the drawer and the event page. */

export const eventPath = (event: ProgramEvent) => `/programs/${event.section}/${event.id}`;

export const formatDates = (event: ProgramEvent) => {
  const start = moment(event.start);
  if (!event.end) return start.format("ddd, MMM D, YYYY");
  const end = moment(event.end);
  return start.isSame(end, "month")
    ? `${start.format("MMM D")} – ${end.format("D, YYYY")}`
    : `${start.format("MMM D")} – ${end.format("MMM D, YYYY")}`;
};

/** Projects without a payment config have no price to show at all. */
export const priceLabel = (price?: number): string | undefined => {
  if (price === undefined) return undefined;
  return price === 0 ? "Free" : `$${price}`;
};

const SAVED_KEY = "programs.saved";

/** Saved events, remembered per browser. Storage can be blocked, so every access is guarded. */
export const useSaved = () => {
  const [saved, setSaved] = useState<string[]>(() => {
    try {
      return JSON.parse(localStorage.getItem(SAVED_KEY) || "[]");
    } catch {
      return [];
    }
  });

  const toggle = useCallback((id: string) => {
    setSaved((prev) => {
      const next = prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id];
      try {
        localStorage.setItem(SAVED_KEY, JSON.stringify(next));
      } catch {
        // Not persisted; still works for this visit.
      }
      return next;
    });
  }, []);

  return { saved, toggle };
};

/** An all-day .ics entry, so it lands on the right dates in any time zone. */
export const downloadIcs = (event: ProgramEvent) => {
  const day = (d: string) => d.replace(/-/g, "");
  const endExclusive = moment(event.end ?? event.start).add(1, "day").format("YYYYMMDD");
  const escape = (s: string) => s.replace(/[\\,;]/g, (c) => `\\${c}`);
  const description = [event.time, event.description].filter(Boolean).join(". ");
  const ics = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Beam//Programs//EN",
    "BEGIN:VEVENT",
    `UID:${event.id}@programs.beam.live`,
    `DTSTAMP:${moment.utc().format("YYYYMMDD[T]HHmmss[Z]")}`,
    `DTSTART;VALUE=DATE:${day(event.start)}`,
    `DTEND;VALUE=DATE:${endExclusive}`,
    `SUMMARY:${escape(event.title)}`,
    ...(event.location ? [`LOCATION:${escape(event.location)}`] : []),
    `DESCRIPTION:${escape(description)}`,
    "END:VEVENT",
    "END:VCALENDAR",
  ].join("\r\n");

  const url = URL.createObjectURL(new Blob([ics], { type: "text/calendar" }));
  const a = document.createElement("a");
  a.href = url;
  a.download = `${event.id}.ics`;
  a.click();
  URL.revokeObjectURL(url);
};

/** Copies the event's Beam Vite site when it has one, otherwise its page here. */
export const copyEventLink = async (event: ProgramEvent) => {
  const url = event.url ?? `${window.location.origin}${eventPath(event)}`;
  try {
    await navigator.clipboard.writeText(url);
    message.success("Link copied");
  } catch {
    message.info(url);
  }
};

/**
 * Dates, and then only the facts the project actually carries: time,
 * location and managers are all optional on a project.
 */
export const EventFacts: FC<{ event: ProgramEvent; className?: string }> = ({ event, className }) => (
  <dl className={`programs-facts${className ? ` ${className}` : ""}`}>
    <div>
      <dt>
        <CalendarOutlined /> Dates
      </dt>
      <dd>{formatDates(event)}</dd>
    </div>
    {event.time && (
      <div>
        <dt>
          <ClockCircleOutlined /> Time
        </dt>
        <dd>{event.time}</dd>
      </div>
    )}
    {event.location && (
      <div>
        <dt>
          <EnvironmentOutlined /> Location
        </dt>
        <dd>{event.location}</dd>
      </div>
    )}
    {event.coach && (
      <div>
        <dt>
          <UserOutlined /> Led by
        </dt>
        <dd>{event.coach}</dd>
      </div>
    )}
  </dl>
);
