import React from "react";
import { Select, Button, Switch } from "antd";
import { ReactSVG } from "react-svg";
import { useDashboard } from "../context";

// The collapsible "more filters" panel: owner (project/role) filter, area
// filter, hail rides and the (disabled) export buttons. Phone search and the
// time range live in the toolbar (StatusFilterBar).
const FilterPanel: React.FC = () => {
  const {
    showTableFilterModal,
    projectFilter,
    handleProjectFilter,
    projectFilterLoading,
    projectFilterValue,
    projectFilterOptions,
    setProjectPagePaths,
    showHail,
    setShowHailPaths,
    timeFilter,
    handleTimeFilter,
    timeFilterLoading,
    timeFilterOptions,
    timeFilterValue,
    setAreaPagePaths,
  } = useDashboard();

  return (
    <div
      className="ride-filters"
      style={showTableFilterModal ? {} : { display: "none" }}
    >
      <div className="ride-filters__group">
        <div className="ride-filters__label" id="ride-filter-owner">
          Owner
        </div>
        <div
          className="ride-segmented"
          role="group"
          aria-labelledby="ride-filter-owner"
        >
          {[
            ["manager", "Manager"],
            ["project", "Project"],
            ["dispatcher", "Dispatcher"],
            ["responder", "Responder"],
          ].map(([key, label]) => (
            <div key={key} onClick={() => handleProjectFilter(key)}>
              <Button
                className={`beam-btn w-70 ${
                  projectFilter === key ? "green-btn cover" : ""
                }`}
                aria-pressed={projectFilter === key}
              >
                {label}
              </Button>
            </div>
          ))}
        </div>
        <Select
          className="w-full"
          placeholder="Select ID"
          aria-label="Owner ID"
          loading={projectFilterLoading}
          value={projectFilterValue}
          allowClear
          showSearch
          filterOption={(input, option) => {
            return (option!.label as unknown as string)
              ?.toLowerCase()
              .includes(input.toLowerCase());
          }}
          options={projectFilterOptions}
          onChange={(value) => {
            setProjectPagePaths(value);
          }}
        ></Select>
      </div>

      <div className="ride-filters__group">
        <div className="ride-filters__label" id="ride-filter-area">
          Area
        </div>
        <div
          className="ride-segmented"
          role="group"
          aria-labelledby="ride-filter-area"
          id="filters"
        >
          {[
            ["state", "State"],
            ["city", "City"],
            ["county", "County"],
            ["zip", "Zip"],
          ].map(([key, label]) => (
            <div key={key} onClick={() => handleTimeFilter(key)}>
              <Button
                className={`beam-btn w-70 ${
                  timeFilter === key ? "green-btn cover" : ""
                }`}
                aria-pressed={timeFilter === key}
              >
                {label}
              </Button>
            </div>
          ))}
        </div>
        <Select
          className="w-full"
          placeholder="Select ID"
          aria-label="Area ID"
          loading={timeFilterLoading}
          allowClear
          options={timeFilterOptions}
          value={timeFilterValue}
          onChange={(value) => {
            setAreaPagePaths(value);
          }}
        ></Select>
        <Select
          className="w-full"
          placeholder="Select Hour(s)"
          aria-label="Hours"
          disabled
        ></Select>
      </div>

      <div className="ride-filters__group ride-filters__group--narrow">
        <div className="ride-filters__label">Options</div>
        <label className="ride-filters__switch">
          <Switch
            onChange={(value) => {
              setShowHailPaths(value);
            }}
            defaultChecked={showHail.current}
          />
          Show hail rides
        </label>

        <div className="ride-filters__label mt-2">Export</div>
        <div className="ride-filters__export">
          <Button
            className="beam-btn export"
            aria-label="Export to CSV"
            disabled
          >
            <ReactSVG src="/images/export-csv.svg" />
          </Button>
          <Button
            className="beam-btn export"
            aria-label="Export to Excel"
            disabled
          >
            <ReactSVG src="/images/export-xls.svg" />
          </Button>
          <Button
            className="beam-btn export"
            aria-label="Export to PDF"
            disabled
          >
            <ReactSVG src="/images/export-pdf.svg" />
          </Button>
        </div>
      </div>
    </div>
  );
};

export default FilterPanel;
