import React, { FC, useEffect, useRef, useState } from "react";
import moment from "moment";

export interface DayValue {
  day: string; // YYYY-MM-DD
  value: number;
}

const HEIGHT = 200;
const MARGIN = { top: 12, right: 12, bottom: 26, left: 34 };
const BAR_COLOR = "#463bbd";

const niceMax = (max: number) => {
  if (max <= 4) return 4;
  const pow = 10 ** Math.floor(Math.log10(max));
  const step = [1, 2, 2.5, 5, 10].map((m) => m * pow).find((s) => max / s <= 4) || pow * 10;
  return Math.ceil(max / step) * step;
};

/** Single-series daily columns with a per-bar hover tooltip. */
const DailyBars: FC<{ data: DayValue[]; label: string }> = ({ data, label }) => {
  const ref = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  const [hover, setHover] = useState<number | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => setWidth(entry.contentRect.width));
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const plotW = Math.max(0, width - MARGIN.left - MARGIN.right);
  const plotH = HEIGHT - MARGIN.top - MARGIN.bottom;
  const max = niceMax(Math.max(0, ...data.map((d) => d.value)));
  const ticks = [0, max / 4, max / 2, (3 * max) / 4, max];
  const slot = data.length ? plotW / data.length : 0;
  const barW = Math.max(2, Math.min(18, slot - 4));
  const y = (v: number) => MARGIN.top + plotH - (v / max) * plotH;
  const labelEvery = Math.ceil(data.length / 8);

  const bar = (x: number, top: number, w: number, h: number) => {
    if (h <= 0) return "";
    const r = Math.min(4, w / 2, h);
    return `M${x},${top + h}V${top + r}Q${x},${top} ${x + r},${top}H${x + w - r}Q${x + w},${top} ${x + w},${top + r}V${top + h}Z`;
  };

  const active = hover !== null ? data[hover] : null;

  return (
    <div ref={ref} className="cpn-bars" role="img" aria-label={label}>
      {width > 0 && (
        <svg width={width} height={HEIGHT}>
          {ticks.map((t) => (
            <g key={t}>
              <line x1={MARGIN.left} x2={width - MARGIN.right} y1={y(t)} y2={y(t)} className="cpn-bars__grid" />
              <text x={MARGIN.left - 6} y={y(t) + 4} textAnchor="end" className="cpn-bars__tick">
                {Number.isInteger(t) ? t : t.toFixed(1)}
              </text>
            </g>
          ))}
          {data.map((d, i) => {
            const x = MARGIN.left + i * slot + (slot - barW) / 2;
            return (
              <g key={d.day} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(null)}>
                {/* Hit target taller and wider than the bar. */}
                <rect x={MARGIN.left + i * slot} y={MARGIN.top} width={slot} height={plotH} fill="transparent" />
                <path
                  d={bar(x, y(d.value), barW, MARGIN.top + plotH - y(d.value))}
                  fill={BAR_COLOR}
                  opacity={hover === null || hover === i ? 1 : 0.45}
                />
                {i % labelEvery === 0 && (
                  <text x={x + barW / 2} y={HEIGHT - 8} textAnchor="middle" className="cpn-bars__tick">
                    {moment(d.day).format("MMM D")}
                  </text>
                )}
              </g>
            );
          })}
        </svg>
      )}
      {active && hover !== null && (
        <div
          className="cpn-bars__tooltip"
          style={{
            left: Math.min(width - 140, Math.max(0, MARGIN.left + hover * slot + slot / 2 - 70)),
            top: Math.max(0, y(active.value) - 56),
          }}
        >
          <div>{moment(active.day).format("ddd, MMM D")}</div>
          <strong>
            {active.value} {active.value === 1 ? "redemption" : "redemptions"}
          </strong>
        </div>
      )}
    </div>
  );
};

export default DailyBars;
