// Persisted under the driver user (read by the driver list and the profile screen):
//   /persistent/static/schoolBus/locationList  { [uuid]: { locationId, locationType: "operationStart",
//                                                  location: { coordinates, attributes },
//                                                  condition: { days, startTime, endTime } } }
//   /persistent/static/schoolBus/license       { licenseNumber, licenseType, experience, expiryDate }
//   /persistent/static/schoolBus/preferences   { experiencedStretcher, ..., preferredPartners, preferenceNotes }

const DAYS_OF_WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
const LICENSE_TYPES = ["CDL Class A", "CDL Class B", "CDL Class C"];
/** TimeInput emits "MM/DD/YYYY HH:mm"; older saves may be ISO strings. */
const OPERATION_TIME_FORMATS = ["MM/DD/YYYY HH:mm", "MM/DD/YYYY HH:mm:ss"];

const PREFERENCE_CHECKS = [
  { name: "experiencedStretcher", label: "Experienced stretcher personnel" },
  {
    name: "trainedInStretchers",
    label: "Trained in stretchers (must go with experienced personnel)",
  },
  { name: "wheelchairOnly", label: "Wheelchair only" },
  { name: "stairChairs", label: "Stair chairs" },
  { name: "overnightOnCall", label: "Potential overnight on-call personnel" },
];

type FormTab = "availability" | "license" | "preferences";
type TabKey = FormTab | "shift" | "timeoff";

const FORM_TABS: { [key in FormTab]: { fields: string[]; saveLabel: string; saved: string } } = {
  availability: { fields: ["operation"], saveLabel: "Save availability", saved: "Availability saved" },
  license: {
    fields: ["licenseNumber", "licenseType", "expiryDate", "experience"],
    saveLabel: "Save license",
    saved: "License saved",
  },
  preferences: {
    fields: [...PREFERENCE_CHECKS.map((c) => c.name), "preferredPartners", "preferenceNotes"],
    saveLabel: "Save preferences",
    saved: "Preferences saved",
  },
};

const isFormTab = (key: TabKey): key is FormTab => key in FORM_TABS;
const tabOfField = (field: string) =>
  (Object.keys(FORM_TABS) as FormTab[]).find((t) => FORM_TABS[t].fields.includes(field));

const parseOperationTime = (raw: any) => {
  if (!raw) return undefined;
  const strict = moment(raw, OPERATION_TIME_FORMATS, true);
  if (strict.isValid()) return strict;
  const loose = moment(new Date(raw));
  return loose.isValid() ? loose : undefined;
};

/**
 * Wraps TimeInput so an untouched stored value is saved back exactly as it
 * was; only a new pick is written in TimeInput's format.
 */
const OperationTimeInput = ({ value, onChange }: { value?: any; onChange?: (v: any) => void }) => {
  const parsed = parseOperationTime(value);
  return (
    <TimeInput
      placeholder="Select time"
      value={parsed ? parsed.format("HH:mm") : undefined}
      onChange={onChange}
    />
  );
};

const toOperationRows = (locationList: any) =>
  Object.values(locationList || {}).map((l: any) => ({
    location: l?.location?.attributes?.address
      ? {
          label: l.location.attributes.address,
          value: {
            description: l.location.attributes.address,
            place_id: "",
            coordinates: l.location.coordinates,
            attributes: l.location.attributes,
          },
        }
      : undefined,
    days: l?.condition?.days,
    startTime: l?.condition?.startTime,
    endTime: l?.condition?.endTime,
  }));

const toLocationList = (operation: any[]) =>
  (operation || []).reduce((acc, x) => {
    const id = generateUUID();
    acc[id] = {
      locationId: id,
      locationType: "operationStart",
      location: {
        coordinates: x?.location?.value?.coordinates,
        attributes: x?.location?.value?.attributes,
      },
      condition: { days: x?.days, startTime: x?.startTime, endTime: x?.endTime },
    };
    return acc;
  }, {} as { [key: string]: any });

/** Publishes JSON-patch changes to a user; resolves false when no reply arrives in time. */
const useUserUpdate = (socket: ISocket) => {
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const uuid = useRef(generateUUID()).current;
  const waiting = useRef<{ resolve: (ok: boolean) => void; timer: any }[]>([]);

  useEffect(
    () => () => {
      waiting.current.forEach((w) => clearTimeout(w.timer));
      waiting.current = [];
    },
    []
  );

  return (userId: string, serviceId: string, changes: any[]) =>
    new Promise<boolean>((resolve) => {
      // UpdateUserBio is shared, so only our own outstanding requests are resolved.
      socket.subscribeToSurvey(
        SocketTopics.SurveyTopics,
        ExtendedBioTopics.UpdateUserBio,
        () => {
          const next = waiting.current.shift();
          if (!next) return;
          clearTimeout(next.timer);
          next.resolve(true);
        },
        uuid
      );
      const entry = { resolve, timer: undefined as any };
      entry.timer = setTimeout(() => {
        waiting.current = waiting.current.filter((w) => w !== entry);
        resolve(false);
      }, REQUEST_TIMEOUT_MS);
      waiting.current.push(entry);
      socket.publishToServiceIdSurvey(
        SocketTopics.SurveyTopics,
        UserTopics.UpdateUser,
        updateUserRequestPayloadV2(userId, changes),
        ExtendedBioTopics.UpdateUserBio,
        serviceId
      );
    });
};

/* ------------------------------------------------------------- sections */

const AvailabilitySection = () => {
  const form = Form.useFormInstance();
  const operation: any[] = Form.useWatch("operation", form) || [];

  return (
    <FormSection
      title="Operation start locations"
      description="Where the driver starts their day, per weekday. Each day can belong to one location only."
    >
      <Form.List name="operation">
        {(fields, { add, remove }) => (
          <>
            {fields.length === 0 && (
              <EmptyState
                title="No start locations yet"
                description="Add where this driver begins operating and on which days."
              />
            )}
            {fields.map((field, index) => {
              const takenElsewhere = operation
                .filter((_, i) => i !== index)
                .flatMap((o) => o?.days || []);
              return (
                <div className="mx-driver-editor__operation" key={field.key}>
                  <div className="mx-driver-editor__operation-head">
                    <span>Location {index + 1}</span>
                    <Tooltip title="Remove location">
                      <Button
                        size="small"
                        icon={<DeleteOutlined />}
                        onClick={() => remove(field.name)}
                      />
                    </Tooltip>
                  </div>
                  <Form.Item
                    label="Start location"
                    name={[field.name, "location"]}
                    rules={[
                      {
                        validator: (_, value) =>
                          value?.value?.coordinates
                            ? Promise.resolve()
                            : Promise.reject(
                                new Error("Search for an address and pick it from the list")
                              ),
                      },
                    ]}
                  >
                    <LocationInput placeholder="Search address" />
                  </Form.Item>
                  <Form.Item
                    label="Days"
                    name={[field.name, "days"]}
                    rules={[{ required: true, type: "array", min: 1, message: "Pick at least one day" }]}
                  >
                    <Select mode="multiple" placeholder="Select days" allowClear>
                      {DAYS_OF_WEEK.map((day) => (
                        <Select.Option key={day} value={day} disabled={takenElsewhere.includes(day)}>
                          {day}
                        </Select.Option>
                      ))}
                    </Select>
                  </Form.Item>
                  <Row gutter={12}>
                    <Col xs={24} sm={12}>
                      <Form.Item
                        label="Start time"
                        name={[field.name, "startTime"]}
                        rules={[{ required: true, message: "Pick a start time" }]}
                      >
                        <OperationTimeInput />
                      </Form.Item>
                    </Col>
                    <Col xs={24} sm={12}>
                      <Form.Item
                        label="End time"
                        name={[field.name, "endTime"]}
                        rules={[{ required: true, message: "Pick an end time" }]}
                      >
                        <OperationTimeInput />
                      </Form.Item>
                    </Col>
                  </Row>
                </div>
              );
            })}
            <Button
              className="mx-btn-secondary mb-3"
              icon={<PlusOutlined />}
              disabled={
                operation.flatMap((o) => o?.days || []).length >= DAYS_OF_WEEK.length &&
                fields.length > 0
              }
              onClick={() => add({})}
            >
              Add start location
            </Button>
          </>
        )}
      </Form.List>
    </FormSection>
  );
};

const LicenseSection = () => (
  <FormSection title="Driver license" description="Used to check the driver can legally take trips.">
    <Row gutter={12}>
      <Col xs={24} sm={12}>
        <Form.Item
          label="License number"
          name="licenseNumber"
          rules={[
            { required: true, whitespace: true, message: "Enter the license number" },
            { max: 40, message: "Keep it under 40 characters" },
          ]}
        >
          <Input placeholder="e.g. D1234-56789-01234" />
        </Form.Item>
      </Col>
      <Col xs={24} sm={12}>
        <Form.Item
          label="License type"
          name="licenseType"
          rules={[{ required: true, message: "Select a license type" }]}
        >
          <Select placeholder="Select license type">
            {LICENSE_TYPES.map((type) => (
              <Select.Option key={type} value={type}>
                {type}
              </Select.Option>
            ))}
          </Select>
        </Form.Item>
      </Col>
      <Col xs={24} sm={12}>
        <Form.Item
          label="Expiry date"
          name="expiryDate"
          rules={[{ required: true, message: "Pick the expiry date" }]}
          extra="An expired license is flagged in the driver list."
        >
          <DatePicker className="w-full" format="MMM D, YYYY" />
        </Form.Item>
      </Col>
      <Col xs={24} sm={12}>
        <Form.Item
          label="Experience"
          name="experience"
          rules={[
            { required: true, message: "Enter years of experience" },
            {
              validator: (_, value) =>
                value === undefined || value === null || value === "" ||
                (Number.isInteger(Number(value)) && Number(value) >= 0 && Number(value) <= 60)
                  ? Promise.resolve()
                  : Promise.reject(new Error("Enter whole years between 0 and 60")),
            },
          ]}
        >
          <InputNumber className="w-full" min={0} max={60} precision={0} addonAfter="years" />
        </Form.Item>
      </Col>
    </Row>
  </FormSection>
);

const PreferencesSection = ({ partners }: { partners: { value: string; label: string }[] }) => (
  <>
    <FormSection title="Capabilities" description="Used when matching drivers to trip requirements.">
      <div className="mx-driver-editor__checks">
        {PREFERENCE_CHECKS.map((c) => (
          <Form.Item key={c.name} name={c.name} valuePropName="checked">
            <Checkbox>{c.label}</Checkbox>
          </Form.Item>
        ))}
      </div>
    </FormSection>
    <FormSection title="Partners & notes">
      <Form.Item
        name="preferredPartners"
        label="Preferred partners to drive with"
        rules={[{ type: "array", max: 10, message: "Pick up to 10 partners" }]}
      >
        <Select
          mode="multiple"
          placeholder="Select drivers"
          allowClear
          optionFilterProp="label"
          options={partners}
        />
      </Form.Item>
      <Form.Item
        name="preferenceNotes"
        label="Notes"
        rules={[{ max: 1000, message: "Keep notes under 1000 characters" }]}
      >
        <Input.TextArea autoSize={{ minRows: 3, maxRows: 6 }} placeholder="Anything dispatch should know" />
      </Form.Item>
    </FormSection>
  </>
);

/* --------------------------------------------------------------- editor */

const EditDriverModal: FC<{
  onClose: () => void;
  socket?: ISocket;
  /** The driver's user record ({ id, live, schoolBus, ... }). */
  student?: any;
  onAdd?: () => void;
  /** Rows of the driver list ({ key, name }), offered as preferred partners. */
  sourceData?: any;
  /** The driver's own profile page: shifts and time off only. */
  fullScreen?: boolean;
}> = ({ onClose, socket, student, onAdd, sourceData, fullScreen }) => {
  const { projects } = useSelector((state: RootState) => state.auth);
  const [form] = Form.useForm();
  const updateUser = useUserUpdate(socket);
  const [activeTab, setActiveTab] = useState<TabKey>(fullScreen ? "shift" : "availability");
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState<{ [key in FormTab]?: boolean }>({});
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const initialValues = useMemo(() => {
    const license = student?.schoolBus?.license || {};
    return {
      operation: toOperationRows(student?.schoolBus?.locationList),
      licenseNumber: license.licenseNumber,
      licenseType: license.licenseType,
      expiryDate: parseLicenseExpiry(license.expiryDate),
      experience: license.experience,
      ...(student?.schoolBus?.preferences || {}),
    };
    // Loaded once per opened driver.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [student?.id]);

  const partners = useMemo(() => {
    const options = (sourceData || [])
      .filter((x: any) => x?.key && x.key !== student?.id)
      .map((x: any) => ({ value: x.key, label: x.name || "Unnamed driver" }));
    // Keep saved partners visible even when they're not in the (filtered) list.
    const saved: string[] = student?.schoolBus?.preferences?.preferredPartners || [];
    saved
      .filter((id) => !options.some((o: any) => o.value === id))
      .forEach((id) => options.push({ value: id, label: "Driver not in current list" }));
    return options;
  }, [sourceData, student]);

  const save = async (values: any) => {
    if (!isFormTab(activeTab)) return;
    const tab = activeTab;
    let change: any;
    if (tab === "availability") {
      change = {
        op: "add",
        path: "/persistent/static/schoolBus/locationList",
        value: toLocationList(values.operation),
      };
    } else if (tab === "license") {
      const raw = student?.schoolBus?.license?.experience;
      change = {
        op: "add",
        path: "/persistent/static/schoolBus/license",
        value: {
          licenseNumber: values.licenseNumber?.trim(),
          licenseType: values.licenseType,
          // Stored as text; an untouched value keeps its original type.
          experience:
            raw !== undefined && Number(raw) === values.experience ? raw : `${values.experience}`,
          expiryDate: values.expiryDate?.format(LICENSE_EXPIRY_FORMAT),
        },
      };
    } else {
      change = {
        op: "add",
        path: "/persistent/static/schoolBus/preferences",
        value: {
          experiencedStretcher: values.experiencedStretcher,
          trainedInStretchers: values.trainedInStretchers,
          wheelchairOnly: values.wheelchairOnly,
          stairChairs: values.stairChairs,
          overnightOnCall: values.overnightOnCall,
          preferredPartners: values.preferredPartners,
          preferenceNotes: values.preferenceNotes,
        },
      };
    }

    setSaving(true);
    const ok = await updateUser(student?.id, projects?.userServiceId, [change]);
    if (!mounted.current) return;
    setSaving(false);
    if (ok) {
      setDirty((d) => ({ ...d, [tab]: false }));
      pushNotification(FORM_TABS[tab].saved, "success", "TOP_CENTER", 2000);
      onAdd?.();
    } else {
      pushNotification(
        "No response from the server. Reopen the driver to check whether the change was saved.",
        "error",
        "TOP_CENTER",
        4000
      );
    }
  };

  const embedded = (content: React.ReactNode) =>
    student?.id ? (
      <div className="mx-driver-editor__embedded">{content}</div>
    ) : (
      <Skeleton active paragraph={{ rows: 5 }} />
    );

  const tabLabel = (key: FormTab, label: string) => (dirty[key] ? `${label} •` : label);

  // Clock in/out now happens in the mobile app's shift timer, which writes the
  // same timesheet records the Timesheet screen reads.
  const trackingTabs = [
    {
      key: "shift",
      label: "Shifts",
      children: embedded(<ShiftModal socket={socket} userId={student?.id} />),
    },
    {
      key: "timeoff",
      label: "Time off",
      children: embedded(<LeaveRequest socket={socket} userId={student?.id} />),
    },
  ];

  if (fullScreen) {
    return (
      <div className="mx-driver-editor mx-driver-editor--page">
        <Tabs
          activeKey={activeTab}
          onChange={(key) => setActiveTab(key as TabKey)}
          destroyInactiveTabPane
          items={trackingTabs}
        />
      </div>
    );
  }

  const name =
    [student?.live?.profile?.firstName, student?.live?.profile?.lastName]
      .filter(Boolean)
      .join(" ") || "Driver";
  const beamId = student?.live?.beamIds?.[0];
  const formTab = isFormTab(activeTab) ? activeTab : undefined;

  return (
    <Modal
      open
      width={880}
      className="beam-modal mx-modal mx-driver-editor"
      onCancel={onClose}
      maskClosable={!saving}
      destroyOnClose
      title={
        <div className="mx-driver-editor__title">
          <span className="mx-staff__avatar">{getInitials(name)}</span>
          <div>
            {name}
            {beamId && <span className="mx-driver-editor__title-sub">{beamId}</span>}
          </div>
        </div>
      }
      footer={
        formTab
          ? [
              dirty[formTab] ? (
                <span key="dirty" style={{ marginRight: "auto" }}>
                  <Pill tone="amber">Unsaved changes</Pill>
                </span>
              ) : null,
              <Button key="cancel" className="mx-btn-secondary" onClick={onClose} disabled={saving}>
                Cancel
              </Button>,
              <Button key="save" className="mx-btn-primary" loading={saving} onClick={form.submit}>
                {FORM_TABS[formTab].saveLabel}
              </Button>,
            ]
          : [
              <Button key="close" className="mx-btn-secondary" onClick={onClose}>
                Close
              </Button>,
            ]
      }
    >
      <Form
        form={form}
        layout="vertical"
        requiredMark={false}
        initialValues={initialValues}
        onFinish={save}
        onValuesChange={(changed) => {
          const tab = tabOfField(Object.keys(changed)[0]);
          if (tab) setDirty((d) => (d[tab] ? d : { ...d, [tab]: true }));
        }}
      >
        <Tabs
          activeKey={activeTab}
          onChange={(key) => !saving && setActiveTab(key as TabKey)}
          // Only the visible tab's fields are validated and saved.
          destroyInactiveTabPane
          items={[
            {
              key: "availability",
              label: tabLabel("availability", "Availability"),
              children: <AvailabilitySection />,
            },
            { key: "license", label: tabLabel("license", "License"), children: <LicenseSection /> },
            {
              key: "preferences",
              label: tabLabel("preferences", "Preferences"),
              children: <PreferencesSection partners={partners} />,
            },
            ...trackingTabs,
          ]}
        />
      </Form>
    </Modal>
  );
};

export default EditDriverModal;
