import React, { FC } from "react";
import { Button, DatePicker, Select } from "antd";
import { CloseCircleFilled } from "@ant-design/icons";
import moment, { Moment } from "moment";

import { ProgramLevel } from "./data";
import { DateRange, EMPTY_FILTERS, Filters } from "./types";
import { FilterDef } from "./api/mapEvents";

const { RangePicker } = DatePicker;

/** Stored `YYYY-MM-DD` bounds into the moments the RangePicker shows. */
const rangeValue = (range?: DateRange): [Moment | null, Moment | null] | null =>
  range && (range.from || range.to)
    ? [range.from ? moment(range.from) : null, range.to ? moment(range.to) : null]
    : null;

/** The RangePicker's moments back into stored `YYYY-MM-DD` bounds. */
const toRange = (value: [Moment | null, Moment | null] | null): DateRange | undefined => {
  if (!value) return undefined;
  const [from, to] = value;
  return { from: from?.format("YYYY-MM-DD"), to: to?.format("YYYY-MM-DD") };
};

/** Used by the event card, drawer and page to label a project's subtype. */
export const PROFILE_LABEL: Record<ProgramLevel, string> = {
  rec: "Recreational",
  travel: "Travel",
};

interface Props {
  filters: Filters;
  onChange: (filters: Filters) => void;
  /** One dropdown per choice element of the event form; empty for sign-up. */
  filterDefs?: FilterDef[];
  /** Extra controls above the filters, e.g. search and sort for events. */
  toolbar?: React.ReactNode;
  /** Called by "Clear" in addition to resetting the shared filters. */
  onClear?: () => void;
  className?: string;
}

/**
 * One control per filterable element on the event form
 * (data.blocks[].elements[]): a dropdown for a choice widget, a date-range
 * picker for a date widget. Nothing here knows what the widgets mean, so a
 * question added, removed or re-marked in the form builder is reflected
 * without a change here.
 */
const FilterBar: FC<Props> = ({ filters, onChange, filterDefs = [], toolbar, onClear, className }) => {
  const setAnswer = (id: string, value?: string) => {
    const answers = { ...filters.answers };
    if (value) answers[id] = value;
    else delete answers[id];
    onChange({ ...filters, answers });
  };

  const setRange = (id: string, range?: DateRange) => {
    const dates = { ...filters.dates };
    if (range && (range.from || range.to)) dates[id] = range;
    else delete dates[id];
    onChange({ ...filters, dates });
  };

  // Only count selections for filters the form still defines, so a removed
  // filter never lingers in the "Clear" count.
  const count = filterDefs.filter((def) =>
    def.kind === "date" ? Boolean(filters.dates[def.id]) : Boolean(filters.answers[def.id])
  ).length;

  return (
    <div className={`programs-card programs-toolbar${className ? ` ${className}` : ""}`}>
      {toolbar && <div className="programs-toolbar__row">{toolbar}</div>}

      <div className={`programs-toolbar__filters${toolbar ? "" : " is-flush"}`}>
        {filterDefs.map((def) => (
          <FilterGroup key={def.id} label={def.label}>
            {def.kind === "date" ? (
              <RangePicker
                className="programs-toolbar__dates"
                value={rangeValue(filters.dates[def.id])}
                onChange={(value) => setRange(def.id, toRange(value))}
              />
            ) : (
              <Select
                allowClear
                placeholder="All"
                className="programs-toolbar__age"
                value={filters.answers[def.id]}
                onChange={(value) => setAnswer(def.id, value)}
                options={def.options.map((option) => ({ value: option, label: option }))}
              />
            )}
          </FilterGroup>
        ))}

        {count > 0 && (
          <Button
            type="link"
            className="programs-link programs-toolbar__clear"
            icon={<CloseCircleFilled />}
            onClick={() => {
              onChange(EMPTY_FILTERS);
              onClear?.();
            }}
          >
            Clear {count}
          </Button>
        )}
      </div>
    </div>
  );
};

const FilterGroup: FC<{ label: string }> = ({ label, children }) => (
  <div className="programs-filter">
    <span className="programs-filter__label">{label}</span>
    {children}
  </div>
);

export default FilterBar;
