/**
 * Pure helpers for the Ride "Map" tab (FleetPanel). They turn the redux data
 * the old Ride MapPanel drew (trip pins, blocked area, stands, fleet zones,
 * assets, selected drivers) into plain shapes. Nothing here touches `google`.
 */
import type { FleetVehicle } from "../../Fleet/fleetUtils";

export interface LatLng {
  lat: number;
  lng: number;
}

const num = (v: any): number | undefined => {
  if (v === null || v === undefined || v === "") return undefined;
  const n = Number(v);
  return Number.isFinite(n) ? n : undefined;
};

const point = (lat: any, lng: any): LatLng | undefined => {
  const a = num(lat);
  const b = num(lng);
  return a === undefined || b === undefined ? undefined : { lat: a, lng: b };
};

/* ------------------------------------------------------------ drivers */

/**
 * A getResponders responder as the dispatch form stores it in
 * `selectedResponders` — identical to the old MapService.createPlaceMarker
 * output, because the submit maps it to `{ id: r.id, beamId: r.title }` and
 * DriversList reads `profile` / `beamIds` from it.
 */
export const toDispatchResponder = (responder: any, vehicles?: any[]) => {
  let location: any;
  (responder?.location?.geoJson?.features ?? []).forEach((feature: any) => {
    if (!location && feature?.geometry?.coordinates?.length > 0) location = feature.geometry;
  });
  let title =
    responder?.beamIds?.[0] || `${responder?.profile?.firstName}.${responder?.profile?.lastName}`;
  (vehicles ?? []).forEach((v: any) => {
    if (v?.id === responder?.id) title = v.name;
  });
  const lat = location?.coordinates?.[1];
  const lng = location?.coordinates?.[0];
  return {
    ...responder,
    lat,
    lng,
    title,
    color: "orange",
    paths: { lat, lng },
    type: "marker",
    filter: "viewOnly",
    fitBounds: false,
  };
};

/** Fleet vehicle ids (stringified responder ids) already added to the dispatch. */
export const pickedVehicleIds = (selectedResponders?: any[]): string[] =>
  (selectedResponders ?? []).filter((r) => r?.id !== undefined && r?.id !== null).map((r) => `${r.id}`);

/** The old map only let the dispatcher pick available (green) drivers; removing is always allowed. */
export const canAssign = (vehicle: Pick<FleetVehicle, "status">, picked: boolean) =>
  picked || vehicle.status === "green";

/* ---------------------------------------------------------- trip pins */

export type PinRole = "pickup" | "dropoff" | "other";

export interface TripPin extends LatLng {
  key: string;
  role: PinRole;
  title?: string;
}

/** `state.auth.otherLocations` ({ pickupLocation, dropoffLocation, … }) → pins with a location. */
export const tripPins = (otherLocations?: Record<string, any>): TripPin[] =>
  Object.keys(otherLocations ?? {}).reduce<TripPin[]>((pins, key) => {
    const loc = otherLocations![key];
    const p = point(loc?.value?.coordinates?.lat, loc?.value?.coordinates?.long);
    if (!p) return pins;
    const role: PinRole = key === "pickupLocation" ? "pickup" : key === "dropoffLocation" ? "dropoff" : "other";
    pins.push({ ...p, key, role, title: loc?.label ?? loc?.value?.description });
    return pins;
  }, []);

/**
 * Ends of the driving route. Pickup → dropoff when both are set; otherwise
 * the old map's rule (exactly two pins, in insertion order).
 */
export const routeEnds = (pins: TripPin[]): [TripPin, TripPin] | undefined => {
  const pickup = pins.find((p) => p.role === "pickup");
  const dropoff = pins.find((p) => p.role === "dropoff");
  if (pickup && dropoff) return [pickup, dropoff];
  return pins.length === 2 ? [pins[0], pins[1]] : undefined;
};

/* ------------------------------------------------------- areas / POIs */

/** GeoJSON [lng, lat] ring (optionally wrapped in its polygon array) → paths. */
export const ringToPaths = (coordinates: any): LatLng[] => {
  const ring = Array.isArray(coordinates?.[0]?.[0]) ? coordinates[0] : coordinates;
  return (Array.isArray(ring) ? ring : [])
    .map((c: any) => point(c?.[1], c?.[0]))
    .filter((p: LatLng | undefined): p is LatLng => !!p);
};

export type AreaShape =
  | { kind: "polygon"; id?: string; name?: string; paths: LatLng[] }
  | { kind: "circle"; id?: string; name?: string; center: LatLng; radius: number };

/** A geofence (`{ location: { type, coordinates }, radius }`) → drawable shape. */
export const geofenceShape = (geofence: any, circleByDefault = false): AreaShape | undefined => {
  const type = geofence?.location?.type;
  const meta = { id: geofence?._id, name: geofence?.name };
  if (type === "Polygon") {
    const paths = ringToPaths(geofence.location.coordinates);
    return paths.length > 2 ? { kind: "polygon", paths, ...meta } : undefined;
  }
  if (type === "Circle" || (circleByDefault && geofence)) {
    const center = point(geofence?.location?.coordinates?.[1], geofence?.location?.coordinates?.[0]);
    const radius = num(geofence?.radius);
    return center && radius ? { kind: "circle", center, radius, ...meta } : undefined;
  }
  return undefined;
};

/** `…admin.fleetZones.items` from the admin's bio → zone shapes. */
export const fleetZoneShapes = (items: any): AreaShape[] =>
  Object.values(items ?? {})
    .map((zone: any) => geofenceShape(zone?.zoneGeofenceId))
    .filter((s): s is AreaShape => !!s);

/** Stand (blocked-area POI) position; stands store `{ lat, long }`. */
export const standPosition = (stand: any): LatLng | undefined =>
  point(stand?.location?.coordinates?.lat, stand?.location?.coordinates?.long);

/** Same as the old MapService.createAssetMarker, but undefined instead of throwing on bad data. */
export const toAssetMarker = (item: any) => {
  const type = item?.metadata?.type;
  const obj = type === "fixedAsset" ? item?.asset : type === "poi" ? item?.poi : undefined;
  const location = obj?.location;
  const p = point(location?.coordinates?.lat, location?.coordinates?.long);
  if (!p) return undefined;
  return {
    ...obj,
    id: item.id,
    assetType: type,
    ...p,
    title: location?.attributes?.title,
    color: "orange",
    paths: p,
    type: "marker",
    filter: "viewOnly",
    fitBounds: false,
  };
};

/** Centre of a set of points (bounding-box centre, like LatLngBounds.getCenter). */
export const boundsCenter = (paths: LatLng[]): LatLng | undefined => {
  if (!paths.length) return undefined;
  const lats = paths.map((p) => p.lat);
  const lngs = paths.map((p) => p.lng);
  return {
    lat: (Math.min(...lats) + Math.max(...lats)) / 2,
    lng: (Math.min(...lngs) + Math.max(...lngs)) / 2,
  };
};

/** URL `lat`/`lng` (web booker) as a centre, if valid. */
export const centerFromQuery = (search: string): LatLng | undefined => {
  const q = new URLSearchParams(search);
  return point(q.get("lat") ?? undefined, q.get("lng") ?? undefined);
};
