import React, { FC } from "react";
import { Card, Col, Row, Tooltip } from "antd";
import {
  BankOutlined,
  DollarCircleOutlined,
  FundOutlined,
  RiseOutlined,
  RollbackOutlined,
  ShoppingOutlined,
  TagsOutlined,
  WalletOutlined,
} from "@ant-design/icons";

import { ExecutiveKpis } from "./types";

/** One tile of a KPI row, in the School3 overview style. */
export interface KpiTile {
  key: string;
  label: string;
  /** Tooltip over the tile. */
  hint?: React.ReactNode;
  value: React.ReactNode;
  /** Small line under the value. */
  sub?: React.ReactNode;
  icon: React.ReactNode;
  color: string;
  bg: string;
}

export interface KpiMeta {
  key: keyof ExecutiveKpis;
  label: string;
  hint: string;
  icon: React.ReactNode;
  color: string;
  bg: string;
  /** Whether a rise in the figure is good news (revenue) or bad (costs). */
  upIs: "good" | "bad";
}

/**
 * The eight dashboard tiles, in reading order: the P&L line first
 * (gross → net revenue, costs, profit), then the cash line.
 */
export const DASHBOARD_KPI_META: KpiMeta[] = [
  {
    key: "grossRevenue",
    label: "Gross Revenue",
    hint: "Total contracted rack-rate value across all active projects, classes, teams, and billing schedules.",
    icon: <DollarCircleOutlined />,
    color: "#463BBD",
    bg: "#ECEAFB",
    upIs: "good",
  },
  {
    key: "deductions",
    label: "Deductions",
    hint: "Cumulative non-cash reductions (0%–100% financial aid scholarships, sibling discounts, early-bird codes).",
    icon: <TagsOutlined />,
    color: "#FBAE16",
    bg: "#FEF5E1",
    upIs: "bad",
  },
  {
    key: "netRevenue",
    label: "Net Revenue",
    hint: "Contracted billing commitments after deductions (Gross Revenue − Deductions).",
    icon: <FundOutlined />,
    color: "#508AFA",
    bg: "#E6F0FF",
    upIs: "good",
  },
  {
    key: "costs",
    label: "Costs",
    hint: "Invoiced payables: coaches, staff, vendors and other programme costs booked against the same projects.",
    icon: <ShoppingOutlined />,
    color: "#FF5F25",
    bg: "#FFEDE6",
    upIs: "bad",
  },
  {
    key: "profit",
    label: "Profit",
    hint: "Net Revenue − Costs. The margin under the figure is profit as a share of net revenue.",
    icon: <RiseOutlined />,
    color: "#1F9D55",
    bg: "#E4F6EC",
    upIs: "good",
  },
  {
    key: "collections",
    label: "Collections",
    hint: "Cleared, verified cash inflows received via Credit Card capture and settled VAR/CPC invoices.",
    icon: <WalletOutlined />,
    color: "#1F9D55",
    bg: "#E4F6EC",
    upIs: "good",
  },
  {
    key: "refunds",
    label: "Refunds",
    hint: "Gross capital returned due to withdrawals, season-ending injuries, or program cancellations.",
    icon: <RollbackOutlined />,
    color: "#FF5F25",
    bg: "#FFEDE6",
    upIs: "bad",
  },
  {
    key: "netCollected",
    label: "Net Collected",
    hint: "Net cash retained from customer billings (Net Collected = Collections − Refunds).",
    icon: <BankOutlined />,
    color: "#463BBD",
    bg: "#ECEAFB",
    upIs: "good",
  },
];

interface Props {
  tiles: KpiTile[];
  /** antd column spans; four across on a wide screen by default. */
  span?: { xs?: number; sm?: number; lg?: number; xl?: number };
}

/**
 * KPI row in the School3 overview style: tinted icon square on the
 * left, label and value on the right.
 */
const KpiCards: FC<Props> = ({ tiles, span }) => {
  const cols = { xs: 24, sm: 12, lg: 6, ...(span || {}) };
  return (
    <Row gutter={[20, 20]} className="kpi-row">
      {tiles.map((tile) => (
        <Col key={tile.key} xs={cols.xs} sm={cols.sm} lg={cols.lg} xl={cols.xl}>
          <Tooltip title={tile.hint}>
            <Card className="kpi-card" bordered={false}>
              <div className="kpi-card-body">
                <div
                  className="kpi-icon"
                  style={{ color: tile.color, background: tile.bg }}
                >
                  {tile.icon}
                </div>
                <div className="kpi-text">
                  <span className="kpi-label">{tile.label}</span>
                  <span className="kpi-value">{tile.value}</span>
                  {tile.sub && <span className="kpi-sub">{tile.sub}</span>}
                </div>
              </div>
            </Card>
          </Tooltip>
        </Col>
      ))}
    </Row>
  );
};

export default KpiCards;
