import React, { FC } from "react";
import { Badge, Button, Card, Empty } from "antd";
import { BellOutlined, ThunderboltOutlined } from "@ant-design/icons";

import { DunningAlert } from "./types";
import { DUNNING_META, formatMoney, formatOffset } from "./selectors";

/** Maps a dunning tone onto the School3 notification dot colours. */
const DOT_CLASS: Record<string, string> = {
  info: "success",
  warning: "warning",
  danger: "error",
  critical: "error",
};

interface Props {
  alerts: DunningAlert[];
  now: number;
  /** Jumps the transactions table to the account behind an alert. */
  onInspect: (alert: DunningAlert) => void;
  onNotify: (alert: DunningAlert) => void;
}

/**
 * Dunning and operational alerts, newest deadline first.
 *
 * Mirrors the automated notification engine into the CFO view so an
 * override can be applied before an account is frozen at T+336h.
 */
const AlertCenter: FC<Props> = ({ alerts, now, onInspect, onNotify }) => {
  const ordered = alerts.slice().sort((a, b) => a.dueAt - b.dueAt);

  return (
    <Card
      className="report-card cfo-alert-card"
      bordered={false}
      title={
        <span className="report-card-title">
          <BellOutlined style={{ color: "#FBAE16" }} /> Dunning Alerts
          <Badge
            count={alerts.length}
            style={{ backgroundColor: "#E5484D", marginLeft: 4 }}
          />
        </span>
      }
      extra={<span className="report-card-date">In window</span>}
      bodyStyle={{ maxHeight: 380, overflowY: "auto" }}
    >
      {ordered.length === 0 && (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description="No alerts in this window"
        />
      )}

      <ul className="notification-list">
        {ordered.map((alert) => {
          const meta = DUNNING_META[alert.bucket];
          return (
            <li key={alert.id}>
              <span className={`notif-dot ${DOT_CLASS[meta.tone]}`} />
              <div className="cfo-alert__body">
                <p className="notif-title">{alert.title}</p>
                <span className="notif-time">
                  {alert.entity} · {alert.project} · {alert.bucket}{" "}
                  {formatOffset(alert.dueAt, now)}
                </span>
                <div className="cfo-alert__actions">
                  <Button size="small" type="link" onClick={() => onInspect(alert)}>
                    Inspect
                  </Button>
                  <Button
                    size="small"
                    type="link"
                    icon={<ThunderboltOutlined />}
                    onClick={() => onNotify(alert)}
                  >
                    Notify
                  </Button>
                </div>
              </div>
              <span className="cfo-alert__amount">
                {formatMoney(alert.amount, alert.currency)}
              </span>
            </li>
          );
        })}
      </ul>
    </Card>
  );
};

export default AlertCenter;
