import React, { FC } from "react";
import { Button, Checkbox, Col, Form, Row, TimePicker } from "antd";
import { DeleteOutlined, PlusOutlined } from "@ant-design/icons";
import moment from "moment";
import { Day, DAY_ORDER, TimeWindow } from "services/apis/aiSchedulerTypes";

// Form values hold moments for the pickers; the API wants "HH:MM" strings.
export interface WindowFormValue {
  days: Day[];
  start: any;
  end: any;
}

export const windowsToForm = (windows?: TimeWindow[]): WindowFormValue[] =>
  (windows || []).map((w) => ({
    days: w.days || [],
    start: w.start ? moment(w.start, "HH:mm") : undefined,
    end: w.end ? moment(w.end, "HH:mm") : undefined,
  }));

export const formToWindows = (values?: WindowFormValue[]): TimeWindow[] =>
  (values || [])
    .filter((v) => v && v.days?.length && v.start && v.end)
    .map((v) => ({
      days: v.days,
      start: v.start.format("HH:mm"),
      end: v.end.format("HH:mm"),
    }));

const DAY_OPTIONS = DAY_ORDER.map((d) => ({
  label: d.charAt(0).toUpperCase() + d.slice(1, 3),
  value: d,
}));

const AvailabilityWindowsEditor: FC<{
  name: string | (string | number)[];
  label: string;
  helpText?: string;
  slotMinutes?: number;
}> = ({ name, label, helpText, slotMinutes }) => {
  return (
    <div className="availability-windows-editor">
      <div className="ant-form-item-label" style={{ paddingBottom: 4 }}>
        <label>{label}</label>
      </div>
      {helpText && (
        <p style={{ color: "#8c8c8c", marginBottom: 8, fontSize: 12 }}>{helpText}</p>
      )}
      <Form.List name={name}>
        {(fields, { add, remove }) => (
          <>
            {fields.map((field) => (
              <Row
                key={field.key}
                gutter={8}
                align="middle"
                className="availability-window-row"
                style={{ marginBottom: 8 }}
              >
                <Col flex="auto">
                  <Form.Item
                    name={[field.name, "days"]}
                    fieldKey={[field.fieldKey, "days"]}
                    rules={[{ required: true, message: "Pick at least one day" }]}
                    style={{ marginBottom: 4 }}
                  >
                    <Checkbox.Group options={DAY_OPTIONS} />
                  </Form.Item>
                  <Row gutter={8}>
                    <Col span={12}>
                      <Form.Item
                        name={[field.name, "start"]}
                        fieldKey={[field.fieldKey, "start"]}
                        rules={[{ required: true, message: "Start time required" }]}
                        style={{ marginBottom: 0 }}
                      >
                        <TimePicker
                          format="HH:mm"
                          minuteStep={slotMinutes || 5}
                          placeholder="Start"
                          style={{ width: "100%" }}
                        />
                      </Form.Item>
                    </Col>
                    <Col span={12}>
                      <Form.Item
                        name={[field.name, "end"]}
                        fieldKey={[field.fieldKey, "end"]}
                        dependencies={[[...(Array.isArray(name) ? name : [name]), field.name, "start"]]}
                        rules={[
                          { required: true, message: "End time required" },
                          ({ getFieldValue }) => ({
                            validator(_, value) {
                              const path = Array.isArray(name) ? name : [name];
                              const start = getFieldValue([...path, field.name, "start"]);
                              if (!value || !start || value.isAfter(start)) {
                                return Promise.resolve();
                              }
                              return Promise.reject(new Error("End must be after start"));
                            },
                          }),
                        ]}
                        style={{ marginBottom: 0 }}
                      >
                        <TimePicker
                          format="HH:mm"
                          minuteStep={slotMinutes || 5}
                          placeholder="End"
                          style={{ width: "100%" }}
                        />
                      </Form.Item>
                    </Col>
                  </Row>
                </Col>
                <Col>
                  <Button
                    type="text"
                    icon={<DeleteOutlined />}
                    onClick={() => remove(field.name)}
                  />
                </Col>
              </Row>
            ))}
            <Button
              type="dashed"
              block
              icon={<PlusOutlined />}
              onClick={() => add({ days: [] })}
            >
              Add window
            </Button>
          </>
        )}
      </Form.List>
    </div>
  );
};

export default AvailabilityWindowsEditor;
