import React from "react";
import { Button, Col, Dropdown, Row } from "antd";
import {
  DownloadOutlined,
  FileExcelOutlined,
  FilePdfOutlined,
  FileTextOutlined,
} from "@ant-design/icons";
import { DashboardFilters, SelectOption, TimeRangeValue } from "../../types";
import TimeRangeSelector from "../TimeRangeSelector";
import { AreaFilter, EntityFilter, PatientSearch } from "./FilterFields";
import "./filters.scss";

type ExportType = "csv" | "xlsx" | "pdf";

interface Props {
  visible: boolean;
  filters: DashboardFilters;
  onChange: (patch: Partial<DashboardFilters>) => void;
  onTimeRangeChange: (value: TimeRangeValue) => void;
  onExport: (type: ExportType) => void;
  onClearAll: () => void;
  activeCount: number;
  entityOptions: SelectOption[];
  entityLoading: boolean;
  areaOptions: SelectOption[];
  areaLoading: boolean;
}

const EXPORT_ITEMS = [
  { key: "csv", label: "CSV", icon: <FileTextOutlined /> },
  { key: "xlsx", label: "Excel (.xlsx)", icon: <FileExcelOutlined /> },
  { key: "pdf", label: "PDF", icon: <FilePdfOutlined /> },
];

const Group = ({ title, children }: { title: string; children: React.ReactNode }) => (
  <div className="mx-filters__group">
    <div className="mx-filters__group-title">{title}</div>
    {children}
  </div>
);

// Kept mounted while hidden so in-progress input isn't lost when toggled.
const FilterPanel = ({
  visible,
  filters,
  onChange,
  onTimeRangeChange,
  onExport,
  onClearAll,
  activeCount,
  entityOptions,
  entityLoading,
  areaOptions,
  areaLoading,
}: Props) => (
  <div className="mx-filters" style={visible ? undefined : { display: "none" }}>
    <div className="mx-filters__header">
      <div className="mx-filters__title">
        Filters
        {activeCount > 0 && <span className="mx-filters__count">{activeCount}</span>}
      </div>
      <div className="mx-filters__header-actions">
        {activeCount > 0 && (
          <Button type="link" size="small" onClick={onClearAll}>
            Clear all
          </Button>
        )}
        <Dropdown
          trigger={["click"]}
          menu={{ items: EXPORT_ITEMS, onClick: ({ key }) => onExport(key as ExportType) }}
        >
          <Button className="mx-btn-secondary" size="small" icon={<DownloadOutlined />}>
            Export
          </Button>
        </Dropdown>
      </div>
    </div>

    <Row gutter={[20, 16]}>
      <Col xs={24} lg={8}>
        <Group title="Who">
          <EntityFilter
            filters={filters}
            onChange={onChange}
            options={entityOptions}
            loading={entityLoading}
          />
        </Group>
      </Col>
      <Col xs={24} lg={8}>
        <Group title="Where">
          <AreaFilter
            filters={filters}
            onChange={onChange}
            options={areaOptions}
            loading={areaLoading}
          />
        </Group>
      </Col>
      <Col xs={24} lg={8}>
        <Group title="When">
          <TimeRangeSelector value={filters.timeRange} onChange={onTimeRangeChange} />
        </Group>
        <Group title="Patient">
          <PatientSearch filters={filters} onChange={onChange} />
        </Group>
      </Col>
    </Row>
  </div>
);

export default FilterPanel;
