import React, { FC } from "react";

import { Reminders } from "../../types";
import { REMINDER_CHANNELS } from "../../paymentConfig";
import { DayListField, FormRow, NullableNumberField, SelectField, SwitchField } from "../fields";
import { SectionProps } from "./types";

const RemindersSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const r = config.reminders;
  const patchR = (changes: Partial<Reminders>) => patch({ reminders: { ...r, ...changes } });

  return (
    <>
      <FormRow>
        <DayListField
          label="Days before due (e.g. 7, 3)"
          value={r.preDueDays}
          disabled={disabled}
          placeholder="7, 3"
          onChange={(preDueDays) => patchR({ preDueDays })}
        />
        <DayListField
          label="Days past due (e.g. 1, 5, 10)"
          value={r.pastDueDays}
          disabled={disabled}
          placeholder="1, 5, 10"
          onChange={(pastDueDays) => patchR({ pastDueDays })}
        />
        <NullableNumberField
          label="Suspend after days past due (blank = never)"
          value={r.suspensionAfterDays}
          disabled={disabled}
          onChange={(suspensionAfterDays) => patchR({ suspensionAfterDays })}
        />
      </FormRow>
      <FormRow>
        <SelectField
          label="Channels"
          mode="multiple"
          value={r.channels}
          disabled={disabled}
          options={REMINDER_CHANNELS}
          onChange={(channels) => patchR({ channels })}
        />
        <SwitchField
          label="Send a reminder on the due date"
          checked={r.onDueDate}
          disabled={disabled}
          onChange={(onDueDate) => patchR({ onDueDate })}
        />
      </FormRow>
    </>
  );
};

export default RemindersSection;
