import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { SyncOutlined } from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SocketTopics } from "constants/enums";
import { syncUserRequestPublishTopic, syncUserSubscriptionTopic } from "hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../helpers/request/RequestPayload";
import { generateUUID } from "utils/appUtil";
import { pushNotification } from "utils/notifications";
import { USER_TYPES } from "utils/PageTypes";
import { DataTableCard, EmptyState, PageHeader } from "../common/ui";
import { REQUEST_TIMEOUT_MS, StaffRow } from "./Driver/staffApi";
import {
  ContactCell,
  FlagCell,
  PersonCell,
  RoleCell,
  countCaption,
  useStaffList,
} from "./Driver/staffList";
import "./Dashboard.scss";
import "./Driver/Driver.scss";

const COLUMNS: ColumnsType<StaffRow> = [
  {
    title: "Dispatcher",
    key: "name",
    sorter: (a, b) => a.name.localeCompare(b.name),
    render: (_, row) => <PersonCell row={row} />,
  },
  {
    title: "Contact",
    key: "contact",
    render: (_, row) => <ContactCell row={row} />,
  },
  {
    title: "Role",
    key: "role",
    render: (_, row) => <RoleCell row={row} />,
  },
  {
    title: "Flag",
    key: "flag",
    align: "center",
    width: 70,
    render: (_, row) => <FlagCell row={row} />,
  },
];

const DispatcherModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, componentUuid, userRole }) => {
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const uuid = useRef(componentUuid || generateUUID()).current;
  const { rows, loading, loadFailed, search, onSearch, load } = useStaffList(
    USER_TYPES.Dispatcher,
    userRole
  );
  const [syncingId, setSyncingId] = useState<string | null>(null);
  // Sync replies arrive on a shared topic in request order.
  const pendingSync = useRef<{ resolve: (response: any) => void; timer: any }[]>([]);
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    document.title = "Dispatcher | Beam";
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      syncUserSubscriptionTopic(encrypted_token?.connectionId),
      (response) => {
        const next = pendingSync.current.shift();
        if (!next) return;
        clearTimeout(next.timer);
        next.resolve(response);
      },
      uuid
    );
    return () => {
      mounted.current = false;
      pendingSync.current.forEach((p) => clearTimeout(p.timer));
      pendingSync.current = [];
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /** Resolves with the reply, or null if none arrives in time. */
  const addUserToOrgPages = (userId: string) =>
    new Promise<any>((resolve) => {
      const entry = { resolve, timer: undefined as any };
      entry.timer = setTimeout(() => {
        pendingSync.current = pendingSync.current.filter((p) => p !== entry);
        resolve(null);
      }, REQUEST_TIMEOUT_MS);
      pendingSync.current.push(entry);
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        syncUserRequestPublishTopic(encrypted_token?.connectionId),
        wrapRequestPayload({ userId: userId?.toString(), serviceId: projects?.userServiceId })
      );
    });

  const syncUser = async (row: StaffRow) => {
    setSyncingId(row.key);
    const response = await addUserToOrgPages(row.key);
    if (!mounted.current) return;
    setSyncingId(null);
    if (response?.response?.status) {
      pushNotification(`Sync requested for ${row.name}`, "success", "TOP_CENTER", 2000);
    } else {
      pushNotification(
        response?.response?.data?.details ||
          (response ? "Sync failed. Please try again." : "No response from the server. Please try again."),
        "error",
        "TOP_CENTER",
        3000
      );
    }
  };

  // The handler changes every render; columns read it through a ref.
  const latest = useRef<any>({});
  latest.current = { syncUser };

  const columns: ColumnsType<StaffRow> = useMemo(
    () => [
      ...COLUMNS,
      {
        title: "",
        key: "actions",
        align: "right",
        width: 60,
        render: (_, row) => (
          <Tooltip title="Sync to organization pages">
            <Button
              size="small"
              className="mx-staff__sync"
              icon={<SyncOutlined spin={syncingId === row.key} />}
              disabled={!!syncingId}
              onClick={() => latest.current.syncUser(row)}
            />
          </Tooltip>
        ),
      },
    ],
    [syncingId]
  );

  const searching = !!search.trim();
  const emptyState = loadFailed ? (
    <EmptyState
      title="Couldn't load dispatchers"
      description={
        <Button className="mx-btn-secondary mt-2" onClick={() => load()}>
          Try again
        </Button>
      }
    />
  ) : searching ? (
    <EmptyState
      title="No matching dispatchers"
      description="Search matches first name, last name or Beam ID (at least 3 characters)."
    />
  ) : (
    <EmptyState
      title="No dispatchers yet"
      description="Users with a dispatch (CAD) or admin role appear here."
    />
  );

  return (
    <div className="mx-staff">
      <PageHeader
        title="Dispatchers"
        subtitle="Users who can book and dispatch trips. Use sync if someone can't see the organization's pages."
        search={{
          value: search,
          onChange: onSearch,
          placeholder: "Search by name or Beam ID",
          loading,
        }}
      />

      <DataTableCard<StaffRow>
        rowKey="key"
        loading={loading}
        caption={countCaption(rows.length, "dispatcher", searching)}
        columns={columns}
        dataSource={rows}
        empty={emptyState}
        scroll={{ x: true }}
      />
    </div>
  );
};

export default DispatcherModal;
