import React, { FC } from "react";

import { formatMoney, formatMoneyShort } from "../selectors";
import { ChartApi } from "./ChartFrame";
import { barPath, linearScale, niceTicks, tickText, useElementWidth } from "./scale";
import { MARK, Series } from "./theme";

/** One horizontal bar: a name, its segments by series key, and the bar's total. */
export interface StackItem {
  id: string;
  name: string;
  values: Record<string, number>;
  total: number;
  /** Extra tooltip lines under the segments (e.g. margin %). */
  extra?: { label: string; value: string }[];
  /** Roll-up rows ("Other") cannot be selected. */
  selectable?: boolean;
}

interface Props {
  items: StackItem[];
  series: Series[];
  currency: string;
  api: ChartApi;
  selected: string | null;
  onSelect: (id: string) => void;
}

const ROW = 34;
const MARGIN = { top: 8, right: 76, bottom: 24, left: 150 };

const truncate = (text: string, max = 22) => (text.length > max ? `${text.slice(0, max - 1)}…` : text);

/**
 * Horizontal stacked bars, one per item: the series separated by surface
 * gaps, the total at the tip. Clicking a bar emphasises it and reports
 * the selection to the caller.
 */
const StackedBarChart: FC<Props> = ({ items, series, currency, api, selected, onSelect }) => {
  const [ref, width] = useElementWidth();
  const height = MARGIN.top + items.length * ROW + MARGIN.bottom;
  const plotW = Math.max(0, width - MARGIN.left - MARGIN.right);

  const max = Math.max(...items.map((p) => p.total), 0);
  const ticks = niceTicks(max, 4);
  const x = linearScale([0, ticks[ticks.length - 1]], [MARGIN.left, MARGIN.left + plotW]);
  const barH = Math.min(MARK.barMax, ROW - 12);

  return (
    <div ref={ref} className="cfo-chart__svg-wrap">
      {width > 0 && (
        <svg width={width} height={height} className="cfo-chart__svg">
          {ticks.map((tick) => (
            <g key={tick}>
              <line x1={x(tick)} x2={x(tick)} y1={MARGIN.top} y2={height - MARGIN.bottom} className="cfo-chart__grid" />
              <text x={x(tick)} y={height - 8} textAnchor="middle" className="cfo-chart__tick">
                {tickText(tick, currency)}
              </text>
            </g>
          ))}

          {items.map((item, i) => {
            const yTop = MARGIN.top + i * ROW + (ROW - barH) / 2;
            const dim = selected !== null && selected !== item.id;
            const selectable = item.selectable !== false;
            const valueOf = (key: string) => item.values[key] || 0;
            let cursor = 0;
            const lastNonZero = series.reduce((acc, s, idx) => (valueOf(s.key) > 0 ? idx : acc), -1);
            const rowsFor = () =>
              series
                .filter((s) => valueOf(s.key) > 0)
                .map((s) => ({
                  swatch: s.color,
                  label: s.label,
                  value: `${formatMoney(valueOf(s.key), currency)}${
                    item.total > 0 ? ` · ${Math.round((valueOf(s.key) / item.total) * 100)}%` : ""
                  }`,
                }))
                .concat([{ swatch: undefined as any, label: "Total", value: formatMoney(item.total, currency) }])
                .concat((item.extra || []).map((line) => ({ swatch: undefined as any, ...line })));
            const showRow = () => api.show({ x: x(item.total / 2), y: yTop - 4, title: item.name, rows: rowsFor() });

            const select = () => selectable && onSelect(item.id);

            return (
              <g key={item.id} className={dim ? "cfo-chart__bar--dim" : undefined}>
                {/* Row hit area sits under the segments: hover reads the whole row, focus/click select it. */}
                <rect
                  x={0}
                  y={MARGIN.top + i * ROW}
                  width={width}
                  height={ROW}
                  fill="transparent"
                  tabIndex={0}
                  aria-label={`${item.name} ${formatMoney(item.total, currency)}`}
                  className={selectable ? "cfo-chart__hit--click" : undefined}
                  onMouseEnter={showRow}
                  onMouseLeave={api.hide}
                  onFocus={showRow}
                  onBlur={api.hide}
                  onClick={select}
                  onKeyDown={(e) => {
                    if (selectable && (e.key === "Enter" || e.key === " ")) {
                      e.preventDefault();
                      select();
                    }
                  }}
                />

                <text x={MARGIN.left - 10} y={yTop + barH / 2} dy="0.35em" textAnchor="end" className="cfo-chart__label">
                  {truncate(item.name)}
                </text>

                {series.map((s, idx) => {
                  const value = valueOf(s.key);
                  const start = x(cursor);
                  const end = x(cursor + value);
                  cursor += value;
                  if (value <= 0) return null;
                  const gap = idx > 0 ? MARK.gap : 0;
                  const w = Math.max(0, end - start - gap);
                  const d =
                    idx === lastNonZero
                      ? barPath(start + gap, yTop, w, barH, MARK.radius, "right")
                      : `M${start + gap},${yTop} h${w} v${barH} h${-w} Z`;
                  return (
                    <path
                      key={s.key}
                      d={d}
                      fill={s.color}
                      className={selectable ? "cfo-chart__hit--click" : undefined}
                      onMouseEnter={() =>
                        api.show({
                          x: start + w / 2,
                          y: yTop - 4,
                          title: item.name,
                          rows: [
                            { swatch: s.color, label: s.label, value: formatMoney(value, currency) },
                            { label: "Share", value: `${Math.round((value / item.total) * 100)}% of ${formatMoney(item.total, currency)}` },
                          ],
                        })
                      }
                      onMouseLeave={api.hide}
                      onClick={select}
                    />
                  );
                })}

                <text x={x(item.total) + 8} y={yTop + barH / 2} dy="0.35em" className="cfo-chart__value">
                  {formatMoneyShort(item.total, currency)}
                </text>
              </g>
            );
          })}
        </svg>
      )}
    </div>
  );
};

export default StackedBarChart;
