import React, { FC } from "react";
import { Alert } from "antd";

const DiagnosticsPanel: FC<{
  diagnostics: string[];
  onClose: () => void;
}> = ({ diagnostics, onClose }) => (
  <Alert
    className="diagnostics-banner mb-3"
    type="error"
    showIcon
    closable
    onClose={onClose}
    message="The solver could not find a feasible schedule"
    description={
      <div>
        <p style={{ marginBottom: 6 }}>Resolve these conflicts and re-solve:</p>
        <ul style={{ paddingLeft: 18, marginBottom: 0 }}>
          {diagnostics.length ? (
            diagnostics.map((d, i) => <li key={i}>{d}</li>)
          ) : (
            <li>No detailed diagnostics were returned.</li>
          )}
        </ul>
      </div>
    }
  />
);

export default DiagnosticsPanel;
