import {
  Circle,
  DirectionsRenderer,
  GoogleMap,
  Marker,
  Polygon,
  withGoogleMap,
  withScriptjs,
  InfoWindow,
} from "react-google-maps";
import React, { useEffect, useRef } from "react";
import DrawingManager from "react-google-maps/lib/components/drawing/DrawingManager";
import { compose, withProps, withStateHandlers, lifecycle } from "recompose";
import { MAP } from "react-google-maps/lib/constants";
import { CloseOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { SET_SELECTED_RESPONDER, SET_SELECTED_ASSETS, SET_SELECTED_PICKUP } from "reducers/reducer";
import { GOOGLE_MAPS_KEY } from "../rideSync";

const getPaths = (polygon: any) => {
  var polygonBounds = polygon.getPath().getArray();
  var bounds = [];
  for (var i = 0; i < polygonBounds.length; i++) {
    var point = {
      lat: polygonBounds[i].lat(),
      lng: polygonBounds[i].lng(),
    };
    bounds.push(point);
  }
  bounds.push(bounds[0]);
  return bounds;
};

/*global google*/
const Map = compose<
  any,
  {
    setActive?: (show?: boolean) => void;
    markers?: any[];
    assetMarkers?: any[];
    currentMarkers?: any[];
    currentLocation?: any;
    polygon?: any;
    polygons?: any;
    circle?: any;
    stands?: any[];
    active?: boolean;
    getPlaces?: (bounds: any) => void;
  }
>(
  withProps({
    googleMapURL:
      `https://maps.googleapis.com/maps/api/js?key=${GOOGLE_MAPS_KEY}&v=3.exp&libraries=geometry,drawing,places`,
    loadingElement: <div style={{ height: `100%` }} />,
    containerElement: <div style={{ height: `100%` }} />,
    mapElement: <div style={{ height: `100%` }} />,
  }),
  withStateHandlers(
    () => ({
      isOpen: false,
      activeMarker: null,
      directions: null,
      selectDirectionPin: null,
      drawingMode: null,
      activeInfo: null,
      activePolygon: null,
    }),
    {
      onToggleOpen:
        ({ isOpen }) =>
        (marker) => ({
          isOpen: !isOpen,
          activeMarker: marker,
        }),
      showDirection: () => (result) => ({
        directions: result,
      }),
      setActivePolygon: () => (result) => ({
        activePolygon: result,
      }),
      setDrawingMode: () => (mode) => ({
        drawingMode: mode,
      }),
      setSelectDirectionPin: () => (pin) => ({
        selectDirectionPin: pin,
      }),
      setActiveInfo: () => (active) => ({
        activeInfo: active,
      }),
    }
  ),
  withScriptjs,
  withGoogleMap
)(
  ({
    isOpen,
    active,
    setActive,
    markers,
    assetMarkers,
    currentMarkers,
    currentLocation,
    getPlaces,
    setActiveInfo,
    activeInfo,
    showDirection,
    directions,
    polygon,
    circle,
    stands,
    polygons,
    setActivePolygon,
    activePolygon,
  }) => {
    const mapRef = useRef(null);
    const direction = useRef(false);
    // Survives re-renders (a plain `let` was reset every render, so the
    // bounds debounce never cancelled the previous timer).
    const timeoutRef = useRef<any>();
    // Auto-fit happens on first load and when the trip pins / stands change;
    // driver markers moving must not yank the view the dispatcher panned to.
    const hasFittedRef = useRef(false);
    const fitKeyRef = useRef<string>();
    const { selectedResponders, selectedAssets } = useSelector(
      (state: RootState) => state.auth
    );
    const dispatch = useDispatch();

    useEffect(() => {
      if (selectedResponders && selectedResponders.length > 0) {
        console.log("update component");
      }
    }, [selectedResponders]);

    useEffect(() => () => clearTimeout(timeoutRef.current), []);

    const onBoundsChanged = () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
      timeoutRef.current = setTimeout(() => {
        if (mapRef.current) {
          let bounds = mapRef.current.getBounds();
          if (bounds) {
            let ne = bounds.getNorthEast();
            let sw = bounds.getSouthWest();
            getPlaces({
              center: mapRef.current.getCenter(),
              bounds: {
                minLat: sw.lat(),
                maxLat: ne.lat(),
                minLon: sw.lng(),
                maxLon: ne.lng(),
              },
            });
          }
        }
      }, 500);
    };

    const handleDirections = (origin, destination) => {
      const DirectionsService = new google.maps.DirectionsService();
      DirectionsService.route(
        {
          origin: new google.maps.LatLng(origin.lat, origin.lng),
          destination: new google.maps.LatLng(destination.lat, destination.lng),
          travelMode: google.maps.TravelMode.DRIVING,
        },
        (result, status) => {
          if (status === google.maps.DirectionsStatus.OK) {
            if(direction.current){
              showDirection(result);
            }
          } else {
            console.error(`error fetching directions ${result}`);
          }
        }
      );
    };

    const fitBounds = () => {
      const bounds = new google.maps.LatLngBounds();
      markers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      assetMarkers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      currentMarkers.forEach((marker: any) => {
        bounds.extend({ lat: marker.lat, lng: marker.lng });
      });
      stands.forEach((marker: any) => {
        bounds.extend({
          lat: marker.location.coordinates?.lat,
          lng: marker.location.coordinates?.long,
        });
      });
      if (bounds.isEmpty()) return;
      mapRef.current.fitBounds(bounds);
      // if (currentMarkers.length === 1 && markers.length === 0) {
      //   setTimeout(() => {
      //     mapRef.current.context[MAP].setZoom(15);
      //   }, 100);
      // }
    };

    // useEffect(() => {
    //   if (currentLocation && mapRef.current) {
    //     mapRef.current.context[MAP].setZoom(16);
    //   }
    // }, [currentLocation]);

    function getPolygonCenter(paths) {
      const bounds = new window.google.maps.LatLngBounds();
      paths.forEach((path) => bounds.extend(path));
      return bounds.getCenter();
    }

    // Trip pins and stands are what the dispatcher explicitly picked.
    const explicitFitKey = JSON.stringify([
      (currentMarkers || []).map((m: any) => [m.lat, m.lng]),
      (stands || []).map((m: any) => [
        m?.location?.coordinates?.lat,
        m?.location?.coordinates?.long,
      ]),
    ]);

    useEffect(() => {
      const hasPoints =
        (markers?.length || 0) +
          (assetMarkers?.length || 0) +
          (currentMarkers?.length || 0) +
          (stands?.length || 0) >
        0;
      if (
        mapRef.current &&
        hasPoints &&
        (!hasFittedRef.current || fitKeyRef.current !== explicitFitKey)
      ) {
        fitBounds();
        hasFittedRef.current = true;
        fitKeyRef.current = explicitFitKey;
      }
    }, [markers, assetMarkers, explicitFitKey]);

    useEffect(() => {
      if (currentMarkers && currentMarkers.length === 2) {
        direction.current = true;
        handleDirections(currentMarkers[0], currentMarkers[1]);
      } else {
        direction.current = false;
        showDirection(undefined);
      }
    }, [explicitFitKey]);

    const mapStyle = [
      // {
      //   elementType: "labels",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // },
      // {
      //   featureType: "administrative.land_parcel",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // },
      // {
      //   featureType: "administrative.neighborhood",
      //   stylers: [
      //     {
      //       visibility: "off"
      //     }
      //   ]
      // }
      {
        featureType: 'poi',
        stylers: [{visibility: 'off'}]
      },
      {
        featureType: 'transit',
        stylers: [{visibility: 'off'}]
      }
    ];

    return (
      <GoogleMap
        defaultZoom={14}
        options={{ maxZoom: 19, styles: mapStyle }}
        center={currentLocation}
        onZoomChanged={() => {
          onBoundsChanged();
        }}
        onCenterChanged={() => {
          onBoundsChanged();
        }}
        onTilesLoaded={() => {
          if (mapRef.current && currentLocation) {
            onBoundsChanged();
          }
        }}
        ref={mapRef}
      >
        {polygon && (
          <Polygon
            path={polygon.paths}
            editable={false}
            options={{
              strokeColor: "#FF0000",
              fillColor: "#FF0000",
            }}
            onClick={(click) => {
              // onToggleOpen({ type: "polygon", ...polygon, mode: "edit" });
            }}
          />
        )}

{polygons.map((polygon: any, idx: number) => (
  <div key={idx}>
            <Polygon
              path={polygon.paths}
              
              editable={false}
              options={{
                strokeColor: "#000",
                fillColor: "rgba(0, 0, 0, 0.3)",
              }}
              onClick={(click) => {
                // onToggleOpen({ type: "polygon", ...polygon, mode: "edit" });
                console.log('on clci', polygon)
                setActivePolygon(idx)
              }}
            />

            {activePolygon === idx && (
              <InfoWindow
                position={getPolygonCenter(polygon.paths)}
                onCloseClick={() => setActivePolygon(null)}
              >
                <div style={{ color: "black", background: "transparent" }}>
                  {polygon.name}
                </div>
              </InfoWindow>
            )}

</div>

          ))}


        {circle && (
          <Circle
            center={{
              lat: circle.location.coordinates?.[1],
              lng: circle.location.coordinates?.[0],
            }}
            radius={circle.radius}
            options={{
              strokeColor: "FF0000",
              fillColor: "FF0000",
            }}
            onClick={(click) => {
              // onToggleOpen({ type: "circle", ...circle, mode: "edit" });
            }}
          />
        )}

        {stands?.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-green.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            position={{
              lat: marker.location.coordinates?.lat,
              lng: marker.location.coordinates?.long,
            }}
            onClick={() => {
              dispatch({ type: SET_SELECTED_PICKUP, payload: marker });
              // on map click
            }}
          ></Marker>
        ))}

        {markers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/car-${
                      selectedResponders.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.status
                        : "blue"
                    }.svg`,
                    // url: '/images/car.svg',
                    scaledSize: new google.maps.Size(60, 60),
                  }
            }
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              if (marker?.status === "green") {
                dispatch({ type: SET_SELECTED_RESPONDER, payload: marker });
              }
              // on map click
            }}
            label={marker.title}
          ></Marker>
        ))}

        {assetMarkers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-${
                      selectedAssets.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.color
                        : "green"
                    }.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              dispatch({ type: SET_SELECTED_ASSETS, payload: marker });
              // on map click
            }}
            label={marker.title}
          ></Marker>
        ))}

        {currentMarkers.map((marker: any, idx: number) => (
          <Marker
            key={idx}
            icon={
              marker.markerIcon
                ? marker.markerIcon
                : {
                    url: `/images/map-plain-icon-${
                      selectedResponders.findIndex((selected) => {
                        return selected.id === marker.id;
                      }) === -1
                        ? marker.color
                        : "green"
                    }.svg`,
                    scaledSize: new google.maps.Size(22, 34),
                  }
            }
            // label={marker.title}
            position={{ lat: marker.lat, lng: marker.lng }}
            onClick={() => {
              setActiveInfo(idx);
            }}
          >
            {activeInfo === idx && (
              <InfoWindow
                onCloseClick={() => {
                  setActiveInfo(null);
                }}
              >
                <div>
                  <div>{marker.title}</div>
                </div>
              </InfoWindow>
            )}
          </Marker>
        ))}

        <Marker
          position={currentLocation}
          icon={{
            url: `/images/map-plain-icon-blue.svg`,
            scaledSize: new google.maps.Size(22, 34),
          }}
          onClick={() => {}}
        ></Marker>

        {directions && (
          <DirectionsRenderer
            directions={directions}
            options={{
              markerOptions: { opacity: 1 },
              panel: document.getElementById("direction-panel"),
              // icon: { scale: 10 },
            }}
          />
        )}
      </GoogleMap>
    );
  }
);

export default Map;
