import { FC, useEffect, useRef, useState } from "react";
import { Button } from "antd";
import { RedoOutlined } from "@ant-design/icons";
import { useLocation } from "react-router-dom";
import { useSelector, useDispatch } from "react-redux";
import { RootState } from "reducers/rootReducer";
import useSocketActions from "hooks/socketActions";
import { generateUUID } from "utils/appUtil";
import PaymentModal from "../PaymentModal";
import "../Dashboard.scss";
import "./RidesTable.scss";
import { INITIAL_STATUS_COUNT } from "./constants";
import { DashboardContext } from "./context";
import { useSyncedRefState } from "./hooks/useSyncedRefState";
import { useDashboardQueries } from "./hooks/useDashboardQueries";
import { useDashboardFilters } from "./hooks/useDashboardFilters";
import { useDashboardSubscriptions } from "./hooks/useDashboardSubscriptions";
import FilterPanel from "./components/FilterPanel";
import StatusFilterBar from "./components/StatusFilterBar";
import PagesTable from "./components/PagesTable";
import { subscribeRideSubmissions } from "../../rideSync";

export { RideStatus, colorRideStatusMapping } from "./constants";

// A booked ride's placeholder waits this long for its row (it may be outside
// the current view, or the ride service may not publish one).
const PLACEHOLDER_MAX_MS = 15000;
// How long a delivered row counts as "seen" for a create reply that lands
// after it.
const SEEN_ROW_MS = 60000;

const DashboardModal: FC<{
  socket: ISocket;
  params?: any;
  filter?: boolean;
  selected?: string;
  componentUuid?: string;
}> = ({ socket, params, filter, selected, componentUuid }) => {
  const { search } = useLocation();
  const {
    userRequests,
    projects,
    selectedPage,
    encrypted_token,
    searchByPhone,
  } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [projectFilter, setProjectFilter] = useState<string>("project");
  const [timeFilter, setTimeFilter] = useState<string>("state");
  const [projectFilterLoading, setProjectFilterLoading] =
    useState<boolean>(false);
  const [projectFilterValue, setProjectFilterValue] = useState<any>(undefined);
  const [timeFilterValue, setTimeFilterValue] = useState<any>(undefined);
  const [statusFilterLoading, setStatusFilterLoading] =
    useState<boolean>(false);
  const [timeFilterLoading, setTimeFilterLoading] = useState<boolean>(false);
  const [projectFilterOptions, setProjectFilterOptions] = useState<any[]>([]);
  const [timeFilterOptions, setTimeFilterOptions] = useState<any[]>([]);
  const [pages, setPages] = useState<any>([]);
  const [isPaymentModalVisible, setIsPaymentModalVisible] = useState<any>();
  const filterUserRequestId = useRef(generateUUID());
  const startDate = useRef<any>(undefined);
  const endDate = useRef<any>(undefined);
  const pageOffset = useRef<any>(0);
  const selectedColor = useRef<any>(undefined);
  const showHail = useRef<boolean>(false);
  const [pageUpdatedQueue, setPageUpdatedQueue] = useState<any[]>([]);
  const [statusCount, setStatusCount] = useState<any>(INITIAL_STATUS_COUNT);
  const [redrawCount, setRedrawCount] = useState<number>(0);
  const [tableDataSource, setTableDataSource, tableDataSourceRef] =
    useSyncedRefState<any[]>([]);
  const usersRef = useRef(undefined);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [showTableFilterModal, setShowTableFilterModal] =
    useState<boolean>(false);
  const [tableHideList, setTableHideList] = useState<any>([]);
  const [statusSelected, setStatusSelected] = useState<any>(undefined);
  // Optimistic "Submitting…" rows for rides this dispatcher just sent, keyed
  // by clientRequestId (main table only). Once the create succeeds the
  // placeholder carries the ride's pageId and is replaced by the real row
  // (ridePageUpdated `row`, or the fetch), whichever order the reply and the
  // event arrive in.
  const [pendingRows, setPendingRows] = useState<any[]>([]);
  // pageId -> when a row for it was last applied (any view).
  const seenRowsRef = useRef<Map<string, number>>(new Map());
  const placeholderTimersRef = useRef<{ [key: string]: any }>({});
  const dropPlaceholder = (key: string) => {
    clearTimeout(placeholderTimersRef.current[key]);
    delete placeholderTimersRef.current[key];
    setPendingRows((rows) => rows.filter((row) => row.key !== key));
  };
  // Called for every row applied to the table (live or fetched).
  const notePageRow = (pageId: any) => {
    const id = pageId?.toString();
    if (!id) return;
    const now = Date.now();
    const seen = seenRowsRef.current;
    seen.set(id, now);
    if (seen.size > 200) {
      seen.forEach((at, key) => {
        if (now - at > SEEN_ROW_MS) seen.delete(key);
      });
    }
    setPendingRows((prev) => {
      const next = prev.filter((row) => row.pageId !== id);
      if (next.length === prev.length) return prev;
      prev
        .filter((row) => row.pageId === id)
        .forEach((row) => {
          clearTimeout(placeholderTimersRef.current[row.key]);
          delete placeholderTimersRef.current[row.key];
        });
      return next;
    });
  };
  useEffect(() => {
    if (!filter) return;
    const unsubscribe = subscribeRideSubmissions((event) => {
      const key = `pending:${event.id}`;
      if (event.state === "done") {
        const pageId = event.pageId?.toString();
        const seenAt = pageId ? seenRowsRef.current.get(pageId) : undefined;
        const inTable =
          !!pageId &&
          (tableDataSourceRef.current || []).some(
            (row: any) => row.key?.toString() === pageId
          );
        const seen = !!seenAt && Date.now() - seenAt < SEEN_ROW_MS;
        if (!pageId || inTable || seen) {
          dropPlaceholder(key);
          return;
        }
        // Booked; keep the placeholder until the ride's row lands.
        setPendingRows((prev) =>
          prev.map((row) => (row.key === key ? { ...row, pageId } : row))
        );
        clearTimeout(placeholderTimersRef.current[key]);
        placeholderTimersRef.current[key] = setTimeout(
          () => dropPlaceholder(key),
          PLACEHOLDER_MAX_MS
        );
        return;
      }
      clearTimeout(placeholderTimersRef.current[key]);
      delete placeholderTimersRef.current[key];
      setPendingRows((prev) => {
        const rest = prev.filter((row) => row.key !== key);
        return [
          {
            key,
            pageStatus: undefined,
            requestedAt:
              event.state === "pending"
                ? "Submitting…"
                : `Failed: ${event.message || "request failed"}`,
            address: event.summary?.pickup,
            dropoffAddress: event.summary?.dropoff,
            passengerName: event.summary?.passengerName,
            passengerPhoneNumber: event.summary?.passengerPhoneNumber,
            name: event.summary?.leg,
            action: {
              pendingSubmission: true,
              failed: event.state === "failed",
              retry: event.retry,
              dismiss: () => dropPlaceholder(key),
            },
          },
          ...rest,
        ];
      });
    });
    return () => {
      unsubscribe();
      Object.keys(placeholderTimersRef.current).forEach((key) =>
        clearTimeout(placeholderTimersRef.current[key])
      );
      placeholderTimersRef.current = {};
    };
  }, [filter]);
  const { getUserRequestPayload } = useSocketActions();
  const adminRoles = useRef(undefined);
  const pagePaths = useRef<any>({
    project: undefined,
    user: undefined,
    area: undefined,
    time: undefined,
  });
  const pageIndex = useRef<any>({
    status: "-@rideStatus:{advance}",
    time: undefined,
    phone: undefined,
  });
  const pageThrottleRef = useRef<any>({});
  // Raw values of the active filters (pagePaths/pageIndex only hold the Redis
  // query fragments), so real-time page updates can apply the same predicates
  // client-side instead of inserting rows the poll query would exclude.
  const activeFiltersRef = useRef<any>({
    project: undefined,
    user: undefined,
    area: undefined,
    phone: undefined,
  });
  const encryptedTokenRef = useRef<any>();
  const loadPaths = useRef<any>([]);
  const timeoutRef = useRef<any>();
  // Always points at the current render's searchPage so the polling
  // interval doesn't run a stale closure (frozen projects/timeFilter).
  const searchPageRef = useRef<any>(() => {});
  // Debounced queries close over the first render's bag, so they read the
  // org (projects.userServiceId) through this ref.
  const projectsRef = useRef<any>();
  projectsRef.current = projects;

  // The shared "bag" consumed by section components (via context) and by the
  // query / filter / subscription hooks below. Each hook's returned actions are
  // folded back in so later hooks and components can reach earlier actions.
  const d: any = {
    // props
    socket,
    params,
    filter,
    selected,
    componentUuid,
    search,
    dispatch,
    getUserRequestPayload,
    // redux
    userRequests,
    projects,
    selectedPage,
    encrypted_token,
    searchByPhone,
    // refs
    filterUserRequestId,
    startDate,
    endDate,
    pageOffset,
    selectedColor,
    showHail,
    tableDataSourceRef,
    usersRef,
    adminRoles,
    pagePaths,
    pageIndex,
    pageThrottleRef,
    activeFiltersRef,
    encryptedTokenRef,
    loadPaths,
    timeoutRef,
    searchPageRef,
    projectsRef,
    // state + setters
    projectFilter,
    setProjectFilter,
    timeFilter,
    setTimeFilter,
    projectFilterLoading,
    setProjectFilterLoading,
    projectFilterValue,
    setProjectFilterValue,
    timeFilterValue,
    setTimeFilterValue,
    statusFilterLoading,
    setStatusFilterLoading,
    timeFilterLoading,
    setTimeFilterLoading,
    projectFilterOptions,
    setProjectFilterOptions,
    timeFilterOptions,
    setTimeFilterOptions,
    pages,
    setPages,
    isPaymentModalVisible,
    setIsPaymentModalVisible,
    pageUpdatedQueue,
    setPageUpdatedQueue,
    statusCount,
    setStatusCount,
    redrawCount,
    setRedrawCount,
    tableDataSource,
    setTableDataSource,
    tableColumns,
    setTableColumns,
    showTableFilterModal,
    setShowTableFilterModal,
    tableHideList,
    setTableHideList,
    statusSelected,
    setStatusSelected,
    pendingRows,
    notePageRow,
  };

  Object.assign(d, useDashboardQueries(d));
  Object.assign(d, useDashboardFilters(d));
  searchPageRef.current = d.searchPage;
  useDashboardSubscriptions(d);

  return (
    <DashboardContext.Provider value={d}>
      <div className={`ride-rides ${filter ? "ride-rides--all" : ""}`}>
        {filter && <StatusFilterBar />}

        <FilterPanel />

        {!filter && (
          <div className="ride-toolbar">
            <div className="ride-toolbar__row">
              <span className="ride-toolbar__count">
                {(d.tableDataSource || []).length} rides
              </span>
              <div className="ride-toolbar__actions">
                <Button
                  className="ride-refresh-btn"
                  icon={
                    <RedoOutlined
                      spin={projectFilterLoading || statusFilterLoading}
                    />
                  }
                  disabled={projectFilterLoading || statusFilterLoading}
                  onClick={() => {
                    setProjectFilterLoading(true);
                    d.searchPage();
                  }}
                >
                  {projectFilterLoading || statusFilterLoading
                    ? "Refreshing…"
                    : "Refresh"}
                </Button>
              </div>
            </div>
          </div>
        )}

        <div className="scrollable-table ride-rides__table">
          <PagesTable />
        </div>
      </div>

      {isPaymentModalVisible && (
        <PaymentModal
          socket={socket}
          payment={isPaymentModalVisible}
          onClose={() => {
            setIsPaymentModalVisible(undefined);
          }}
        />
      )}
    </DashboardContext.Provider>
  );
};

export default DashboardModal;
