import React from "react";
import { Button, Checkbox, Col, DatePicker, InputNumber, Radio, Row, Select, Tag } from "antd";
import moment, { Moment } from "moment";
import {
  DEFAULT_SCHEDULE,
  RecurringSchedule,
  WEEKDAYS,
  ordinal,
  toDay,
} from "./recurrence";

const DATE_FORMAT = "ddd, MMM D, YYYY";
const WEEKDAY_VALUES = [1, 2, 3, 4, 5];

const Field = ({ label, children }: { label: string; children: React.ReactNode }) => (
  <div className="mx-recurring-picker__field">
    <div className="mx-recurring-picker__label">{label}</div>
    {children}
  </div>
);

/**
 * Form control for `schedule`. Always emits the full object so the stored
 * shape keeps every key, whichever mode is active.
 */
const SchedulePicker = ({
  value,
  onChange,
}: {
  value?: RecurringSchedule;
  onChange?: (value: RecurringSchedule) => void;
}) => {
  const schedule = { ...DEFAULT_SCHEDULE, ...(value || {}) };
  const update = (patch: Partial<RecurringSchedule>) => onChange?.({ ...schedule, ...patch });

  const today = moment().startOf("day");
  const start = toDay(schedule.startDate);
  const customDates: Moment[] = (schedule.customDates || [])
    .map((d) => moment(d))
    .filter((d) => d.isValid())
    .sort((a, b) => a.valueOf() - b.valueOf());

  const addCustomDate = (date: Moment | null) => {
    if (!date || customDates.some((d) => d.isSame(date, "day"))) return;
    update({ customDates: [...customDates, date] });
  };

  return (
    <div className="mx-recurring-picker">
      <Radio.Group
        optionType="button"
        buttonStyle="solid"
        value={schedule.mode}
        onChange={(e) => update({ mode: e.target.value })}
        options={[
          { label: "Repeats", value: "repeat" },
          { label: "Specific dates", value: "custom" },
        ]}
      />

      {schedule.mode === "custom" ? (
        <Field label="Dates">
          <DatePicker
            className="mx-recurring-picker__date"
            placeholder="Add a date"
            format={DATE_FORMAT}
            value={null}
            onChange={addCustomDate}
            disabledDate={(date) =>
              !!date &&
              (date.isBefore(today, "day") || customDates.some((d) => d.isSame(date, "day")))
            }
          />
          <div className="mx-recurring-picker__tags">
            {customDates.length === 0 ? (
              <span className="mx-recurring-picker__hint">No dates yet. Pick one above to add it.</span>
            ) : (
              customDates.map((date) => (
                <Tag
                  key={date.format("YYYY-MM-DD")}
                  closable
                  onClose={(e) => {
                    e.preventDefault();
                    update({ customDates: customDates.filter((d) => !d.isSame(date, "day")) });
                  }}
                >
                  {date.format("ddd, MMM D, YYYY")}
                </Tag>
              ))
            )}
          </div>
        </Field>
      ) : (
        <>
          <Field label="Frequency">
            <Radio.Group
              optionType="button"
              value={schedule.repeatType}
              onChange={(e) => update({ repeatType: e.target.value })}
              options={[
                { label: "Daily", value: "daily" },
                { label: "Weekly", value: "weekly" },
                { label: "Monthly", value: "monthly" },
              ]}
            />
          </Field>

          {schedule.repeatType === "daily" && (
            <Field label="Repeat every">
              <InputNumber
                min={1}
                max={365}
                precision={0}
                addonAfter={Number(schedule.everyX) === 1 ? "day" : "days"}
                value={schedule.everyX}
                onChange={(val) => update({ everyX: val ?? 1 })}
                style={{ width: 160 }}
              />
            </Field>
          )}

          {schedule.repeatType === "weekly" && (
            <Field label="On">
              <Checkbox.Group
                className="mx-recurring-picker__days"
                value={schedule.repeatDays}
                onChange={(val) => update({ repeatDays: val as number[] })}
                options={WEEKDAYS.map((d) => ({ label: d.short, value: d.value }))}
              />
              <div className="mx-recurring-picker__quick">
                <Button type="link" size="small" onClick={() => update({ repeatDays: WEEKDAY_VALUES })}>
                  Weekdays
                </Button>
                <Button
                  type="link"
                  size="small"
                  onClick={() => update({ repeatDays: WEEKDAYS.map((d) => d.value) })}
                >
                  Every day
                </Button>
                <Button type="link" size="small" onClick={() => update({ repeatDays: [] })}>
                  Clear
                </Button>
              </div>
            </Field>
          )}

          {schedule.repeatType === "monthly" && (
            <Field label="On day of the month">
              <Select
                mode="multiple"
                style={{ width: "100%" }}
                placeholder="e.g. 1st, 15th"
                value={schedule.monthRepeatDates}
                onChange={(val) => update({ monthRepeatDates: [...val].sort((a, b) => a - b) })}
                options={Array.from({ length: 31 }, (_, i) => ({ label: ordinal(i + 1), value: i + 1 }))}
              />
            </Field>
          )}

          <Row gutter={16}>
            <Col xs={24} md={12}>
              <Field label="Starts">
                <DatePicker
                  className="mx-recurring-picker__date"
                  format={DATE_FORMAT}
                  placeholder="Start date"
                  value={schedule.startDate ? moment(schedule.startDate) : null}
                  onChange={(val) => update({ startDate: val })}
                />
              </Field>
            </Col>
            <Col xs={24} md={12}>
              <Field label="Ends">
                <DatePicker
                  className="mx-recurring-picker__date"
                  format={DATE_FORMAT}
                  placeholder="No end date (optional)"
                  allowClear
                  value={schedule.endUntil ? moment(schedule.endUntil) : null}
                  onChange={(val) => update({ endUntil: val })}
                  disabledDate={(date) => !!date && !!start && date.isBefore(start, "day")}
                />
              </Field>
            </Col>
          </Row>
        </>
      )}
    </div>
  );
};

export default SchedulePicker;
