/**
 * Runtime configuration for the public Programs page.
 *
 * The page is served without a sign-in, so there is no socket. The organization
 * is carried by a `?token=` that the decrypt service turns into its ids, the
 * same token other Beam screens use (see ServiceFormModal). Each org-specific
 * value — the CUDB org id, its config user and connection — is resolved in the
 * order: URL query parameter, then the decrypted token, then a build-time env
 * var, then the staging default.
 *
 * So the page points at an organization with just
 *   /programs?token=<token>
 * and a query param can still pin any single value for debugging, e.g.
 *   /programs?token=<token>&serviceId=<org>
 */

import { decryptProgramsToken, DecodedToken } from "./token";

/**
 * Hardcoded: the Programs page always runs on `org-beam-sport`. Every API call
 * (projects, forms, roles) uses this serviceId and the admin user below,
 * regardless of any `?token=`, query param or env var.
 */
const SERVICE_ID = "org-beam-sport";

/**
 * Object id of the organization's config user: projects (and their extended
 * bio answers) hang off this user. It is also the `createdBy` of the org's
 * `project:extendedBio` forms, which is how it can be looked up again.
 * Hardcoded alongside the serviceId above.
 */
const ADMIN_USER_ID = "120129";

const DEFAULT_CONNECTION_ID = "177438";

/** Matches the CUDB subdomain template the CPC app uses: `{serviceId}-api...`. */
const DEFAULT_SERVICE_BASE = "-api.staging.beam.live";

const DEFAULT_ECOSYSTEM = "beamdevlive";
const DEFAULT_BDS_API = "https://bds-api.staging.beam.live";
const DEFAULT_CPC_APP = "https://cpc.staging.beam.live";

/** Where an event's `beamViteWebsiteName` points. */
const DEFAULT_BEAMVITE = "https://beamvite.beam.live";

/** The Beam logo shipped in `public/images`, the same mark the app's other headers use. */
const DEFAULT_LOGO = "/images/logo-icon.svg";

const env = (key: string): string | undefined => {
  const value = process.env[key];
  return typeof value === "string" && value.trim() ? value.trim() : undefined;
};

const queryParam = (key: string): string | undefined => {
  if (typeof window === "undefined") return undefined;
  const value = new URLSearchParams(window.location.search).get(key);
  return value && value.trim() ? value.trim() : undefined;
};

/**
 * Query parameter wins over the decrypted token, which wins over the env var,
 * which wins over the staging default. `tokenValue` is the value the `?token=`
 * carried for this id, or undefined when there is no (usable) token.
 */
const resolve = (
  param: string,
  envKey: string,
  fallback: string,
  tokenValue?: string
): string => queryParam(param) ?? tokenValue ?? env(envKey) ?? fallback;

const trimSlash = (url: string): string => url.replace(/\/+$/, "");

export interface ProgramsConfig {
  ecosystem: string;
  bdsApiUrl: string;
  /** The organization's own CUDB API, derived from `serviceId`. */
  cudbApiUrl: string;
  serviceId: string;
  adminUserId: string;
  connectionId: string;
  cpcAppUrl: string;
  beamViteUrl: string;
  logoUrl: string;
  /** Pins the event-type widget when a form words its headline differently. */
  sectionElementId?: string;
}

/**
 * The config, with the organization taken from a decrypted token when one is
 * passed in. Only the org-specific ids (CUDB org, config user, connection) look
 * at the token; the ecosystem-wide service URLs are the same for every org.
 * Synchronous: the token is decrypted by `resolveProgramsConfig` first.
 */
export const getProgramsConfig = (decoded?: DecodedToken): ProgramsConfig => {
  // serviceId and adminUserId are hardcoded to org-beam-sport (see constants);
  // the token/query/env are not consulted for them.
  const serviceId = SERVICE_ID;
  const serviceBase = env("REACT_APP_SERVICE_BASE_API_URI") ?? DEFAULT_SERVICE_BASE;

  return {
    ecosystem: env("REACT_APP_ECO_SYSTEM") ?? DEFAULT_ECOSYSTEM,
    bdsApiUrl: trimSlash(env("REACT_APP_BDS_API") ?? DEFAULT_BDS_API),
    cudbApiUrl: trimSlash(`https://${serviceId}${serviceBase}`),
    serviceId,
    adminUserId: ADMIN_USER_ID,
    connectionId: resolve(
      "connectionId",
      "REACT_APP_PROGRAMS_CONNECTION_ID",
      DEFAULT_CONNECTION_ID,
      decoded?.connectionId
    ),
    cpcAppUrl: trimSlash(env("REACT_APP_CPC_APP_URL") ?? DEFAULT_CPC_APP),
    beamViteUrl: trimSlash(env("REACT_APP_BEAMVITE_URL") ?? DEFAULT_BEAMVITE),
    logoUrl: env("REACT_APP_PROGRAMS_LOGO_URL") ?? DEFAULT_LOGO,
    sectionElementId:
      queryParam("sectionElementId") ?? env("REACT_APP_PROGRAMS_SECTION_ELEMENT_ID"),
  };
};

/**
 * The config with the organization resolved from the `?token=` when present:
 * the token is decrypted into `{ serviceId, userId, connectionId }` and those
 * drive the CUDB org id, config user and connection. A missing or undecryptable
 * token falls back to the query/env/staging defaults, so the page still loads.
 */
export const resolveProgramsConfig = async (): Promise<ProgramsConfig> => {
  const token = queryParam("token");
  const decoded = token ? await decryptProgramsToken(token) : null;
  return getProgramsConfig(decoded ?? undefined);
};

/**
 * `beamViteWebsiteName` is a human-typed name ("NC State - Student Alumni"),
 * so it has to be percent-encoded before it goes into the path.
 */
export const beamViteUrlFor = (websiteName: string | undefined, config: ProgramsConfig): string | undefined => {
  const name = websiteName?.trim();
  return name ? `${config.beamViteUrl}/${encodeURIComponent(name)}` : undefined;
};

/**
 * An explicit sign-up form/role for one section, when a deployment wants to
 * pin them instead of letting `resolveSignup` find the role by name.
 *
 * Per section slug: `?recreationalFormId=` / `REACT_APP_PROGRAMS_RECREATIONAL_FORM_ID`,
 * and the same with `RoleId` / `_ROLE_ID`.
 */
export const signupOverride = (
  sectionId: string
): { formId?: string; roleId?: string } => {
  const camel = sectionId.replace(/-([a-z])/g, (_, c: string) => c.toUpperCase());
  const upper = sectionId.replace(/-/g, "_").toUpperCase();
  return {
    formId: resolveOptional(`${camel}FormId`, `REACT_APP_PROGRAMS_${upper}_FORM_ID`),
    roleId: resolveOptional(`${camel}RoleId`, `REACT_APP_PROGRAMS_${upper}_ROLE_ID`),
  };
};

const resolveOptional = (param: string, envKey: string): string | undefined =>
  queryParam(param) ?? env(envKey);
