import React from "react";
import { Button, Tag } from "antd";
import moment from "moment";
import { AREA_FILTERS, ENTITY_FILTERS, STATUS_OPTIONS } from "../../constants";
import { DashboardFilters, SelectOption, TimeRangeValue } from "../../types";
import "./filters.scss";

const RANGE_LABELS: Record<string, string> = {
  today: "Today",
  todayAndBeyond: "Today and beyond",
  tomorrow: "Tomorrow",
  nextWeek: "Next week",
  allTime: "All time",
};

const describeRange = ({ selected, startTimestamp, endTimestamp }: TimeRangeValue) => {
  if (RANGE_LABELS[selected]) return RANGE_LABELS[selected];
  if (selected === "specificDate") return moment(startTimestamp).format("MMM D, YYYY");
  return `${moment(startTimestamp).format("MMM D")} – ${moment(endTimestamp).format("MMM D, YYYY")}`;
};

interface Chip {
  key: string;
  label: string;
  remove: () => void;
}

/** One removable chip per active filter; "today" is the default, not a filter. */
export const getActiveFilters = (
  filters: DashboardFilters,
  handlers: {
    onChange: (patch: Partial<DashboardFilters>) => void;
    onTimeRangeChange: (value: TimeRangeValue) => void;
  },
  options: { entityOptions: SelectOption[] }
): Chip[] => {
  const { onChange, onTimeRangeChange } = handlers;
  const chips: Chip[] = [];
  if (filters.timeRange.selected !== "today") {
    chips.push({
      key: "time",
      label: describeRange(filters.timeRange),
      remove: () => onTimeRangeChange({ selected: "today" }),
    });
  }
  if (filters.status) {
    const status = STATUS_OPTIONS.find((s) => s.color === filters.status)?.label;
    chips.push({
      key: "status",
      label: `Status: ${status ?? filters.status}`,
      remove: () => onChange({ status: undefined }),
    });
  }
  if (filters.entityValue) {
    const type = ENTITY_FILTERS.find((f) => f.type === filters.entityType)?.label;
    const value = options.entityOptions.find((o) => o.value === filters.entityValue)?.label;
    chips.push({
      key: "entity",
      label: `${type}: ${value ?? filters.entityValue}`,
      remove: () => onChange({ entityValue: undefined }),
    });
  }
  if (filters.areaValue) {
    const type = AREA_FILTERS.find((f) => f.type === filters.areaType)?.label;
    chips.push({
      key: "area",
      label: `${type}: ${filters.areaValue}`,
      remove: () => onChange({ areaValue: undefined }),
    });
  }
  if (filters.name) {
    chips.push({
      key: "name",
      label: `Patient: ${filters.name}`,
      remove: () => onChange({ name: undefined }),
    });
  }
  if (filters.phone) {
    chips.push({
      key: "phone",
      label: `Phone: ${filters.phone}`,
      remove: () => onChange({ phone: undefined }),
    });
  }
  return chips;
};

const ActiveFilterChips = ({ chips, onClearAll }: { chips: Chip[]; onClearAll: () => void }) =>
  chips.length === 0 ? null : (
    <div className="mx-filter-chips">
      <span className="mx-filter-chips__label">Showing</span>
      {chips.map((chip) => (
        <Tag
          key={chip.key}
          closable
          className="mx-filter-chips__chip"
          onClose={(e) => {
            e.preventDefault();
            chip.remove();
          }}
        >
          {chip.label}
        </Tag>
      ))}
      <Button type="link" size="small" onClick={onClearAll}>
        Clear all
      </Button>
    </div>
  );

export default ActiveFilterChips;
