import { useState, useEffect, useRef } from "react";
import {
  ExtendedBioTopics,
  SocketTopics,
  SurveyQuestionTopics,
  PageTopics,
  CADSectionTopics,
  BioTopics,
} from "../constants/enums";
import { useSelector } from "react-redux";
import useSocketActions from "./socketActions";
import mqtt from "mqtt";
import { generateUUID } from "utils/appUtil";
import { useLocation } from "react-router-dom";
import { wrapRequestPayload } from "../helpers/request/RequestPayload";
import { RootState } from "reducers/rootReducer";

const MQTTPattern = require("mqtt-pattern");

// Shared by the connect options and the half-open-socket staleness check.
const KEEPALIVE_SECONDS = 60;
// A healthy connection receives a PINGRESP every keepalive period, so no
// inbound packet for notably longer means the socket is half-open. 1.5x
// keepalive detects that ~30s sooner than 2x while staying clear of a single
// slightly-late ping.
const STALE_MS = 1.5 * KEEPALIVE_SECONDS * 1000;
// A QoS-1 PUBACK is broker-generated and normally lands in well under a
// second. 4s proved too tight on slow links (a late PUBACK caused a duplicate
// re-publish and a needless rebuild), so wait 10s before treating it as lost.
const PUBLISH_ACK_TIMEOUT_MS = 10000;
// One late PUBACK alone isn't proof of a dead socket. Rebuild when at least
// this many publishes are overdue at once, or when nothing at all has arrived
// since the overdue publish was sent.
const OVERDUE_PUBLISHES_TO_REBUILD = 2;

// Broker credentials; env overrides, current shared defaults otherwise.
const MQTT_USERNAME = process.env.REACT_APP_MQTT_USERNAME || "live";
const MQTT_PASSWORD = process.env.REACT_APP_MQTT_PASSWORD || "beamL1ve";

export interface PublishOptions {
  // Re-send the publish after an ack timeout. Safe for lookups (the default);
  // pass false for requests with side effects (refunds, links sent to
  // passengers, verification codes, record updates), where an unacked publish
  // may already have reached the broker and a re-send would act twice.
  retryOnAckTimeout?: boolean;
}

// Runs one subscriber callback so a throw can't stop the remaining ones.
const safeInvoke = (label: string, fn: () => void) => {
  try {
    fn();
  } catch (error) {
    console.error(`Socket handler failed (${label})`, error);
  }
};

// Raw message logging is opt-in (REACT_APP_SOCKET_DEBUG=true or
// localStorage.socketDebug = "1"): logging every full payload is noisy and
// leaks ride/passenger data into the console.
const socketDebugEnabled = () => {
  if (process.env.REACT_APP_SOCKET_DEBUG === "true") return true;
  try {
    return localStorage.getItem("socketDebug") === "1";
  } catch (e) {
    return false;
  }
};

export default () => {
  const [connectedClient, setConnectedClient] = useState<any>();
  // Incremented on every successful (re)connect so screens can resync data
  // they may have missed while the socket was down.
  const [connectionEpoch, setConnectionEpoch] = useState<number>(0);
  const { encrypted_token } = useSelector(
    (state: RootState) => state.auth
  );
  const { search } = useLocation();
  const {
    getSurveyList,
    getSectionList,
    getBio,
    getRoleList,
    getExtendedBioList,
    getVehicleExtendedBioList,
    getProjectList,
    getRespondersList,
    getAssetsList,
    setSubmitted,
    getPageResult,
    handlePageEot,
    getUsersList,
    handleMessages,
    handleAppendMessage,
    handleUserBds,
    handleAggregateBds,
    handlePageResults,
    handleAggregate,
    getAccountsList,
    handleAdminRoles
  } = useSocketActions();
  const callbacks = useRef<any>({});
  const surveyTopicIds = useRef<any>({});
  const clientRef = useRef<any>(null);
  // Every topic the app has asked to subscribe to. Re-asserted on each
  // 'connect' so subscriptions survive reconnects, failed SUBACKs and client
  // replacement instead of being silently lost.
  const desiredSubsRef = useRef<Set<string>>(new Set());
  // Client operations (subscribe/publish) requested while there is no CONNECTED
  // client — before the first connect, or during a reconnect window. Flushed on
  // the next 'connect'. This must live at our layer, not mqtt's outbound store:
  // recovery REPLACES the client, and anything sitting in the old client's
  // store is lost with it. Queuing here lets a publish made mid-reconnect
  // survive the swap and go out once we're connected again.
  const pendingOpsRef = useRef<Array<(client: any) => void>>([]);
  const MAX_PENDING_OPS = 200;
  // The message listener closes over the current render (redux state, handler
  // fns from useSocketActions); the socket holds one stable wrapper that reads
  // this ref, so messages are never handled by a stale closure.
  const messageListenerRef = useRef<any>(() => { });
  // Timestamp of the last inbound packet (any packet, PINGRESP included).
  // A healthy connection receives at least one packet per keepalive period,
  // so a large gap while client.connected is still true means the socket is
  // half-open (dead TCP the client hasn't noticed yet).
  const lastPacketAtRef = useRef<number>(0);
  // QoS-1 publishes whose PUBACK is past PUBLISH_ACK_TIMEOUT_MS.
  const overduePublishesRef = useRef<number>(0);

  // Queue an op to run on the next 'connect'. Capped so a long outage can't
  // grow it without bound; drops the oldest when full.
  const enqueuePending = (operation: (client: any) => void) => {
    if (pendingOpsRef.current.length >= MAX_PENDING_OPS) {
      pendingOpsRef.current.shift();
      console.warn("Socket op queue full — dropping oldest queued op");
    }
    pendingOpsRef.current.push(operation);
  };

  const withClient = (operation: (client: any) => void) => {
    const client = clientRef.current;
    if (client && client.connected) operation(client);
    else enqueuePending(operation);
  };

  // Wake events (online, focus, visibilitychange) often fire together, so the
  // reconnect kick is debounced.
  const lastKickAtRef = useRef<number>(0);

  const createClient = () => {
    const client = mqtt.connect(
      `${process.env.REACT_APP_BASE_WS_URL}?v=${new Date().getTime()}`,
      {
        clientId: "web-" + generateUUID(),
        username: MQTT_USERNAME,
        password: MQTT_PASSWORD,
        // Background tabs get their timers throttled to ~1/minute, so with a
        // 30s keepalive the ping misses its slot and the broker drops the
        // connection on every longer tab switch. 60s keeps the ping inside
        // the broker's 1.5x grace window even when throttled.
        keepalive: KEEPALIVE_SECONDS,
        reconnectPeriod: 2000, // auto reconnect every 2 seconds
        // Default is 30s. On reconnect, 'online' fires before the network is
        // truly ready, so the first attempts' CONNACK hangs — and _setupStream
        // clears the 2s reconnect timer while waiting, so nothing retries until
        // this timeout fires. At 30s that made recovery take minutes; 10s
        // recycles a hung attempt fast while still tolerating a slow handshake.
        connectTimeout: 10000,
        clean: true,
      }
    );

    // Handlers no-op once the ref is cleared on unmount (clientRef !== client),
    // so a late event on an ended client can't touch app state.
    client.on("connect", () => {
      if (clientRef.current !== client) return;
      console.log("Connected as", client.options.clientId);
      // Re-assert every subscription the app has asked for on EVERY connect
      // (initial and each reconnect). This is REQUIRED, not just defensive:
      // each reconnect uses a fresh clientId with clean:true, so the broker
      // carries over no subscriptions and we must re-establish them all here.
      const topics = Array.from(desiredSubsRef.current);
      console.log(`Resubscribing to ${topics.length} topic(s)`);
      if (topics.length) {
        client.subscribe(topics, { qos: 1 }, (error, granted) => {
          if (error) console.log("Resubscribe error", error);
          else console.log(`Resubscribed to ${granted?.length ?? 0} topic(s)`);
        });
      }
      // Flush operations queued while we had no connected client (initial boot
      // or a reconnect window). Run AFTER resubscribe so any publish that
      // expects a reply already has its subscription in place.
      const ops = pendingOpsRef.current.splice(0);
      if (ops.length) console.log(`Flushing ${ops.length} queued op(s)`);
      ops.forEach((operation) => operation(client));
      lastPacketAtRef.current = Date.now();
      overduePublishesRef.current = 0;
      setConnectedClient(client);
      setConnectionEpoch((epoch) => epoch + 1);
    });
    client.on("packetreceive", () => {
      if (clientRef.current !== client) return;
      lastPacketAtRef.current = Date.now();
    });
    client.on("error", (err) => {
      // Do NOT end() here: end() disables reconnectPeriod permanently, so a
      // single transient error would kill all real-time updates until a full
      // page reload. Let the client retry on its own.
      console.error("Connection error: ", err);
    });
    client.on("reconnect", () => {
      // Use a brand-new clientId for every reconnect attempt. Reusing the id
      // makes the broker hold our previous (half-open) session under it and
      // stall the new CONNECT until its keepalive grace expires (minutes) —
      // this was the multi-minute recovery. A fresh id is one the broker has
      // never seen, so the connection is accepted immediately; the stale
      // session times out on its own (harmless with clean:true). The CONNECT
      // packet reads clientId from options at send time, so mutating it here
      // (before _setupStream runs) applies to this attempt.
      client.options.clientId = "web-" + generateUUID();
      console.log("Reconnecting as", client.options.clientId);
    });
    client.on("offline", () => {
      console.log("Socket offline");
    });
    client.on("disconnect", () => {
      console.log("Disconnecting");
    });
    client.on("message", (topic: string, message: any) => {
      if (clientRef.current !== client) return;
      messageListenerRef.current(topic, message);
    });

    return client;
  };

  const socketConnect = () => {
    // Idempotent: the app must hold exactly one broker connection. A second
    // call (e.g. StrictMode double-effect) would leak the first client and
    // deliver every message twice.
    if (clientRef.current) return;
    // Seed the rebuild clock so the supervisor gives this initial attempt its
    // full budget before intervening (it defaults to 0 = "long overdue").
    lastKickAtRef.current = Date.now();
    // Queued ops are flushed by the 'connect' handler, not here — publishing on
    // a not-yet-connected client would just re-queue in mqtt's doomed store.
    clientRef.current = createClient();
  };

  // Recover by REPLACING the client with a fresh one that starts connecting
  // immediately. We do NOT rely on mqtt.js's internal reconnect loop: after a
  // real network drop it reliably stalls in this environment — a single hung
  // attempt that never recycles for minutes (its stream-close/connack timers
  // don't fire promptly), which was the multi-minute recovery. We also avoid
  // client.reconnect() (it emits 'connect' with the internal `disconnected`
  // flag still set, so the client looks connected but silently swallows every
  // publish). A brand-new client has none of that state, uses a fresh clientId
  // (so the broker never stalls on our prior half-open session), begins its
  // CONNECT right now, and re-establishes all subscriptions in its 'connect'
  // handler. Its own reconnect loop remains as a backstop between wake events.
  const replaceClient = (reason: string) => {
    const now = Date.now();
    if (now - lastKickAtRef.current < 2000) return;
    lastKickAtRef.current = now;
    console.log(`Socket: rebuilding connection (${reason})`);
    const staleClient = clientRef.current;
    clientRef.current = createClient();
    if (staleClient) {
      try {
        // Force-close (no DISCONNECT handshake — the old socket may be dead).
        staleClient.end(true);
      } catch (error) {
        console.error("Error closing stale client", error);
      }
    }
  };

  useEffect(() => {
    return () => {
      // Read the ref, not state: a []-deps cleanup closing over state would
      // always see the initial undefined and never end the connection.
      if (clientRef.current) {
        clientRef.current.end(undefined, undefined, () => {
          console.log("Disconnected");
        });
        clientRef.current = null;
      }
    };
  }, []);

  // After a network drop or laptop sleep the TCP connection is dead but
  // client.connected can stay true — mqtt.js won't notice until a keepalive
  // ping times out — and once it does, its internal reconnect can stall. So on
  // any wake signal (tab visible/focused, or network back) we proactively
  // rebuild the connection unless it's provably healthy right now.
  useEffect(() => {
    const wake = (aggressive: boolean) => {
      const client = clientRef.current;
      if (!client) return;
      // Disconnected: don't wait for the (stall-prone) internal loop — start a
      // fresh attempt now.
      if (!client.connected) {
        replaceClient("reconnect on wake (was disconnected)");
        return;
      }
      const msSinceLastPacket = Date.now() - lastPacketAtRef.current;
      const looksStale = msSinceLastPacket > STALE_MS;
      if (aggressive || looksStale) {
        replaceClient(
          `connection unproven, ${Math.round(
            msSinceLastPacket / 1000
          )}s since last packet`
        );
      }
    };
    // The browser only fires 'online' after having been offline, so a socket
    // still reporting connected is almost certainly half-open — always rebuild.
    // On tab wake, rebuild if disconnected or if packet silence says stale.
    const onOnline = () => wake(true);
    const onFocus = () => wake(false);
    const onVisibilityChange = () => {
      if (document.visibilityState === "visible") wake(false);
    };
    document.addEventListener("visibilitychange", onVisibilityChange);
    window.addEventListener("focus", onFocus);
    window.addEventListener("online", onOnline);
    return () => {
      document.removeEventListener("visibilitychange", onVisibilityChange);
      window.removeEventListener("focus", onFocus);
      window.removeEventListener("online", onOnline);
    };
  }, []);

  // Supervisor: our own reconnect cadence, independent of mqtt's internal loop
  // and ping detection (both of which stall after a real drop). It rebuilds
  // with a fresh client when the connection is either disconnected or
  // half-open (reports connected but no packet has arrived for >2x keepalive),
  // throttled to ~9s between rebuilds (roughly the per-attempt connectTimeout).
  // So the moment the network is back we reconnect within one cycle instead of
  // waiting minutes. Foreground timers are reliable; background throttling is
  // covered by the wake handlers above.
  useEffect(() => {
    const RETRY_MS = 9000;
    const supervisor = setInterval(() => {
      const client = clientRef.current;
      if (!client) return;
      if (Date.now() - lastKickAtRef.current < RETRY_MS) return;
      const stale = Date.now() - lastPacketAtRef.current > STALE_MS;
      if (!client.connected) {
        replaceClient("supervisor retry (still disconnected)");
      } else if (stale) {
        replaceClient("supervisor retry (half-open, no packets)");
      }
    }, 3000);
    return () => clearInterval(supervisor);
  }, []);

  const publishToEventServiceIdSurvey = (
    event: SocketTopics,
    topic: string,
    data: IPublishRequest,
    subscribePath: string,
    serviceId: string,
    callback: any = () => { }
  ) => {
    const query = new URLSearchParams(search);
    const wrappedData = wrapRequestPayload(data);
    let connectionId = encrypted_token?.connectionId || query.get("connectionId");
    if (connectionId === null || connectionId === undefined || connectionId === '') {
      connectionId = Math.floor(100000 + Math.random() * 90000);
    }
    const searchTopic = `${process.env.REACT_APP_ECO_SYSTEM}/connection/${connectionId}/service/${serviceId}/${topic}`;
    console.log('search topic', searchTopic);
    // Tracked like any other subscription so the reply topic is re-asserted
    // after a reconnect instead of being silently lost.
    desiredSubsRef.current.add(`${searchTopic}/reply`);
    withClient((client) => {
      client.subscribe(`${searchTopic}/reply`, { qos: 1 }, (error) => {
        if (error) {
          console.log("Subscribe to topics error", error);
          return;
        }
        surveyTopicIds.current[wrappedData.id] = subscribePath;
      });
      client.publish(
        searchTopic,
        JSON.stringify(wrappedData),
        { qos: 1 },
        (error) => {
          if (error) {
            callback({ status: false });
          } else {
            callback({ status: true });
          }
        }
      );
    });
  };

  const registerCallback = (
    topic: string,
    callback: any,
    componentUuid?: string
  ) => {
    if (!callbacks.current[topic]) callbacks.current[topic] = [];
    const index = callbacks.current[topic].findIndex((x) => {
      return x.componentUuid === componentUuid;
    });
    if (index !== -1) {
      callbacks.current[topic][index] = {
        componentUuid,
        callback,
      };
    } else {
      callbacks.current[topic].push({
        componentUuid,
        callback,
      });
    }
  };

  const subscribeToEventSurvey = (
    event: SocketTopics,
    topic: string,
    callback: any = () => { },
    componentUuid?: string
  ) => {
    registerCallback(topic, callback, componentUuid);
  };

  const publishToEvent = (
    event: SocketTopics,
    topic: string,
    data: IPublishWrapRequest | IPublishRequest,
    callback: any = () => { },
    qos?: number,
    options: PublishOptions = {}
  ) => {
    const effectiveQos = qos ?? 1;
    const retryOnAckTimeout = options.retryOnAckTimeout !== false;
    // doPublish is re-runnable: withClient runs it now if connected, else
    // queues it for the next 'connect'. For QoS 1 we also guard against a
    // half-open socket — a client that reports connected but whose TCP is
    // dead. The publish callback fires on PUBACK; if none arrives in time the
    // publish is re-queued (lookups only, see PublishOptions) and the client
    // is rebuilt once the socket looks dead rather than merely slow.
    const doPublish = (client: any) => {
      if (socketDebugEnabled()) console.log("publishing to event", topic, data);
      let settled = false;
      let overdue = false;
      const sentAt = Date.now();
      const ackTimer =
        effectiveQos === 0
          ? null
          : setTimeout(() => {
            if (settled) return;
            overdue = true;
            overduePublishesRef.current += 1;
            const silentSinceSend = lastPacketAtRef.current < sentAt;
            const looksDead =
              silentSinceSend ||
              overduePublishesRef.current >= OVERDUE_PUBLISHES_TO_REBUILD;
            if (retryOnAckTimeout) {
              // Settle now: the re-queued copy reports the result. This copy
              // stays counted as overdue until its PUBACK lands (or the next
              // connect resets the count).
              settled = true;
              if (looksDead) {
                // Goes out on the rebuilt client's 'connect'.
                console.warn("publish unacked — requeueing", topic);
                enqueuePending(doPublish);
              } else {
                // Connection is alive, just slow: re-send on it now.
                console.warn("publish unacked — re-sending", topic);
                withClient(doPublish);
              }
            } else {
              console.warn("publish unacked — not re-sent (has side effects)", topic);
            }
            if (looksDead) replaceClient("publish unacked (half-open?)");
          }, PUBLISH_ACK_TIMEOUT_MS);
      client.publish(
        topic,
        JSON.stringify(data),
        { qos: effectiveQos },
        (error: any) => {
          if (overdue) {
            overdue = false;
            overduePublishesRef.current = Math.max(
              0,
              overduePublishesRef.current - 1
            );
          }
          if (settled) return;
          settled = true;
          if (ackTimer) clearTimeout(ackTimer);
          callback({ status: !error });
        }
      );
    };
    withClient(doPublish);
  };

  const subscribeToEvent = (
    event: SocketTopics,
    topic: string,
    callback: any = () => { },
    componentUuid?: string
  ) => {
    // Register the handler and remember the topic immediately. Previously
    // both happened inside the SUBACK callback, so a missing client or a
    // failed subscribe silently lost the subscription with no retry.
    registerCallback(topic, callback, componentUuid);
    desiredSubsRef.current.add(topic);
    withClient((client) => {
      client.subscribe(topic, { qos: 1 }, (error) => {
        if (error) {
          // Retried on the next 'connect' via desiredSubsRef.
          console.log("Subscribe to topics error", error);
        }
      });
    });
  };

  const unSubscribeToEvent = (
    event: SocketTopics,
    topic: string,
    callback: any = () => { },
    componentUuid?: string
  ) => {
    // With a componentUuid only that component's handler is dropped; the
    // broker subscription stays while other components still listen.
    if (componentUuid !== undefined) {
      const remaining = (callbacks.current[topic] || []).filter(
        (x: any) => x.componentUuid !== componentUuid
      );
      if (remaining.length) {
        callbacks.current[topic] = remaining;
        return;
      }
    }
    desiredSubsRef.current.delete(topic);
    // Drop the handlers too, or messages matching this topic through a
    // wildcard overlap keep invoking callbacks of unmounted components.
    delete callbacks.current[topic];
    withClient((client) => {
      client.unsubscribe(topic, (error) => {
        if (error) {
          console.log("unSubsribed to topics error", error);
          return;
        }
      });
    });
  };

  const socketMessageReceivedListener = (topic: string, message: any) => {
    const payload = { topic, message: message.toString() };
    // console.log('payload', payload);
    if (!payload.message) return;

    if (socketDebugEnabled()) console.log('payload', payload);

    let data: any;
    try {
      data = JSON.parse(payload.message);
    } catch (error) {
      console.error("Socket message is not JSON", topic, error);
      return;
    }
    if (data && surveyTopicIds.current?.[data.id]) {
      topic = surveyTopicIds.current[data.id];
      data = data.response;
    }
    Object.keys(callbacks?.current || {}).map((callbackTopic) => {
      if (MQTTPattern.matches(callbackTopic, topic)) {
        (callbacks?.current?.[callbackTopic] || []).map(({ callback }) => {
          safeInvoke(callbackTopic, () => callback(data));
        });
      }
    });
    safeInvoke(topic, () => dispatchToAppHandlers(topic, data));
  };

  // Built-in (redux) handlers keyed by topic; isolated from the per-topic
  // callbacks above so a throw in one can't skip the other.
  const dispatchToAppHandlers = (topic: string, data: any) => {

    // if (callbacks?.current?.[topic]) {
    //   callbacks?.current?.[topic](data);
    // }
    if (topic === CADSectionTopics.GetSectionList) {
      getSectionList(data);
    }
    if (topic === BioTopics.GetBio) {
      getBio(data);
    }
    if (topic === BioTopics.GetRoleList) {
      getRoleList(data);
    }
    if (topic === SurveyQuestionTopics.GetSurveyQuestions) {
      getSurveyList(data);
    }
    if (topic === ExtendedBioTopics.GetRolesBio) {
      getExtendedBioList(data);
    }
    if (topic === ExtendedBioTopics.GetVehicleBio) {
      getVehicleExtendedBioList(data);
    }
    if (topic.includes(PageTopics.GetProjectsResult)) {
      console.log("getProjectList", data.response);
      getProjectList(data.response);
    }
    if (topic.includes(PageTopics.GetAccountsResult)) {
      getAccountsList(data.response);
    }
    if (topic.includes(PageTopics.GetRespondersResult)) {
      getRespondersList(data.response);
    }
    if (topic.includes(PageTopics.GetAssetsResult)) {
      getAssetsList(data.response);
    }
    if (
      topic.includes(PageTopics.CreateEventResult) ||
      topic.includes(PageTopics.CreateTicketResult) ||
      topic.includes(PageTopics.CreateRideResult) ||
      topic.includes(PageTopics.CreateSchoolResult) ||
      topic.includes(PageTopics.CreateShuttleBusResult)
    ) {
      setSubmitted(data.response);
    }
    if (topic.includes(PageTopics.SearchPageResult)) {
      getPageResult(data);
    }
    if (topic.includes(PageTopics.BdsEot)) {
      handlePageEot({ subscribeToEvent, publishToEvent }, topic, data);
    }
    if (topic.includes(PageTopics.SearchUser)) {
      getUsersList(data.id, data.response);
    }
    if (topic.includes(PageTopics.SearchMessage)) {
      handleMessages(data.id, data.response);
    }
    if (topic.includes(PageTopics.GroupMembers)) {
      handleAppendMessage(data);
    }
    if (topic.includes(PageTopics.SearchBds)) {
      handleUserBds(data);
    }
    if (topic.includes(PageTopics.GetPageAggregateBds)) {
      handleAggregateBds(data);
    }
    if (topic.includes(PageTopics.GetPageResult)) {
      handlePageResults(data);
    }
    if (
      topic.includes(PageTopics.GetAggregateBds) &&
      topic.includes(PageTopics.Connection)
    ) {
      handleAggregate(data);
    }
    if (topic.includes(PageTopics.GetPageResult)) {
      handlePageResults(data);
    }
    if (topic.includes(PageTopics.GetAdminRoles)) {
      handleAdminRoles(data);
    }
  };
  // Re-point every render so the socket's stable 'message' wrapper always
  // dispatches through the latest closure (fresh redux state and handlers).
  messageListenerRef.current = socketMessageReceivedListener;

  return {
    socketClient: connectedClient,
    connectionEpoch,
    socketConnect,
    subscribeToEventSurvey,
    publishToEventServiceIdSurvey,
    socketSubscribeToEvent: subscribeToEvent,
    socketUnSubscribeToEvent: unSubscribeToEvent,
    socketPublishToEvent: publishToEvent,
  };
};
