import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Input } from "antd";
import {
  FilePdfOutlined,
  MinusOutlined,
  PauseCircleOutlined,
  PlayCircleOutlined,
  PlusOutlined,
  ZoomInOutlined,
  ZoomOutOutlined,
} from "@ant-design/icons";
import _ from "lodash";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import {
  getPageRequestPublishTopic,
  getPageSubscriptionTopic,
  getPageEotSubscriptionTopic,
  getUsersSubscriptionTopic,
  getSearchMessageSubscriptionTopic,
  getFocusMessagePublishTopic,
  getPageGroupMembersSubscriptionTopic,
  getAggregateBdsPublishTopic,
  getAggregateBdsSubscriptionTopic,
  getBdsEotSubscriptionTopic,
} from "hooks/MQTTConstants";
import { useLocation } from "react-router-dom";
import { SocketTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import moment from "moment";
import { useDispatch } from "react-redux";
import { CLEAR_SUMMARY } from "reducers/reducer";
import { generateUUID } from "utils/appUtil";
import { formatForRedis, attributeKeyGenerator } from "utils/appUtil";
import html2PDF from "jspdf-html2canvas";
import { QRCodeSVG } from "qrcode.react";
import { GET_AGGREGATE } from "../../../reducers/reducer";
import useSocketActions from "../../../hooks/socketActions";
import { reverseGeocodeAddress } from "utils/placeName";
import { formatSpeed } from "../Fleet/fleetUtils";
import {
  findGpsWindow,
  formatDateTime,
  formatDuration,
  formatOffset,
  gpsHistoryRequest,
  gpsWindowKey,
  humanizeEventType,
  pointNear,
  staticRouteMapUrl,
  toLatLng,
  toMs,
  tripStats,
  tripTimes,
} from "../RideSummary/tripReport";
import {
  InfoItem,
  InfoList,
  KpiStrip,
  LocationRow,
  ReportCard,
  ReportHeader,
  StatusPill,
} from "../RideSummary/TripReportParts";

const { TextArea } = Input;
const DEFAULT_LIMIT = 720; // minutes per timeline page
const DEFAULT_ZOOM = 20; // px per minute
const TIMELINE_SPEEDS = [1, 2, 5, 7, 10, 15, 20, 30, 50, 100];
const TIMELINE_PAD = 5; // minutes drawn past the last event
const SCROLL_TOLERANCE = 2;
const MESSAGE_PAGE_SIZE = 100;
const MAX_MESSAGES = 1000;

const getEventIcon = (event) => {
  switch (event.messageType) {
    case "place":
      return { icon: "Place-icon", color: "purple" };
    case "video-call":
      return { icon: "Audio-icon", color: "green" };
    case "b2t-call":
      return { icon: "B2T-icon", color: "green" };
    case "beam-assist":
      return { icon: "Incident-icon", color: "orange" };
    case "capture":
      return { icon: "Capture-icon", color: "gray" };
    case "alert":
      return { icon: "Alert-icon", color: "yellow" };
    case "gps":
      return { icon: "iot_blue", color: "purple" };
    case "gps-stop":
      return { icon: "iot_blue", color: "purple" };
    case "gps-report":
      return { icon: "IoT File-icon", color: "green" };
    case "media":
      return { icon: "Image-icon", color: "blue" };
    case "rsvp":
      return { icon: "RSVP-icon", color: "yellow" };
    case "rsvp-response":
      return { icon: "RSVP-icon", color: "yellow" };
    case "video-recording":
      return { icon: "Video-icon", color: "blue" };
    case "sound-recording":
      return { icon: "Audio-icon", color: "green" };
    case "event":
      return { icon: "Event-icon", color: "orange" };
  }
};

const userLabel = (user: any) => {
  const full = [user?.firstName, user?.lastName].filter((x) => x && x !== "undefined").join(" ");
  return full || user?.beamId || user?.email || user?.phone || `User #${user?.id}`;
};

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w.charAt(0).toUpperCase())
    .join("") || "?";

const isAtEnd = (el: HTMLElement) => el.scrollLeft >= el.scrollWidth - el.clientWidth - SCROLL_TOLERANCE;

// Demo reward, hardcoded until rewards come from the backend.
const REWARD = {
  points: 12,
  store: "Sam's Club",
  couponCode: "BEAM-SAMS-12",
  couponUrl: "https://www.samsclub.com/",
};

const AnalyticsSummaryModal: FC<{ socket: ISocket; params?: any }> = ({ socket }) => {
  const { search } = useLocation();
  const { page, users, messages, requestIds, gps } = useSelector((state: RootState) => state.auth);
  const [pageInfo, setPageInfo] = useState<InfoItem[]>([]);
  const [pageLocation, setPageLocation] = useState<any>();
  const dispatch = useDispatch();
  const [messageBreakTime, setMessageBreakTime] = useState<any[]>([]);
  const [timeDiff, setTimeDiff] = useState<any>({
    offset: 0,
    limit: DEFAULT_LIMIT,
    length: 0,
  });
  const [zoom, setZoom] = useState<number>(DEFAULT_ZOOM);
  const [play, setPlay] = useState<boolean>(false);
  const [playSpeed, setPlaySpeed] = useState<number>(2);
  const [messagesLoaded, setMessagesLoaded] = useState(false);
  const [truncated, setTruncated] = useState(false);
  const [exporting, setExporting] = useState(false);
  const timelineRef = useRef<HTMLDivElement>(null);
  const reportRef = useRef<HTMLElement>(null);
  const playTimer = useRef<any>();
  const timeDiffRef = useRef(timeDiff);
  timeDiffRef.current = timeDiff;
  const requestedGps = useRef<string>("");
  const { handleMessages } = useSocketActions();

  const startTime = toMs(messages?.[0]?.createdAt);

  const getTime = (time: number, date = false): string =>
    moment((startTime ?? 0) + time * 60 * 1000).format(`${date ? "MMM D " : ""}hh:mm A`);

  const checkin = (time: number) => {
    const points = messageBreakTime.filter((bt) => bt.time === time);
    return points.length > 0 ? points : null;
  };

  const focusMessage = (messageId: string) => {
    const query = new URLSearchParams(search);
    const connectionId = query.get("connectionId");
    socket.publishToEvent(SocketTopics.PublishPageTopics, getFocusMessagePublishTopic(page?.objectId, connectionId), {
      messageId,
    });
  };

  const messageRequest = (pageId, offset: number): any => ({
    select: {
      index: {
        searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:message:createdAt`,
        searchQuery: `@pageId:{${pageId.toString()}}`,
        searchOptions: "TIMEOUT 100",
      },
      load: { object: "$" },
    },
    operations: [
      {
        sortBy: {
          properties: [
            {
              field: "@createdAt",
              order: "DESC",
            },
          ],
        },
      },
    ],
    result: {
      pagination: {
        offset,
        limit: MESSAGE_PAGE_SIZE,
      },
    },
    sortBy: {
      properties: [
        {
          field: "@createdAt",
          order: "DESC",
        },
      ],
      max: 10000,
    },
  });

  // Newest first, page by page (up to MAX_MESSAGES) so long incidents start
  // at the beginning; each page re-renders with everything loaded so far.
  const getMessages = (pageId) => {
    const requestId = generateUUID();
    localStorage.setItem("requestId", requestId);
    localStorage.setItem("requestService", "summary");
    setMessagesLoaded(false);
    setTruncated(false);
    const rows: any[] = [];
    const seen = new Set<string>();

    const fetchPage = (offset: number) => {
      dispatch(
        GET_AGGREGATE({
          requestData: messageRequest(pageId, offset),
          callback: (response) => {
            if (localStorage.getItem("requestId") !== requestId) return; // superseded
            const batch = Array.isArray(response) ? response : [];
            batch.forEach((row) => {
              const id = row?.object?.pageInfo?.pageMessageId;
              if (id !== undefined && id !== null) {
                if (seen.has(`${id}`)) return;
                seen.add(`${id}`);
              }
              rows.push(row);
            });
            handleMessages(requestId, rows.slice());
            const more = batch.length === MESSAGE_PAGE_SIZE;
            if (more && offset + MESSAGE_PAGE_SIZE < MAX_MESSAGES) {
              fetchPage(offset + MESSAGE_PAGE_SIZE);
            } else {
              setTruncated(more);
              setMessagesLoaded(true);
            }
          },
        })
      );
    };
    fetchPage(0);
  };

  useEffect(() => {
    dispatch({ type: CLEAR_SUMMARY }); // also resets `gps`
    requestedGps.current = "";
    if (socket.client) {
      const query = new URLSearchParams(search);
      const connectionId = query.get("connectionId");
      const pageId = query.get("pageId");
      const cudbServiceId = query.get("cudbServiceId");
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getPageSubscriptionTopic(connectionId));
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getPageEotSubscriptionTopic(pageId));
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getUsersSubscriptionTopic(connectionId, cudbServiceId));
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getSearchMessageSubscriptionTopic(pageId, connectionId));
      if (pageId) {
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageRequestPublishTopic(connectionId),
          wrapRequestPayload(
            {
              objectId: pageId,
              paths: ["$"],
              returnPaths: ["$"],
            },
            pageId
          )
        );
        socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getPageGroupMembersSubscriptionTopic(pageId));
        getMessages(pageId);
      }
    }
  }, [search, socket.client]);

  const getPageUsers = (ids) => {
    const query = new URLSearchParams(search);
    const cudbServiceId = query.get("cudbServiceId");
    const connectionId = query.get("connectionId");
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery: `@serviceId:{'${formatForRedis(cudbServiceId)}'}`,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds: ids,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: ``,
      },
      anyStatus: false,
    };
    socket.publishToEvent(
      SocketTopics.PublishPageTopics,
      getAggregateBdsPublishTopic(connectionId),
      wrapRequestPayload(userRequest, requestIds.user)
    );
  };

  useEffect(() => {
    if (page) {
      const query = new URLSearchParams(search);
      const connectionId = query.get("connectionId");
      const pageId = query.get("pageId");
      if (pageId !== page.objectId) return;
      let info: InfoItem[] = [];
      const onMove = page?.persistent?.static?.profile ?? {};
      if (onMove.type === "cad") {
        Object.keys(onMove).forEach((key) => {
          if (typeof onMove[key] === "string") {
            info.push({ name: attributeKeyGenerator(key), value: onMove[key] });
          } else if (onMove[key]?.type === "location" || onMove[key]?.type === "incident-location") {
            setPageLocation({ name: attributeKeyGenerator(key), value: onMove[key] });
          }
        });
      } else {
        info = [
          { name: "Incident Type", value: "Hail ride" },
          { name: "First Name", value: "N/A" },
          { name: "Last Name", value: "N/A" },
          { name: "Phone", value: "N/A" },
          { name: "Alternative Phone", value: "N/A" },
        ];
      }
      info = [...info, { name: "Dispatch Time", value: formatDateTime(page?.persistent?.static?.metadata?.createdAt) }];
      setPageInfo(info);
      const members = page?.persistent?.static?.metadata?.members?.users ?? {};
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getAggregateBdsSubscriptionTopic(connectionId));
      getPageUsers(Object.keys(members));
    }
  }, [page]);

  useEffect(() => {
    if (users && socket.client) {
      const query = new URLSearchParams(search);
      const cudbServiceId = query.get("cudbServiceId");

      users.forEach((user) => {
        socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getBdsEotSubscriptionTopic(cudbServiceId, user.id));
      });
    }
  }, [users, socket.client]);

  useEffect(() => {
    if (messages && messages.length > 0) {
      const start = toMs(messages[0]?.createdAt) ?? 0;
      const end = toMs(messages[messages.length - 1]?.createdAt) ?? start;
      const breakTimes = messages.map((message) => {
        const eventIcon = getEventIcon(message);
        return {
          time: Math.floor(((toMs(message.createdAt) ?? start) - start) / 1000 / 60),
          name: eventIcon?.icon,
          icon: eventIcon?.color,
          type: humanizeEventType(message.messageType),
          id: message.id,
        };
      });
      const diffMinutes = (end - start) / 1000 / 60;
      setMessageBreakTime(breakTimes);
      if (timeDiff.offset === 0) {
        setTimeDiff({ offset: 0, limit: DEFAULT_LIMIT, length: diffMinutes });
      } else {
        setTimeDiff({
          offset: timeDiff.offset,
          limit: timeDiff.limit,
          length: diffMinutes,
        });
      }
    }
  }, [messages]);

  // Playback: scroll the timeline; stop at the very end of the last page.
  useEffect(() => {
    if (playTimer.current) clearInterval(playTimer.current);
    playTimer.current = undefined;
    if (!play) return;
    playTimer.current = setInterval(() => {
      const el = timelineRef.current;
      if (!el) return;
      if (!isAtEnd(el)) {
        el.scrollLeft += TIMELINE_SPEEDS[playSpeed];
      } else if (timeDiffRef.current.length <= timeDiffRef.current.limit) {
        setPlay(false);
      }
    }, 10);
  }, [play, playSpeed]);

  useEffect(
    () => () => {
      if (playTimer.current) clearInterval(playTimer.current);
    },
    []
  );

  /* ------------------------------------------------------------- GPS */

  const gpsWindow = useMemo(() => (messagesLoaded ? findGpsWindow(messages) : undefined), [messages, messagesLoaded]);

  useEffect(() => {
    const requestData = gpsHistoryRequest(gpsWindow);
    const key = gpsWindowKey(gpsWindow);
    if (!requestData || requestedGps.current === key) return;
    requestedGps.current = key;
    dispatch({
      type: "GET_HISTORICAL_GPS",
      payload: { requestData },
    });
  }, [gpsWindow]);

  const s = page?.persistent?.static;
  const meterUnit = s?.profile?.meterDetails?.unit ?? s?.meter?.meterDetails?.unit;
  const stats = useMemo(() => tripStats(gps?.samples, meterUnit), [gps, meterUnit]);
  const times = useMemo(
    () => tripTimes({ page, window: gpsWindow, points: stats?.track, waitMs: stats?.waitMs }),
    [page, gpsWindow, stats]
  );
  // The GPS report's first and last breadcrumbs are the trip's start and end.
  const trackStart = stats?.track?.length ? stats.track[0] : undefined;
  const trackEnd = stats?.track?.length ? stats.track[stats.track.length - 1] : undefined;
  const [startAddress, setStartAddress] = useState<string>();
  const [endAddress, setEndAddress] = useState<string>();
  useEffect(() => {
    let cancelled = false;
    setStartAddress(undefined);
    setEndAddress(undefined);
    const lookup = (point: { lat: number; lng: number } | undefined, set: (a: string) => void) => {
      if (!point) return;
      reverseGeocodeAddress({ lat: point.lat, long: point.lng }).then(
        (address) => {
          if (!cancelled && address) set(address);
        },
        () => undefined
      );
    };
    lookup(trackStart, setStartAddress);
    lookup(trackEnd, setEndAddress);
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [trackStart?.lat, trackStart?.lng, trackEnd?.lat, trackEnd?.lng]);

  // Demo store pin near where the trip ended (or the incident), stable per page.
  const incidentPoint = toLatLng(pageLocation?.value) ?? toLatLng(page?.persistent?.static?.live?.location);
  const storeCenter = trackEnd ? { lat: trackEnd.lat, lng: trackEnd.lng } : incidentPoint;
  const storePoint = useMemo(
    () => (storeCenter ? pointNear(storeCenter, `${page?.objectId ?? ""}`) : undefined),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [storeCenter?.lat, storeCenter?.lng, page?.objectId]
  );

  const mapUrl = useMemo(() => {
    const extraMarkers = storePoint ? [{ ...storePoint, color: "purple", label: "S" }] : [];
    if (stats) {
      return staticRouteMapUrl({
        track: stats.track,
        pickup: trackStart && { lat: trackStart.lat, lng: trackStart.lng },
        dropoff: trackEnd && { lat: trackEnd.lat, lng: trackEnd.lng },
        extraMarkers,
      });
    }
    return incidentPoint ? staticRouteMapUrl({ pickup: incidentPoint, extraMarkers }) : undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stats, trackStart, trackEnd, storePoint, incidentPoint?.lat, incidentPoint?.lng]);

  const tripRows: InfoItem[] = [
    { name: "Moving distance", value: stats ? `${stats.distance.toFixed(2)} ${stats.unit}` : "—" },
    { name: "Moving time", value: stats ? formatDuration(stats.movingMs) : "—" },
    { name: "Wait time", value: stats ? formatDuration(stats.waitMs) : "—" },
    { name: "Stops (3 min+)", value: stats ? `${stats.stops.length}` : "—" },
    { name: "Max speed", value: stats ? formatSpeed(stats.maxSpeed, stats.unit === "mi" ? "mph" : "kph") : "—" },
    { name: "Start time", value: formatDateTime(times.start) },
    { name: "End time", value: formatDateTime(times.end) },
    { name: "Total time", value: formatDuration(times.totalMs) },
  ];

  /* ---------------------------------------------------------- render */

  const exportPdf = () => {
    if (!reportRef.current || exporting) return;
    setExporting(true);
    Promise.resolve(
      html2PDF(reportRef.current, {
        jsPDF: {
          format: "a4",
        },
        html2canvas: {
          scrollX: 0,
          scrollY: -window.scrollY,
        },
        imageType: "image/jpeg",
        output: "./pdf/generate.pdf",
      })
    ).finally(() => setExporting(false));
  };

  const senderName = (senderId: any) => {
    if (senderId === undefined || senderId === null || `${senderId}` === "0" || `${senderId}` === "") return "System";
    const user = (users ?? []).find((x) => String(x.id) === String(senderId));
    return user ? userLabel(user) : `User #${senderId}`;
  };

  if (!page) {
    return (
      <main className="trip-report" aria-busy="true">
        <div className="trip-report__page">
          <p className="tr-loading">Loading summary…</p>
        </div>
      </main>
    );
  }

  const isCad = s?.profile?.type === "cad";
  const lastSlot = Math.min(timeDiff.limit, Math.ceil(timeDiff.length) + TIMELINE_PAD);

  return (
    <main className="trip-report" ref={reportRef}>
      <div className="trip-report__page">
        <ReportHeader
          kicker="Incident summary"
          title={s?.metadata?.title}
          status={page?.nonpersistent?.static?.live?.status?.name}
          subtitle={<span className="tr-header__date">{formatDateTime(s?.metadata?.createdAt)}</span>}
          actions={
            <button type="button" className="tr-btn tr-btn--primary" onClick={exportPdf} disabled={exporting}>
              <FilePdfOutlined aria-hidden="true" />
              {exporting ? "Exporting…" : "Export PDF"}
            </button>
          }
        />

        {/* Same figures as the Trip summary table below. */}
        <KpiStrip
          label="Trip totals"
          items={[
            {
              label: "Total distance",
              value: stats ? `${stats.distance.toFixed(2)} ${stats.unit === "mi" ? "miles" : "km"}` : undefined,
            },
            { label: "Moving time", value: stats ? formatDuration(stats.movingMs) : undefined },
            { label: "Wait time", value: stats ? formatDuration(stats.waitMs) : undefined },
            { label: "Total time", value: formatDuration(times.totalMs) },
          ]}
        />

        <div className="tr-grid">
          <div className="tr-col">
            <ReportCard id="incident-info" title="Incident information">
              <InfoList items={pageInfo} />
            </ReportCard>

            <ReportCard id="trip-summary" title="Trip summary">
              <table className="tr-table">
                <caption className="tr-sr-only">Trip summary from the GPS breadcrumbs</caption>
                <tbody>
                  {tripRows.map((row) => (
                    <tr key={row.name}>
                      <th scope="row">{row.name}</th>
                      <td className="tr-num">{row.value}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {!stats && (
                <p className="tr-note">
                  {messagesLoaded && !gpsWindow ? "No GPS trip recorded on this page." : "GPS track not loaded."}
                </p>
              )}
            </ReportCard>
          </div>

          <div className="tr-col">
            <ReportCard id="locations" title="Locations">
              {mapUrl && (
                <figure className="tr-map">
                  <img
                    src={mapUrl}
                    alt={stats ? "Map of the GPS route recorded during the trip" : "Map of the incident location"}
                  />
                  <figcaption>
                    {stats && (
                      <>
                        GPS route · {stats.track.length} points · {stats.totalDistance.toFixed(1)} {stats.unit}
                        {storePoint && " · "}
                      </>
                    )}
                    {storePoint && (
                      <>
                        <span className="tr-store-pin" aria-hidden="true">
                          S
                        </span>{" "}
                        {REWARD.store}
                      </>
                    )}
                  </figcaption>
                </figure>
              )}
              <ul className="tr-locations">
                {trackStart && trackEnd ? (
                  <>
                    <LocationRow
                      tone="green"
                      title="Start location"
                      location={{ lat: trackStart.lat, lng: trackStart.lng }}
                      address={startAddress}
                    />
                    <LocationRow
                      tone="red"
                      title="End location"
                      location={{ lat: trackEnd.lat, lng: trackEnd.lng }}
                      address={endAddress}
                    />
                  </>
                ) : (
                  <>
                    {/* No GPS report: the incident location, as before. */}
                    {isCad && pageLocation && (
                      <LocationRow tone="green" title={pageLocation.name} location={pageLocation.value} />
                    )}
                    {!isCad && (
                      <LocationRow tone="green" title="Incident location" location={s?.live?.location} />
                    )}
                  </>
                )}
              </ul>
            </ReportCard>

            <ReportCard id="rewards" title="Rewards">
              <div className="tr-reward">
                <div className="tr-reward__points" aria-label={`${REWARD.points} points earned`}>
                  <span className="tr-reward__value">{REWARD.points}</span>
                  <span className="tr-reward__unit">points</span>
                </div>
                <p className="tr-reward__text">
                  You have earned <strong>{REWARD.points} points</strong>. Use the attached coupon and redeem it at
                  any {REWARD.store} near you.
                </p>
              </div>
              <div className="tr-coupon">
                <QRCodeSVG
                  value={REWARD.couponUrl}
                  size={112}
                  level="M"
                  className="tr-coupon__qr"
                  aria-label={`QR code for the ${REWARD.store} coupon`}
                />
                <div className="tr-coupon__body">
                  <span className="tr-coupon__label">Coupon code</span>
                  <span className="tr-coupon__code">{REWARD.couponCode}</span>
                  <a className="tr-btn tr-btn--primary" href={REWARD.couponUrl} target="_blank" rel="noopener noreferrer">
                    Open coupon
                  </a>
                </div>
              </div>
            </ReportCard>

            <ReportCard id="actions" title="Protocols & actions" className="tr-noprint">
              <label htmlFor="tr-protocols" className="tr-field-label">
                Protocols <span className="tr-muted">(optional, max. 500 characters)</span>
              </label>
              <TextArea id="tr-protocols" className="tr-textarea" autoSize={{ minRows: 3, maxRows: 3 }} maxLength={500} />
              <div className="tr-actions">
                <button type="button" className="tr-btn">
                  Survey
                </button>
                <button type="button" className="tr-btn">
                  NCIC
                </button>
                <button type="button" className="tr-btn">
                  NFIRS
                </button>
              </div>
              <button type="button" className="tr-btn tr-btn--primary tr-btn--block">
                End Event
              </button>
            </ReportCard>
          </div>
        </div>

        <ReportCard id="people" title="People on page">
          {users && users.length ? (
            <ul className="tr-people">
              {users.map((user) => {
                const name = userLabel(user);
                const status = user?.nonpersistent?.static?.live?.status;
                const color = typeof status === "string" ? status : status?.name;
                return (
                  <li className="tr-person" key={user.id}>
                    <span className="tr-person__avatar" aria-hidden="true">
                      {initials(name)}
                    </span>
                    <div className="tr-person__text">
                      <h3 className="tr-person__name">{name}</h3>
                      <p>{user?.email || "No email"}</p>
                      <p>{user?.phone || "No phone"}</p>
                    </div>
                    {color && <StatusPill color={color} />}
                  </li>
                );
              })}
            </ul>
          ) : (
            <p className="tr-empty">No members loaded</p>
          )}
        </ReportCard>

        <ReportCard
          id="timeline"
          title="Timeline"
          actions={
            <div className="tr-toolbar" role="toolbar" aria-label="Timeline controls">
              {!play ? (
                <button type="button" className="tr-btn tr-btn--sm" onClick={() => setPlay(true)}>
                  <PlayCircleOutlined aria-hidden="true" /> Play
                </button>
              ) : (
                <>
                  <button type="button" className="tr-btn tr-btn--sm" onClick={() => setPlay(false)}>
                    <PauseCircleOutlined aria-hidden="true" /> Pause
                  </button>
                  <button
                    type="button"
                    className="tr-btn tr-btn--sm tr-btn--icon"
                    aria-label="Slower"
                    title="Slower"
                    disabled={playSpeed === 0}
                    onClick={() => playSpeed > 0 && setPlaySpeed(playSpeed - 1)}
                  >
                    <MinusOutlined aria-hidden="true" />
                  </button>
                  <span className="tr-toolbar__value" aria-live="polite">
                    ×{TIMELINE_SPEEDS[playSpeed]}
                  </span>
                  <button
                    type="button"
                    className="tr-btn tr-btn--sm tr-btn--icon"
                    aria-label="Faster"
                    title="Faster"
                    disabled={playSpeed === TIMELINE_SPEEDS.length - 1}
                    onClick={() => playSpeed < TIMELINE_SPEEDS.length - 1 && setPlaySpeed(playSpeed + 1)}
                  >
                    <PlusOutlined aria-hidden="true" />
                  </button>
                </>
              )}
              <span className="tr-toolbar__sep" aria-hidden="true" />
              <button
                type="button"
                className="tr-btn tr-btn--sm tr-btn--icon"
                aria-label="Zoom in"
                title="Zoom in"
                onClick={() => {
                  const el = timelineRef.current;
                  if (!el) return;
                  const scrollWidthBefore = el.scrollWidth;
                  setZoom(zoom + DEFAULT_ZOOM);
                  setTimeout(() => {
                    if (!timelineRef.current) return;
                    const scrollWidthAfter = timelineRef.current.scrollWidth;
                    const percentageIncrease = (scrollWidthAfter - scrollWidthBefore) / scrollWidthBefore + 1;
                    timelineRef.current.scrollLeft = timelineRef.current.scrollLeft * percentageIncrease + DEFAULT_ZOOM;
                  }, 100);
                }}
              >
                <ZoomInOutlined aria-hidden="true" />
              </button>
              <button
                type="button"
                className="tr-btn tr-btn--sm tr-btn--icon"
                aria-label="Zoom out"
                title="Zoom out"
                disabled={zoom <= DEFAULT_ZOOM}
                onClick={() => {
                  if (zoom > DEFAULT_ZOOM) setZoom(zoom - DEFAULT_ZOOM);
                }}
              >
                <ZoomOutOutlined aria-hidden="true" />
              </button>
            </div>
          }
        >
          <div
            className="tr-timeline"
            ref={timelineRef}
            onScroll={(e) => {
              const el = e.currentTarget;
              if (isAtEnd(el) && el.scrollWidth > el.clientWidth) {
                if (timeDiff.length > timeDiff.limit) {
                  setTimeDiff({
                    offset: timeDiff.offset + DEFAULT_LIMIT,
                    limit: timeDiff.limit + DEFAULT_LIMIT,
                    length: timeDiff.length,
                  });
                  el.scrollLeft = 5;
                } else {
                  setPlay(false);
                }
              } else if (el.scrollLeft <= SCROLL_TOLERANCE && timeDiff.offset !== 0) {
                setTimeDiff({
                  offset: timeDiff.offset - DEFAULT_LIMIT,
                  limit: timeDiff.limit - DEFAULT_LIMIT,
                  length: timeDiff.length,
                });
                el.scrollLeft = el.scrollWidth - el.clientWidth - 5;
              }
            }}
          >
            <div className="tr-timeline__bar">
              {_.range(timeDiff.offset, Math.max(lastSlot, timeDiff.offset + 1)).map((minute) => {
                const points = checkin(minute);
                const tick = minute % 5 === 0;
                if (!tick && !points) return <div className="tr-slot" style={{ width: zoom }} key={minute} />;
                const tone = points?.[points.length - 1]?.icon ?? "gray";
                return (
                  <div
                    className={`tr-slot tr-slot--tick ${points ? `tr-slot--event tr-tone--${tone}` : ""}`}
                    style={{ width: zoom }}
                    key={minute}
                  >
                    {tick && <span className="tr-slot__label">{getTime(minute, true)}</span>}
                    {points &&
                      points.map((point, j) => (
                        <div className="tr-event" style={{ paddingLeft: j * 10 }} key={point.id}>
                          <button
                            type="button"
                            className="tr-event__btn"
                            aria-label={`Focus ${point.type} at ${getTime(point.time)}`}
                            title={`${point.type} · ${getTime(point.time)}`}
                            onClick={() => focusMessage(point.id)}
                          >
                            <img src={`/images/${point.name ?? "text-icon"}.png`} alt="" />
                          </button>
                          {points.length === 1 && <span className="tr-event__type">{point.type}</span>}
                          {j === Math.floor(points.length / 2) && (
                            <span className="tr-event__time">{getTime(point.time)}</span>
                          )}
                        </div>
                      ))}
                  </div>
                );
              })}
            </div>
          </div>
          {timeDiff.length > DEFAULT_LIMIT && (
            <p className="tr-note">
              Showing {getTime(timeDiff.offset, true)} – {getTime(Math.min(lastSlot, timeDiff.limit), true)}. Scroll past
              either end to page through the incident.
            </p>
          )}
        </ReportCard>

        <ReportCard id="events" title="Events">
          {truncated && (
            <p className="tr-note tr-note--warn" role="status">
              Showing the latest {MAX_MESSAGES} messages; older events are not loaded.
            </p>
          )}
          {messages && messages.length ? (
            <div className="tr-table-wrap">
              <table className="tr-table tr-events">
                <thead>
                  <tr>
                    <th scope="col">Event</th>
                    <th scope="col">Status</th>
                    <th scope="col">User</th>
                    <th scope="col">Time</th>
                    <th scope="col">
                      <span className="tr-sr-only">Location</span>
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {messages.map((event, i) => {
                    const lat = event?.data?.coordinates?.lat ?? event?.data?.location?.coordinates?.lat;
                    const long = event?.data?.coordinates?.long ?? event?.data?.location?.coordinates?.long;
                    const created = toMs(event.createdAt);
                    const type = humanizeEventType(event.messageType);
                    return (
                      <tr key={event.id ?? i}>
                        <td>
                          <button
                            type="button"
                            className="tr-event-cell"
                            onClick={() => focusMessage(event.id)}
                            aria-label={`Focus ${type} in the page`}
                          >
                            <img src={`/images/${getEventIcon(event)?.icon ?? "text-icon"}.png`} alt="" />
                            <span>{type}</span>
                          </button>
                        </td>
                        <td>
                          {event.status ? (
                            <span className="tr-status-cell">
                              <StatusPill color={event.status.color} label={event.status.name} />
                              {event.status.onMoveEvent && <span className="tr-flag">Flagged</span>}
                            </span>
                          ) : (
                            <span className="tr-muted">—</span>
                          )}
                        </td>
                        <td>{senderName(event.senderId)}</td>
                        <td className="tr-nowrap" title={formatDateTime(created)}>
                          {created ? moment(created).format("hh:mm A") : "—"}
                          {created && startTime !== undefined && (
                            <span className="tr-muted"> · {formatOffset(created - startTime)}</span>
                          )}
                        </td>
                        <td className="tr-num">
                          {lat !== undefined && long !== undefined && (
                            <a
                              className="tr-btn tr-btn--sm"
                              href={`https://maps.google.com/?q=${lat},${long}`}
                              target="_blank"
                              rel="noopener noreferrer"
                              aria-label={`Open ${type} location in Google Maps`}
                            >
                              Map
                            </a>
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          ) : (
            <p className="tr-empty">{messagesLoaded ? "No events" : "Loading events…"}</p>
          )}
        </ReportCard>
      </div>
    </main>
  );
};

export default AnalyticsSummaryModal;
