import {
  BdsFormInfo,
  LiveUserRow,
  OrgRole,
  ProjectForm,
  RawProject,
  SurveyElement,
} from "./beamTypes";
import { escapeTag, postBds, postCudb, unwrapValue } from "./client";
import { ProgramsConfig } from "./config";

/** Where the admin console keeps an organization's projects on its config user. */
const PROJECT_ITEMS_PATH = "/persistent/static/admin/project/items";

const BDS_TYPE = "project:extendedBio";

/**
 * Every project of the organization, in the map's insertion order.
 *
 * The whole map comes back in one call — there is no server-side search,
 * sort or pagination for projects — and each project already carries its
 * `extendedBio` answers, so no second call per project is needed.
 */
export const fetchProjects = async (
  config: ProgramsConfig,
  signal?: AbortSignal
): Promise<RawProject[]> => {
  const response = await postCudb(
    config,
    "searchInUser",
    {
      objectId: config.adminUserId,
      paths: ["$"],
      returnPaths: [PROJECT_ITEMS_PATH],
      resultType: "value",
    },
    signal
  );

  const items = unwrapValue(response.data);
  if (!items || typeof items !== "object" || Array.isArray(items)) return [];

  return Object.entries(items as Record<string, RawProject>)
    .filter(([, project]) => project && typeof project === "object")
    .map(([id, project]) => ({ ...project, _id: project._id || id }));
};

/** Blocks hold the widgets; legacy forms keep a flat `questions` list instead. */
export const elementsOf = (info: BdsFormInfo | undefined): SurveyElement[] => {
  const data = info?.data;
  if (!data) return [];
  if (Array.isArray(data.blocks) && data.blocks.length > 0) {
    return data.blocks.flatMap((block) => block?.elements ?? []);
  }
  return data.questions ?? [];
};

/**
 * The organization's active `project:extendedBio` forms. These define both the
 * widgets an event carries and which projects count as events: a project is an
 * event only when its `extendedBio.surveyId` is one of these forms.
 */
export const fetchProjectForms = async (
  config: ProgramsConfig,
  signal?: AbortSignal
): Promise<ProjectForm[]> => {
  const searchQuery =
    `@type:{${escapeTag(BDS_TYPE)}}` +
    `@partitions:{${escapeTag(`org:${config.serviceId}`)}}` +
    "@objectStatus:{active}";

  const response = await postBds<Array<{ objectId?: string | number; info?: BdsFormInfo }>>(
    config,
    "aggregateBds",
    {
      select: {
        index: { searchIndex: `${config.ecosystem}:query:bulk`, searchQuery },
        load: { objectId: "$.objectId", info: "$.info", createdAt: "$.info.createdAt" },
      },
      sortBy: { properties: [{ field: "@createdAt", order: "DESC" }], max: 100000 },
      result: { pagination: { offset: 0, limit: 1000 } },
    },
    signal
  );

  const rows = Array.isArray(response.data) ? response.data : [];
  return rows
    .filter((row) => row?.info?.type === BDS_TYPE)
    // BDS returns objectId as a number; surveyId on a project is a string.
    .map((row) => ({
      id: String(row.objectId),
      name: row.info?.name ?? "",
      elements: elementsOf(row.info),
    }));
};

/**
 * One form by id. Only needed when a project's answers point at a form the
 * list call did not return (for example after the form was archived).
 */
export const fetchForm = async (
  config: ProgramsConfig,
  formId: string,
  signal?: AbortSignal
): Promise<ProjectForm | null> => {
  const response = await postBds<{ header?: BdsFormInfo[][] }>(
    config,
    "searchInQuery",
    { objectId: formId, paths: ["$"], returnPaths: ["$..info"], resultType: "value" },
    signal
  );

  const info = response.data?.header?.[0]?.[0];
  // searchInQuery returns any BDS object, so the type has to be checked.
  if (!info || info.type !== BDS_TYPE) return null;
  return { id: String(formId), name: info.name ?? "", elements: elementsOf(info) };
};

/**
 * The organization's live users, used to turn a project's `managerLiveUserIds`
 * into coach names. Admin-level accounts are excluded, same as the console.
 */
export const fetchLiveUsers = async (
  config: ProgramsConfig,
  signal?: AbortSignal
): Promise<LiveUserRow[]> => {
  const searchQuery =
    `(@userType:{user}@serviceId:{${escapeTag(config.serviceId)}}` +
    "-@profileRole:{master\\-client | reseller | distributor | master})";

  const response = await postBds<LiveUserRow[]>(
    config,
    "aggregateBds",
    {
      select: {
        index: {
          searchIndex: `${config.ecosystem}:user:role`,
          searchQuery,
          searchOptions: "VERBATIM TIMEOUT 1000000",
        },
        load: {
          objectId: "$.objectId",
          firstName: "$.nonpersistent.static.live.profile.firstName",
          lastName: "$.nonpersistent.static.live.profile.lastName",
          beamId: "$.persistent.static.live.beamIds[0]",
        },
      },
      filter: { expression: "" },
      result: { pagination: { offset: 0, limit: 1000 } },
    },
    signal
  );

  return Array.isArray(response.data) ? response.data : [];
};

/**
 * The organization's roles, read off the config user as one array.
 *
 * The Programs page needs them for the sign-up sections: a role carries the
 * `extendedBioId` of its registration form, which is how the admin console
 * decides which form to open for a role.
 */
export const fetchRoles = async (
  config: ProgramsConfig,
  signal?: AbortSignal
): Promise<OrgRole[]> => {
  const response = await postCudb(
    config,
    "searchInUser",
    {
      objectId: config.adminUserId,
      paths: ["$"],
      returnPaths: ["$..persistent.static.admin.role"],
    },
    signal
  );

  return unwrapRoles(response.data).filter(
    (role) => role && typeof role === "object" && role._id
  );
};

/** Roles sit one array deeper than a single value: drill to the array of objects. */
const unwrapRoles = (data: unknown): OrgRole[] => {
  let current: unknown = data;
  while (Array.isArray(current) && current.length > 0 && Array.isArray(current[0])) {
    current = current[0];
  }
  return Array.isArray(current) ? (current as OrgRole[]) : [];
};
