/**
 * Presentational building blocks shared by the ride summary and the incident
 * summary reports. Styles: TripReport.scss (scoped under `.trip-report`).
 */
import React, { FC, ReactNode } from "react";
import { RIDE_STATUS_LABELS } from "../Ride/Dashboard/DashboardModal/constants";
import { toLatLng } from "./tripReport";
import "../Ride/Dashboard/DashboardModal/RidesTable.scss";
import "./TripReport.scss";

// Legacy colour names that have no `.ride-status--*` tone of their own.
const TONE_ALIASES: Record<string, string> = { yellow: "amber", orange: "red" };

/** A backend status colour → a `.ride-status--<tone>` the theme defines. */
export const statusTone = (color?: string) => {
  const c = `${color ?? ""}`.toLowerCase();
  const tone = TONE_ALIASES[c] ?? c;
  return RIDE_STATUS_LABELS[tone] ? tone : "gray";
};

const capitalize = (s: string) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

export const StatusPill: FC<{ color?: string; label?: string }> = ({ color, label }) => {
  const tone = statusTone(color);
  const text = label || (color ? RIDE_STATUS_LABELS[`${color}`.toLowerCase()] ?? capitalize(`${color}`) : "Unknown");
  return (
    <span className={`ride-status ride-status--${tone}`}>
      <span className="ride-status__dot" aria-hidden="true" />
      {text}
    </span>
  );
};

export const ReportCard: FC<{
  id: string;
  title: string;
  actions?: ReactNode;
  className?: string;
}> = ({ id, title, actions, className, children }) => (
  <section className={`tr-card ${className ?? ""}`} aria-labelledby={`${id}-title`}>
    <header className="tr-card__head">
      <h2 id={`${id}-title`} className="tr-card__title">
        {title}
      </h2>
      {actions}
    </header>
    <div className="tr-card__body">{children}</div>
  </section>
);

export interface InfoItem {
  name: string;
  value: ReactNode;
}

const isEmpty = (v: ReactNode) => v === undefined || v === null || v === "";

export const InfoList: FC<{ items: InfoItem[]; empty?: string }> = ({ items, empty = "No information" }) =>
  items.length ? (
    <dl className="tr-dl">
      {items.map((item, i) => (
        <div className="tr-dl__row" key={`${item.name}-${i}`}>
          <dt>{item.name}</dt>
          <dd>{isEmpty(item.value) ? "—" : item.value}</dd>
        </div>
      ))}
    </dl>
  ) : (
    <p className="tr-empty">{empty}</p>
  );

export interface Kpi {
  label: string;
  value: ReactNode;
  hint?: string;
}

export const KpiStrip: FC<{ items: Kpi[]; label: string }> = ({ items, label }) => (
  <dl className="tr-kpis" aria-label={label}>
    {items.map((k) => (
      <div className="tr-kpi" key={k.label}>
        <dt>{k.label}</dt>
        <dd>
          {isEmpty(k.value) ? "—" : k.value}
          {k.hint && <span className="tr-kpi__hint">{k.hint}</span>}
        </dd>
      </div>
    ))}
  </dl>
);

/** A pickup / dropoff / incident location with its coordinates and a map link. */
export const LocationRow: FC<{
  tone: "green" | "blue" | "red";
  title: string;
  location?: any;
  address?: string;
}> = ({ tone, title, location, address }) => {
  const ll = toLatLng(location);
  const text = address || location?.attributes?.address;
  return (
    <li className="tr-location">
      <span className={`tr-location__pin tr-location__pin--${tone}`} aria-hidden="true" />
      <div className="tr-location__text">
        <h3 className="tr-location__title">{title}</h3>
        <p className="tr-location__address">{text || (ll ? "Address unavailable" : "Not recorded")}</p>
        {ll && (
          <p className="tr-location__coords">
            {ll.lat.toFixed(6)}, {ll.lng.toFixed(6)}
            {" · "}
            <a
              href={`https://maps.google.com/?q=${ll.lat},${ll.lng}`}
              target="_blank"
              rel="noopener noreferrer"
              aria-label={`Open ${title.toLowerCase()} in Google Maps`}
            >
              Open map
            </a>
          </p>
        )}
      </div>
    </li>
  );
};

export const ReportHeader: FC<{
  kicker: string;
  title?: string;
  subtitle?: ReactNode;
  status?: string;
  actions?: ReactNode;
}> = ({ kicker, title, subtitle, status, actions }) => (
  <header className="tr-header">
    <div className="tr-header__main">
      <p className="tr-header__kicker">{kicker}</p>
      <h1 className="tr-header__title">{title || "Untitled"}</h1>
      <div className="tr-header__meta">
        <StatusPill color={status} />
        {subtitle}
      </div>
    </div>
    {actions && <div className="tr-header__actions">{actions}</div>}
  </header>
);
