import { getMaskedLocation, reverseGeocode } from "./utils";
import {
  buildScheduledInstant,
  OUTBOUND_LEG_SUFFIX,
  RETURN_LEG_SUFFIX,
} from "../rideSync";

export interface BuildRideRequestsCtx {
  userId: any;
  connectionId: any;
  responders: any[];
  pageId: any;
  submitPageId: { current: boolean };
  webBooker: boolean;
  encrypted_token: any;
  projects: any;
  locationTypeFare: { current: any };
  couponResponse: any;
  bookingOtp?: string;
  // One id per form submission; legs get `:out` / `:ret` suffixes. The ride
  // service dedupes on it, so a retry of the same form never double-books.
  clientRequestId?: string;
  // updatedAt of the ride as loaded in the panel; sent on Update so the ride
  // service can reject a stale overwrite (STALE_UPDATE).
  expectedUpdatedAt?: number;
  // Fleet IANA timezone for interpreting the picked date/time (browser zone
  // when undefined).
  timezone?: string;
  // Non-blocking notices for the dispatcher (e.g. past schedule time).
  onNotice?: (message: string) => void;
}

// Thrown for invalid input the dispatcher must fix before submitting.
export class RideRequestValidationError extends Error {}

const SCHEDULE_FIELDS = ["scheduleDate", "scheduleTime"];

// The ride service reverse-geocodes the masked pickup itself (default). Set
// REACT_APP_SERVER_MASKED_GEOCODE=false against a ride service that predates
// that, and the address is resolved here as before.
const SERVER_MASKED_GEOCODE =
  process.env.REACT_APP_SERVER_MASKED_GEOCODE !== "false";

// Masked pickup sent with a ride request: coordinates only when the ride
// service fills the address, else geocoded here.
const maskedPickupFields = async (pickupLocation: any) => {
  const coordinates = getMaskedLocation(
    pickupLocation?.coordinates?.lat,
    pickupLocation?.coordinates?.long
  );
  if (SERVER_MASKED_GEOCODE) {
    return { maskedPickupLocation: { coordinates } };
  }
  const address = await reverseGeocode(coordinates);
  return {
    maskedPickupLocation: { attributes: { address }, coordinates },
    maskedPickupAddress: address,
  };
};

// Builds the array of ride-create event requests (one-way and/or round-trip)
// from the resolved form attributes. Pure aside from geocoding lookups (the
// masked pickup only when REACT_APP_SERVER_MASKED_GEOCODE=false).
export async function buildRideRequests(
  sortedAttributes: any,
  values: any,
  ctx: BuildRideRequestsCtx
): Promise<any[]> {
  const {
    userId,
    connectionId,
    responders,
    pageId,
    submitPageId,
    webBooker,
    projects,
    locationTypeFare,
    couponResponse,
    bookingOtp,
    clientRequestId,
    expectedUpdatedAt,
    timezone,
    onNotice,
  } = ctx;

  const keys = Object.keys(sortedAttributes);
  const dispatchKey = keys.find(
    (key) => sortedAttributes?.[key]?.type === "dispatchType"
  );
  const rideTypeKey = keys.find(
    (key) =>
      sortedAttributes?.[key]?.type === "rideType" &&
      sortedAttributes?.[key]?.value === "roundTrip"
  );
  const isUpdate = !!(submitPageId.current && pageId);
  // Updating an existing ride must not create (or overwrite the outbound page
  // with) its return leg again: the return trip is its own ride.
  const buildReturnLeg = !!rideTypeKey && !isUpdate;
  if (rideTypeKey && isUpdate) {
    onNotice?.(
      "Only this ride is updated; its return trip is a separate ride and is not changed."
    );
  }

  // Coupons apply to the outbound leg only (the backend counts one use per
  // couponId), and a discountedFare is only meaningful with a couponId.
  const couponId = couponResponse?.data?.couponId ?? undefined;
  const now = Date.now();
  const leg = (suffix: string) =>
    clientRequestId
      ? buildReturnLeg
        ? `${clientRequestId}${suffix}`
        : clientRequestId
      : undefined;

  let outboundInstant: number | undefined;

  const buildOutbound = async () => {
    if (!dispatchKey) return undefined;
    let tripDispatch: any;
    let scheduledAt: number | undefined;
    const oneWaysortedAttributes = {
      ...sortedAttributes,
    };
    const oneWayUnstructured = { ...values };
    if (sortedAttributes?.[dispatchKey]?.value === "schedule") {
      oneWaysortedAttributes["scheduleDate"] =
        oneWaysortedAttributes?.[dispatchKey]?.date;
      oneWaysortedAttributes["scheduleTime"] =
        oneWaysortedAttributes?.[dispatchKey]?.time;
      const instant = buildScheduledInstant(
        oneWaysortedAttributes?.[dispatchKey],
        timezone
      );
      let leadTime = webBooker ? 20 : oneWaysortedAttributes?.leadTime || 0;
      if (instant === undefined || instant < now) {
        // A pickup time in the past is dispatched now, but say so and don't
        // leave a stale schedule on the ride.
        if (instant !== undefined) {
          onNotice?.(
            "The scheduled pickup time is in the past — the ride will be dispatched immediately."
          );
        }
        tripDispatch = { type: "immediate" };
        oneWaysortedAttributes[dispatchKey] = {
          type: "dispatchType",
          value: "immediate",
        };
        oneWayUnstructured.dispatch = {
          type: "dispatchType",
          value: "immediate",
        };
        SCHEDULE_FIELDS.forEach((f) => delete oneWaysortedAttributes[f]);
      } else if (instant - leadTime * 60000 < now) {
        // Inside the lead time: dispatch now, keep the pickup time on the ride.
        tripDispatch = { type: "immediate" };
        scheduledAt = instant;
      } else {
        scheduledAt = instant;
        tripDispatch = {
          utcDateTime: new Date(instant - leadTime * 60000).toUTCString(),
          rideDateTime: new Date(instant).toUTCString(),
          ridelocalDateTime: instant,
          type: "schedule",
        };
      }
    } else {
      tripDispatch = {
        type: "immediate",
      };
    }
    outboundInstant = scheduledAt ?? now;
    delete oneWaysortedAttributes?.leadTime;
    delete oneWaysortedAttributes?.roundTripLeadTime;
    delete oneWaysortedAttributes?.roundTripNotify;
    if (!couponId) delete oneWaysortedAttributes.discountedFare;
    if (scheduledAt !== undefined) oneWaysortedAttributes.scheduledAt = scheduledAt;
    if (oneWaysortedAttributes?.notify?.customTime) {
      oneWaysortedAttributes.notify.notifyTime =
        oneWaysortedAttributes.notify.customTime.toString();
    }
    oneWaysortedAttributes.vehicleTypeName =
      oneWaysortedAttributes.vehicleType?.name;
    oneWaysortedAttributes.vehicleType =
      oneWaysortedAttributes.vehicleType?.value;

    const maskedPickup = await maskedPickupFields(
      oneWaysortedAttributes?.pickupLocation
    );

    return {
      userId,
      rideRequestAttributes: {
        ...oneWaysortedAttributes,
        drivers: responders,
        pickupAddress:
          oneWaysortedAttributes?.pickupLocation?.attributes?.address,
        dropoffAddress:
          oneWaysortedAttributes?.dropoffLocation?.attributes?.address,
        ...maskedPickup,
        cudbServiceId: projects?.userServiceId,
      },
      drivers: responders,
      connectionId,
      unstructuredAttributes: {
        ...oneWayUnstructured,
        rideType: {
          type: "rideType",
          value: "oneWay",
        },
        vehicle: undefined,
        fixedPriceList: locationTypeFare.current,
      },
      pageId: isUpdate ? pageId : undefined,
      title: new Date().toLocaleString(),
      dispatch: tripDispatch,
      // The ride service treats createdAt as the ride time for scheduled rides
      // (dashboard day windows and cancellationDeadlineAt are derived from it),
      // so it is unchanged; scheduledAt carries the pickup instant explicitly.
      createdAt: tripDispatch?.ridelocalDateTime || new Date().getTime(),
      ...(scheduledAt !== undefined ? { scheduledAt } : {}),
      cudbServiceId: projects?.userServiceId,
      ...(webBooker
        ? {
          verifyCustomer: true,
          bookingOtp,
        }
        : {}),
      couponId,
      ...(leg(OUTBOUND_LEG_SUFFIX)
        ? { clientRequestId: leg(OUTBOUND_LEG_SUFFIX) }
        : {}),
      ...(isUpdate && expectedUpdatedAt ? { expectedUpdatedAt } : {}),
    };
  };

  const buildReturn = async () => {
    const key = rideTypeKey;
    const roundTripAttributes = {
      ...sortedAttributes,
    };
    const roundTripUnstructuredAttributes = {
      ...values,
    };
    roundTripAttributes["scheduleDate"] = roundTripAttributes?.[key]?.date;
    roundTripAttributes["scheduleTime"] = roundTripAttributes?.[key]?.time;
    const instant = buildScheduledInstant(roundTripAttributes?.[key], timezone);
    if (instant === undefined) {
      throw new RideRequestValidationError("Select the return trip date and time");
    }
    if (outboundInstant !== undefined && instant <= outboundInstant) {
      throw new RideRequestValidationError(
        "The return trip must be after the outbound pickup time"
      );
    }
    let leadTime = webBooker ? 20 : roundTripAttributes?.roundTripLeadTime || 0;
    const roundTripDispatch = {
      utcDateTime: new Date(instant - leadTime * 60000).toUTCString(),
      rideDateTime: new Date(instant).toUTCString(),
      ridelocalDateTime: instant,
      type: "schedule",
    };
    const tempLocation = roundTripAttributes.pickupLocation;
    roundTripAttributes.pickupLocation = roundTripAttributes.dropoffLocation;
    roundTripAttributes.dropoffLocation = tempLocation;

    const tempUnstructuredLocation =
      roundTripUnstructuredAttributes.pickupLocation;
    roundTripUnstructuredAttributes.pickupLocation =
      roundTripUnstructuredAttributes.dropoffLocation;
    roundTripUnstructuredAttributes.dropoffLocation = tempUnstructuredLocation;

    roundTripUnstructuredAttributes.dispatch = {
      date: roundTripUnstructuredAttributes.rideType.date,
      time: roundTripUnstructuredAttributes.rideType.time,
      type: "dispatchType",
      value: "schedule",
    };

    roundTripUnstructuredAttributes.rideType = {
      type: "rideType",
      value: "oneWay",
    };
    // The coupon was used by the outbound leg.
    delete roundTripUnstructuredAttributes.coupon;

    roundTripAttributes.notify = roundTripAttributes?.roundTripNotify;
    delete roundTripAttributes?.leadTime;
    delete roundTripAttributes?.roundTripLeadTime;
    delete roundTripAttributes?.roundTripNotify;
    delete roundTripAttributes.discountedFare;
    delete roundTripAttributes.coupon;
    delete roundTripAttributes.couponId;
    roundTripAttributes.scheduledAt = instant;
    if (roundTripAttributes?.notify?.customTime) {
      roundTripAttributes.notify.notifyTime =
        roundTripAttributes.notify.customTime.toString();
    }
    roundTripAttributes.vehicleTypeName = roundTripAttributes.vehicleType?.name;
    roundTripAttributes.vehicleType = roundTripAttributes.vehicleType?.value;
    const roundMaskedPickup = await maskedPickupFields(
      roundTripAttributes?.pickupLocation
    );
    return {
      userId,
      rideRequestAttributes: {
        ...roundTripAttributes,
        // Drivers picked for the outbound leg are not invited to the return.
        drivers: [],
        pickupAddress: roundTripAttributes?.pickupLocation?.attributes?.address,
        dropoffAddress:
          roundTripAttributes?.dropoffLocation?.attributes?.address,
        ...roundMaskedPickup,
        cudbServiceId: projects?.userServiceId,
      },
      drivers: [],
      connectionId,
      unstructuredAttributes: {
        ...roundTripUnstructuredAttributes,
        vehicle: undefined,
        fixedPriceList: locationTypeFare.current,
      },
      // Always a new ride.
      pageId: undefined,
      title: new Date().toLocaleString(),
      dispatch: roundTripDispatch,
      createdAt: roundTripDispatch?.ridelocalDateTime || new Date().getTime(),
      scheduledAt: instant,
      cudbServiceId: projects?.userServiceId,
      ...(webBooker
        ? {
          verifyCustomer: true,
          bookingOtp,
        }
        : {}),
      ...(leg(RETURN_LEG_SUFFIX)
        ? { clientRequestId: leg(RETURN_LEG_SUFFIX) }
        : {}),
    };
  };

  // buildOutbound sets outboundInstant synchronously (before its first await),
  // so the return leg can be validated against it; geocoding still overlaps.
  const outboundPromise = buildOutbound();
  const returnPromise = buildReturnLeg ? buildReturn() : Promise.resolve(undefined);
  const [outbound, returnLeg] = await Promise.all([outboundPromise, returnPromise]);
  return [outbound, returnLeg].filter(Boolean);
}
