import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { Button, Row, Col, Table, Input, Skeleton, DatePicker, Radio, Select } from "antd";

import { ReactSVG } from "react-svg";
import {
  SearchOutlined,
  ArrowLeftOutlined,
  EditOutlined,
  SettingOutlined,
} from "@ant-design/icons";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import { formatForRedis } from "utils/appUtil";
import { USER_TYPES, PERMISSION_TYPES } from "utils/PageTypes";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";
import { SocketTopics, UserTopics, ExtendedBioTopics } from "constants/enums";
import useSocketActions from "../../../../../hooks/socketActions";
import { pushNotification } from "utils/notifications";
import moment from "moment";
import AddToGroupModal, { GroupUser } from "../Groups/AddToGroupModal";
import "../Dashboard.scss";

let timeout;

// Sports dashboard: the Players screen can be narrowed to one of these team
// roleIds via the Team dropdown. Values are the hardcoded player team roleIds.
const PLAYER_TEAM_OPTIONS = [
  { label: "Recreational", value: "0c1c18ab-fe5f-4d40-a944-c78888fd2235" },
  { label: "Travel", value: "806397b8-e4be-4f3d-b7ef-83983ccc634d" },
];

const StudentsModal: FC<{
  socket: ISocket;
  params?: any;
  componentUuid?: string;
  userRole?: any;
}> = ({ socket, params, componentUuid, userRole }) => {
  const { selectedPage, encrypted_token, projects, adminUserRoles } = useSelector(
    (state: RootState) => state.auth
  );
  const dispatch = useDispatch();
  const { updateUserRequestPayloadV2 } = useSocketActions();
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const students = useRef<any>();
  const [iframeStudentId, setIframeStudentId] = useState<any>(undefined);
  const [iframeStudentName, setIframeStudentName] = useState<any>("");
  const [configureMode, setConfigureMode] = useState<boolean>(false);
  const isMounted = useRef(true);
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);

  const [selectedRole, setSelectedRole] = useState<any>({});
  useEffect(() => {
    if (adminUserRoles.length > 0) {
      const coachRole = adminUserRoles.filter(
        (x: any) =>
          x.name.toLowerCase() === "player" &&
          x.permissions.indexOf(PERMISSION_TYPES.OnMove) === -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
          x.permissions.indexOf(PERMISSION_TYPES.Dashboard) === -1 && x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1
      );
      setSelectedRole(coachRole[0] || {});

    }
  }, [adminUserRoles]);

  // Attendance: track the date being managed and the per-student status map.
  // Refs mirror state so the (memoised) column renderers always read fresh values.
  const [attendanceDate, setAttendanceDate] = useState<any>(moment());
  const attendanceDateRef = useRef<any>(attendanceDate);
  const [attendance, setAttendance] = useState<any>({});
  const attendanceRef = useRef<any>({});
  const [savingAttendanceId, setSavingAttendanceId] = useState<any>(undefined);
  const savingAttendanceRef = useRef<any>(undefined);

  // Class assignment: classes are projects. Map keeps the assigned project ids
  // per user; refs mirror state so the (memoised) column renderers stay fresh.
  const [classesByUser, setClassesByUser] = useState<any>({});
  const classesByUserRef = useRef<any>({});
  const [savingClassesId, setSavingClassesId] = useState<any>(undefined);
  const savingClassesRef = useRef<any>(undefined);
  // Selected class to filter the table by (client-side, against assigned classes).
  const [classFilter, setClassFilter] = useState<any>(undefined);
  // Selected team (Recreational / Travel) — narrows the query by roleId. The ref
  // mirrors state so the debounced search reads the current selection.
  // Multi-select + "Add to Group": adds the selected players to a BDS group.
  // Row keys are the numeric user ids (x.id), so keep React.Key here — forcing
  // them to strings would stop the controlled selection from matching the rows.
  const [selectedKeys, setSelectedKeys] = useState<React.Key[]>([]);
  const [groupModalOpen, setGroupModalOpen] = useState(false);
  // Date-of-birth month-range filter (MM-YYYY) over live.profile.doB.
  const [dobRange, setDobRange] = useState<[any, any] | null>(null);
  // Recreational / Travel subtype dropdown (server-side roleId filter, using the
  // two hardcoded player team roleIds in PLAYER_TEAM_OPTIONS).
  const [teamFilter, setTeamFilter] = useState<string | undefined>(undefined);
  const teamFilterRef = useRef<string | undefined>(undefined);
  // Dynamic filters (same source as Programs / Teams): the players' extendedBio
  // survey configs, with the selected values applied client-side to the rows.
  const [surveyConfigs, setSurveyConfigs] = useState<any[]>([]);
  const [filterValues, setFilterValues] = useState<Record<string, any>>({});
  const [playerUsers, setPlayerUsers] = useState<any[]>([]);
  const classOptions = (projects?.projects || []).map((project: any) => ({
    label: project?.name,
    value: project?.id,
  }));

  const updateClasses = (userId: string, classIds: string[]) => {
    if (!userId) return;
    const newMap = { ...classesByUserRef.current, [userId]: classIds };
    classesByUserRef.current = newMap;
    setClassesByUser(newMap);
    savingClassesRef.current = userId;
    setSavingClassesId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/classes",
          value: classIds,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingClassesRef.current = undefined;
        setSavingClassesId(undefined);
        pushNotification(
          "Classes updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  const handleAttendanceDateChange = (date: any) => {
    if (!date) return;
    attendanceDateRef.current = date;
    setAttendanceDate(date);
  };

  const updateAttendance = (userId: string, status: string) => {
    const dateKey = attendanceDateRef.current?.format("YYYY-MM-DD");
    if (!userId || !dateKey) return;
    const record = {
      status,
      markedAt: new Date().getTime(),
      markedBy: encrypted_token?.userId,
    };
    // Merge into the existing map so prior days are preserved, then write the
    // whole attendance object one level under schoolBus (mirrors locationList).
    const userAttendance = {
      ...(attendanceRef.current?.[userId] || {}),
      [dateKey]: record,
    };
    const newMap = { ...attendanceRef.current, [userId]: userAttendance };
    attendanceRef.current = newMap;
    setAttendance(newMap);
    savingAttendanceRef.current = userId;
    setSavingAttendanceId(userId);

    socket.publishToServiceIdSurvey(
      SocketTopics.SurveyTopics,
      UserTopics.UpdateUser,
      updateUserRequestPayloadV2(userId, [
        {
          op: "add",
          path: "/persistent/static/school/attendance",
          value: userAttendance,
        },
      ]),
      ExtendedBioTopics.UpdateUserBio,
      projects?.userServiceId
    );
    socket.subscribeToSurvey(
      SocketTopics.SurveyTopics,
      ExtendedBioTopics.UpdateUserBio,
      () => {
        savingAttendanceRef.current = undefined;
        setSavingAttendanceId(undefined);
        pushNotification(
          "Attendance updated successfully",
          "success",
          "TOP_CENTER",
          2000
        );
      }
    );
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  const formatUserFilterText = (text: string) => {
    var result = "";
    let comp = text
      .trim()
      .split(" ")
      .filter((word) => word.length > 2)
      .map((x) => {
        return "*" + formatForRedis(x) + "*";
      });
    if (comp.length == 0) {
      return result;
    }
    comp.forEach((element) => {
      result += `@firstName:(${element})|@lastName:(${element})|`;
    });
    result += `@beamIds:{${comp.join("|")}}`;
    return `(${result})`;
  };

  const getUsersByRole = (roles, filterText = undefined) => {
    let searchQuery = `@serviceId:{'${formatForRedis(
      projects?.userServiceId
    )}'}`;
    if (filterText && filterText.length > 2) {
      searchQuery += formatUserFilterText(filterText);
    }
    const userRoles = roles.filter(
      (x: any) =>
        x.name.toLowerCase() === "player" &&
        x.permissions.indexOf(PERMISSION_TYPES.OnMove) === -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Admin) === -1 &&
        x.permissions.indexOf(PERMISSION_TYPES.Dashboard) === -1 && x.permissions.indexOf(PERMISSION_TYPES.Live) !== -1
    );

    // Recreational / Travel selected: narrow to that single roleId; otherwise
    // load every player role plus both hardcoded team roleIds.
    const selectedTeam = teamFilterRef.current;
    const rolesQuery = selectedTeam
      ? [`@roleId === '${selectedTeam}'`]
      : [
          ...userRoles.map((y: any) => `@roleId === '${y._id}'`),
          ...PLAYER_TEAM_OPTIONS.map((team) => `@roleId === '${team.value}'`),
        ];
    const userRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:userNameIndex`,
          searchQuery,
          searchOptions: "TIMEOUT 5000",
        },
        list: {
          objectIds: userRole === "driver" ? [encrypted_token?.userId] : undefined,
        },
        load: {
          id: "$.objectId",
          status: "$.nonpersistent.static.live.status",
          live: "$.persistent.static.live",
          roleId: "$..admin.profile.roleId",
          schoolBus: "$..schoolBus",
          school: "$.persistent.static.school",
          extendedBio: "$..extendedBio",
        },
      },
      apply: {
        expression: "",
        name: "",
      },
      result: {},
      filter: {
        expression: `exists(@roleId) && (${rolesQuery.join("||")})`,
      },
      anyStatus: false,
    };
    setLoading(true);
    dispatch(
      GET_AGGREGATE({
        requestData: userRequest,
        callback: (response) => {
          setLoading(false);
          let sourceData = [];
          let columns: any = [
            {
              title: "Status",
              key: "userStatus",
              dataIndex: "userStatus",
              render: (status: string) => (
                <Button className="beam-btn icon-btn ml-2">
                  <ReactSVG
                    src="/images/flag-icon.svg"
                    className={`${status ?? "gray"}-icon`}
                  />
                </Button>
              ),
            },
            {
              title: "Name",
              key: "name",
              dataIndex: "name",
            },
            {
              title: "Custom id",
              key: "customId",
              dataIndex: "customId",
            },
            {
              title: "Email",
              key: "email",
              dataIndex: "email",
            },
            {
              title: "Phone",
              key: "phone",
              dataIndex: "phone",
            },
            // {
            //   title: "Class",
            //   key: "classes",
            //   dataIndex: "classes",
            //   render: (_: any, record: any) => {
            //     const userId = record?.action?.userId;
            //     return (
            //       <Select
            //         mode="multiple"
            //         allowClear
            //         size="small"
            //         style={{ minWidth: 200 }}
            //         placeholder="Assign classes"
            //         options={classOptions}
            //         value={record?.classes || []}
            //         loading={record?.savingClasses}
            //         disabled={record?.savingClasses}
            //         onChange={(ids) => updateClasses(userId, ids)}
            //         filterOption={(input, option) =>
            //           (option?.label ?? "")
            //             .toString()
            //             .toLowerCase()
            //             .includes(input.toLowerCase())
            //         }
            //       />
            //     );
            //   },
            // },
            // {
            //   title: "Attendance",
            //   key: "attendance",
            //   dataIndex: "attendance",
            //   render: (_: any, record: any) => {
            //     const userId = record?.action?.userId;
            //     return (
            //       <Radio.Group
            //         size="small"
            //         optionType="button"
            //         buttonStyle="solid"
            //         value={record?.attendanceStatus}
            //         disabled={record?.savingAttendance}
            //         onChange={(e) => updateAttendance(userId, e.target.value)}
            //       >
            //         <Radio.Button value="present">Present</Radio.Button>
            //         <Radio.Button value="absent">Absent</Radio.Button>
            //         <Radio.Button value="late">Late</Radio.Button>
            //       </Radio.Group>
            //     );
            //   },
            // },
            {
              title: "Action",
              key: "action",
              dataIndex: "action",
              render: (action: any) => (
                <Row style={{ width: 135 }}>
                  <Col span={8}>
                    <Button
                      style={{ boxShadow: "none" }}
                      className="beam-btn icon-btn yellow-btn cover"
                      onClick={() => {
                        setIframeStudentId(action.userId);
                        setIframeStudentName(action.name);
                      }}
                    >
                      <EditOutlined />
                    </Button>
                  </Col>
                </Row>
              ),
            },
          ];
          const attendanceMap: any = {};
          const classesMap: any = {};
          response?.map((x, i) => {
            if (x?.school?.attendance) {
              attendanceMap[x?.id] = x?.school?.attendance;
            }
            if (x?.school?.classes) {
              classesMap[x?.id] = x?.school?.classes;
            }
            sourceData.push({
              key: x.id,
              userStatus: x?.status?.name,
              name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              email: x?.live?.alternativeIds?.email,
              phone: x?.live?.alternativeIds?.phone,
              customId: x?.live?.alternativeIds?.customId,
              action: {
                userId: x?.id,
                user: x,
                name: `${x?.live?.profile?.firstName} ${x?.live?.profile?.lastName}`,
              },
            });
          });
          attendanceRef.current = attendanceMap;
          setAttendance(attendanceMap);
          classesByUserRef.current = classesMap;
          setClassesByUser(classesMap);
          students.current = sourceData;
          setPlayerUsers(response || []);
          setTableColumns(columns);
          setTableDataSource(sourceData);
        },
      })
    );
  };

  useEffect(() => {
    isMounted.current = true;
    return () => {
      isMounted.current = false;
    };
  }, []);

  // The players' `user:extendedBio` survey configs — the source of the dynamic
  // filters (same shape Programs and the Teams tab read their filters from).
  const fetchFilterConfigs = () => {
    if (!projects?.userServiceId) return;
    const requestData = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:query:bulk`,
          searchQuery: `@type:{project\\:extendedBio}@partitions:{org\\:${formatForRedis(
            projects?.userServiceId
          )}}@objectStatus:{active}`,
        },
        load: {
          objectId: "$.objectId",
          info: "$.info",
          createdAt: "$.info.createdAt",
        },
      },
      sortBy: {
        properties: [{ field: "@createdAt", order: "DESC" }],
        max: 100000,
      },
      result: { pagination: { offset: 0, limit: 1000 } },
    };
    dispatch(
      GET_AGGREGATE({
        requestData,
        callback: (data: any[]) => {
          if (!isMounted.current) return;
          setSurveyConfigs(Array.isArray(data) ? data : []);
        },
      })
    );
  };

  useEffect(() => {
    if (projects?.adminUserId) {
      getUsersByRole(adminUserRoles);
      fetchFilterConfigs();
    }
  }, [projects]);

  const loadingColumns = [
    {
      title: "...",
      dataIndex: "loading",
      key: "loading",
      render: () => (
        <Skeleton
          active
          title={false}
          paragraph={{
            rows: 7,
            width: "100%",
          }}
        />
      ),
    },
  ];

  const loadingData = Array(1)
    .fill({})
    .map((_, index) => ({ key: `loading-${index}` }));

  // Strip the HTML wrapper survey headlines/choices ship with down to text,
  // decoding the common entities (e.g. `&amp;` -> `&`) so labels read cleanly.
  const stripHtml = (value: any) =>
    (value || "")
      .toString()
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/\s+/g, " ")
      .trim();

  // Distinct answer values across the loaded players for a survey element id,
  // flattening array answers (multi-choice, ranking, contactInfo, address).
  const distinctAnswerValues = (elementId: string) => {
    const set = new Set<any>();
    (playerUsers || []).forEach((u: any) => {
      const answer = u?.extendedBio?.answers?.[elementId];
      if (answer === undefined || answer === null || answer === "") return;
      if (Array.isArray(answer)) {
        answer.forEach((v) => {
          if (v !== undefined && v !== null && v !== "") set.add(v);
        });
      } else if (typeof answer !== "object") {
        set.add(answer);
      }
    });
    return Array.from(set).map((v) => ({ label: `${v}`, value: v }));
  };

  // Dynamic filter definitions, built from the org's `project:extendedBio`
  // survey configs (the same source Programs reads): every `isFilter` widget
  // becomes one dropdown. Gender and Age group are left out here — Gender is a
  // fixed dropdown built below, and Age group was dropped.
  const filterFields = useMemo(() => {
    const seen = new Set<string>();
    const fields: any[] = [];

    (surveyConfigs || []).forEach((survey: any) => {
      const blocks = survey?.info?.data?.blocks || [];
      blocks.forEach((block: any) => {
        (block?.elements || []).forEach((el: any) => {
          if (!el?.isFilter || !el?.id || seen.has(el.id)) return;

          const label = stripHtml(el?.headline?.default) || el.id;
          // Gender is a fixed dropdown; Age group was removed — skip both here.
          if (/gender/i.test(label) || /\bage\b/i.test(label)) return;
          seen.add(el.id);

          let options: { label: string; value: any }[] = [];

          if (
            el.type === "multipleChoiceSingle" ||
            el.type === "multipleChoiceMulti" ||
            el.type === "ranking" ||
            el.type === "pictureSelection"
          ) {
            options = (el.choices || []).map((c: any) => ({
              label: stripHtml(c?.label?.default),
              value: stripHtml(c?.label?.default),
            }));
          } else if (el.type === "rating") {
            options = Array.from({ length: el?.range || 5 }, (_, i) => ({
              label: `${i + 1}`,
              value: i + 1,
            }));
          } else if (el.type === "nps") {
            options = Array.from({ length: 11 }, (_, i) => ({
              label: `${i}`,
              value: i,
            }));
          } else if (el.type === "matrix" || el.type === "selectUsers") {
            // Object-valued answers don't map to a single dropdown; skip.
            return;
          } else {
            options = distinctAnswerValues(el.id);
          }

          fields.push({ id: el.id, label, kind: "value", options });
        });
      });
    });

    // Gender is a standard profile field (live.profile.gender), not a survey
    // answer, so it's a fixed dropdown shown first. Stored values are lowercase
    // ("female"), so options carry the lowercase value and matching is
    // case-insensitive.
    const special = [
      {
        id: "__gender",
        label: "Gender",
        kind: "gender",
        options: [
          { label: "Male", value: "male" },
          { label: "Female", value: "female" },
          { label: "Coed", value: "coed" },
        ],
      },
    ];

    return [...special, ...fields];
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [surveyConfigs, playerUsers]);

  // Filters that currently have a value selected (drives the clear button).
  const activeFilters = useMemo(
    () =>
      filterFields.filter(
        (f: any) =>
          filterValues[f.id] !== undefined &&
          filterValues[f.id] !== null &&
          filterValues[f.id] !== ""
      ),
    [filterFields, filterValues]
  );

  // Derive per-row attendance/class values so each row gets a NEW reference when
  // these change. rc-table memoises rows by record reference, so without this the
  // cells wouldn't re-render on update or when the attendance date changes.
  const tableData = useMemo(() => {
    const dateKey = attendanceDate?.format("YYYY-MM-DD");
    return (tableDataSource || [])
      .filter((row: any) => {
        if (classFilter) {
          const userId = row?.action?.userId;
          if (!(classesByUser?.[userId] || []).includes(classFilter)) return false;
        }
        // Dynamic extendedBio filters: a row matches when its answer equals the
        // selected value (array answers match when any item does; objects by id).
        const answers = row?.action?.user?.extendedBio?.answers || {};
        const profile = row?.action?.user?.live?.profile || {};
        // Date-of-birth range (month granularity): keep players whose doB falls
        // within the selected MM-YYYY range.
        if (dobRange && (dobRange[0] || dobRange[1])) {
          const dob = profile.doB ?? profile.dob;
          const m = dob ? moment(dob) : null;
          if (!m || !m.isValid()) return false;
          if (dobRange[0] && m.isBefore(moment(dobRange[0]).startOf("month"))) return false;
          if (dobRange[1] && m.isAfter(moment(dobRange[1]).endOf("month"))) return false;
        }
        for (const f of activeFilters) {
          const value = filterValues[f.id];
          // Gender and Age group read the player profile, not the survey answers.
          if (f.kind === "gender") {
            if (`${profile.gender ?? ""}`.trim().toLowerCase() !== `${value}`.toLowerCase())
              return false;
            continue;
          }
          const answer = answers[f.id];
          if (Array.isArray(answer)) {
            const ok = answer.some((a: any) =>
              a && typeof a === "object"
                ? `${a.id}` === `${value}`
                : `${a}` === `${value}`
            );
            if (!ok) return false;
          } else if (`${answer}` !== `${value}`) {
            return false;
          }
        }
        return true;
      })
      .map((row: any) => {
        const userId = row?.action?.userId;
        return {
          ...row,
          attendanceStatus: attendance?.[userId]?.[dateKey]?.status,
          classes: classesByUser?.[userId] || [],
          savingAttendance: savingAttendanceId === userId,
          savingClasses: savingClassesId === userId,
        };
      });
  }, [
    tableDataSource,
    attendance,
    classesByUser,
    attendanceDate,
    savingAttendanceId,
    savingClassesId,
    classFilter,
    activeFilters,
    filterValues,
    dobRange,
  ]);

  // Resolve the selected row keys back to { id, beamId } for the group modal.
  const selectedUsers: GroupUser[] = useMemo(() => {
    const byKey: Record<string, any> = {};
    (tableDataSource || []).forEach((row: any) => {
      byKey[row.key] = row?.action?.user;
    });
    return selectedKeys.map((k) => ({
      id: String(k),
      beamId: byKey[`${k}`]?.live?.beamIds?.[0],
    }));
  }, [selectedKeys, tableDataSource]);

  // id -> name for labelling a group's current members in the Add-to-Group popup.
  const usersById = useMemo(() => {
    const map: Record<string, string> = {};
    (tableDataSource || []).forEach((row: any) => {
      map[`${row.key}`] = row?.name || `#${row.key}`;
    });
    return map;
  }, [tableDataSource]);

  if (iframeStudentId !== undefined || configureMode) {
    const iframeUrl = configureMode
      ? selectedRole?.extendedBioId ? `https://cpc.staging.beam.live/admin/extendedBio/${selectedRole?.extendedBioId}/edit?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}` : `https://cpc.staging.beam.live/admin/extendedBio/new?t=user&serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}&roleId=${selectedRole?._id}`
      : selectedRole?.extendedBioId ? `https://cpc.staging.beam.live/eb/${selectedRole?.extendedBioId}?serviceId=${projects?.userServiceId}&adminUserId=${projects?.adminUserId}&connectionId=${encrypted_token?.connectionId}&userId=${iframeStudentId}` : undefined;
    return (
      <React.Fragment>
        <Row>
          <Col span={24} className="d-flex justify-content-start">
            <Button
              style={{ boxShadow: "none" }}
              className="beam-btn icon-btn cover mr-2"
              onClick={() => {
                setIframeStudentId(undefined);
                setConfigureMode(false);
              }}
            >
              <ArrowLeftOutlined />
            </Button>
            <div>
              <h2 style={{ marginBottom: 0 }}>
                {configureMode ? "" : iframeStudentName}
              </h2>
            </div>
          </Col>
        </Row>
        <Row className="mt-3">
          <Col span={24}>
            <iframe
              title="student-detail"
              src={iframeUrl}
              style={{ width: "100%", height: "100vh", border: "none" }}
            />
          </Col>
        </Row>
      </React.Fragment>
    );
  }

  return (
    <React.Fragment>
      <Row>
        <Col span={24}>
          <div>
            <h2 style={{ marginBottom: 4 }}>Players</h2>
            <p style={{ marginBottom: 0, color: "#8c8c8c" }}>Home &gt; Players</p>
          </div>
        </Col>
      </Row>

      <Row className="mt-3">
        <Col
          span={24}
          style={{
            display: "flex",
            flexDirection: isMobile ? "column" : "row",
            flexWrap: "wrap",
            alignItems: isMobile ? "stretch" : "flex-end",
            gap: 10,
            width: "100%",
          }}
        >
            <Input
              allowClear
              onChange={(e) => {
                let value: string = e.target.value;
                if (timeout) clearTimeout(timeout);
                timeout = setTimeout(() => {
                  if (value.includes("-")) value = formatForRedis(value);
                  getUsersByRole(adminUserRoles, value);
                }, 500);
              }}
              style={{ width: isMobile ? "100%" : 240, flexShrink: 0 }}
              placeholder="Search by name"
              prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
            />
            <Select
              allowClear
              placeholder="Recreational / Travel"
              options={PLAYER_TEAM_OPTIONS}
              value={teamFilter}
              onChange={(value) => {
                teamFilterRef.current = value;
                setTeamFilter(value);
                getUsersByRole(adminUserRoles);
              }}
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
            />
            <Select
              allowClear
              showSearch
              placeholder="Team"
              options={classOptions}
              value={classFilter}
              onChange={(value) => setClassFilter(value)}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toString()
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              style={{ width: isMobile ? "100%" : 200, flexShrink: 0 }}
            />
            {filterFields.map((f: any) => (
              <div
                key={f.id}
                style={{
                  display: "flex",
                  flexDirection: "column",
                  gap: 4,
                  width: isMobile ? "100%" : 180,
                  flexShrink: 0,
                }}
              >
                <span
                  title={f.label}
                  style={{
                    fontSize: 12,
                    color: "#8c8c8c",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  {f.label}
                </span>
                <Select
                  allowClear
                  showSearch
                  placeholder="All"
                  options={f.options}
                  value={filterValues[f.id]}
                  onChange={(value) =>
                    setFilterValues((prev) => ({ ...prev, [f.id]: value }))
                  }
                  filterOption={(input, option) =>
                    (option?.label ?? "")
                      .toString()
                      .toLowerCase()
                      .includes(input.toLowerCase())
                  }
                  style={{ width: "100%" }}
                />
              </div>
            ))}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 4,
                width: isMobile ? "100%" : 240,
                flexShrink: 0,
              }}
            >
              <span style={{ fontSize: 12, color: "#8c8c8c" }}>Date of birth</span>
              <DatePicker.RangePicker
                picker="month"
                format="MM-YYYY"
                value={dobRange as any}
                onChange={(vals) => setDobRange(vals as any)}
                style={{ width: "100%" }}
              />
            </div>
            {activeFilters.length > 0 && (
              <Button
                type="link"
                onClick={() => setFilterValues({})}
                style={{ flexShrink: 0, paddingLeft: 0 }}
              >
                Clear filters
              </Button>
            )}
            <DatePicker
              allowClear={false}
              value={attendanceDate}
              onChange={handleAttendanceDateChange}
              format="YYYY-MM-DD"
              disabledDate={(current) =>
                current && current > moment().endOf("day")
              }
              style={{ width: isMobile ? "100%" : 150, flexShrink: 0 }}
            />
            {userRole === "admin" && (
              <Button
                className="beam-btn configure-btn"
                icon={<SettingOutlined />}
                onClick={() => setConfigureMode(true)}
                style={{ flexShrink: 0, width: isMobile ? "100%" : "auto" }}
              >

              </Button>
            )}
        </Col>
      </Row>

      {selectedKeys.length > 0 && (
        <Row className="mt-3">
          <Col span={24} style={{ display: "flex", alignItems: "center", gap: 12 }}>
            <span style={{ color: "#595959" }}>{selectedKeys.length} selected</span>
            <Button
              type="primary"
              className="beam-btn"
              onClick={() => setGroupModalOpen(true)}
            >
              Add to Group
            </Button>
          </Col>
        </Row>
      )}

      <Row
        gutter={20}
        className="scrollable-table mt-3"
        style={{ display: "grid", marginRight: -20 }}
      >
        <Col xs={24} sm={24} md={24} style={{ maxHeight: 1000, overflow: "scroll" }}>
          <Table
            dataSource={loading ? loadingData : tableData}
            columns={loading ? loadingColumns : tableColumns}
            scroll={{ x: true }}
            onChange={(e) => { }}
            rowKey="key"
            rowSelection={
              loading
                ? undefined
                : {
                    selectedRowKeys: selectedKeys,
                    onChange: (keys) => setSelectedKeys(keys),
                  }
            }
            rowClassName={(record, index) => {
              if (record?.key === selectedPage?.page?.pageId) return "row-selected";
              return "";
            }}
          />
        </Col>
      </Row>

      <AddToGroupModal
        open={groupModalOpen}
        users={selectedUsers}
        usersById={usersById}
        serviceId={projects?.userServiceId}
        connectionId={encrypted_token?.connectionId}
        socket={socket}
        onClose={() => setGroupModalOpen(false)}
        onAdded={() => setSelectedKeys([])}
      />
    </React.Fragment>
  );
};

export default StudentsModal;
