// A hung create would otherwise leave the dispatcher spinning forever. On
// timeout the request may still land server-side, so callers keep the same
// clientRequestId for the retry (the ride service dedupes on it).
const CREATE_RIDE_TIMEOUT_MS = 30000;

export const createRideRequest = async (payload: { data: any }) => {
  let timer: any;
  const timeout = new Promise((resolve) => {
    timer = setTimeout(
      () =>
        resolve({
          status: false,
          message: 'timeout',
          data: { details: 'Request timed out', code: 'TIMEOUT' },
        }),
      CREATE_RIDE_TIMEOUT_MS
    );
  });
  const request = getRideApiV1()
    .postJson(`/${process.env.REACT_APP_ECO_SYSTEM}/connection/wc-plus/service/wc-plus/createRideRequest`, payload.data)
    .then((response) => parseApiResponse(response))
    .catch((error) => {
      console.log('error', error);
      return error?.response?.data?.message || error?.message;
    });
  return Promise.race([request, timeout]).then((response) => {
    clearTimeout(timer);
    return response;
  });
};

