import { FC, useState, useRef } from "react";
import { useHistory, useLocation } from "react-router-dom";
import { Button, Checkbox, Form } from "antd";
import { ShareAltOutlined } from "@ant-design/icons";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { generateUUID } from "utils/appUtil";
import useSocketActions from "../../../../hooks/socketActions";
import { DEFAULT_FORM_VALUES } from "./utils";
import { DispatchPanelContext } from "./context";
import { useIsMobile } from "./hooks/useIsMobile";
import { useRideSocketActions } from "./hooks/useRideSocketActions";
import { useDispatchForm } from "./hooks/useDispatchForm";
import { useDispatchSubmit } from "./hooks/useDispatchSubmit";
import { useDispatchSubscriptions } from "./hooks/useDispatchSubscriptions";
import PassengerSection from "./components/PassengerSection";
import AccountSection from "./components/AccountSection";
import LocationSection from "./components/LocationSection";
import EstimationSummary from "./components/EstimationSummary";
import VehicleTypeSection from "./components/VehicleTypeSection";
import DispatchScheduleSection from "./components/DispatchScheduleSection";
import DispatcherRideSection from "./components/DispatcherRideSection";
import WebBookerFareSection from "./components/WebBookerFareSection";
import PaymentProviderSection from "./components/PaymentProviderSection";
import CouponSection from "./components/CouponSection";
import DriversList from "./components/DriversList";
import DispatchActions from "./components/DispatchActions";
import VerifyCodeModal from "./components/VerifyCodeModal";
import OverlayModals from "./components/OverlayModals";
import SubmitAlerts from "./components/SubmitAlerts";
import FormSection from "./components/FormSection";
import "./DispatchPanel.scss";

const DispatchPanel: FC<{
  socket: ISocket;
  params: any;
  fullScreen?: boolean;
  scale?: boolean;
  componentUuids?: string;
}> = ({ socket, params, fullScreen, scale, componentUuids }) => {
  const [nine11Form] = Form.useForm();
  const [error, setError] = useState<string>("");
  const { screens, setScreens } = params;
  const { search } = useLocation();
  const history = useHistory();
  const { projects, accounts } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const {
    selectedResponders,
    submitted,
    page,
    encrypted_token,
    selectedPickup,
    standLocations,
    selectedPage,
    userInfo,
  } = useSelector((state: RootState) => state.auth);
  const [searching, setSearching] = useState<boolean>(false);
  const [ridePageId, setPageId] = useState<any>(undefined);
  const [ridePageStatus, setPageStatus] = useState<any>(undefined);
  const [verifyModal, setVerifyModal] = useState<any>(undefined);
  const { getUserRequestPayload } = useSocketActions();
  const filterUserRequestId = useRef(generateUUID());
  const [estimation, setEstimation] = useState<any>();
  const [estimatedFare, setEstimatedFare] = useState<any>();
  const [dispatchType, setDispatchType] = useState<any>();
  const [rideType, setRideType] = useState<any>();
  const [payType, setPayType] = useState<any>("meter");
  const [vehicleType, setVehicleType] = useState<any>();
  const [isConfirmationModalVisible, setIsConfirmationModalVisible] =
    useState<any>(undefined);
  const [isPhoneFilterModalVisible, setIsPhoneFilterModalVisible] =
    useState<any>(undefined);
  const [isShareModalVisible, setIsShareModalVisible] =
    useState<boolean>(false);
  const [isAddCardModalVisible, setIsAddCardModalVisible] = useState<any>();
  const [isCancelModalVisible, setIsCancelModalVisible] =
    useState<boolean>(false);
  const submitPageId = useRef(true);
  const locationType = useRef(undefined);
  const [coupons, setCoupons] = useState<any>();
  const [webBooker, setWebBooker] = useState<boolean>(false);
  const locationTypeFare = useRef<any>({
    pickup: undefined,
    dropoff: undefined,
  });
  const [blocked, setBlocked] = useState<boolean>(false);
  const [couponResponse, setCouponResponse] = useState<any>();
  const [payWith, setPayWith] = useState<any>();
  // Web booker: OTP the passenger verified before their card on file is
  // loaded. Reused as the booking OTP at submit.
  const [verifiedOtp, setVerifiedOtp] = useState<string>();
  const [cardOtpError, setCardOtpError] = useState<string>();
  const cardOtpPendingRef = useRef<string>();
  const [loaded, setLoaded] = useState<boolean>(false);
  // Fixed pickup (e.g. a hotel) from a scanned location QR. The ref is for
  // socket callbacks registered once, which would otherwise see a stale value.
  const [pickupReference, setPickupReference] = useState<any>();
  const pickupReferenceRef = useRef<any>();
  const isMobile = useIsMobile();
  const fareType = Form.useWatch("fareType", nine11Form);
  // { id, fingerprint } of the current booking attempt (see useDispatchSubmit).
  const clientRequestRef = useRef<any>();
  // updatedAt of the ride loaded in the form; sent as expectedUpdatedAt.
  const loadedUpdatedAtRef = useRef<number>();
  // Mirror of ridePageId for long-lived socket callbacks.
  const ridePageIdRef = useRef<any>();
  ridePageIdRef.current = ridePageId;
  // Code + request id of the latest applyCoupon publish; older replies are
  // ignored.
  const couponRequestRef = useRef<any>();
  // Request id of the latest estimation publish; older replies are ignored.
  const estimationRequestIdRef = useRef<string>();
  // "Changed by someone else" notice for the loaded ride.
  const [rideNotice, setRideNotice] = useState<any>();
  // Persistent submit problem with optional Retry (timeouts, partial round
  // trips, Paystack resume failures).
  const [submitIssue, setSubmitIssue] = useState<any>();

  // The shared "bag" consumed by section components (via context) and by the
  // action/subscription hooks below. Hook return values are folded back in so
  // later hooks and components can reach earlier hooks' actions.
  const d: any = {
    socket,
    form: nine11Form,
    fullScreen,
    scale,
    isMobile,
    screens,
    setScreens,
    history,
    search,
    dispatch,
    getUserRequestPayload,
    filterUserRequestId,
    submitPageId,
    locationType,
    locationTypeFare,
    // redux
    projects,
    accounts,
    selectedResponders,
    submitted,
    page,
    encrypted_token,
    selectedPickup,
    standLocations,
    selectedPage,
    userInfo,
    // local state + setters
    error,
    setError,
    searching,
    setSearching,
    ridePageId,
    setPageId,
    ridePageStatus,
    setPageStatus,
    verifyModal,
    setVerifyModal,
    estimation,
    setEstimation,
    estimatedFare,
    setEstimatedFare,
    dispatchType,
    setDispatchType,
    rideType,
    setRideType,
    payType,
    setPayType,
    vehicleType,
    setVehicleType,
    isConfirmationModalVisible,
    setIsConfirmationModalVisible,
    isPhoneFilterModalVisible,
    setIsPhoneFilterModalVisible,
    isShareModalVisible,
    setIsShareModalVisible,
    isAddCardModalVisible,
    setIsAddCardModalVisible,
    isCancelModalVisible,
    setIsCancelModalVisible,
    coupons,
    setCoupons,
    webBooker,
    setWebBooker,
    blocked,
    setBlocked,
    couponResponse,
    setCouponResponse,
    payWith,
    setPayWith,
    verifiedOtp,
    setVerifiedOtp,
    cardOtpError,
    setCardOtpError,
    cardOtpPendingRef,
    loaded,
    setLoaded,
    pickupReference,
    setPickupReference,
    pickupReferenceRef,
    fareType,
    clientRequestRef,
    loadedUpdatedAtRef,
    ridePageIdRef,
    couponRequestRef,
    estimationRequestIdRef,
    rideNotice,
    setRideNotice,
    submitIssue,
    setSubmitIssue,
  };

  Object.assign(d, useRideSocketActions(d));
  Object.assign(d, useDispatchForm(d));
  Object.assign(d, useDispatchSubmit(d));
  useDispatchSubscriptions(d);

  return (
    <DispatchPanelContext.Provider value={d}>
      <div
        className={`main-column ride-dispatch-panel ${isMobile ? "" : "mr-4"}`}
        style={scale ? { height: "auto" } : {}}
      >
        <div className="main-content">
          <Form
            className="auth-form ride-form"
            name="register-form"
            initialValues={DEFAULT_FORM_VALUES}
            id="register-form"
            layout="vertical"
            form={nine11Form}
            onFinish={d.onSubmitHandler}
            requiredMark={false}
            onValuesChange={(value, allValues) => {
              localStorage.setItem("form", JSON.stringify(allValues));
            }}
            style={!fullScreen ? { height: "48vh" } : {}}
          >
            <div className="main-header ride-panel-head">
              <div className="d-flex align-items-center ride-panel-head__title">
                <img
                  src="/images/logo-icon.svg"
                  alt="Beam Logo"
                  className="ride-panel-head__logo"
                  style={{ height: 32, marginRight: 12 }}
                />
                <h3 className="ml-3">
                  {ridePageId && page
                    ? `${page?.persistent?.static?.metatdata?.title}`
                    : "Ride booking"}
                </h3>
              </div>
              <div className="d-flex">
                {encrypted_token && !webBooker && (
                  <Button
                    type="text"
                    className="ride-icon-btn"
                    aria-label="Share dispatch link"
                    title="Share dispatch link"
                    icon={<ShareAltOutlined />}
                    onClick={() => {
                      setIsShareModalVisible(true);
                    }}
                  />
                )}
              </div>
            </div>

            <SubmitAlerts />

            <div
              className="main-cards ride-panel-body"
              style={{
                maxHeight: scale ? "calc(100vh)" : "calc(100vh - 200px)",
              }}
            >
              <FormSection title="Passenger">
                <PassengerSection />
                <AccountSection />
                <p className="ride-hint mt-2 mb-0">Max. 3 passengers</p>
              </FormSection>

              <FormSection title="Trip">
                <LocationSection />
                <EstimationSummary />
              </FormSection>

              <FormSection title="Schedule">
                <DispatchScheduleSection />
              </FormSection>

              <FormSection title="Vehicle & fare">
                <VehicleTypeSection />
                <DispatcherRideSection />
                <WebBookerFareSection />
              </FormSection>

              <FormSection title="Payment & coupon">
                <PaymentProviderSection />
                <CouponSection />
              </FormSection>

              <FormSection title="Drivers">
                <DriversList />
              </FormSection>

              {encrypted_token && !webBooker && (
                <FormSection title="Options">
                  <Form.Item
                    name="sharePassengerLink"
                    valuePropName="checked"
                  >
                    <Checkbox>
                      Do you want to share link with passenger?
                    </Checkbox>
                  </Form.Item>
                </FormSection>
              )}
            </div>

            <div className="ride-panel-foot">
              {error && (
                <Form.Item>
                  <p className="error" role="alert">
                    {error}
                  </p>
                </Form.Item>
              )}

              <DispatchActions />
            </div>
          </Form>
        </div>

        <OverlayModals />
        <VerifyCodeModal />
      </div>
    </DispatchPanelContext.Provider>
  );
};

export default DispatchPanel;
