import "react-phone-number-input/style.css";
import PhoneInput, { formatPhoneNumberIntl } from "react-phone-number-input";
import { throttle, debounce } from "throttle-debounce";
import "../Dashboard/Dashboard.scss";
import "../Dashboard/DashboardModal/RidesTable.scss";
import "./ShareDispatchUrlModal.scss";
import "./RideFilterModal.scss";
import {
  RequestedAtCell,
  StatusTag,
} from "../Dashboard/DashboardModal/components/RideCells";

const { Panel } = Collapse;

const { Option } = Select;
let typingTimeout;

const RideFilterModal: FC<{
  socket: ISocket;
  params?: any;
  filter?: boolean;
  selected?: string;
  componentUuid?: string;
  onClose?: any;
  phone?: string;
}> = ({ socket, params, filter, selected, componentUuid, onClose, phone }) => {
  const { search } = useLocation();
  const {
    userRequests,
    projects,
    pageAggregateBds,
    selectedPage,
    encrypted_token,
    searchByPhone,
  } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [isModalVisible, setIsModalVisible] = useState<boolean>(true);
  const [projectFilter, setProjectFilter] = useState<string>("project");
  const [timeFilter, setTimeFilter] = useState<string>("state");
  const [projectFilterLoading, setProjectFilterLoading] =
    useState<boolean>(false);
  const [projectFilterValue, setProjectFilterValue] = useState<any>(undefined);
  const [timeFilterValue, setTimeFilterValue] = useState<any>(undefined);
  const [statusFilterLoading, setStatusFilterLoading] =
    useState<boolean>(false);
  const [timeFilterLoading, setTimeFilterLoading] = useState<boolean>(false);
  const [projectFilterOptions, setProjectFilterOptions] = useState<any[]>([]);
  const [timeFilterOptions, setTimeFilterOptions] = useState<any[]>([]);
  const [pages, setPages] = useState<any>([]);
  const [pageLocations, setPageLocations] = useState<any>([]);
  const filterUserRequestId = useRef(generateUUID());
  const pageUserRequestId = useRef(generateUUID());
  const startDate = useRef<any>(undefined);
  const endDate = useRef<any>(undefined);
  const pageOffset = useRef<any>(0);
  const selectedColor = useRef<any>(undefined);
  const [pageUpdated, setPageUpdated] = useState<any>();
  const [statusCount, setStatusCount] = useState<any>({
    all: 0,
    live: 0,
    amber: 0,
    purple: 0,
    red: 0,
    green: 0,
    blue: 0,
    grey: 0,
    black: 0,
    brown: 0,
    aqua: 0,
  });
  const [redrawCount, setRedrawCount] = useState<number>(0);
  const [tableDataSource, setTableDataSource] = useState<any>([]);
  const tableDataSourceRef = useRef(undefined);
  const usersRef = useRef(undefined);
  const [tableColumns, setTableColumns] = useState<any>([]);
  const [showTableFilterModal, setShowTableFilterModal] =
    useState<boolean>(false);
  const [tableHideList, setTableHideList] = useState<any>([]);
  const [statusSelected, setStatusSelected] = useState<any>(undefined);
  const { getUserRequestPayload } = useSocketActions();
  const adminRoles = useRef(undefined);
  const pagePaths = useRef({
    project: undefined,
    user: undefined,
    status: undefined,
    area: undefined,
    time: undefined,
    phone: undefined,
  });
  const pageThrottleRef = useRef({});
  const encryptedTokenRef = useRef<any>();

  const loadPaths = useRef<any>([]);

  // const getPageStatusthrottleFunc = throttle(
  //   2000,
  //   (num) => {
  //     console.log('throttle');
  //     getPageStatus();
  //   },
  //   { noLeading: false, noTrailing: false }
  // );

  const setPhonePagePaths = (value) => {
    pagePaths.current.phone = value;

    // ? `exists(@phone) && contains(@phone, '${value}')`
    // : undefined;

    setStatusFilterLoading(true);
    pagePaths.current.status = undefined;
    selectedColor.current = "lime";
    setStatusSelected("lime");
    searchPage();
  };



  const searchPage = (offset = 0) => {
    const expressions = [];
    const load = {};
    if (loadPaths.current) {
      loadPaths.current.map((x) => {
        load[x.key] = x.value;
      });
    }
    pageOffset.current = offset;
    const getPagesRequest = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:page:ride`,
          searchQuery: `@pageMembers:{'${
            encrypted_token?.userId
          }'}(-@rideType:{hail})@pageType:{event}@passengerPhoneNumber:{${formatForRedis(
            pagePaths.current.phone
          )}}`,
          searchOptions: "VERBATIM TIMEOUT 10000",
        },
        load: {
          profile: "$..profile",
          dashboard: "$..dashboard",
          ride: "$.persistent.static.ride",
          dynamic: "$.persistent.dynamic.ride",
          rideType: "$..profile.type",
          pageId: "$.objectId",
          createdAt: "$.persistent.static.metadata.createdAt",
          updatedAt:
            "$.nonpersistent.dynamic.metadata.lastSent.members.updatedAt",
          status: "$.nonpersistent.static.live.status.name",
          phone: "$..dashboard.passengerPhoneNumber",
          ...load,
        },
      },
      filter: {
        expression: expressions.join("&&"),
      },
      sortBy: {
        properties: [
          selected === "advance"
            ? {
                field: "@createdAt",
                order: "ASC",
              }
            : {
                field: "@updatedAt",
                order: "DESC",
              },
        ],
        max: 1000,
      },
      result: pagePaths.current.phone
        ? {
            pagination: {
              offset: offset,
              limit: 50,
            },
          }
        : {},
    };
    dispatch(
      GET_AGGREGATE({
        requestData: getPagesRequest,
        callback: (response) => {
          console.log("resppnse", response);
          setPages(response);
          pageOffset.current = pageOffset.current + 30;
          let sourceData = offset > 0 ? [...tableDataSource] : [];
          // The phone is the search key, so it isn't repeated per row.
          let columns: any = [
            {
              title: "Status",
              key: "pageStatus",
              dataIndex: "pageStatus",
              width: 120,
              render: (status: string) => <StatusTag status={status} />,
            },
            {
              title: "Requested",
              key: "requestedAt",
              dataIndex: "requestedAt",
              width: 130,
              render: (text: string, record: any) => (
                <RequestedAtCell text={text} record={record} />
              ),
            },
            {
              title: "Trip",
              key: "trip",
              render: (_: any, record: any) => (
                <div className="ride-search__trip">
                  <span className="ride-search__stop">
                    <i className="is-pickup" aria-hidden="true" />
                    <span title={record.address}>{record.address || "—"}</span>
                  </span>
                  <span className="ride-search__stop">
                    <i className="is-dropoff" aria-hidden="true" />
                    <span title={record.dropoffAddress}>
                      {record.dropoffAddress || "—"}
                    </span>
                  </span>
                </div>
              ),
            },
            {
              title: "Passenger",
              key: "passengerName",
              dataIndex: "passengerName",
              width: 150,
              render: (name: string) => name || <span className="ride-search__muted">—</span>,
            },
            {
              title: "Driver",
              key: "driverName",
              width: 160,
              render: (_: any, record: any) =>
                record.driverName ? (
                  <div className="ride-search__stack">
                    <span>{record.driverName}</span>
                    {record.vehicleName && (
                      <span className="ride-search__muted">{record.vehicleName}</span>
                    )}
                  </div>
                ) : (
                  <span className="ride-search__muted">—</span>
                ),
            },
            {
              title: "Fare",
              key: "fixedFare",
              dataIndex: "fixedFare",
              width: 90,
              align: "right",
              render: (fare: string) => fare || <span className="ride-search__muted">—</span>,
            },
          ];
          response?.map((x, i) => {
            // const profile = x?.profile;
            const profile = {
              ...(x?.profile || {}),
              ...(x?.dashboard || {}),
              ...(x?.ride || {}),
              ...(x?.dynamic || {}),
            };

            const source: any = {};
            Object.keys(profile).map((p) => {
              if (typeof profile[p] === "string") {
                source[p] = profile[p];
              }
            });
            sourceData.push({
              key: x.pageId,
              pageStatus: x.status,
              name: "",
              action: {
                pageId: x.pageId,
                page: {
                  ...x,
                  profile,
                },
                summary: source.summary,
                cudbServiceId: projects?.userServiceId,
              },
              ...source,
              address:
                source?.address && source?.adress !== ""
                  ? source?.address
                  : profile?.pickupLocation?.attributes?.address,
              dropoffAddress:
                source?.dropoffAddress && source?.dropoffAddress !== ""
                  ? source?.dropoffAddress
                  : profile?.dropoffLocation?.attributes?.address,
              _createdAt: Number(x.createdAt) || undefined,
              requestedAt: x.createdAt
                ? new Date(Number(x.createdAt)).toLocaleTimeString([], {
                    hour: "2-digit",
                    minute: "2-digit",
                  })
                : "",
            });
          });
          console.log("source data", sourceData);
          sourceData.map((x) => {
            const profile = {
              ...(x?.profile || {}),
              ...(x?.dashboard || {}),
              ...(x?.ride || {}),
              ...(x?.dynamic || {}),
            };
            Object.keys(profile || {}).map((p) => {
              if (
                columns.findIndex((c) => {
                  return c.key === p;
                }) === -1 &&
                typeof profile[p] === "string"
              ) {
              }
            });
          });

          columns.push({
            title: "",
            key: "action",
            dataIndex: "action",
            width: 150,
            fixed: "right",
            render: (action: any) => (
              <div className="ride-search__actions">
                <Button
                  size="small"
                  className="ride-search__rebook"
                  icon={<CopyOutlined />}
                  onClick={() => {
                    dispatch({
                      type: "SET_SELECTED_PAGE",
                      payload: { page: action?.page, ignorePage: true },
                    });
                    handleOk();
                  }}
                >
                  Rebook
                </Button>
                <Tooltip title="Open ride chat">
                  <Button
                    size="small"
                    aria-label="Open ride chat"
                    icon={<MessageOutlined />}
                    onClick={() => {
                      popupCenter(
                        `${process.env.REACT_APP_WEB}/page/${action?.pageId}`,
                        "BeamLive",
                        window.innerWidth * 0.7,
                        window.innerHeight * 0.9
                      );
                    }}
                  />
                </Tooltip>
              </div>
            ),
          });
          setTableColumns(columns);

          console.log("set source date", sourceData);
          setTableDataSource(sourceData);
          tableDataSourceRef.current = sourceData;
          setPageLocations(
            response?.map((x) => {
              return {
                lat: x?.persistent?.static?.live?.location?.coordinates?.lat,
                lng: x?.persistent?.static?.live?.location?.coordinates.long,
                title: x?.persistent?.static?.metadata?.title,
              };
            })
          );
          setStatusFilterLoading(false);
          setProjectFilterLoading(false);
          setTimeFilterLoading(false);
        },
      })
    );
    // getPageStatus();
    // getPageStatusthrottleFunc();
  };

  useEffect(() => {
    if (encrypted_token) {
      // const query = new URLSearchParams(search);
      // const userId = query.get("userId");
      // const connectionId = query.get("connectionId");
      encryptedTokenRef.current = encrypted_token;

      setProjectFilterLoading(true);
      // searchPage();

      setPhonePagePaths(phone);

      // setTableHideList(JSON.parse(localStorage.getItem("tableHideList")) || []);
    }
  }, [encrypted_token]);

  useEffect(() => {
    if (projects) {
      // const query = new URLSearchParams(search);
      // const connectionId = query.get("connectionId");
      const options = [];
      projects?.projects?.map((project) => {
        options.push({ label: project.name, value: project.id });
      });
      setProjectFilterOptions(options);
    }
  }, [projects]);

  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  const handleOk = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  return (
    <React.Fragment>
      <Modal
        title={null}
        visible={isModalVisible}
        onCancel={handleCancel}
        width={1100}
        className="ride-modal ride-search-modal"
        footer={null}
        destroyOnClose={true}
      >
        <h2 className="ride-modal__title">Previous rides</h2>
        <p className="ride-modal__desc">
          {phone
            ? `Rides booked for ${formatPhoneNumberIntl(phone) || phone}`
            : "Rides for this passenger"}
          {tableDataSource?.length > 0 &&
            ` · ${tableDataSource.length} found, newest first`}
          . Rebook copies a ride into the booking form.
        </p>
        <Table
          size="small"
          dataSource={tableDataSource}
          columns={tableColumns}
          loading={projectFilterLoading}
          className="ride-search__table"
          scroll={{ x: 900, y: 460 }}
          pagination={{ pageSize: 10, size: "small", showSizeChanger: false, hideOnSinglePage: true }}
          locale={{ emptyText: "No rides found for this phone number" }}
          rowClassName={(record) =>
            record?.key === selectedPage?.page?.pageId ? "is-selected" : ""
          }
        />
      </Modal>
    </React.Fragment>
  );
};

export default RideFilterModal;
