import React from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { QRCodeSVG } from "qrcode.react";
import { CouponInfo } from "../types";
import { conditionLines, discountHeadline } from "../couponRules";

// One canvas drawing serves the editor preview, PNG download, printing and the
// image emailed to each recipient, so they always match.

export const CARD_WIDTH = 600;
export const CARD_HEIGHT = 900;
export const DEFAULT_ACCENT = "#463bbd";

const FONT = '"Nunito-Regular", "Helvetica Neue", Arial, sans-serif';
const FONT_BOLD = '"Nunito-Bold", "Helvetica Neue", Arial, sans-serif';

const loadImage = (src: string, crossOrigin?: string) =>
  new Promise<HTMLImageElement | null>((resolve) => {
    const img = new Image();
    if (crossOrigin) img.crossOrigin = crossOrigin;
    const timer = setTimeout(() => resolve(null), 6000);
    img.onload = () => {
      clearTimeout(timer);
      resolve(img);
    };
    img.onerror = () => {
      clearTimeout(timer);
      resolve(null);
    };
    img.src = src;
  });

// A logo served without CORS headers would taint the canvas and break
// toDataURL, so it is only drawn when it loads with crossOrigin; otherwise the
// brand name is drawn instead.
const logoCache = new Map<string, Promise<HTMLImageElement | null>>();
const loadLogo = (url?: string) => {
  if (!url) return Promise.resolve(null);
  if (!logoCache.has(url)) logoCache.set(url, loadImage(url, "anonymous"));
  return logoCache.get(url)!;
};

const qrImage = (value: string, size: number) => {
  let svg = renderToStaticMarkup(<QRCodeSVG value={value} size={size} level="M" marginSize={0} />);
  if (!svg.includes("xmlns=")) svg = svg.replace("<svg", '<svg xmlns="http://www.w3.org/2000/svg"');
  return loadImage(`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`);
};

const wrapLines = (ctx: CanvasRenderingContext2D, text: string, maxWidth: number, maxLines: number) => {
  const lines: string[] = [];
  for (const paragraph of `${text || ""}`.split(/\n/)) {
    let line = "";
    for (const word of paragraph.split(/\s+/).filter(Boolean)) {
      const next = line ? `${line} ${word}` : word;
      if (ctx.measureText(next).width > maxWidth && line) {
        lines.push(line);
        line = word;
      } else {
        line = next;
      }
    }
    if (line) lines.push(line);
  }
  if (lines.length > maxLines) {
    const kept = lines.slice(0, maxLines);
    let last = kept[maxLines - 1];
    while (last && ctx.measureText(`${last}…`).width > maxWidth) last = last.slice(0, -1);
    kept[maxLines - 1] = `${last}…`;
    return kept;
  }
  return lines;
};

const roundRect = (ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) => {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
};

export interface CardOptions {
  /** Encoded in the QR. */
  url: string;
  /** Printed under the code, e.g. the recipient's name. */
  caption?: string;
  scale?: number;
}

/** Draws the coupon card and returns it as a canvas. */
export const drawCouponCard = async (info: CouponInfo, { url, caption, scale = 1 }: CardOptions) => {
  const card = info.card || {};
  const accent = card.accentColor || DEFAULT_ACCENT;
  const canvas = document.createElement("canvas");
  canvas.width = CARD_WIDTH * scale;
  canvas.height = CARD_HEIGHT * scale;
  const ctx = canvas.getContext("2d")!;
  ctx.scale(scale, scale);
  const cx = CARD_WIDTH / 2;
  const pad = 40;
  const textWidth = CARD_WIDTH - pad * 2;

  const [logo, qr] = await Promise.all([loadLogo(card.logoUrl), qrImage(url, 520)]);

  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, CARD_WIDTH, CARD_HEIGHT);

  // Header band: logo, or the brand name when there is no usable logo.
  const bandHeight = 150;
  ctx.fillStyle = accent;
  ctx.fillRect(0, 0, CARD_WIDTH, bandHeight);
  if (logo) {
    const boxW = 300;
    const boxH = 90;
    const ratio = Math.min(boxW / logo.width, boxH / logo.height);
    const w = logo.width * ratio;
    const h = logo.height * ratio;
    ctx.fillStyle = "#ffffff";
    roundRect(ctx, cx - w / 2 - 14, bandHeight / 2 - h / 2 - 10, w + 28, h + 20, 12);
    ctx.fill();
    ctx.drawImage(logo, cx - w / 2, bandHeight / 2 - h / 2, w, h);
  } else {
    ctx.fillStyle = "#ffffff";
    ctx.textAlign = "center";
    ctx.font = `28px ${FONT_BOLD}`;
    ctx.fillText(info.brandName || "Coupon", cx, bandHeight / 2 + 10, textWidth);
  }

  let y = bandHeight + 52;
  ctx.textAlign = "center";
  ctx.fillStyle = "#1d2433";
  ctx.font = `28px ${FONT_BOLD}`;
  for (const line of wrapLines(ctx, card.headline || info.title || "", textWidth, 2)) {
    ctx.fillText(line, cx, y);
    y += 36;
  }

  ctx.fillStyle = accent;
  ctx.font = `60px ${FONT_BOLD}`;
  y += 34;
  ctx.fillText(discountHeadline(info), cx, y, textWidth);
  y += 22;

  const body = card.text ?? info.description ?? "";
  if (body) {
    ctx.fillStyle = "#5a6478";
    ctx.font = `18px ${FONT}`;
    y += 14;
    for (const line of wrapLines(ctx, body, textWidth, 3)) {
      y += 24;
      ctx.fillText(line, cx, y);
    }
  }

  // QR block, anchored from the bottom so long text never pushes it off.
  const qrSize = 250;
  const qrTop = Math.max(y + 24, CARD_HEIGHT - 190 - qrSize);
  ctx.fillStyle = "#ffffff";
  ctx.strokeStyle = "#e4e7eb";
  ctx.lineWidth = 2;
  roundRect(ctx, cx - qrSize / 2 - 16, qrTop - 16, qrSize + 32, qrSize + 32, 16);
  ctx.fill();
  ctx.stroke();
  if (qr) ctx.drawImage(qr, cx - qrSize / 2, qrTop, qrSize, qrSize);

  let fy = qrTop + qrSize + 46;
  if (caption) {
    ctx.fillStyle = "#1d2433";
    ctx.font = `16px ${FONT_BOLD}`;
    ctx.fillText(caption, cx, fy, textWidth);
    fy += 24;
  }
  ctx.fillStyle = "#5a6478";
  ctx.font = `14px ${FONT}`;
  const conditions = conditionLines(info).join(" · ");
  for (const line of wrapLines(ctx, conditions, textWidth, 2)) {
    ctx.fillText(line, cx, fy);
    fy += 20;
  }
  if (info.code) {
    ctx.font = `14px ${FONT_BOLD}`;
    ctx.fillText(`Code: ${info.code}`, cx, fy, textWidth);
    fy += 20;
  }

  // Footer strip.
  ctx.fillStyle = "#f5f7fa";
  ctx.fillRect(0, CARD_HEIGHT - 44, CARD_WIDTH, 44);
  ctx.fillStyle = "#7b8794";
  ctx.font = `13px ${FONT}`;
  ctx.fillText(card.footer || "Show this QR code at checkout", cx, CARD_HEIGHT - 17, textWidth);

  return canvas;
};

export const renderCouponCardPng = async (info: CouponInfo, options: CardOptions) =>
  (await drawCouponCard(info, options)).toDataURL("image/png");

export const downloadDataUrl = (dataUrl: string, filename: string) => {
  const a = document.createElement("a");
  a.href = dataUrl;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
};

/** Opens a print window with one card per page. */
export const printCards = (dataUrls: string[], title = "Coupons") => {
  const win = window.open("", "_blank");
  if (!win) return false;
  const pages = dataUrls
    .map((src) => `<div class="page"><img src="${src}" alt="Coupon" /></div>`)
    .join("");
  win.document.write(`<!doctype html><html><head><title>${title.replace(/</g, "&lt;")}</title>
    <style>
      /* No page margin: browsers print their date / title / URL header and footer there. */
      @page { margin: 0; }
      body { margin: 0; }
      .page { padding: 12mm; box-sizing: border-box; }
      .page { display: flex; justify-content: center; align-items: flex-start; page-break-after: always; }
      .page:last-child { page-break-after: auto; }
      img { width: 90mm; height: auto; border: 1px dashed #c5d2e9; }
    </style></head><body>${pages}</body></html>`);
  win.document.close();
  const images = Array.from(win.document.images);
  Promise.all(images.map((img) => (img.complete ? Promise.resolve() : new Promise((r) => (img.onload = r))))).then(
    () => {
      win.focus();
      win.print();
    }
  );
  return true;
};

export const slug = (text: string) =>
  `${text || "coupon"}`
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40) || "coupon";
