import React, { useMemo, useState } from "react";
import { Alert, Button, Input, Segmented, Skeleton, Tooltip } from "antd";
import { CheckOutlined, SearchOutlined, UserAddOutlined } from "@ant-design/icons";
import moment from "moment";
import { EmptyState, matchesSearch, Pill } from "../ui";
import { SHIFT_TYPES } from "../shiftTypes";
import {
  AVAILABILITY_META,
  DayJob,
  DriverEvaluation,
  DriverRecord,
  formatMinutes,
  isRecommended,
  JOB_BUFFER_MIN,
  rankDrivers,
  toMinutes,
} from "./availability";
import DayTimeline from "./DayTimeline";
import { useDriverDay } from "./useDriverDay";
import "./driver-availability.scss";

type Filter = "recommended" | "scheduled" | "all";
const PAGE_SIZE = 12;

interface Props {
  day?: number;
  pickupTime?: string;
  /** The job being assigned (excluded from workload). */
  pageId?: string;
  jobs?: DayJob[];
  primaryId?: string;
  secondaryIds?: string[];
  onAssignPrimary: (driver: DriverRecord) => void;
  onAddSecondary?: (driver: DriverRecord) => void;
  title?: React.ReactNode;
  /** Pinned to the top and highlighted, e.g. the lane a job was dropped on. */
  highlightId?: string;
}

const initials = (name: string) =>
  name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((p) => p[0]?.toUpperCase())
    .join("");

const Legend = () => (
  <div className="mx-driver-picker__legend">
    {SHIFT_TYPES.map((t) => (
      <span key={t.value}>
        <i style={{ background: t.color }} />
        {t.label}
      </span>
    ))}
    <span>
      <i className="mx-driver-picker__legend-job" />
      Job
    </span>
    <span>
      <i className="mx-driver-picker__legend-pickup" />
      This pickup
    </span>
  </div>
);

const DriverRow = ({
  evaluation,
  pickupMin,
  isPrimary,
  isSecondary,
  highlighted,
  onAssignPrimary,
  onAddSecondary,
}: {
  evaluation: DriverEvaluation;
  pickupMin?: number;
  isPrimary: boolean;
  isSecondary: boolean;
  highlighted?: boolean;
  onAssignPrimary: () => void;
  onAddSecondary?: () => void;
}) => {
  const { driver, availability, jobs, conflicts, reasons, slots } = evaluation;
  const meta = AVAILABILITY_META[availability];
  return (
    <div
      className={`mx-driver-row mx-driver-row--${meta.tone} ${
        isPrimary ? "mx-driver-row--selected" : ""
      } ${highlighted ? "mx-driver-row--highlighted" : ""}`}
    >
      <div className={`mx-driver-row__avatar mx-driver-row__avatar--${meta.tone}`}>
        {initials(driver.name) || "?"}
      </div>
      <div className="mx-driver-row__main">
        <div className="mx-driver-row__title">
          <span className="mx-driver-row__name">{driver.name}</span>
          <Pill tone={meta.tone}>{meta.label}</Pill>
          <Pill tone="gray" plain>
            {jobs.length} {jobs.length === 1 ? "job" : "jobs"}
          </Pill>
          {conflicts.length > 0 && <Pill tone="red">Clash</Pill>}
        </div>
        {highlighted && !isPrimary && (
          <div className="mx-driver-row__callout">Dropped on this driver — click Assign to confirm</div>
        )}
        {reasons.length > 0 && <div className="mx-driver-row__reasons">{reasons.join(" · ")}</div>}
        <DayTimeline slots={slots} jobs={jobs} pickupMin={pickupMin} />
      </div>
      <div className="mx-driver-row__actions">
        {isPrimary ? (
          <Button className="mx-btn-secondary" icon={<CheckOutlined />} disabled>
            Assigned
          </Button>
        ) : (
          <Button className="mx-btn-primary" onClick={onAssignPrimary}>
            Assign
          </Button>
        )}
        {onAddSecondary && !isPrimary && (
          <Tooltip title={isSecondary ? "Already a second driver" : "Add as second driver"}>
            <Button
              type="link"
              size="small"
              icon={<UserAddOutlined />}
              disabled={isSecondary}
              onClick={onAddSecondary}
            >
              {isSecondary ? "Second" : "+ Second"}
            </Button>
          </Tooltip>
        )}
      </div>
    </div>
  );
};

/**
 * Ranks drivers for a job using the shift roster, approved time off and the
 * jobs already on their plate that day, and lets the dispatcher assign in one
 * click.
 */
const DriverPicker = ({
  day,
  pickupTime,
  pageId,
  jobs: providedJobs,
  primaryId,
  secondaryIds = [],
  onAssignPrimary,
  onAddSecondary,
  title,
  highlightId,
}: Props) => {
  const { drivers, slotsByDriver, timeOffDriverIds, jobs, loading, ready } = useDriverDay({
    day,
    jobs: providedJobs,
  });
  const [filter, setFilter] = useState<Filter>("recommended");
  const [query, setQuery] = useState("");
  const [limit, setLimit] = useState(PAGE_SIZE);
  const pickupMin = toMinutes(pickupTime);

  const ranked = useMemo(
    () =>
      day === undefined
        ? []
        : rankDrivers(drivers, { slotsByDriver, timeOffDriverIds, jobs, day, pickupMin, pageId }),
    [drivers, slotsByDriver, timeOffDriverIds, jobs, day, pickupMin, pageId]
  );

  const counts = useMemo(
    () => ({
      recommended: ranked.filter(isRecommended).length,
      scheduled: ranked.filter((e) => e.slots.length > 0).length,
      all: ranked.length,
    }),
    [ranked]
  );

  const visible = ranked.filter((e) => {
    if (!matchesSearch(query, e.driver.name, e.driver.obj?.beamId)) return false;
    // The current assignee and a highlighted driver always stay visible.
    if (e.driver.id === primaryId || e.driver.id === highlightId) return true;
    if (filter === "recommended") return isRecommended(e);
    if (filter === "scheduled") return e.slots.length > 0;
    return true;
  });

  if (highlightId) {
    const index = visible.findIndex((e) => e.driver.id === highlightId);
    if (index > 0) visible.unshift(...visible.splice(index, 1));
  }

  const current = ranked.find((e) => e.driver.id === primaryId);
  const warning =
    current &&
    (current.availability === "time-off"
      ? `${current.driver.name} has approved time off on this day.`
      : current.conflicts.length > 0
      ? `${current.driver.name} already has ${current.conflicts
          .map((c) => `${c.label} at ${formatMinutes(c.pickupMin)}`)
          .join(", ")} — within ${JOB_BUFFER_MIN} minutes of this pickup.`
      : !["on-shift", "on-call", "available"].includes(current.availability)
      ? `${current.driver.name} isn't on shift${pickupMin !== undefined ? ` at ${pickupTime}` : ""}.`
      : undefined);

  if (day === undefined) {
    return (
      <div className="mx-driver-picker">
        <EmptyState
          title="Pick a pickup date first"
          description="Suggestions use that day's shift roster, time off and existing jobs."
        />
      </div>
    );
  }

  return (
    <div className="mx-driver-picker">
      <div className="mx-driver-picker__header">
        <div>
          <div className="mx-driver-picker__title">{title ?? "Suggested drivers"}</div>
          <div className="mx-driver-picker__subtitle">
            {moment(day).format("ddd, MMM D")}
            {pickupMin !== undefined ? ` · pickup ${pickupTime}` : " · no pickup time yet"}
          </div>
        </div>
        <Legend />
      </div>

      {warning && <Alert type="warning" showIcon message={warning} className="mb-2" />}

      <div className="mx-driver-picker__controls">
        <Segmented
          value={filter}
          onChange={(v) => {
            setFilter(v as Filter);
            setLimit(PAGE_SIZE);
          }}
          options={[
            { label: `Recommended (${counts.recommended})`, value: "recommended" },
            { label: `Scheduled (${counts.scheduled})`, value: "scheduled" },
            { label: `Everyone (${counts.all})`, value: "all" },
          ]}
        />
        <Input
          allowClear
          prefix={<SearchOutlined />}
          placeholder="Search drivers"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          className="mx-driver-picker__search"
        />
      </div>

      {!ready && loading ? (
        <Skeleton active avatar paragraph={{ rows: 2 }} />
      ) : visible.length === 0 ? (
        <EmptyState
          title={filter === "recommended" ? "No one is clearly free" : "No drivers match"}
          description={
            filter === "recommended"
              ? "Nobody on the roster covers this time without a clash. Check who is scheduled or view everyone."
              : undefined
          }
          action={
            filter !== "all" ? { label: "Show everyone", onClick: () => setFilter("all") } : undefined
          }
        />
      ) : (
        <div className="mx-driver-picker__list">
          {visible.slice(0, limit).map((evaluation) => (
            <DriverRow
              key={evaluation.driver.id}
              evaluation={evaluation}
              pickupMin={pickupMin}
              isPrimary={evaluation.driver.id === primaryId}
              isSecondary={secondaryIds.includes(evaluation.driver.id)}
              highlighted={evaluation.driver.id === highlightId}
              onAssignPrimary={() => onAssignPrimary(evaluation.driver)}
              onAddSecondary={onAddSecondary && (() => onAddSecondary(evaluation.driver))}
            />
          ))}
          {visible.length > limit && (
            <Button type="link" onClick={() => setLimit((l) => l + PAGE_SIZE)}>
              Show {Math.min(PAGE_SIZE, visible.length - limit)} more
            </Button>
          )}
        </div>
      )}
    </div>
  );
};

export default DriverPicker;
