import { useEffect, useState } from "react";
import { STORAGE_KEYS } from "../constants";
import { SortOrder } from "../types";

const load = (): SortOrder[] => {
  try {
    return JSON.parse(localStorage.getItem(STORAGE_KEYS.sortOrders) || "[]");
  } catch {
    return [];
  }
};

/** Multi-column sort, persisted across sessions. */
export const useSortOrders = () => {
  const [sortOrders, setSortOrders] = useState<SortOrder[]>(load);

  useEffect(() => {
    if (sortOrders.length > 0) {
      localStorage.setItem(STORAGE_KEYS.sortOrders, JSON.stringify(sortOrders));
    } else {
      localStorage.removeItem(STORAGE_KEYS.sortOrders);
    }
  }, [sortOrders]);

  return [sortOrders, setSortOrders] as const;
};
