import React, { FC, useEffect, useState } from "react";
import { Tooltip } from "antd";
import {
  CompressOutlined,
  ExpandOutlined,
  ExportOutlined,
  FormOutlined,
  LockOutlined,
} from "@ant-design/icons";

import { SectionDef } from "./data";
import { SignupTarget } from "./api/signup";

interface Props {
  section: SectionDef;
  /** The org's form for this section; absent when no role is bound to one. */
  signup?: SignupTarget;
}

/**
 * Recreational and Traveler: the CPC sign-up form in a branded frame, with the
 * rest of the journey alongside. These sections have no filters.
 */
const SignupSection: FC<Props> = ({ section, signup }) => (
  <div className="programs-signup programs-rise">
    <div className="programs-formstep">
      {signup ? (
        <FormFrame section={section} signup={signup} />
      ) : (
        <MissingForm section={section} />
      )}
      <Journey section={section} />
    </div>
  </div>
);

/**
 * No role in this organization carries a registration form for the section.
 * Saying so beats embedding another organization's form.
 */
const MissingForm: FC<{ section: SectionDef }> = ({ section }) => (
  <div className="programs-card programs-noform">
    <FormOutlined />
    <h3>{section.label} registration isn't set up yet</h3>
    <p>
      No role in this organization has a registration form bound to it. Create one in the form
      builder and assign it to the {section.label.toLowerCase()} role.
    </p>
  </div>
);

const FormFrame: FC<{ section: SectionDef; signup: SignupTarget }> = ({ section, signup }) => {
  const [loaded, setLoaded] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const { url: formUrl, embedUrl } = signup;

  // Esc leaves the expanded view (declared before the early listener effect).
  useEffect(() => {
    if (!expanded) return undefined;
    const onKey = (e: KeyboardEvent) => e.key === "Escape" && setExpanded(false);
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [expanded]);

  return (
    <div className={`programs-frame${expanded ? " is-expanded" : ""}`}>
      <div className="programs-frame__bar">
        <span className="programs-frame__icon">
          <FormOutlined />
        </span>
        <div className="programs-frame__heading">
          <strong>{section.label} registration</strong>
          <div className="programs-frame__chips">
            <span className="programs-frame__hint">Basic + extended bio</span>
          </div>
        </div>
        <div className="programs-frame__actions">
          <Tooltip title={expanded ? "Exit full screen (Esc)" : "Full screen"}>
            <button
              type="button"
              className="programs-icon-btn"
              aria-label={expanded ? "Exit full screen" : "Full screen"}
              onClick={() => setExpanded((v) => !v)}
            >
              {expanded ? <CompressOutlined /> : <ExpandOutlined />}
            </button>
          </Tooltip>
          <Tooltip title="Open in new tab">
            <a
              className="programs-icon-btn"
              href={formUrl}
              target="_blank"
              rel="noopener noreferrer"
              aria-label="Open in new tab"
            >
              <ExportOutlined />
            </a>
          </Tooltip>
        </div>
      </div>

      <div className="programs-frame__viewport">
        {!loaded && <FormSkeleton />}
        <iframe
          title={`${section.label} registration form`}
          src={embedUrl}
          className={`programs-frame__iframe${loaded ? " is-loaded" : ""}`}
          onLoad={() => setLoaded(true)}
        />
      </div>

      <div className="programs-frame__foot">
        <LockOutlined /> Form hosted by Beam · {new URL(formUrl).host}
      </div>
    </div>
  );
};

const Journey: FC<{ section: SectionDef }> = ({ section }) => (
  <aside className="programs-card programs-next">
    <h3>Your path</h3>
    <ol>
      {section.steps.map((s, i) => (
        <li key={s.title} className={i === 0 ? "is-current" : ""}>
          <strong>{s.title}</strong>
          <span>{s.detail}</span>
        </li>
      ))}
    </ol>
  </aside>
);

const FormSkeleton: FC = () => (
  <div className="programs-skeleton" aria-label="Loading form">
    <div className="programs-skeleton__card">
      <span className="programs-skeleton__bar programs-skeleton__bar--progress" />
      <span className="programs-skeleton__bar programs-skeleton__bar--title" />
      {[0, 1, 2, 3].map((i) => (
        <React.Fragment key={i}>
          <span className="programs-skeleton__bar programs-skeleton__bar--label" />
          <span className="programs-skeleton__bar programs-skeleton__bar--input" />
        </React.Fragment>
      ))}
    </div>
  </div>
);

export default SignupSection;
