import React, { FC, useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, Select, Slider, Spin, Tooltip } from "antd";
import {
  AimOutlined,
  CaretRightOutlined,
  CloseOutlined,
  ExpandOutlined,
  PauseOutlined,
  ReloadOutlined,
} from "@ant-design/icons";
import moment from "moment";
import { useSelector } from "react-redux";
import { useLocation } from "react-router-dom";
import { RootState } from "reducers/rootReducer";
import GooglePlacesAutocomplete, { geocodeByPlaceId } from "react-google-places-autocomplete";
import { pushNotification } from "utils/notifications";
import FleetMap, { DotFilter } from "./FleetMap";
import VehiclePanel, { VehicleActionButton, VehicleActionSpec } from "./VehiclePanel";
import HistoryPanel, { HistoryRange, Layers } from "./HistoryPanel";
import { LatLng, TrackError, useLiveFleet, useTrackHistory } from "./fleetApi";
import {
  countByStatus,
  countByTrip,
  countOffered,
  filterVehicles,
  FleetVehicle,
  formatSpeed,
  hasLocation,
  indexAtTime,
  SPEED_COLORS,
  SpeedUnit,
  summarizeTrack,
  toVehicle,
  TRIP_META,
  TrackPoint,
  VehicleFilter,
  VehicleOffers,
} from "./fleetUtils";
import "./Fleet.scss";

export const DEFAULT_CENTER: LatLng = { lat: 29.95106579999999, lng: -90.0715323 };
const PREFS_KEY = "fleetDashboardPrefs";
const PREFS_VERSION = 2;
const PLAYBACK_TICK_MS = 200;
/** Same key School's map search uses. */
const GOOGLE_API_KEY = "AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M";

interface Prefs {
  refreshSec: number;
  unit: SpeedUnit;
  layers: Layers;
  /** Last searched place; the map opens there next time. */
  place?: LatLng & { label: string; placeId?: string };
}

const DEFAULT_PREFS: Prefs = { refreshSec: 15, unit: "mph", layers: { dots: true, stops: true, arrows: true } };

const readPrefs = (): Prefs => {
  try {
    const saved = JSON.parse(localStorage.getItem(PREFS_KEY) || "{}");
    // Before v2 breadcrumb markers defaulted to off; drop that saved choice once.
    const layers = saved?.v === PREFS_VERSION ? saved?.layers : { ...saved?.layers, dots: undefined };
    return {
      ...DEFAULT_PREFS,
      ...saved,
      layers: { ...DEFAULT_PREFS.layers, ...JSON.parse(JSON.stringify(layers ?? {})) },
    };
  } catch {
    return DEFAULT_PREFS;
  }
};

/** Extra things a host draws on, and asks of, the Fleet map. */
export interface FleetOverlay {
  /**
   * react-google-maps layers drawn on the same GoogleMap. Pass components
   * (not pre-built elements holding `google.maps.*` values) so they render
   * after the Maps script has loaded.
   */
  layers?: React.ReactNode;
  /** Points to fit when `fitKey` changes (e.g. pickup / dropoff). */
  fitPoints?: LatLng[];
  fitKey?: string;
  /** Bump `key` to pan there and refresh live positions around it. */
  focus?: LatLng & { key: number };
  /** Extra buttons in the map tool column. */
  tools?: React.ReactNode;
}

export interface FleetViewProps {
  socket: ISocket;
  /** hpd-dps project to scope live positions to. */
  projectId?: string;
  /** Fill the parent (no 100vh) with a compact toolbar. */
  embedded?: boolean;
  /** Left side of the toolbar (the standalone page puts its logo/title here). */
  brand?: React.ReactNode;
  /**
   * Where the map opens. Omitted: URL lat/lng, else the last searched place,
   * else the browser location, else New Orleans.
   */
  initialCenter?: LatLng;
  /** ISO country code to scope the place search to. */
  searchCountry?: string;
  /** Google Maps key for the map script (defaults to the Fleet app's). */
  googleApiKey?: string;
  overlay?: FleetOverlay;
  /** Vehicles the host has picked; highlighted in the list and on the map. */
  selectedVehicleIds?: string[];
  /** Per-vehicle action button (list rows and the selected-vehicle card). */
  onVehicleAction?: (vehicle: FleetVehicle) => void;
  vehicleAction?: (vehicle: FleetVehicle, picked: boolean) => VehicleActionSpec;
  /**
   * Rides currently offered to drivers, by vehicle id (Ride dispatch screen).
   * Shown as an "Offer pending" pill, an "Offered" filter and an amber ring
   * on the map. Omitted: none of that is shown.
   */
  offers?: VehicleOffers;
}

const defaultVehicleAction = (_: FleetVehicle, picked: boolean): VehicleActionSpec => ({
  label: picked ? "Added" : "Add",
  active: picked,
});

/**
 * Fleet dashboard body: live positions from hpd-dps getResponders (polled),
 * vehicle list with status filters, per-vehicle breadcrumb history with
 * playback. Assumes the host has already bootstrapped `encrypted_token` and
 * `projects` in redux; shows a spinner until then.
 */
const FleetView: FC<FleetViewProps> = ({
  socket,
  projectId,
  embedded,
  brand,
  initialCenter: initialCenterProp,
  searchCountry,
  googleApiKey,
  overlay,
  selectedVehicleIds,
  onVehicleAction,
  vehicleAction = defaultVehicleAction,
  offers,
}) => {
  const { search } = useLocation();
  const query = useMemo(() => new URLSearchParams(search), [search]);
  const { encrypted_token, projects, vehicles: vehicleNames } = useSelector((state: RootState) => state.auth);
  const ready = !!encrypted_token?.connectionId && !!projects?.userServiceId;
  const fetchLive = useLiveFleet(socket, projectId);
  const fetchTrack = useTrackHistory(socket);
  const overlayRef = useRef(overlay);
  overlayRef.current = overlay;

  const [prefs, setPrefsState] = useState<Prefs>(readPrefs);
  const setPrefs = (next: Partial<Prefs>) =>
    setPrefsState((prev) => {
      const merged = { ...prev, ...next };
      try {
        localStorage.setItem(PREFS_KEY, JSON.stringify({ ...merged, v: PREFS_VERSION }));
      } catch {
        /* private mode */
      }
      return merged;
    });

  /* ----------------------------------------------------------------- live */

  // Host's centre, else URL lat/lng, else the last searched place, else the dispatcher's location.
  const initialCenter = useMemo<LatLng>(() => {
    if (initialCenterProp) return initialCenterProp;
    const lat = parseFloat(query.get("lat") || "");
    const lng = parseFloat(query.get("lng") || "");
    if (Number.isFinite(lat) && Number.isFinite(lng)) return { lat, lng };
    return prefs.place ? { lat: prefs.place.lat, lng: prefs.place.lng } : DEFAULT_CENTER;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);
  const [defaultCenter, setDefaultCenter] = useState<LatLng>(initialCenter);
  const [centerReady, setCenterReady] = useState(initialCenter !== DEFAULT_CENTER);
  const centerRef = useRef<LatLng>(initialCenter);

  // Without a centre yet, start where the dispatcher is.
  useEffect(() => {
    if (centerReady) return;
    const done = (c?: LatLng) => {
      if (c) {
        centerRef.current = c;
        setDefaultCenter(c);
      }
      setCenterReady(true);
    };
    if (!navigator.geolocation) return done();
    navigator.geolocation.getCurrentPosition(
      (pos) => done({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      () => done(),
      { timeout: 5000 }
    );
  }, [centerReady]);

  const [fleet, setFleet] = useState<FleetVehicle[]>([]);
  const [liveLoading, setLiveLoading] = useState(false);
  const [liveError, setLiveError] = useState(false);
  const [updatedAt, setUpdatedAt] = useState<number>();
  const [, tick] = useState(0);
  const [fitKey, setFitKey] = useState(0);
  const firstLoad = useRef(true);
  const inFlight = useRef(false);
  const liveSeq = useRef(0);

  /** `force` supersedes a poll in flight, e.g. after jumping to a searched place. */
  const refreshLive = useCallback(
    async (force = false) => {
      if (!ready || (inFlight.current && !force)) return;
      const seq = ++liveSeq.current;
      inFlight.current = true;
      setLiveLoading(true);
      const responders = await fetchLive(centerRef.current);
      if (seq !== liveSeq.current) return;
      inFlight.current = false;
      setLiveLoading(false);
      if (!responders) {
        setLiveError(true);
        return;
      }
      setLiveError(false);
      setFleet(responders.map((r) => toVehicle(r, vehicleNames)));
      setUpdatedAt(Date.now());
      if (firstLoad.current) {
        firstLoad.current = false;
        // The host's own points (e.g. a trip being dispatched) win over the fleet.
        if (!overlayRef.current?.fitPoints?.length) setFitKey((k) => k + 1);
      }
    },
    [ready, fetchLive, vehicleNames]
  );

  useEffect(() => {
    if (ready && centerReady) refreshLive();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [ready, centerReady]);

  useEffect(() => {
    if (!ready || !prefs.refreshSec) return;
    const id = setInterval(() => {
      if (!document.hidden) refreshLive();
    }, prefs.refreshSec * 1000);
    return () => clearInterval(id);
  }, [ready, prefs.refreshSec, refreshLive]);

  // Keeps "Updated 12s ago" honest.
  useEffect(() => {
    const id = setInterval(() => tick((n) => n + 1), 5000);
    return () => clearInterval(id);
  }, []);

  /* ----------------------------------------------------------- place search */

  const [viewport, setViewport] = useState<{ bounds: any; key: number }>();
  const [placeValue, setPlaceValue] = useState<any>(
    // The autocomplete reads `value.place_id` on every option, so a restored
    // place must carry an object there, not null. A host-given centre isn't
    // that place, so don't show it then.
    prefs.place && !initialCenterProp
      ? {
          label: prefs.place.label,
          value: { place_id: prefs.place.placeId ?? "", description: prefs.place.label },
        }
      : null
  );

  const goToPlace = async (option: any) => {
    setPlaceValue(option);
    if (!option?.value?.place_id) {
      setPrefs({ place: undefined });
      return;
    }
    try {
      const [result] = await geocodeByPlaceId(option.value.place_id);
      const geometry = result?.geometry;
      if (!geometry) return;
      const center = { lat: geometry.location.lat(), lng: geometry.location.lng() };
      centerRef.current = center;
      setPrefs({ place: { ...center, label: option.label, placeId: option.value.place_id } });
      // Countries and cities come with a viewport; a street address doesn't.
      if (geometry.viewport) setViewport({ bounds: geometry.viewport, key: Date.now() });
      else setFocus({ ...center, key: Date.now() });
      firstLoad.current = false;
      refreshLive(true);
    } catch (e) {
      console.error(e);
      pushNotification("Couldn't find that place", "error", "TOP_CENTER", 2000);
    }
  };

  const [filter, setFilter] = useState<VehicleFilter>({ search: "", statuses: [], locatedOnly: false });
  const visible = useMemo(() => filterVehicles(fleet, filter, offers), [fleet, filter, offers]);
  const offeredCount = useMemo(() => countOffered(fleet, offers), [fleet, offers]);
  const counts = useMemo(() => countByStatus(fleet), [fleet]);
  const tripCounts = useMemo(() => countByTrip(fleet), [fleet]);
  const onMap = useMemo(() => visible.filter(hasLocation), [visible]);

  const [selectedId, setSelectedId] = useState<string>();
  const [focus, setFocus] = useState<{ lat: number; lng: number; key: number }>();
  const selected = fleet.find((v) => v.id === selectedId);

  const select = (id: string | undefined) => {
    setSelectedId(id);
    const v = fleet.find((x) => x.id === id);
    if (v && hasLocation(v) && !historyFor) setFocus({ lat: v.lat!, lng: v.lng!, key: Date.now() });
  };

  /* ------------------------------------------------------------- overlay */

  const [overlayFit, setOverlayFit] = useState<{ points: LatLng[]; key: string }>();
  useEffect(() => {
    const points = overlay?.fitPoints ?? [];
    if (points.length) setOverlayFit({ points, key: `${overlay?.fitKey ?? ""}:${Date.now()}` });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [overlay?.fitKey]);

  useEffect(() => {
    const f = overlay?.focus;
    if (!f) return;
    centerRef.current = { lat: f.lat, lng: f.lng };
    setFocus({ lat: f.lat, lng: f.lng, key: f.key });
    firstLoad.current = false;
    refreshLive(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [overlay?.focus?.key]);

  /* -------------------------------------------------------------- history */

  const [historyFor, setHistoryFor] = useState<FleetVehicle>();
  const [range, setRange] = useState<HistoryRange>();
  const [track, setTrack] = useState<TrackPoint[]>();
  const [trackLoading, setTrackLoading] = useState(false);
  const [trackError, setTrackError] = useState<string>();
  const [dotFilter, setDotFilter] = useState<DotFilter>("all");
  const [minStopMin, setMinStopMin] = useState(3);
  const trackRequest = useRef(0);

  const summary = useMemo(
    () => (track && track.length ? summarizeTrack(track, minStopMin * 60000) : undefined),
    [track, minStopMin]
  );

  const loadTrack = async (vehicle: FleetVehicle, next: HistoryRange) => {
    const requestNo = ++trackRequest.current;
    setRange(next);
    setTrackLoading(true);
    setTrackError(undefined);
    try {
      const points = await fetchTrack(vehicle.id, next.from, next.to);
      if (requestNo !== trackRequest.current) return;
      setTrack(points);
      setPlayIndex(0);
      setPlaying(false);
      if (points.length) setFitKey((k) => k + 1);
    } catch (e: any) {
      if (requestNo !== trackRequest.current) return;
      setTrack(undefined);
      setTrackError(e instanceof TrackError ? e.message : "Couldn't load the GPS history");
    } finally {
      if (requestNo === trackRequest.current) setTrackLoading(false);
    }
  };

  const openHistory = (vehicle: FleetVehicle) => {
    trackRequest.current += 1;
    setSelectedId(vehicle.id);
    setHistoryFor(vehicle);
    setTrack(undefined);
    setTrackError(undefined);
    setRange(undefined);
    setTrackLoading(false);
  };

  const closeHistory = () => {
    trackRequest.current += 1;
    setHistoryFor(undefined);
    setTrack(undefined);
    setPlaying(false);
    setTrackLoading(false);
  };

  /* ------------------------------------------------------------- playback */

  const [playIndex, setPlayIndex] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [rate, setRate] = useState(60);
  const clock = useRef(0);

  useEffect(() => {
    if (!playing || !track?.length) return;
    clock.current = track[playIndex]?.t ?? track[0].t;
    const id = setInterval(() => {
      clock.current += PLAYBACK_TICK_MS * rate;
      const idx = indexAtTime(track, clock.current);
      setPlayIndex(idx);
      if (idx >= track.length - 1) setPlaying(false);
    }, PLAYBACK_TICK_MS);
    return () => clearInterval(id);
    // Restart only on play/pause, rate or a new track; scrubbing while paused moves playIndex.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [playing, rate, track]);

  const jumpTo = (index: number) => {
    setPlaying(false);
    setPlayIndex(index);
    const p = track?.[index];
    if (p) setFocus({ lat: p.lat, lng: p.lng, key: Date.now() });
  };

  const head = track?.[playIndex];
  const selectedPicked = !!selected && !!selectedVehicleIds?.includes(selected.id);

  /* --------------------------------------------------------------- render */

  return (
    <div className={`flt-shell ${embedded ? "flt-shell--embedded" : ""}`}>
      <div className={`flt-shell__header ${embedded ? "flt-shell__header--compact" : ""}`}>
        {brand}
        <div className="flt-shell__live">
          <span className={`flt-live-dot ${liveError ? "is-error" : prefs.refreshSec ? "is-on" : ""}`} />
          {liveError
            ? "Couldn't reach live tracking"
            : updatedAt
            ? `Updated ${moment(updatedAt).fromNow()}`
            : "Connecting…"}
        </div>
        <div className="flt-place-search">
          <GooglePlacesAutocomplete
            apiKey={googleApiKey || GOOGLE_API_KEY}
            autocompletionRequest={
              searchCountry ? { componentRestrictions: { country: [searchCountry] } } : undefined
            }
            selectProps={{
              value: placeValue,
              onChange: goToPlace,
              isClearable: true,
              placeholder: embedded ? "Search map" : "Search a city, country or address",
              styles: {
                input: (provided: any) => ({ ...provided, fontFamily: "Nunito-Regular" }),
                menu: (provided: any) => ({ ...provided, zIndex: 1100 }),
              },
            }}
          />
        </div>
        <div className="flt-shell__actions">
          <span className="flt-muted">Auto refresh</span>
          <Select<number>
            size="small"
            style={{ width: 90 }}
            value={prefs.refreshSec}
            onChange={(refreshSec) => setPrefs({ refreshSec })}
            options={[
              { value: 0, label: "Off" },
              { value: 10, label: "10s" },
              { value: 15, label: "15s" },
              { value: 30, label: "30s" },
              { value: 60, label: "1m" },
            ]}
          />
          <Tooltip title="Refresh around the map centre">
            <Button
              size="small"
              icon={<ReloadOutlined />}
              loading={liveLoading}
              onClick={() => refreshLive(true)}
              disabled={!ready}
            />
          </Tooltip>
        </div>
      </div>

      {!ready ? (
        <div className="flt-shell__loading">
          <Spin />
          <span>Loading your organization…</span>
        </div>
      ) : (
        <div className="flt-shell__body">
          <aside className="flt-shell__side">
            {historyFor ? (
              <HistoryPanel
                vehicle={historyFor}
                onBack={closeHistory}
                range={range}
                onLoad={(r) => loadTrack(historyFor, r)}
                loading={trackLoading}
                error={trackError}
                track={track}
                summary={summary}
                unit={prefs.unit}
                onUnit={(unit) => setPrefs({ unit })}
                layers={prefs.layers}
                onLayers={(layers) => setPrefs({ layers })}
                dotFilter={dotFilter}
                onDotFilter={setDotFilter}
                minStopMin={minStopMin}
                onMinStopMin={setMinStopMin}
                onJump={jumpTo}
              />
            ) : (
              <VehiclePanel
                vehicles={visible}
                counts={counts}
                tripCounts={tripCounts}
                total={fleet.length}
                filter={filter}
                onFilter={setFilter}
                loading={liveLoading}
                selectedId={selectedId}
                onSelect={select}
                onHistory={openHistory}
                highlightIds={selectedVehicleIds}
                onAction={onVehicleAction}
                actionFor={onVehicleAction ? vehicleAction : undefined}
                offers={offers}
                offeredCount={offeredCount}
              />
            )}
          </aside>

          <main className="flt-shell__map">
            {centerReady ? (
              <FleetMap
                vehicles={historyFor ? onMap.filter((v) => v.id === historyFor.id) : onMap}
                selectedId={selectedId}
                onSelect={historyFor ? () => undefined : select}
                track={track}
                stops={summary?.stops}
                showDots={prefs.layers.dots}
                showStops={prefs.layers.stops}
                showArrows={prefs.layers.arrows}
                dotFilter={dotFilter}
                playbackIndex={track?.length ? playIndex : undefined}
                unit={prefs.unit}
                fitKey={fitKey}
                focus={focus}
                viewport={viewport}
                defaultCenter={defaultCenter}
                onCenterChanged={(c) => {
                  centerRef.current = c;
                }}
                highlightIds={selectedVehicleIds}
                offers={offers}
                fitTo={overlayFit}
                apiKey={googleApiKey}
              >
                {overlay?.layers}
              </FleetMap>
            ) : (
              <div className="flt-shell__loading">
                <Spin />
              </div>
            )}

            <div className="flt-map-tools">
              <Tooltip title="Fit to view" placement="left">
                <Button icon={<ExpandOutlined />} onClick={() => setFitKey((k) => k + 1)} />
              </Tooltip>
              {selected && hasLocation(selected) && !track && (
                <Tooltip title="Centre on selected" placement="left">
                  <Button
                    icon={<AimOutlined />}
                    onClick={() => setFocus({ lat: selected.lat!, lng: selected.lng!, key: Date.now() })}
                  />
                </Tooltip>
              )}
              {overlay?.tools}
            </div>

            {selected && !historyFor && (
              <div className="flt-card">
                <div className="flt-card__head">
                  <div>
                    <div className="flt-vehicle__name">{selected.name}</div>
                    {selected.subtitle && <div className="flt-muted">{selected.subtitle}</div>}
                  </div>
                  <Button type="text" size="small" icon={<CloseOutlined />} onClick={() => setSelectedId(undefined)} />
                </div>
                <div className="flt-muted">
                  {hasLocation(selected)
                    ? `${selected.lat!.toFixed(5)}, ${selected.lng!.toFixed(5)}`
                    : "No live location"}
                  {selected.lastSeen ? ` · ${moment(selected.lastSeen).fromNow()}` : ""}
                </div>
                {selected.driver && (
                  <dl className="flt-card__contact">
                    {selected.driver.name && (
                      <>
                        <dt>Driver</dt>
                        <dd>{selected.driver.name}</dd>
                      </>
                    )}
                    {selected.trip && (
                      <>
                        <dt>Ride</dt>
                        <dd>{TRIP_META[selected.trip].label}</dd>
                      </>
                    )}
                    {selected.driver.phone && (
                      <>
                        <dt>Phone</dt>
                        <dd>
                          <a href={`tel:${selected.driver.phone}`}>{selected.driver.phone}</a>
                        </dd>
                      </>
                    )}
                    {selected.driver.email && (
                      <>
                        <dt>Email</dt>
                        <dd>
                          <a href={`mailto:${selected.driver.email}`}>{selected.driver.email}</a>
                        </dd>
                      </>
                    )}
                    {selected.driver.customId && (
                      <>
                        <dt>Custom ID</dt>
                        <dd>{selected.driver.customId}</dd>
                      </>
                    )}
                  </dl>
                )}
                {onVehicleAction && (
                  <div className="mt-2">
                    <VehicleActionButton
                      block
                      vehicle={selected}
                      spec={vehicleAction(selected, selectedPicked)}
                      onAction={onVehicleAction}
                    />
                  </div>
                )}
                <Button className="mx-btn-primary mt-2 w-100" onClick={() => openHistory(selected)}>
                  Show history
                </Button>
              </div>
            )}

            {track && track.length > 0 && (
              <>
                <div className="flt-legend">
                  <span>
                    <i style={{ background: SPEED_COLORS.idle }} /> Idle
                  </span>
                  <span>
                    <i style={{ background: SPEED_COLORS.moving }} /> Moving
                  </span>
                  <span>
                    <i style={{ background: SPEED_COLORS.speeding }} /> Over {formatSpeed(13.4, prefs.unit)}
                  </span>
                </div>
                <div className="flt-playback">
                  <Button
                    shape="circle"
                    type="primary"
                    icon={playing ? <PauseOutlined /> : <CaretRightOutlined />}
                    onClick={() => {
                      if (!playing && playIndex >= track.length - 1) setPlayIndex(0);
                      setPlaying(!playing);
                    }}
                  />
                  <div className="flt-playback__track">
                    <Slider
                      min={0}
                      max={track.length - 1}
                      value={playIndex}
                      tooltipVisible={false}
                      onChange={(v: number) => {
                        setPlaying(false);
                        setPlayIndex(v);
                      }}
                    />
                    <div className="flt-playback__meta">
                      <span>{head && moment(head.t).format("MMM D, h:mm:ss A")}</span>
                      <span>{head && formatSpeed(head.speed, prefs.unit)}</span>
                    </div>
                  </div>
                  <Select<number>
                    size="small"
                    style={{ width: 76 }}
                    value={rate}
                    onChange={setRate}
                    options={[10, 30, 60, 120, 300].map((r) => ({ value: r, label: `${r}×` }))}
                  />
                </div>
              </>
            )}
          </main>
        </div>
      )}
    </div>
  );
};

export default FleetView;
