import React, { FC, useEffect, useState } from "react";
import { Modal, Select, Button, Spin, Empty, Tag } from "antd";

import { pushNotification } from "utils/notifications";
import {
  getUsersAggregateList,
  getGroupKeys,
  setGroupKeys,
} from "../../../../../services/apis/collections/oAuthApis";
import { SocketTopics } from "constants/enums";
import {
  getPageUpdateRequestPublishTopic,
  getPageUpdateSubscriptionTopic,
} from "../../../../../hooks/MQTTConstants";
import { wrapRequestPayload } from "../../../../../helpers/request/RequestPayload";

/**
 * "Add to Group" popup for the Players page. Lists the org's BDS groups
 * (`aggregateBds`, static only) and adds the selected players to the chosen
 * group the way the admin console does it (spec 5.2), over shared-react's own
 * BDS/Page plumbing:
 *
 *   1. getkeys(groupId)                              — current membership keys
 *   2. setkeys(groupId, keys ∪ new user keys)        — add the players (members)
 *   3. updatePage(pageId) add page members "write"   — chat-page access (best effort)
 *
 * All BDS calls are the same REST client the dashboard already uses for
 * aggregateBds; the page update uses the app socket, like createAssistPage.
 */

const ECO = process.env.REACT_APP_ECO_SYSTEM;

/** RediSearch tag escaping for the partition value (e.g. org-beam-sport). */
const escapeTag = (value: string): string =>
  value.replace(/[,.<>{}[\]"':;!@#$%^&*()\-+=~|\\ ]/g, (c) => `\\${c}`);

interface GroupRow {
  id: string;
  name: string;
  pageId?: string;
}

export interface GroupUser {
  id: string;
  beamId?: string;
}

const AddToGroupModal: FC<{
  open: boolean;
  /** Selected players to add. */
  users: GroupUser[];
  /** The org's CUDB service id (projects.userServiceId). */
  serviceId: string;
  connectionId: string;
  socket?: ISocket;
  onClose: () => void;
  /** Called after the users are added (e.g. to clear the table selection). */
  onAdded?: () => void;
  /** user id -> display name, for labelling the group's current members. */
  usersById?: Record<string, string>;
}> = ({ open, users, serviceId, connectionId, socket, onClose, onAdded, usersById }) => {
  const [groups, setGroups] = useState<GroupRow[]>([]);
  const [loadingGroups, setLoadingGroups] = useState(false);
  const [selectedGroupId, setSelectedGroupId] = useState<string | undefined>(undefined);
  const [submitting, setSubmitting] = useState(false);
  // The selected group's current members (user ids), shown in the popup.
  const [existingMemberIds, setExistingMemberIds] = useState<Set<string>>(new Set());
  const [memberNames, setMemberNames] = useState<Record<string, string>>({});
  const [loadingMembers, setLoadingMembers] = useState(false);

  useEffect(() => {
    if (!open || !serviceId) return;
    let active = true;
    setLoadingGroups(true);
    setSelectedGroupId(undefined);
    setExistingMemberIds(new Set());

    const requestData = {
      select: {
        index: {
          searchIndex: `${ECO}:query:bulk`,
          // Only static groups: members can only be added to those (spec 5.2).
          searchQuery: `@type:{user\\:static}@partitions:{org\\:${escapeTag(serviceId)}}`,
        },
        load: { objectId: "$.objectId", info: "$.info", createdAt: "$.info.createdAt" },
      },
      sortBy: { properties: [{ field: "@createdAt", order: "ASC" }], max: 100000 },
      result: { pagination: { offset: 0, limit: 1000 } },
    };

    getUsersAggregateList({ data: requestData })
      .then((res: any) => {
        if (!active) return;
        setLoadingGroups(false);
        const rows = Array.isArray(res?.data) ? res.data : [];
        setGroups(
          rows.map((r: any) => ({
            id: `${r?.objectId}`,
            name: r?.info?.name || `Group ${r?.objectId}`,
            pageId: r?.info?.data?.group?.pageId,
          }))
        );
      })
      .catch(() => {
        if (!active) return;
        setLoadingGroups(false);
        pushNotification("Could not load groups", "error", "TOP_CENTER", 3000);
      });

    return () => {
      active = false;
    };
  }, [open, serviceId]);

  // Best-effort: put the new users on the group's chat page with role "write".
  const updateGroupPage = (group: GroupRow) => {
    if (!group.pageId || !socket || !connectionId) return;
    const now = Date.now();
    const changes = [
      ...users.map((u) => ({
        op: "add",
        path: `/persistent/static/metadata/members/users/${u.id}`,
        value: { beamId: u.beamId || "", role: "write" },
      })),
      { op: "replace", path: "/persistent/static/metadata/title", value: group.name },
      { op: "add", path: "/persistent/dynamic/metadata/updatedAt", value: now },
    ];
    try {
      socket.subscribeToEvent(
        SocketTopics.SubscribePageTopics,
        getPageUpdateSubscriptionTopic(connectionId),
        () => undefined
      );
      socket.publishToEvent(
        SocketTopics.PublishPageTopics,
        getPageUpdateRequestPublishTopic(connectionId),
        wrapRequestPayload({ objectId: String(group.pageId), changes })
      );
    } catch {
      // Membership (keys) already succeeded; page sync is non-fatal.
    }
  };

  // Resolve display names for a set of member user ids (one aggregateBds call).
  const resolveMemberNames = (ids: string[]) => {
    if (!ids.length || !serviceId) return;
    getUsersAggregateList({
      data: {
        select: {
          index: {
            searchIndex: `${ECO}:userNameIndex`,
            searchQuery: `@serviceId:{'${escapeTag(serviceId)}'}`,
            searchOptions: "TIMEOUT 5000",
          },
          // objectIds must be strings (the service calls .includes on them).
          list: { objectIds: ids },
          load: {
            id: "$.objectId",
            firstName: "$.persistent.static.live.profile.firstName",
            lastName: "$.persistent.static.live.profile.lastName",
          },
        },
        apply: { expression: "", name: "" },
        result: {},
        filter: { expression: "" },
        anyStatus: false,
      },
    })
      .then((res: any) => {
        const rows = Array.isArray(res?.data) ? res.data : [];
        const map: Record<string, string> = {};
        rows.forEach((x: any) => {
          const name = `${x?.firstName ?? ""} ${x?.lastName ?? ""}`.trim();
          if (x?.id !== undefined && name) map[`${x.id}`] = name;
        });
        setMemberNames(map);
      })
      .catch(() => undefined);
  };

  // Fetch the selected group's current members (getkeys -> user ids) + names.
  const loadMembers = (groupId?: string) => {
    setMemberNames({});
    if (!groupId) {
      setExistingMemberIds(new Set());
      return;
    }
    setLoadingMembers(true);
    getGroupKeys({ data: { queryId: Number(groupId) } })
      .then((res: any) => {
        const keys: string[] = res?.data?.keys || [];
        const ids = keys.filter((k) => k.includes(":user:")).map((k) => k.split(":")[2]);
        setExistingMemberIds(new Set(ids));
        resolveMemberNames(ids);
      })
      .catch(() => setExistingMemberIds(new Set()))
      .finally(() => setLoadingMembers(false));
  };

  const handleAdd = async () => {
    const group = groups.find((g) => g.id === selectedGroupId);
    if (!group || !users.length) return;
    setSubmitting(true);
    try {
      const queryId = Number(group.id);
      const keysRes: any = await getGroupKeys({ data: { queryId } });
      if (!keysRes || keysRes.status === false) {
        pushNotification(keysRes?.message || "Could not read the group", "error", "TOP_CENTER", 3500);
        return;
      }
      const existing: string[] = keysRes?.data?.keys || [];
      const userKeys = users.map((u) => `${ECO}:user:${u.id}:${serviceId}`);
      // setkeys replaces the whole set, so send the union of old + new.
      const merged = Array.from(new Set([...existing, ...userKeys]));

      const setRes: any = await setGroupKeys({ data: { queryId, keys: merged } });
      if (!setRes || setRes.status === false) {
        pushNotification(setRes?.message || "Could not add users", "error", "TOP_CENTER", 3500);
        return;
      }

      updateGroupPage(group);

      pushNotification(
        `${users.length} ${users.length === 1 ? "player" : "players"} added to ${group.name}`,
        "success",
        "TOP_CENTER",
        2500
      );
      onAdded?.();
      onClose();
    } catch {
      pushNotification("Could not add users to the group", "error", "TOP_CENTER", 3500);
    } finally {
      setSubmitting(false);
    }
  };

  // How many of the players being added are already in the selected group.
  const alreadyCount = users.filter((u) => existingMemberIds.has(`${u.id}`)).length;
  const allAlready = users.length > 0 && alreadyCount === users.length;

  return (
    <Modal
      title="Add to group"
      visible={open}
      onCancel={onClose}
      width="480px"
      className="beam-modal"
      footer={null}
      destroyOnClose
    >
      <p style={{ color: "#8c8c8c", marginBottom: 12 }}>
        Add the selected {users.length === 1 ? "player" : "players"} to a group.
      </p>
      {loadingGroups ? (
        <div style={{ textAlign: "center", padding: "24px 0" }}>
          <Spin tip="Loading groups..." />
        </div>
      ) : groups.length ? (
        <Select
          showSearch
          allowClear
          placeholder="Select a group"
          value={selectedGroupId}
          onChange={(value) => {
            setSelectedGroupId(value);
            loadMembers(value);
          }}
          options={groups.map((g) => ({ label: g.name, value: g.id }))}
          filterOption={(input, option) =>
            (option?.label ?? "").toString().toLowerCase().includes(input.toLowerCase())
          }
          style={{ width: "100%" }}
        />
      ) : (
        <Empty description="No groups found" image={Empty.PRESENTED_IMAGE_SIMPLE} />
      )}

      {selectedGroupId && (
        <div style={{ marginTop: 16 }}>
          <div style={{ fontSize: 12, color: "#8c8c8c", marginBottom: 6 }}>
            Current members{loadingMembers ? "" : ` (${existingMemberIds.size})`}
          </div>
          {loadingMembers ? (
            <Spin size="small" />
          ) : existingMemberIds.size ? (
            <div
              style={{
                maxHeight: 160,
                overflow: "auto",
                display: "flex",
                flexWrap: "wrap",
                gap: 6,
              }}
            >
              {Array.from(existingMemberIds).map((id) => {
                // Green = this member is also among the players you're adding now.
                const alreadySelected = users.some((u) => `${u.id}` === id);
                return (
                  <Tag key={id} color={alreadySelected ? "green" : undefined}>
                    {memberNames[id] || usersById?.[id] || `#${id}`}
                  </Tag>
                );
              })}
            </div>
          ) : (
            <span style={{ color: "#8c8c8c" }}>No members yet</span>
          )}
        </div>
      )}

      {selectedGroupId && !loadingMembers && alreadyCount > 0 && (
        <p style={{ color: "#d48806", marginTop: 12, marginBottom: 0 }}>
          {alreadyCount} of the selected {alreadyCount === 1 ? "player is" : "players are"} already
          in this group{allAlready ? "" : " and will be skipped"}.
        </p>
      )}

      {/* The beam-modal style hides the default Modal footer, so the actions
          live in the body (same pattern as the Teams/Classes modal). */}
      <div style={{ display: "flex", gap: 12, marginTop: 24 }}>
        <Button
          type="primary"
          className="beam-btn green-btn cover"
          style={{ flex: 1 }}
          loading={submitting}
          disabled={!selectedGroupId || allAlready}
          onClick={handleAdd}
        >
          Add {users.length} {users.length === 1 ? "player" : "players"}
        </Button>
        <Button
          className="beam-btn orange-btn bordered"
          style={{ flex: 1 }}
          onClick={onClose}
          disabled={submitting}
        >
          Cancel
        </Button>
      </div>
    </Modal>
  );
};

export default AddToGroupModal;
