import { useCallback } from "react";
import { useDispatch, useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { formatForRedis } from "utils/appUtil";
import { GET_AGGREGATE } from "../../../../../reducers/reducer";

// Locations are custom objects partitioned [`org:<id>`, `type:location`] with
// `/info = { name, fullName, location, address }`. DispatchPanel and
// DispatchingForm read them, so keep this shape.

export const REQUEST_TIMEOUT_MS = 15000;

export interface LocationRecord {
  objectId: string;
  info?: { name?: string; fullName?: string; location?: any; address?: string };
  partitions?: string[];
  status?: any;
  name?: string;
}

export interface LocationRow {
  key: string;
  name: string;
  address: string;
  record: LocationRecord;
}

export const LOCATION_NAME_MAX = 80;

export const locationNameKey = (name: any) => `${name ?? ""}`.trim().toLowerCase();

export const toLocationInfo = (values: { name: string; location: any }) => {
  const name = values.name.trim();
  return {
    name,
    fullName: name.toLowerCase(),
    location: values.location,
    address: values.location?.label,
  };
};

const escapeSearch = (text: string) =>
  /[-']/.test(text) ? formatForRedis(text) : text;

/**
 * Lists this org's locations, optionally filtered server-side by name.
 * Resolves null when the request fails or times out (GET_AGGREGATE doesn't
 * call back on errors).
 */
export const useLocationQuery = () => {
  const dispatch = useDispatch();
  const { projects } = useSelector((state: RootState) => state.auth);

  return useCallback(
    (searchText = "") =>
      new Promise<LocationRow[] | null>((resolve) => {
        const query = searchText.trim().toLowerCase();
        const timer = setTimeout(() => resolve(null), REQUEST_TIMEOUT_MS);
        dispatch(
          GET_AGGREGATE({
            requestData: {
              select: {
                index: {
                  searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:custom:createdAt`,
                  searchQuery: `@partitions:{'org\\:${formatForRedis(
                    projects?.userServiceId
                  )}'}@partitions:{type\\:location}`,
                  searchOptions: "VERBATIM TIMEOUT 10000",
                },
                load: {
                  info: "$.info",
                  objectId: "$.objectId",
                  partitions: "$.partitions",
                  status: "$..status",
                  name: "$.info.fullName",
                },
              },
              filter: {
                expression: query
                  ? `exists(@name) && contains(lower(@name), '${escapeSearch(query)}')`
                  : "",
              },
            },
            callback: (response: LocationRecord[]) => {
              clearTimeout(timer);
              resolve(
                (response || [])
                  .map((x) => ({
                    key: x?.objectId,
                    name: x?.info?.name || "",
                    address: x?.info?.address || x?.info?.location?.label || "",
                    record: x,
                  }))
                  .sort((a, b) => a.name.localeCompare(b.name))
              );
            },
          })
        );
      }),
    [dispatch, projects?.userServiceId]
  );
};

/** Exact, case-insensitive name clash against all of the org's locations. */
export const findNameClash = (rows: LocationRow[], name: string, exceptObjectId?: string) =>
  rows.find(
    (r) =>
      r.key !== exceptObjectId &&
      (locationNameKey(r.name) === locationNameKey(name) ||
        locationNameKey(r.record?.info?.fullName) === locationNameKey(name))
  );
