import React, { useState, useEffect, useRef } from "react";
import { Modal, Button, Row, Col, Input, Dropdown, Menu } from "antd";
import {
  placeLabelFromPrediction,
  reverseGeocodeName,
  countryRestriction,
  ensureActiveCountry,
  getActiveCountry,
  primeActiveCountry,
  setActiveCountry,
} from "utils/placeName";

/** Wait for typing to pause before asking for predictions. */
const PREDICTION_DEBOUNCE_MS = 250;

/** `.beam-btn` and the form input styles hide antd's disabled look. */
export const disabledStyle: React.CSSProperties = {
  opacity: 0.55,
  cursor: "not-allowed",
};

interface LocationValue {
  label: string;
  value: {
    place_id: string;
    coordinates: { lat: number; long: number };
    attributes: { address: string; zip?: string; city?: string; state?: string; country?: string };
  };
}

interface LocationInputProps {
  value?: any;
  onChange?: (value: LocationValue) => void;
  placeholder?: string;
  disabled?: boolean;
}

const LocationInput: React.FC<LocationInputProps> = ({ value, placeholder, onChange, disabled }) => {
  const [inputValue, setInputValue] = useState("");
  const [modalInputValue, setModalInputValue] = useState("");
  const [predictions, setPredictions] = useState<any[]>([]);
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [latLng, setLatLng] = useState({ lat: 37.7749, lng: -122.4194 });
  const mapRef = useRef<HTMLDivElement | null>(null);
  const [map, setMap] = useState<google.maps.Map | null>(null);
  const [marker, setMarker] = useState<google.maps.Marker | null>(null);
  const pasteDetectedRef = useRef(false);
  const manualSelectionRef = useRef(false);
  const autoSelectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
  // The text we last wrote into the input ourselves (a selected place, a
  // confirmed map pin, the incoming `value`). The predictions effect skips it,
  // so our own writes don't reopen the list with a different set of places.
  const programmaticValueRef = useRef<string | null>(null);
  // Guards the prediction list against changing under the operator's cursor —
  // see applyPredictions.
  const predictionSeqRef = useRef(0);
  const pointerInListRef = useRef(false);
  const heldPredictionsRef = useRef<any[] | null>(null);
  // Re-render once the dispatching country is known so the next keystroke's
  // predictions are scoped to it.
  const [country, setCountry] = useState(getActiveCountry());

  /** Resolve the country to scope predictions to: whatever this field already
   *  holds wins (the ride is being planned there), else the operator's own
   *  position. Unrestricted until one of those answers. */
  useEffect(() => {
    let cancelled = false;
    const coordinates = value?.value?.coordinates;
    const resolve = coordinates
      ? primeActiveCountry(coordinates)
      : ensureActiveCountry();
    resolve
      .then((code) => {
        if (!cancelled && code) setCountry(code);
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [value?.value?.coordinates?.lat, value?.value?.coordinates?.long]);

  /** Initialize from `value` prop */
  useEffect(() => {
    if (value) {
      let address: string = "";
      if (typeof value === "string") {
        address = value;
      } else {
        address = value.value?.attributes?.address || value.label;
      }
      programmaticValueRef.current = address;
      setInputValue(address);
      setModalInputValue(address);
      if (value?.value?.coordinates) {
        setLatLng({
          lat: value.value.coordinates.lat,
          lng: value.value.coordinates.long,
        });
      }
    }
  }, [value]);

  /**
   * Apply a prediction list — unless the pointer is inside the dropdown, in
   * which case it is held until the pointer leaves.
   *
   * This is the fix for picking "Askari 10" and getting a different place: the
   * operator aims at a row, and between pressing and releasing the mouse a
   * late prediction response re-renders the list. The click then lands on
   * whatever row moved into that spot. Rows may not move while they are being
   * clicked, full stop.
   */
  const applyPredictions = (preds: any[]) => {
    if (pointerInListRef.current) {
      heldPredictionsRef.current = preds;
      return;
    }
    setPredictions(preds);
  };

  /** Fetch predictions when user types */
  useEffect(() => {
    if (!inputValue) {
      setPredictions([]);
      return;
    }
    // Don't re-query for text we just wrote ourselves (a selected place, a
    // confirmed map pin). Doing so re-opened the list with predictions for the
    // resolved address — a different set of places than the operator chose from.
    if (programmaticValueRef.current === inputValue) {
      programmaticValueRef.current = null;
      setPredictions([]);
      return;
    }
    // Debounced: a request per keystroke made the list churn for the whole time
    // the operator was reaching for a row.
    const seq = ++predictionSeqRef.current;
    const timer = setTimeout(() => {
      const service = new window.google.maps.places.AutocompleteService();
      // Scoped to the dispatching country: an unrestricted search buries the
      // local street the operator wants under same-named places worldwide.
      service.getPlacePredictions(
        { input: inputValue, ...countryRestriction() } as google.maps.places.AutocompletionRequest,
        (preds) => {
          // Responses can land out of order — an older one must never replace
          // the list the operator is currently looking at.
          if (seq !== predictionSeqRef.current) return;
          applyPredictions(preds || []);
        }
      );
    }, PREDICTION_DEBOUNCE_MS);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [inputValue, country]);

  /** Auto-select first prediction on paste */
  useEffect(() => {
    // Clear any existing timeout
    if (autoSelectTimeoutRef.current) {
      clearTimeout(autoSelectTimeoutRef.current);
    }

    // Only auto-select if paste was detected, predictions are available, and user hasn't manually selected
    if (pasteDetectedRef.current && predictions.length > 0 && !manualSelectionRef.current) {
      autoSelectTimeoutRef.current = setTimeout(() => {
        if (predictions.length > 0 && !manualSelectionRef.current) {
          // Auto-select the first prediction
          fetchPlaceDetails(
            predictions[0].place_id,
            false,
            predictions[0].description
          );
          // Reset paste flag after auto-selection
          pasteDetectedRef.current = false;
        }
      }, 500); // Wait 500ms for predictions to fully load
    }

    return () => {
      if (autoSelectTimeoutRef.current) {
        clearTimeout(autoSelectTimeoutRef.current);
      }
    };
  }, [predictions]);

  /** Initialize modal map */
  useEffect(() => {
    if (!isModalOpen) return;
  
    const googleMap = new window.google.maps.Map(mapRef.current, {
      center: latLng,
      zoom: 15,
    });
  
    const newMarker = new window.google.maps.Marker({
      position: latLng,
      map: googleMap,
      draggable: true,
    });
  
    newMarker.addListener("dragend", () => {
      const newPosition = newMarker.getPosition();
      if (newPosition) {
        const lat = newPosition.lat();
        const lng = newPosition.lng();
        setLatLng({ lat, lng });
        // Keep the address text with the pin. Confirm builds the location out
        // of this text, so leaving the previous address here saved the new
        // coordinates under the old — visibly wrong — address.
        reverseGeocodeName(lat, lng).then((name) => {
          if (name) setModalInputValue(name);
        });
      }
    });
  
    setMap(googleMap);
    setMarker(newMarker);
  
    return () => {
      newMarker.setMap(null);
    };
  }, [isModalOpen, latLng])
 

  /** Fetch full place details.
   *
   * `description` is the prediction text the operator clicked. It matters:
   * Place Details answers with `formatted_address`, which for an establishment
   * is that place's street address (and, where there is none, a plus code) —
   * so using it alone replaced the operator's choice with a different-looking
   * address. placeLabelFromDetails keeps the place's name in front of it, and
   * the description is the fallback when Details returns nothing usable.
   */
  const fetchPlaceDetails = (
    placeId: string,
    isManualSelection: boolean = false,
    description?: string
  ) => {
    if (isManualSelection) {
      manualSelectionRef.current = true;
    }
    const service = new window.google.maps.places.PlacesService(document.createElement("div"));
    service.getDetails(
      {
        placeId,
        fields: [
          "place_id",
          "name",
          "formatted_address",
          "geometry",
          "address_components",
        ],
      },
      (result, status) => {
        if (status === window.google.maps.places.PlacesServiceStatus.OK && result) {
          const attributes = {
            // What the operator clicked, verbatim — the input must never show a
            // different address than the row they picked. Place Details is only
            // consulted when the prediction itself is a plus code.
            address: placeLabelFromPrediction(description, result),
            zip: "",
            city: "",
            state: "",
            country: "",
          };

          result.address_components?.forEach((comp) => {
            if (comp.types.includes("postal_code")) attributes.zip = comp.short_name;
            if (comp.types.includes("locality")) attributes.city = comp.short_name;
            if (comp.types.includes("administrative_area_level_1")) attributes.state = comp.short_name;
            if (comp.types.includes("country")) {
              attributes.country = comp.long_name;
              // Strongest signal there is for scoping later searches: the
              // operator just picked a place in this country.
              setActiveCountry(comp.short_name);
              setCountry(comp.short_name.toLowerCase());
            }
          });

          const coordinates = {
            lat: result.geometry?.location?.lat() || 0,
            long: result.geometry?.location?.lng() || 0,
          };

          const location: LocationValue = {
            label: attributes.address,
            value: { place_id: placeId, coordinates, attributes },
          };

          programmaticValueRef.current = attributes.address;
          setInputValue(attributes.address);
          setModalInputValue(attributes.address);
          onChange?.(location);
          setLatLng({ lat: coordinates.lat, lng: coordinates.long });
          setDropdownVisible(false);
        } else if (description) {
          // Details failed (quota, transient error). Previously the field kept
          // the half-typed text and the form value was never set, so the ride
          // went out with a stale location. Resolve the place through the
          // Geocoder instead, keeping the label the operator picked.
          new window.google.maps.Geocoder().geocode(
            { placeId },
            (geo: any, geoStatus: string) => {
              const hit = geoStatus === "OK" ? geo?.[0] : null;
              if (!hit?.geometry?.location) return;
              const coordinates = {
                lat: hit.geometry.location.lat(),
                long: hit.geometry.location.lng(),
              };
              const location: LocationValue = {
                label: description,
                value: {
                  place_id: placeId,
                  coordinates,
                  attributes: { address: description },
                },
              };
              programmaticValueRef.current = description;
              setInputValue(description);
              setModalInputValue(description);
              onChange?.(location);
              setLatLng({ lat: coordinates.lat, lng: coordinates.long });
              setDropdownVisible(false);
            }
          );
        }
      }
    );
  };

  const handleInputChange = (value: string) => {
    // Check if this is a paste event by checking if pasteDetectedRef is already set
    // If not set, this is regular typing, so reset paste flag
    if (!pasteDetectedRef.current) {
      // User is typing (not pasting), reset flags to allow auto-selection on next paste
      manualSelectionRef.current = false;
    }
    // Real typing — never treat it as one of our own writes.
    programmaticValueRef.current = null;
    setInputValue(value);
  };

  const handlePaste = () => {
    // Mark that a paste event occurred
    pasteDetectedRef.current = true;
    // Reset manual selection flag on paste to allow auto-selection
    manualSelectionRef.current = false;
  };

  const handleConfirmLocation = () => {
    const location: LocationValue = {
      label: modalInputValue,
      value: {
        place_id: "",
        coordinates: { lat: latLng.lat, long: latLng.lng },
        attributes: { address: modalInputValue },
      },
    };
    programmaticValueRef.current = modalInputValue;
    setInputValue(modalInputValue);
    onChange?.(location);
    setIsModalOpen(false);
  };

  /** Prediction menu.
   *
   * The wrapper freezes the list while the pointer is inside it: whatever the
   * operator can see and aim at stays put until they leave or pick something.
   * Any prediction response that arrives meanwhile is held and applied on exit.
   */
  const menu = (
    <div
      onMouseEnter={() => {
        pointerInListRef.current = true;
      }}
      onMouseLeave={() => {
        pointerInListRef.current = false;
        if (heldPredictionsRef.current) {
          const held = heldPredictionsRef.current;
          heldPredictionsRef.current = null;
          setPredictions(held);
        }
      }}
    >
      <Menu>
        {predictions.map((item) => (
          <Menu.Item
            key={item.place_id}
            onClick={() => {
              // The row that was picked wins, whatever the list does next.
              heldPredictionsRef.current = null;
              pointerInListRef.current = false;
              fetchPlaceDetails(item.place_id, true, item.description);
            }}
          >
            {item.description}
          </Menu.Item>
        ))}
      </Menu>
    </div>
  );

  return (
    <div style={{ display: "flex", alignItems: "center", width: "100%" }}>
      {/* Main Input with dropdown */}
      {/* Dropdown clones its child with its own `disabled`, so it has to be
          passed here too — on the Input alone it is overwritten. */}
      <Dropdown
        overlay={menu}
        visible={!disabled && dropdownVisible && predictions.length > 0}
        placement="bottomLeft"
        disabled={disabled}
      >
        <Input
          value={inputValue}
          placeholder={placeholder}
          disabled={disabled}
          style={disabled ? disabledStyle : undefined}
          onChange={(e) => handleInputChange(e.target.value)}
          onPaste={handlePaste}
          onFocus={() => setDropdownVisible(true)}
          onBlur={() => setTimeout(() => setDropdownVisible(false), 200)}
        />
      </Dropdown>

      {/* Map Button */}
      <Button
        className="ml-2 beam-btn"
        disabled={disabled}
        style={disabled ? disabledStyle : undefined}
        onClick={() => setIsModalOpen(true)}
      >
        Map
      </Button>

      {/* Map Modal */}
      <Modal
        title="Select Location on Map"
        visible={isModalOpen}
        onCancel={() => setIsModalOpen(false)}
        footer={null}
      >
        <Input
          value={modalInputValue}
          placeholder="Enter address"
          onChange={(e) => setModalInputValue(e.target.value)}
          style={{ margin: "10px 0" }}
        />

        <div ref={mapRef} style={{ width: "100%", height: "400px" }} />

        <Row className="mt-3">
          <Col span={14} className="pr-2">
            <Button type="primary" block onClick={handleConfirmLocation} className="beam-btn green-btn">
              Confirm
            </Button>
          </Col>
          <Col span={10} className="pl-2">
            <Button block onClick={() => setIsModalOpen(false)} className="beam-btn">
              Cancel
            </Button>
          </Col>
          </Row>
        </Modal>
    </div>
  );
};

export default LocationInput;
