import React from "react";
import { Row, Col, Form } from "antd";
import { isValidPhoneNumber } from "react-phone-number-input";
import RideTypeInput from "common/RideTypeInput";
import NumberInput from "common/NumberInput";
import FareTypeInput from "common/FareTypeInput";
import PayTypeInput from "common/PayTypeInput";
import VehicleInput from "common/VehicleInput";
import { useDispatchPanel } from "../context";

// Ride type + fare + pay + vehicle options shown only for dispatchers
// (authenticated, non web-booker sessions).
const DispatcherRideSection: React.FC = () => {
  const {
    encrypted_token,
    webBooker,
    rideType,
    setRideType,
    estimatedFare,
    setCouponResponse,
    form,
    setIsAddCardModalVisible,
    socket,
    vehicleType,
    couponRequestRef,
    setPayType,
  } = useDispatchPanel();

  if (!(encrypted_token && !webBooker)) return null;

  return (
    <React.Fragment>
      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="rideType"
            rules={[
              { required: true, message: "**Required Field" },
              {
                message: "**Required Field",
                validator: async (_, value) => {
                  if (
                    value?.value === "roundTrip" &&
                    (!value?.date || !value?.time)
                  ) {
                    return Promise.reject("**Required Field");
                  }
                },
              },
            ]}
          >
            <RideTypeInput
              placeholder="Select ride"
              onChange={(value: any) => {
                setRideType(value.value);
              }}
            />
          </Form.Item>
        </Col>
      </Row>

      {rideType === "roundTrip" && (
        <React.Fragment>
          <Row className="mt-3">
            <Col span={24}>
              <Form.Item
                name="roundTripLeadTime"
                rules={[{ required: true, message: "**Required Field" }]}
              >
                <NumberInput
                  placeholder={"Enter lead time"}
                  onChange={(value: any) => {}}
                />
              </Form.Item>
            </Col>
          </Row>

          <Row>
            <Col span={24}>
              <Form.Item name="roundTripNotify"></Form.Item>
            </Col>
          </Row>
        </React.Fragment>
      )}

      <hr />

      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="fareType"
            rules={[
              { required: true, message: "**Required Field" },
              {
                validator: (_, value) => {
                  if (value?.value === "bid" && value?.estimatedFare > 0) {
                    const minBid = value?.estimatedFare * 0.7;
                    const maxBid = value?.estimatedFare * 1.3;

                    if (value?.fare < minBid || value?.fare > maxBid) {
                      return Promise.reject(
                        `Bid must be between ${minBid.toFixed(
                          0
                        )} and ${maxBid.toFixed(0)}`
                      );
                    }
                  }
                  if (value?.value === "bid" && value?.fare === undefined) {
                    return Promise.reject("**Required Field");
                  }
                  return Promise.resolve();
                },
              },
            ]}
          >
            <FareTypeInput
              placeholder="Select fare"
              estimatedFare={estimatedFare}
              onChange={(value: any) => {
                couponRequestRef.current = undefined;
                setCouponResponse(undefined);
                form.setFieldsValue({ coupon: undefined });
              }}
            />
          </Form.Item>
        </Col>
      </Row>

      <hr />

      <Row className="mt-3">
        <Col span={24}>
          <Form.Item
            name="payType"
            rules={[{ required: true, message: "**Required Field" }]}
          >
            <PayTypeInput
              placeholder="Select payment option"
              onChange={(value: any) => {
                // Was setRideType, which hid the return-trip fields whenever
                // the payment option changed.
                setPayType(value.value);

                const phone = form.getFieldValue("passengerPhoneNumber");
                const email = form.getFieldValue("passengerEmail");
                if (
                  value?.value === "now" &&
                  phone &&
                  isValidPhoneNumber(phone)
                ) {
                  setIsAddCardModalVisible({
                    phone,
                    email,
                  });
                } else {
                  setIsAddCardModalVisible(undefined);
                }
              }}
            />
          </Form.Item>
        </Col>
      </Row>

      <hr />

      <Row className="mt-3">
        <Col span={24}>
          <Form.Item name="vehicle">
            <VehicleInput
              placeholder="Select vehicle"
              onChange={(value: any) => {}}
              socket={socket}
              vehicleType={vehicleType}
            />
          </Form.Item>
        </Col>
      </Row>

      <hr />
    </React.Fragment>
  );
};

export default DispatcherRideSection;
