import React, { FC, useEffect, useMemo, useRef, useState } from "react";
import { wrapRequestPayload } from "../../../helpers/request/RequestPayload";
import { getPageRequestPublishTopic, getPageSubscriptionTopic } from "hooks/MQTTConstants";
import { useLocation } from "react-router-dom";
import { SocketTopics } from "constants/enums";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { useDispatch } from "react-redux";
import { CLEAR_SUMMARY } from "reducers/reducer";
import { attributeKeyGenerator } from "utils/appUtil";
import { generateUUID } from "utils/appUtil";
import { GET_AGGREGATE } from "../../../reducers/reducer";
import useSocketActions from "../../../hooks/socketActions";

import Geocode from "react-geocode";
import { reverseGeocodeAddress } from "utils/placeName";
import {
  findGpsWindow,
  formatDateTime,
  formatDuration,
  gpsHistoryRequest,
  gpsWindowKey,
  LatLng,
  staticRouteMapUrl,
  toLatLng,
  tripStats,
  tripTimes,
} from "./tripReport";
import { InfoItem, InfoList, KpiStrip, LocationRow, ReportCard, ReportHeader } from "./TripReportParts";

Geocode.setApiKey("AIzaSyDgNagv_ozKWc6IQ75Ol4cH8fxdntOaW6M");
Geocode.setLanguage("en");
Geocode.setRegion("us");

const unitMap = {
  imperial: "miles",
  metric: "km",
};

// Meter fields that are not fare lines (amount is the Total row).
const FARE_SKIP = new Set(["amount", "unit", "currency", "waitIndex", "movingIndex"]);

const toNumber = (v: any) => (v === "" || v === null || v === undefined ? NaN : Number(v));

const formatMoney = (v: any, currency?: string) => {
  const n = toNumber(v);
  const text = Number.isFinite(n) ? n.toFixed(2) : `${v ?? "—"}`;
  return currency ? `${currency} ${text}` : text;
};

const hhmmss = (seconds: number) => new Date(seconds * 1000).toISOString().slice(11, 19);

interface FareLine {
  name: string;
  value: string;
}

const RideSummaryModal: FC<{ socket: ISocket; params?: any }> = ({ socket }) => {
  const { search } = useLocation();
  const { page, messages, gps } = useSelector((state: RootState) => state.auth);
  const dispatch = useDispatch();
  const [pickupAddress, setPickupAddress] = useState<string>("");
  const [dropOffAddress, setDropOffAddress] = useState<string>("");
  const { handleMessages } = useSocketActions();
  const requestedGps = useRef<string>("");

  const pageId = new URLSearchParams(search).get("pageId");
  const currentPage = page && page.objectId === pageId ? page : undefined;
  const s = currentPage?.persistent?.static;

  // results[0] is a plus code ("52CV+RM6, A5, Harare") wherever the point has
  // no street address, so the summary went out with a code instead of a place.
  // placeName ranks the results and composes road/suburb/city instead.
  const reverseGeocode = (point: LatLng | undefined, callback: (address: string) => void) => {
    if (!point) return;
    reverseGeocodeAddress({ lat: point.lat, long: point.lng }).then(
      (address) => {
        if (address) callback(address);
      },
      (error) => {
        console.error(error);
      }
    );
  };

  const getMessages = (pageId) => {
    const requestId = generateUUID();
    localStorage.setItem("requestId", requestId);
    localStorage.setItem("requestService", "summary");

    const messageRequest: any = {
      select: {
        index: {
          searchIndex: `${process.env.REACT_APP_ECO_SYSTEM}:message:createdAt`,
          searchQuery: `@pageId:{${pageId.toString()}}@type:{'gps\\-report'}`,
          searchOptions: "TIMEOUT 100",
        },
        load: { object: "$" },
      },
      operations: [
        {
          sortBy: {
            properties: [
              {
                field: "@createdAt",
                order: "DESC",
              },
            ],
          },
        },
      ],
      result: {
        pagination: {
          offset: 0,
          limit: 1,
        },
      },
      sortBy: {
        properties: [
          {
            field: "@createdAt",
            order: "DESC",
          },
        ],
        max: 10000,
      },
    };

    dispatch(
      GET_AGGREGATE({
        requestData: messageRequest,
        callback: (response) => {
          handleMessages(requestId, response);
        },
      })
    );
  };

  useEffect(() => {
    dispatch({ type: CLEAR_SUMMARY }); // also resets `gps`
    requestedGps.current = "";
    if (socket.client) {
      const query = new URLSearchParams(search);
      const connectionId = query.get("connectionId") || "0";
      const pageId = query.get("pageId");
      socket.subscribeToEvent(SocketTopics.SubscribePageTopics, getPageSubscriptionTopic(connectionId));
      if (pageId) {
        socket.publishToEvent(
          SocketTopics.PublishPageTopics,
          getPageRequestPublishTopic(connectionId),
          wrapRequestPayload(
            {
              objectId: pageId,
              paths: ["$"],
              returnPaths: ["$"],
            },
            pageId
          )
        );
        socket.subscribeToEvent(
          SocketTopics.SubscribePageTopics,
          `${process.env.REACT_APP_ECO_SYSTEM}/service/live/service/liveStorage/searchMessage/reply`
        );
      }
    }
  }, [search, socket.client]);

  const gpsWindow = useMemo(() => findGpsWindow(messages), [messages]);

  // Breadcrumbs for the report's GPS window, once per window.
  useEffect(() => {
    const requestData = gpsHistoryRequest(gpsWindow);
    const key = gpsWindowKey(gpsWindow);
    if (!requestData || requestedGps.current === key) return;
    requestedGps.current = key;
    dispatch({
      type: "GET_HISTORICAL_GPS",
      payload: { requestData },
    });
  }, [gpsWindow]);

  // Page arrived: load its report message and geocode the endpoints.
  useEffect(() => {
    if (!currentPage) return;
    getMessages(pageId);
    reverseGeocode(toLatLng(pickupLocation(currentPage)), setPickupAddress);
    reverseGeocode(toLatLng(dropoffLocation(currentPage)), setDropOffAddress);
  }, [currentPage]);

  const meterUnit = s?.profile?.meterDetails?.unit ?? s?.meter?.meterDetails?.unit;
  const stats = useMemo(() => tripStats(gps?.samples, meterUnit), [gps, meterUnit]);
  // Same wait the page shows: the meter's (seconds), else the GPS idle time.
  const meterWaitSec = toNumber(
    s?.profile?.meterDetails?.waitTime ?? s?.meter?.meterDetails?.waitTime
  );
  const waitMs = Number.isFinite(meterWaitSec) ? meterWaitSec * 1000 : stats?.waitMs;
  const times = useMemo(
    () => tripTimes({ page: currentPage, window: gpsWindow, points: stats?.track, waitMs }),
    [currentPage, gpsWindow, stats, waitMs]
  );

  const report = useMemo(() => (currentPage ? buildReport(currentPage) : undefined), [currentPage]);

  const pickup = currentPage ? pickupLocation(currentPage) : undefined;
  const dropoff = currentPage ? dropoffLocation(currentPage) : undefined;
  const mapUrl = useMemo(
    () =>
      staticRouteMapUrl({
        track: stats?.track,
        pickup: toLatLng(pickup),
        dropoff: toLatLng(dropoff),
      }),
    [stats, pickup, dropoff]
  );

  if (!currentPage || !report) {
    return (
      <main className="trip-report" aria-busy="true">
        <div className="trip-report__page">
          <p className="tr-loading">Loading ride summary…</p>
        </div>
      </main>
    );
  }

  const { meter, currency, distanceLabel, fareLines, travelInfo, rideInfo, fleet } = report;

  const meterDistance = toNumber(meter.movingDistance);
  const meterWait = toNumber(meter.waitTime);
  const distance = Number.isFinite(meterDistance)
    ? `${meterDistance.toFixed(1)} ${distanceLabel}`
    : stats
    ? `${stats.distance.toFixed(1)} ${stats.unit}`
    : undefined;
  const waitTime = Number.isFinite(meterWait)
    ? formatDuration(meterWait * 1000)
    : stats
    ? formatDuration(stats.waitMs)
    : undefined;

  const timeRows: InfoItem[] = [
    { name: "Start time", value: formatDateTime(times.start) },
    { name: "End time", value: formatDateTime(times.end) },
    { name: "Total time", value: formatDuration(times.totalMs) },
  ];

  return (
    <main className="trip-report">
      <div className="trip-report__page">
        <ReportHeader
          kicker="Ride summary"
          title={s?.metadata?.title}
          status={currentPage?.nonpersistent?.static?.live?.status?.name}
          subtitle={
            <>
              <span className="tr-header__id">Ride #{pageId}</span>
              <span className="tr-header__date">{formatDateTime(s?.metadata?.createdAt)}</span>
            </>
          }
        />

        <KpiStrip
          label="Ride totals"
          items={[
            { label: "Total fare", value: meter.amount !== undefined ? formatMoney(meter.amount, currency) : undefined },
            { label: "Distance", value: distance },
            { label: "Wait time", value: waitTime },
            { label: "Total time", value: formatDuration(times.totalMs) },
          ]}
        />

        <div className="tr-grid">
          <div className="tr-col">
            <ReportCard id="ride-info" title="Ride information">
              <InfoList items={[...rideInfo, ...timeRows]} />
            </ReportCard>

            <ReportCard id="travel-info" title="Travel information">
              <InfoList items={travelInfo} empty="No travel details recorded" />
            </ReportCard>

            <ReportCard id="fare" title="Fare breakdown">
              <table className="tr-table tr-fare">
                <caption className="tr-sr-only">Fare breakdown{currency ? ` in ${currency}` : ""}</caption>
                <thead>
                  <tr>
                    <th scope="col">Item</th>
                    <th scope="col" className="tr-num">
                      Amount
                    </th>
                  </tr>
                </thead>
                <tbody>
                  {fareLines.map((line) => (
                    <tr key={line.name}>
                      <th scope="row">{line.name}</th>
                      <td className="tr-num">{line.value}</td>
                    </tr>
                  ))}
                </tbody>
                <tfoot>
                  <tr className="tr-fare__total">
                    <th scope="row">Total</th>
                    <td className="tr-num">{formatMoney(meter.amount ?? 0, currency)}</td>
                  </tr>
                </tfoot>
              </table>
            </ReportCard>
          </div>

          <div className="tr-col">
            <ReportCard id="locations" title="Locations">
              {mapUrl && (
                <figure className="tr-map">
                  <img
                    src={mapUrl}
                    alt={`Route map from ${pickupAddress || "pickup"} to ${dropOffAddress || "dropoff"}`}
                  />
                  {stats && (
                    <figcaption>
                      GPS route · {stats.track.length} points · {stats.totalDistance.toFixed(1)} {stats.unit}
                    </figcaption>
                  )}
                </figure>
              )}
              <ul className="tr-locations">
                <LocationRow tone="green" title="Pickup location" location={pickup} address={pickupAddress} />
                <LocationRow tone="blue" title="Dropoff location" location={dropoff} address={dropOffAddress} />
              </ul>
            </ReportCard>

            <ReportCard id="fleet" title="Fleet information">
              {fleet.logo && (
                <img className="tr-fleet__logo" src={fleet.logo} alt={`${fleet.companyName ?? "Fleet"} logo`} />
              )}
              <InfoList
                items={[
                  { name: "Company name", value: fleet.companyName ?? "N/A" },
                  { name: "Company address", value: fleet.address ?? "N/A" },
                ]}
              />
              {fleet.comment && <p className="tr-note">{fleet.comment}</p>}
            </ReportCard>
          </div>
        </div>
      </div>
    </main>
  );
};

const pickupLocation = (page: any) =>
  page?.persistent?.static?.profile?.pickupLocation ||
  page?.persistent?.static?.dashboard?.pickupLocation ||
  page?.persistent?.static?.live?.location;

// The profile stores the end coordinates directly, the meter wraps them in a
// location object; toLatLng / LocationRow read both.
const dropoffLocation = (page: any) =>
  page?.persistent?.static?.profile?.tripDetails?.end?.location ||
  page?.persistent?.static?.meter?.tripDetails?.end?.location;

/** Static sections of the report from the page (no GPS involved). */
const buildReport = (page: any) => {
  const pageStatic = page?.persistent?.static ?? {};
  const onMove = {
    ...(pageStatic.profile || {}),
    ...(pageStatic.ride || {}),
    ...(page?.persistent?.dynamic?.ride || {}),
    ...(pageStatic.dashboard || {}),
    ...(pageStatic.meter || {}),
  };
  const type = onMove.type;
  delete onMove.summary;
  delete onMove.type;

  // Placeholders first; real values with the same label replace them.
  const info = new Map<string, any>();
  info.set("Ride type", type === "cad" ? "CAD" : "Hail ride");
  if (type !== "cad") {
    ["First Name", "Last Name", "Phone", "Alternative Phone"].forEach((name) => info.set(name, "N/A"));
  }
  Object.keys(onMove).forEach((key) => {
    if (typeof onMove[key] === "string" && onMove[key] !== "") {
      info.set(attributeKeyGenerator(key), onMove[key]);
    }
  });
  const rideInfo: InfoItem[] = Array.from(info.entries()).map(([name, value]) => ({ name, value }));

  const trip = pageStatic.profile?.tripDetails || pageStatic.meter?.tripDetails || {};
  const travelInfo: InfoItem[] = Object.keys(trip)
    .filter((key) => typeof trip[key] === "string" || typeof trip[key] === "number")
    .map((key) => ({ name: attributeKeyGenerator(key), value: trip[key] }));

  // Copy: never mutate the page in the store.
  const meter = { ...(pageStatic.profile?.meterDetails || pageStatic.meter?.meterDetails || {}) };
  const currency: string | undefined = meter.currency;
  const distanceLabel = unitMap[meter.unit] ?? unitMap.metric;
  const fareLines: FareLine[] = [];
  Object.keys(meter).forEach((key) => {
    const raw = meter[key];
    if (FARE_SKIP.has(key) || (typeof raw !== "string" && typeof raw !== "number")) return;
    const n = toNumber(raw);
    if (raw === "" || n === 0) return; // hide empty / zero lines
    let value: string;
    if (key === "movingDistance") value = Number.isFinite(n) ? `${n.toFixed(1)} ${distanceLabel}` : `${raw}`;
    else if (key === "waitTime") value = Number.isFinite(n) ? hhmmss(n) : `${raw}`;
    else if (key === "tip") value = formatMoney(Math.round(n), currency);
    else value = Number.isFinite(n) ? formatMoney(n, currency) : `${raw}`;
    fareLines.push({ name: attributeKeyGenerator(key), value });
  });

  const fleetDetails = pageStatic.profile?.fleetDetails || pageStatic.meter?.fleetDetailsCopy || {};
  const fleet = {
    logo: fleetDetails?.logoImage?.urls?.original?.url as string | undefined,
    companyName: fleetDetails?.companyName as string | undefined,
    address: fleetDetails?.location?.attributes?.address as string | undefined,
    comment: (fleetDetails?.comment || "") as string,
  };

  return { meter, currency, distanceLabel, fareLines, travelInfo, rideInfo, fleet };
};

export default RideSummaryModal;
