import React, { FC } from "react";

import { ScholarshipRule } from "../../types";
import { AmountRuleFields, FormRow, NullableNumberField, SwitchField, TextField } from "../fields";
import { SectionProps } from "./types";

const ScholarshipSection: FC<SectionProps> = ({ config, patch, disabled }) => {
  const s = config.scholarship;
  const patchS = (changes: Partial<ScholarshipRule>) => patch({ scholarship: { ...s, ...changes } });

  return (
    <>
      <SwitchField
        label="Offer scholarships on this plan"
        checked={s.enabled}
        disabled={disabled}
        onChange={(enabled) => patchS({ enabled })}
      />
      {s.enabled && (
        <>
          <FormRow>
            <AmountRuleFields
              value={s}
              currency={config.currency}
              valueLabel="Maximum award value"
              disabled={disabled}
              onChange={(rule) => patchS(rule)}
            />
            <NullableNumberField
              label="Max number of awards (blank = unlimited)"
              min={1}
              value={s.maxAwards}
              disabled={disabled}
              onChange={(maxAwards) => patchS({ maxAwards })}
            />
          </FormRow>
          <FormRow>
            <SwitchField
              label="Requires admin approval"
              checked={s.requiresApproval}
              disabled={disabled}
              onChange={(requiresApproval) => patchS({ requiresApproval })}
            />
            <SwitchField
              label="Requires proof documents"
              checked={s.requiresDocuments}
              disabled={disabled}
              onChange={(requiresDocuments) => patchS({ requiresDocuments })}
            />
          </FormRow>
          <TextField
            label="Note shown to applicants"
            rows={2}
            value={s.note}
            disabled={disabled}
            onChange={(note) => patchS({ note })}
          />
        </>
      )}
    </>
  );
};

export default ScholarshipSection;
