import React, { FC, useEffect, useMemo, useState } from "react";
import {
  Modal,
  Form,
  Row,
  Col,
  Button,
  Table,
  Radio,
  DatePicker,
  Tag,
} from "antd";
import moment from "moment";

// Manage per-date attendance for the students of a single class (project).
// Attendance is stored on the project object under:
//   attendance: { [YYYY-MM-DD]: { [studentId]: { status, markedAt, markedBy } } }
const AttendanceModal: FC<{
  visible: boolean;
  classData: any;
  usersMap: any;
  markedBy?: any;
  saving?: boolean;
  onClose: () => void;
  // Receives the full updated project object to persist (replace op upstream).
  onSave: (updatedProject: any) => void;
}> = ({ visible, classData, usersMap, markedBy, saving, onClose, onSave }) => {
  const [date, setDate] = useState<any>(moment());
  // statusMap: { [studentId]: "present" | "absent" | "late" } for the chosen date
  const [statusMap, setStatusMap] = useState<any>({});

  const studentIds: any[] = useMemo(
    () => classData?.liveUserIds || [],
    [classData]
  );

  const nameOf = (id: any) => usersMap?.[id?.toString()] || `#${id}`;

  // Load the saved statuses whenever the date or class changes.
  useEffect(() => {
    if (!visible) return;
    const dateKey = date?.format("YYYY-MM-DD");
    const dayRecord = classData?.attendance?.[dateKey] || {};
    const next: any = {};
    Object.keys(dayRecord).forEach((sid) => {
      next[sid] = dayRecord[sid]?.status;
    });
    setStatusMap(next);
  }, [visible, date, classData]);

  const setStatus = (studentId: any, status: string) => {
    setStatusMap((prev: any) => ({ ...prev, [studentId?.toString()]: status }));
  };

  const summary = useMemo(() => {
    const counts = { present: 0, absent: 0, late: 0 };
    Object.values(statusMap).forEach((s: any) => {
      if (counts[s] !== undefined) counts[s] += 1;
    });
    return counts;
  }, [statusMap]);

  const handleSave = () => {
    const dateKey = date?.format("YYYY-MM-DD");
    if (!dateKey) return;
    const markedAt = new Date().getTime();
    const dayRecord: any = {};
    studentIds.forEach((sid) => {
      const status = statusMap?.[sid?.toString()];
      if (status) {
        dayRecord[sid?.toString()] = { status, markedAt, markedBy };
      }
    });
    const updatedProject = {
      ...classData,
      attendance: {
        ...(classData?.attendance || {}),
        [dateKey]: dayRecord,
      },
    };
    onSave(updatedProject);
  };

  const columns = [
    {
      title: "Student",
      key: "name",
      dataIndex: "name",
    },
    {
      title: "Attendance",
      key: "status",
      render: (_: any, record: any) => (
        <Radio.Group
          size="small"
          optionType="button"
          buttonStyle="solid"
          value={statusMap?.[record?.id?.toString()]}
          onChange={(e) => setStatus(record?.id, e.target.value)}
        >
          <Radio.Button value="present">Present</Radio.Button>
          <Radio.Button value="absent">Absent</Radio.Button>
          <Radio.Button value="late">Late</Radio.Button>
        </Radio.Group>
      ),
    },
  ];

  const dataSource = studentIds.map((id) => ({
    key: id,
    id,
    name: nameOf(id),
  }));

  return (
    <Modal
      title={
        classData?.name ? `Attendance — ${classData.name}` : "Attendance"
      }
      visible={visible}
      onCancel={onClose}
      width="640px"
      className="beam-modal"
      footer={[]}
      destroyOnClose
    >
      <Form className="auth-form" layout="vertical" requiredMark={false}>
        <Row gutter={16} align="middle">
          <Col xs={24} sm={12}>
            <Form.Item label="Date" className="mb-2">
              <DatePicker
                allowClear={false}
                value={date}
                onChange={(d) => d && setDate(d)}
                format="YYYY-MM-DD"
                disabledDate={(current) =>
                  current && current > moment().endOf("day")
                }
                style={{ width: "100%" }}
              />
            </Form.Item>
          </Col>
          <Col xs={24} sm={12} className="d-flex align-items-end">
            <div style={{ paddingBottom: 8 }}>
              <Tag color="green">Present: {summary.present}</Tag>
              <Tag color="red">Absent: {summary.absent}</Tag>
              <Tag color="orange">Late: {summary.late}</Tag>
            </div>
          </Col>
        </Row>

        <Table
          dataSource={dataSource}
          columns={columns}
          pagination={false}
          scroll={{ y: 320 }}
          locale={{ emptyText: "No students in this class" }}
        />

        <Form.Item className="action-grp mt-4">
          <Row>
            <Col span={14} className="pr-2">
              <Button
                loading={saving}
                disabled={!studentIds.length}
                className="beam-btn green-btn cover w-full"
                onClick={handleSave}
              >
                Save attendance
              </Button>
            </Col>
            <Col span={10} className="pl-2">
              <Button
                className="beam-btn orange-btn bordered w-full"
                onClick={onClose}
              >
                Cancel
              </Button>
            </Col>
          </Row>
        </Form.Item>
      </Form>
    </Modal>
  );
};

export default AttendanceModal;
