import React, { useEffect, useState } from "react";
import { Row, Col, Checkbox, Input, Button, DatePicker } from "antd";
import RenderFields from "../RenderFields";
import { ArrowRightOutlined, DeleteOutlined, DownOutlined } from "@ant-design/icons";
import _ from "lodash";
import moment from "moment";


const RelationInput: React.FC<any> = ({
  value,
  placeholder,
  options,
  onChange,
  socket,
  disabled = false,
}) => {
    const [choiceCount, setChoiceCount] = useState<number>(1);
    const [val, setVal] = useState<any>(value || [{name: "", relation: "", dateOfBirth: ""}]);

    useEffect(()=>{
    if(value){
      setVal(value);
    }
    }, [value])
  
  return (
    <React.Fragment>
    <span className="col-label">{placeholder}</span>
    <Row className="tiles">
          { _.times(val?.length || choiceCount, (i) => {
            return (
                <Col span={24}>
              <Row>
                <Col span={6} key={`name-${i}`} className="mb-3">
                  <Input
                    disabled={disabled}
                    value={val[i]?.name}
                    className="beam-input"
                    placeholder="Family member name"
                    onChange={(e) => {
                      const updatedVal = [...val]; 
                      updatedVal[i] = { ...updatedVal[i], name: e.target.value }; 
                      setVal(updatedVal); 
                      onChange(updatedVal); 
                    }}
                  />
                </Col>
                <Col span={2} className="d-flex justify-content-center">
                  <ArrowRightOutlined style={{ fontSize: "18px", color: "#555" }} />
                </Col>
                <Col span={6} key={`relation-${i}`} className="mb-3">
                  <Input
                    disabled={disabled}
                    value={val[i]?.relation}
                    placeholder="Enter Relation"
                    className="beam-input"
                    onChange={(e) => {
                      const updatedVal = [...val]; 
                      updatedVal[i] = { ...updatedVal[i], relation: e.target.value };
                      setVal(updatedVal); 
                      onChange(updatedVal);
                    }}
                  />
                </Col>
                <Col span={6} key={`dateOfBirth-${i}`} className="ml-2 mb-3">
                 <div className="datetime-item">
                 <img src="/images/date.png" />
                <DatePicker
                   disabled={disabled}
                   value={val[i]?.dateOfBirth ? moment(val[i]?.dateOfBirth, "MM/DD/YYYY HH:mm:ss") : undefined}
                   onChange={(date: moment.Moment | null) => {
                    const updatedVal = [...val]; 
                    updatedVal[i] = { ...updatedVal[i], dateOfBirth: date?.format("MM/DD/YYYY HH:mm:ss") };
                    setVal(updatedVal); 
                    onChange(updatedVal);
            }}
                    placeholder="Date of birth"
                    suffixIcon={<DownOutlined />}
                />
                </div>
              </Col>
               
                { !disabled && <Col span={2} className="t-right pl-2">
                  <Button
                    className="beam-btn"
                    onClick={() => {
                      if (val.length > 1) { 
                        const updatedVal = [...val]; 
                        updatedVal.splice(i, 1); 
                        setVal(updatedVal); 
                        onChange(updatedVal); 
                      }
                    }}
                  >
                    <DeleteOutlined />
                  </Button>
                </Col>}
             
              </Row>
              </Col>
            );
          })}
        
          {!disabled && <Col span={24} className="t-right">
            <Button
              className="beam-btn"
              onClick={() => {
                const updatedVal = [...val, { name: "", relation: "" }];
                setVal(updatedVal);
                onChange(updatedVal);
              }}
            >
              Add
            </Button>
          </Col>}
        
        </Row>
  </React.Fragment>
);
};

export default RelationInput;
