"use strict";
import React, { FC, useEffect, useRef, useState, Component } from "react";
import { Link, useLocation } from "react-router-dom";
import { Input, Button, Modal, Row, Col, Upload } from "antd";
import _ from "lodash";
import { useDispatch, useSelector } from "react-redux";
import { UPLOAD_MEDIA } from "../reducers/reducer";
import { RootState } from "reducers/rootReducer";
import SignatureCanvas from 'react-signature-canvas';


const UploadSignatureModal: FC<{ isBio?: boolean, onClose?: () => void, onUploadSignature: any }> = ({ isBio, onClose, onUploadSignature }) => {
  const [isModalVisible, setIsModalVisible] = useState<boolean>(true);
  const [fileList, setFileList] = useState<any>([]);
  const [geoLocation, setGeoLocation] = useState<any>();
  const location = useLocation();
  const [file, setFile] = useState<any>("");
  const { userBds } = useSelector((state: RootState) => state.auth);
  const [saving, setSaving] = useState<boolean>(false);
  // const { fileToSend } = useSelector((state: RootState) => state.message);
  const { fileToSend } = useSelector((state: RootState) => state.auth);
  const sentCount = useRef(0);
  const canvasRef = useRef<any>();


  const handleCancel = () => {
    setIsModalVisible(false);
    onClose && onClose();
  };

  const dataURItoBlob = (dataURI) => {
    // convert base64/URLEncoded data component to raw binary data held in a string
    var byteString;
    if (dataURI.split(',')[0].indexOf('base64') >= 0)
      byteString = atob(dataURI.split(',')[1]);
    else
      byteString = unescape(dataURI.split(',')[1]);

    var mimeString = dataURI.split(',')[0].split(':')[1].split(';')[0];

    var ia = new Uint8Array(byteString.length);
    for (var i = 0; i < byteString.length; i++) {
      ia[i] = byteString.charCodeAt(i);
    }
    return new Blob([ia], { type: mimeString });
  }

  const dispatch = useDispatch();
  const handleOk = () => {
    const dataUri = canvasRef.current.getTrimmedCanvas().toDataURL('image/png');
    const fileBlob = dataURItoBlob(dataUri);
    const dateTime = new Date().getTime();
    const queryParams = new URLSearchParams(location.search);
    const customerId = queryParams.get("customerId");
    const userId = queryParams.get("userId");
    const serviceId = queryParams.get("serviceId");

    let form = new FormData();
    form.append("file", fileBlob, `signature-${dateTime}.png`);
    form.append("info", JSON.stringify({
      customerId, userId, location: geoLocation ? {
        coordinates: geoLocation, clbs: {
          tags: ['type:media', `org:${serviceId}`, `signature-${dateTime}.png`]
        }
      } : undefined
    }));
    dispatch(UPLOAD_MEDIA({ form, isBio: false }));
    setSaving(true);
  };

  useEffect(() => {
    getCurrentLocation()
  }, []);

  useEffect(() => {
    if (fileToSend) {
      console.log({ fileToSend });
      setIsModalVisible(false);
      onClose && onClose();
      setSaving(false);
      const image = {
        name: fileToSend?.media?.originalName,
        url: fileToSend?.media?.urls?.original?.url,
        ...fileToSend?.media,
      };
      onUploadSignature({ files: [image] });
      //  sentCount.current += 1;
      // if(sentCount.current === fileList.length){
      //   setIsModalVisible(false);
      //   onClose && onClose();
      //   setSaving(false);
      // }
    }
  }, [fileToSend]);

  const getCurrentLocation = () => {
    return new Promise((resolve, reject) => {
      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition((position) => {
          setGeoLocation({
            lat: position?.coords?.latitude,
            long: position?.coords?.longitude,
          });
        });
      } else {
        reject("Geolocation is not supported by this browser.");
      }
    });
  };

  useEffect(() => {
    getCurrentLocation()
  }, []);

  return (
    <Modal
      title="Add a signature"
      visible={isModalVisible}
      onOk={handleOk}
      onCancel={handleCancel}
      width="480px"
      className="beam-modal"
      footer={[]}
      destroyOnClose={true}
    >
      <SignatureCanvas ref={(ref) => { canvasRef.current = ref }} penColor='black' backgroundColor='white'
        canvasProps={{ width: 420, height: 200, className: 'sigCanvas' }} />

      <Row className="action-grp mt-4">
        <Col span={14} className="pr-2">
          <Button
            className="beam-btn green-btn cover w-full"
            onClick={handleOk}
            loading={saving}
          >
            Upload
          </Button>
        </Col>
        <Col span={10} className="pl-2">
          <Button
            className="beam-btn orange-btn bordered w-full"
            onClick={handleCancel}
          >
            Cancel
          </Button>
        </Col>
      </Row>
    </Modal>
  );
};

export default UploadSignatureModal;
