/**
 * Public programs page: the shape of a section and the copy for the ones we
 * know by name.
 *
 * The section list itself is **not** fixed. It is built at runtime from the
 * event-type widget of the organization's `project:extendedBio` form (see
 * `api/mapEvents#buildSections`), so an admin adding a new program in the
 * form builder adds a sidebar entry without a code change.
 *
 * Two slugs are special: `recreational` and `traveler` embed the CPC sign-up
 * form. Every other section lists the event projects whose event-type answer
 * is that section.
 */

export type ProgramLevel = "rec" | "travel";

export type SectionKind = "form" | "events";

export interface SectionStep {
  title: string;
  detail: string;
}

export interface SectionDef {
  /** URL slug: `/programs/<id>`. */
  id: string;
  /**
   * The event-type answer this section lists, exactly as the form stores it
   * ("Special Events"). Absent on the two sign-up sections.
   */
  answer?: string;
  label: string;
  /** One-line hint under the label in the sidebar. */
  hint: string;
  eyebrow: string;
  title: string;
  description: string;
  kind: SectionKind;
  /** The path from the slide; only the sign-up sections have one. */
  steps: SectionStep[];
}

/** `Special Events` -> `special-events`, so a program name can be a URL. */
export const slugify = (value: string): string =>
  value
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

