import moment from "moment-timezone";
import { SocketTopics } from "constants/enums";
import { generateUUID } from "utils/appUtil";

// Shared plumbing for keeping the dispatch panel and the dashboards in sync
// with the ride service: one fan-out for ridePageUpdated events, updatedAt
// helpers, request ids and ride-service error codes.

export const GOOGLE_MAPS_KEY = process.env.REACT_APP_GOOGLE_MAPS_KEY || "";
if (!GOOGLE_MAPS_KEY) {
  console.warn("REACT_APP_GOOGLE_MAPS_KEY is not set; maps and geocoding will fail");
}

// Opt-in console logging of raw socket traffic (set REACT_APP_SOCKET_DEBUG=true
// or localStorage.socketDebug = "1").
export const isSocketDebug = () => {
  if (process.env.REACT_APP_SOCKET_DEBUG === "true") return true;
  try {
    return localStorage.getItem("socketDebug") === "1";
  } catch (e) {
    return false;
  }
};

// ---------------------------------------------------------------------------
// ridePageUpdated fan-out
// ---------------------------------------------------------------------------

export interface RidePageUpdatedEvent {
  pageId: string;
  // Optional (newer ride service): { pageId, status, updatedAt }.
  meta?: { pageId?: any; status?: string; updatedAt?: number };
  // Optional (newer ride service): the ride as the dashboard loads it
  // ({ pageId, updatedAt, persistent, nonpersistent }, same shape as a
  // getPageById result), so it can be applied without a fetch.
  row?: any;
}

type RidePageListener = (event: RidePageUpdatedEvent) => void;

const RIDE_EVENTS_COMPONENT_UUID = "ride-page-events";
const ridePageListeners: { [topic: string]: Set<RidePageListener> } = {};
const registeredTopics = new Set<string>();

export const getRidePageUpdatedTopic = (userId: any) =>
  `${process.env.REACT_APP_ECO_SYSTEM}/service/live/user/${userId}/ridePageUpdated`;

// Every consumer (each dashboard table, the dispatch panel) shares ONE socket
// callback per topic and gets the event through this fan-out. Returns an
// unsubscribe so unmounted components stop receiving events.
export const subscribeRidePageUpdated = (
  socket: ISocket,
  userId: any,
  listener: RidePageListener
) => {
  if (!userId) return () => {};
  const topic = getRidePageUpdatedTopic(userId);
  if (!ridePageListeners[topic]) ridePageListeners[topic] = new Set();
  ridePageListeners[topic].add(listener);
  if (!registeredTopics.has(topic)) {
    registeredTopics.add(topic);
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      topic,
      (response: any) => {
        const pageId = response?.data?.toString?.();
        if (!pageId) return;
        const row =
          response?.row &&
          typeof response.row === "object" &&
          response.row.pageId?.toString() === pageId
            ? response.row
            : undefined;
        const event: RidePageUpdatedEvent = {
          pageId,
          meta: response?.meta,
          row,
        };
        Array.from(ridePageListeners[topic] || []).forEach((fn) => {
          try {
            fn(event);
          } catch (e) {
            console.error("ridePageUpdated listener failed", e);
          }
        });
      },
      RIDE_EVENTS_COMPONENT_UUID
    );
  }
  return () => {
    ridePageListeners[topic]?.delete(listener);
  };
};

// ---------------------------------------------------------------------------
// Ride submissions in flight (optimistic dashboard rows)
// ---------------------------------------------------------------------------

export interface RideSubmissionEvent {
  id: string;
  // pending: request sent; failed: show Retry; done: replace the placeholder
  // with the ride's row (`pageId`, when the ride service returned one).
  state: "pending" | "failed" | "done";
  pageId?: string;
  summary?: {
    pickup?: string;
    dropoff?: string;
    passengerName?: string;
    passengerPhoneNumber?: string;
    leg?: string;
  };
  message?: string;
  retry?: () => void;
}

const submissionListeners = new Set<(event: RideSubmissionEvent) => void>();

export const emitRideSubmission = (event: RideSubmissionEvent) => {
  Array.from(submissionListeners).forEach((fn) => {
    try {
      fn(event);
    } catch (e) {
      console.error("ride submission listener failed", e);
    }
  });
};

export const subscribeRideSubmissions = (
  listener: (event: RideSubmissionEvent) => void
) => {
  submissionListeners.add(listener);
  return () => {
    submissionListeners.delete(listener);
  };
};

// ---------------------------------------------------------------------------
// updatedAt
// ---------------------------------------------------------------------------

const toMs = (value: any): number | undefined => {
  const n = Number(value);
  return Number.isFinite(n) && n > 0 ? n : undefined;
};

// Last-modified time of a ride page in any of the shapes the dashboard and the
// panel hold (search row with a loaded `updatedAt`, or a full page document).
export const getPageUpdatedAt = (page: any): number | undefined =>
  toMs(page?.updatedAt) ??
  toMs(page?.nonpersistent?.dynamic?.metadata?.lastSent?.members?.updatedAt) ??
  toMs(page?.page?.updatedAt);

// ---------------------------------------------------------------------------
// Request ids
// ---------------------------------------------------------------------------

export const newClientRequestId = (): string => {
  try {
    const c: any = typeof window !== "undefined" ? (window as any).crypto : undefined;
    if (c?.randomUUID) return c.randomUUID();
  } catch (e) {}
  return generateUUID();
};

export const RETURN_LEG_SUFFIX = ":ret";
export const OUTBOUND_LEG_SUFFIX = ":out";

export const legLabel = (clientRequestId?: string) =>
  clientRequestId?.endsWith(RETURN_LEG_SUFFIX) ? "Return trip" : "Outbound trip";

// ---------------------------------------------------------------------------
// Ride service errors (HTTP 200 { status:false, message, data:{details, code} })
// ---------------------------------------------------------------------------

export const RideErrorCode = {
  InvalidState: "INVALID_STATE",
  StaleUpdate: "STALE_UPDATE",
  DuplicateInProgress: "DUPLICATE_IN_PROGRESS",
  NotAssignedDriver: "NOT_ASSIGNED_DRIVER",
  InvalidAmount: "INVALID_AMOUNT",
  OfferExpired: "OFFER_EXPIRED",
  Timeout: "TIMEOUT",
};

const CODE_MESSAGES: { [code: string]: string } = {
  [RideErrorCode.InvalidState]: "Ride already completed/cancelled",
  [RideErrorCode.StaleUpdate]:
    "This ride was changed by someone else. The latest version has been loaded — review and submit again.",
  [RideErrorCode.DuplicateInProgress]: "Already submitting… please wait",
  [RideErrorCode.Timeout]:
    "The ride service did not respond in time. Check the rides list, then retry.",
};

export interface RideResponseMeta {
  status?: boolean;
  message?: string;
  code?: string;
}

// Normalises a CREATE_RIDE / CANCEL_RIDE callback into ok / code / message.
// `data` is the reply's data, `meta` the envelope (absent on older callers).
// `preferDetails` keeps the server's wording for INVALID_STATE (an update of a
// started ride is not "completed/cancelled").
export const parseRideResponse = (
  data: any,
  meta?: RideResponseMeta,
  opts: { preferDetails?: boolean } = {}
) => {
  const code: string | undefined = data?.code ?? meta?.code;
  const failed = meta?.status === false || data?.status === false || !!code;
  const details =
    typeof data?.details === "string" && data.details ? data.details : undefined;
  const mapped = code ? CODE_MESSAGES[code] : undefined;
  const message =
    (opts.preferDetails && code === RideErrorCode.InvalidState
      ? details || mapped
      : mapped || details) ||
    meta?.message ||
    (typeof data === "string" ? data : undefined);
  return { ok: !failed, code, message };
};

// ---------------------------------------------------------------------------
// Scheduling
// ---------------------------------------------------------------------------

// The fleet's IANA timezone when the org settings expose one; otherwise the
// browser's zone is used (undefined).
export const getFleetTimezone = (projects: any): string | undefined => {
  const tz =
    projects?.timezone ||
    projects?.timeZone ||
    projects?.webSettings?.timezone ||
    projects?.webSettings?.timeZone;
  return typeof tz === "string" && moment.tz.zone(tz) ? tz : undefined;
};

// Pickup instant (epoch ms, seconds/ms zeroed) from a schedule field value
// ({ date: 'MM/DD/YYYY', time: 'HH:mm', dateTimestamp, timeTimestamp }).
export const buildScheduledInstant = (
  schedule: any,
  timezone?: string
): number | undefined => {
  if (schedule?.date && schedule?.time) {
    const parsed = timezone
      ? moment.tz(`${schedule.date} ${schedule.time}`, "MM/DD/YYYY HH:mm", true, timezone)
      : moment(`${schedule.date} ${schedule.time}`, "MM/DD/YYYY HH:mm", true);
    if (parsed.isValid()) return parsed.seconds(0).milliseconds(0).valueOf();
  }
  if (schedule?.dateTimestamp && schedule?.timeTimestamp) {
    const date = new Date(schedule.dateTimestamp);
    const time = new Date(schedule.timeTimestamp);
    date.setHours(time.getHours(), time.getMinutes(), 0, 0);
    return date.getTime();
  }
  return undefined;
};
