import React, { FC, useMemo, useState } from "react";
import {
  Button,
  Col,
  Input,
  Popconfirm,
  Radio,
  Row,
  Switch,
  Table,
  Tag,
  Tooltip,
} from "antd";
import { DeleteOutlined, EditOutlined, PlusOutlined, SearchOutlined } from "@ant-design/icons";
import { deleteResource, updateResource } from "services/apis/collections/aiSchedulerApis";
import { getErrorMessage } from "services/apis/aiSchedulerClient";
import { OrgSettings, SchedResource, TimeWindow } from "services/apis/aiSchedulerTypes";
import { pushNotification } from "utils/notifications";
import ResourceFormModal from "./ResourceFormModal";

const describeWindows = (windows?: TimeWindow[]): string => {
  if (!windows?.length) return "Always";
  return windows
    .map((w) => `${(w.days || []).map((d) => d.charAt(0).toUpperCase() + d.slice(1, 3)).join(",")} ${w.start}–${w.end}`)
    .join(" · ");
};

const ResourcesTab: FC<{
  orgId: string;
  resources: SchedResource[];
  settings?: OrgSettings;
  refetch: () => Promise<void>;
}> = ({ orgId, resources, settings, refetch }) => {
  const [search, setSearch] = useState("");
  const [kindFilter, setKindFilter] = useState<string | undefined>(undefined);
  const [editing, setEditing] = useState<SchedResource | undefined>(undefined);
  const [creating, setCreating] = useState(false);
  const [togglingId, setTogglingId] = useState<string | undefined>(undefined);

  const knownKinds = useMemo(
    () => Array.from(new Set(resources.map((r) => r.kind).filter(Boolean))),
    [resources]
  );
  const knownLocations = useMemo(
    () => Array.from(new Set(resources.map((r) => r.location).filter(Boolean))) as string[],
    [resources]
  );

  const filtered = useMemo(
    () =>
      resources.filter(
        (r) =>
          (!kindFilter || r.kind === kindFilter) &&
          (!search || r.name?.toLowerCase().includes(search.toLowerCase()))
      ),
    [resources, search, kindFilter]
  );

  const toggleActive = async (r: SchedResource, active: boolean) => {
    if (!r.id) return;
    setTogglingId(r.id);
    try {
      await updateResource(orgId, r.id, { ...r, active });
      await refetch();
      pushNotification(
        active ? `${r.name} is back in scheduling` : `${r.name} pulled out of scheduling`,
        "success",
        "TOP_CENTER",
        2000
      );
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    } finally {
      setTogglingId(undefined);
    }
  };

  const handleDelete = async (r: SchedResource) => {
    if (!r.id) return;
    try {
      await deleteResource(orgId, r.id);
      await refetch();
      pushNotification(`${r.name} deleted`, "success", "TOP_CENTER", 2000);
    } catch (e) {
      pushNotification(getErrorMessage(e), "error", "TOP_CENTER", 4000);
    }
  };

  const columns = [
    {
      title: "Name",
      dataIndex: "name",
      key: "name",
      sorter: (a: SchedResource, b: SchedResource) => (a.name || "").localeCompare(b.name || ""),
    },
    {
      title: "Kind",
      dataIndex: "kind",
      key: "kind",
      render: (kind: string) => <Tag color="blue">{kind}</Tag>,
    },
    {
      title: "Capacity",
      dataIndex: "capacity",
      key: "capacity",
      render: (c?: number) => c ?? "—",
    },
    {
      title: "Qty",
      dataIndex: "quantity",
      key: "quantity",
      render: (q?: number) => q ?? 1,
    },
    {
      title: "Location",
      dataIndex: "location",
      key: "location",
      render: (l?: string) => l || "—",
    },
    {
      title: "Tags",
      dataIndex: "tags",
      key: "tags",
      render: (tags?: string[]) =>
        tags?.length ? tags.map((t) => <Tag key={t}>{t}</Tag>) : "—",
    },
    {
      title: "Availability",
      dataIndex: "availability",
      key: "availability",
      render: (w?: TimeWindow[]) => (
        <Tooltip title={describeWindows(w)}>
          <span>{w?.length ? `${w.length} window${w.length > 1 ? "s" : ""}` : "Always"}</span>
        </Tooltip>
      ),
    },
    {
      title: "Buffer",
      dataIndex: "bufferMinutes",
      key: "bufferMinutes",
      render: (b?: number) => (b ? `${b} min` : "—"),
    },
    {
      title: "Active",
      dataIndex: "active",
      key: "active",
      render: (_: any, r: SchedResource) => (
        <Switch
          size="small"
          checked={r.active !== false}
          loading={togglingId === r.id}
          onChange={(checked) => toggleActive(r, checked)}
        />
      ),
    },
    {
      title: "",
      key: "actions",
      render: (_: any, r: SchedResource) => (
        <div style={{ display: "flex", gap: 8 }}>
          <Button
            className="beam-btn icon-btn cover"
            icon={<EditOutlined />}
            onClick={() => setEditing(r)}
          />
          <Popconfirm
            title={`Delete ${r.name}?`}
            okText="Delete"
            okButtonProps={{ danger: true }}
            onConfirm={() => handleDelete(r)}
          >
            <Button className="beam-btn icon-btn cover" icon={<DeleteOutlined />} />
          </Popconfirm>
        </div>
      ),
    },
  ];

  return (
    <div className="scheduler-tab">
      <Row gutter={[12, 12]} align="middle">
        <Col xs={24} sm={12} md={8} lg={6}>
          <Input
            allowClear
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search resources"
            prefix={<SearchOutlined style={{ color: "#bfbfbf" }} />}
          />
        </Col>
        {knownKinds.length > 0 && (
          <Col flex="none">
            <Radio.Group
              value={kindFilter || "all"}
              onChange={(e) =>
                setKindFilter(e.target.value === "all" ? undefined : e.target.value)
              }
            >
              <Radio.Button value="all">All ({resources.length})</Radio.Button>
              {knownKinds.map((k) => (
                <Radio.Button key={k} value={k}>
                  {k} ({resources.filter((r) => r.kind === k).length})
                </Radio.Button>
              ))}
            </Radio.Group>
          </Col>
        )}
        <Col flex="auto" style={{ textAlign: "right" }}>
          <Button
            className="beam-btn green-btn cover"
            icon={<PlusOutlined />}
            onClick={() => setCreating(true)}
          >
            Add resource
          </Button>
        </Col>
      </Row>

      <Row className="scrollable-table mt-3" style={{ display: "grid" }}>
        <Col span={24} style={{ maxHeight: 800, overflow: "auto" }}>
          <Table
            rowKey={(r: SchedResource) => r.id || r.name}
            dataSource={filtered}
            columns={columns as any}
            scroll={{ x: true }}
            locale={{ emptyText: "No resources yet — add rooms, teachers and equipment" }}
          />
        </Col>
      </Row>

      <ResourceFormModal
        visible={creating || editing !== undefined}
        orgId={orgId}
        resource={editing}
        settings={settings}
        knownKinds={knownKinds}
        knownLocations={knownLocations}
        onClose={() => {
          setCreating(false);
          setEditing(undefined);
        }}
        onSaved={refetch}
      />
    </div>
  );
};

export default ResourcesTab;
