import React from "react";
import { Form, FormInstance, Tooltip } from "antd";
import { scrollWithinContainer } from "../common/ui";

export type SectionKey = "patient" | "trip" | "billing" | "assignment";

// Mirrors the `required` rules in DispatchingForm; assignment is optional
// but worth flagging.
const SECTIONS: { key: SectionKey; title: string; fields: [string, string][] }[] = [
  {
    key: "patient",
    title: "Patient",
    fields: [
      ["patientFirstName", "first name"],
      ["patientLastName", "last name"],
    ],
  },
  {
    key: "trip",
    title: "Trip",
    fields: [
      ["serviceType", "service type"],
      ["transferType", "transfer type"],
      ["pickupLocation", "pickup address"],
      ["dropoffLocation", "drop-off address"],
      ["pickupDate", "pickup date"],
      ["usedServiceBefore", "used service before"],
    ],
  },
  {
    key: "billing",
    title: "Billing",
    fields: [
      ["billingInstitute", "billing institute"],
      ["pricingType", "pricing type"],
    ],
  },
  { key: "assignment", title: "Assignment", fields: [["primaryResponder", "driver"]] },
];

const isFilled = (value: any) =>
  value !== undefined &&
  value !== null &&
  value !== "" &&
  !(Array.isArray(value) && value.length === 0) &&
  !(typeof value === "object" && "id" in value && !value.id && !value.value);

export const sectionIndex = (key: SectionKey) => SECTIONS.findIndex((s) => s.key === key) + 1;
export const sectionAnchor = (key: SectionKey) => `section-${key}`;

/**
 * Missing field labels per section, live from the form. `skip` lists fields
 * the current form doesn't show (e.g. pickup date in recurring bookings).
 */
export const useSectionStatus = (form: FormInstance, skip: string[] = []) => {
  // One watch per field keeps this reactive without watching the whole form.
  const values: Record<string, any> = {};
  SECTIONS.forEach((section) =>
    section.fields.forEach(([name]) => {
      // eslint-disable-next-line react-hooks/rules-of-hooks
      values[name] = Form.useWatch(name, form);
    })
  );

  return SECTIONS.reduce((acc, section) => {
    acc[section.key] = section.fields
      .filter(([name]) => !skip.includes(name) && !isFilled(values[name]))
      .map(([, label]) => label);
    return acc;
  }, {} as Record<SectionKey, string[]>);
};

const scrollTo = (key: SectionKey) =>
  scrollWithinContainer(document.getElementById(sectionAnchor(key)), {
    offset: 8,
    stickySelector: ".fixed-fields-container",
  });

/** Step chips that show what's left and jump to each section. */
const BookingProgress = ({ status }: { status: Record<SectionKey, string[]> }) => (
  <div className="mx-progress">
    {SECTIONS.map((section, i) => {
      const missing = status[section.key] || [];
      const done = missing.length === 0;
      return (
        <Tooltip
          key={section.key}
          title={done ? "Complete" : `Missing: ${missing.join(", ")}`}
        >
          <span
            className={`mx-progress__step ${done ? "mx-progress__step--done" : ""}`}
            onClick={() => scrollTo(section.key)}
          >
            <span className="mx-progress__index">{done ? "✓" : i + 1}</span>
            {section.title}
            {!done && <span className="mx-progress__missing">{missing.length} left</span>}
          </span>
        </Tooltip>
      );
    })}
  </div>
);

export default BookingProgress;
