import { useEffect, useMemo, useState } from "react";
import { SocketTopics } from "constants/enums";
import {
  getOrgRideInvitationSubscriptionTopic,
  getRideInvitationSubscriptionTopic,
} from "hooks/MQTTConstants";
import { RidePageUpdatedEvent, subscribeRidePageUpdated } from "./rideSync";

// Live "who is this ride being offered to" for the dispatcher. One socket
// subscription to the org's ride-invitation topic feeds a module-level store
// that every rides table and the Fleet tab read, so a broadcast ring (one
// event per driver) shows every driver, not just the last one.
//
// Offers live only in memory: what was offered before the dashboard opened
// (or before a reload) is not known.

export interface RideOffer {
  driverUserId: string;
  offerId?: string;
  /** Local clock, when the event arrived. */
  receivedAt: number;
  /** Local clock, when the offer runs out. */
  expiresAt: number;
  /** Pickup address from the invitation payload, when it carries one. */
  pickup?: string;
}

export interface RideOffersState {
  /** pageId -> live offers for that ride (newest last). */
  byPage: Record<string, RideOffer[]>;
}

export interface DriverOffer {
  pageId: string;
  expiresAt: number;
  offerId?: string;
  pickup?: string;
}

export const EMPTY_OFFERS_STATE: RideOffersState = { byPage: {} };

// Ring time when the payload has neither a usable expiresAt nor a timeout.
export const DEFAULT_OFFER_MS = 20000;
// Upper bound for any offer (guards against a bad timestamp / clock skew).
export const MAX_OFFER_MS = 10 * 60 * 1000;

const LEGACY_INVITATION_WILDCARD =
  process.env.REACT_APP_RIDE_INVITATION_LEGACY_WILDCARD === "true";

// Ride statuses (backend colours) in which a ride can still be offered:
// dispatching, scheduled (advance pre-dispatch) and escalated (re-dispatch).
// Any other status means accepted / cancelled / completed.
const OFFERING_STATUSES = new Set(["purple", "brown", "red"]);
export const isOfferingStatus = (status?: string) =>
  !status || OFFERING_STATUSES.has(status);

// ---------------------------------------------------------------------------
// Pure helpers / reducers
// ---------------------------------------------------------------------------

/**
 * When an offer runs out, on the local clock. The server's expiresAt (newer
 * ride service, server clock) is used when it is plausible here: in the
 * future, within MAX_OFFER_MS and not longer than the ring `timeout` (+5s
 * slack). Otherwise (old backend, or skewed clocks) receivedAt + timeout,
 * else receivedAt + DEFAULT_OFFER_MS.
 */
export const offerExpiresAt = (data: any, receivedAt: number): number => {
  const timeoutMs = Number(data?.timeout) * 1000;
  const hasTimeout = Number.isFinite(timeoutMs) && timeoutMs > 0;
  const expiresAt = Number(data?.expiresAt);
  if (Number.isFinite(expiresAt) && expiresAt > 0) {
    const left = expiresAt - receivedAt;
    const cap = hasTimeout ? Math.min(MAX_OFFER_MS, timeoutMs + 5000) : MAX_OFFER_MS;
    if (left > 0 && left <= cap) return expiresAt;
  }
  return receivedAt + (hasTimeout ? Math.min(timeoutMs, MAX_OFFER_MS) : DEFAULT_OFFER_MS);
};

export interface ParsedInvitation {
  pageId: string;
  offer: RideOffer;
}

/**
 * Invitation socket message -> offer, or undefined when it is not for this
 * org (cudbServiceId) or incomplete.
 */
export const parseInvitation = (
  response: any,
  serviceId: any,
  receivedAt: number,
  legacyWildcard = LEGACY_INVITATION_WILDCARD
): ParsedInvitation | undefined => {
  const data = response?.data;
  const driverUserId =
    data?.driverUserId?.toString() || response?.pattern?.split("/")?.[4];
  const pageId = data?.pageId?.toString();
  const attributes = data?.rideRequestAttributes;
  const cudbServiceId = attributes?.cudbServiceId;
  if (cudbServiceId !== undefined && `${serviceId}` !== `${cudbServiceId}`) return;
  // The wildcard topic carries every org's invitations: only trust tagged ones.
  if (legacyWildcard && cudbServiceId === undefined) return;
  if (!driverUserId || !pageId) return;
  const expiresAt = offerExpiresAt(data, receivedAt);
  if (expiresAt <= receivedAt) return;
  const pickup =
    attributes?.pickupAddress || attributes?.pickupLocation?.attributes?.address;
  return {
    pageId,
    offer: {
      driverUserId,
      offerId: data?.offerId ? `${data.offerId}` : undefined,
      receivedAt,
      expiresAt,
      pickup: typeof pickup === "string" && pickup ? pickup : undefined,
    },
  };
};

const withoutDriver = (
  byPage: Record<string, RideOffer[]>,
  driverUserId: string
) => {
  let changed = false;
  const next: Record<string, RideOffer[]> = {};
  Object.keys(byPage).forEach((pageId) => {
    const list = byPage[pageId];
    const kept = list.filter((o) => o.driverUserId !== driverUserId);
    if (kept.length !== list.length) changed = true;
    if (kept.length) next[pageId] = kept.length === list.length ? list : kept;
  });
  return changed ? next : byPage;
};

/**
 * Adds an offer. A driver holds one offer at a time (the dispatch engine
 * rings each driver for one ride at once), so the driver's older offer — on
 * this ride or any other — is replaced.
 */
export const addOffer = (
  state: RideOffersState,
  pageId: string,
  offer: RideOffer
): RideOffersState => {
  const byPage = { ...withoutDriver(state.byPage, offer.driverUserId) };
  byPage[pageId] = [...(byPage[pageId] || []), offer];
  return { byPage };
};

/** Drops offers that ran out. Same reference when nothing expired. */
export const pruneExpired = (
  state: RideOffersState,
  now: number
): RideOffersState => {
  let changed = false;
  const byPage: Record<string, RideOffer[]> = {};
  Object.keys(state.byPage).forEach((pageId) => {
    const list = state.byPage[pageId];
    const live = list.filter((o) => o.expiresAt > now);
    if (live.length !== list.length) changed = true;
    if (live.length) byPage[pageId] = live.length === list.length ? list : live;
  });
  return changed ? { byPage } : state;
};

/** Drops every offer for one ride. Same reference when it had none. */
export const clearPage = (
  state: RideOffersState,
  pageId: string
): RideOffersState => {
  if (!state.byPage[pageId]) return state;
  const byPage = { ...state.byPage };
  delete byPage[pageId];
  return { byPage };
};

/** Ride status carried by a ridePageUpdated event (meta or row), if any. */
export const eventStatus = (event: RidePageUpdatedEvent): string | undefined =>
  event?.meta?.status ||
  event?.row?.nonpersistent?.static?.live?.status?.name ||
  undefined;

/**
 * ridePageUpdated: a ride that left the offering statuses (accepted,
 * cancelled, completed…) has no live offers any more.
 */
export const applyRideUpdate = (
  state: RideOffersState,
  event: RidePageUpdatedEvent
): RideOffersState => {
  const status = eventStatus(event);
  if (!status || isOfferingStatus(status)) return state;
  return clearPage(state, `${event.pageId}`);
};

/** driverId -> the offer that driver currently holds. */
export const selectByDriver = (
  state: RideOffersState
): Record<string, DriverOffer> => {
  const out: Record<string, DriverOffer> = {};
  Object.keys(state.byPage).forEach((pageId) => {
    state.byPage[pageId].forEach((o) => {
      const prev = out[o.driverUserId];
      if (!prev || prev.expiresAt < o.expiresAt) {
        out[o.driverUserId] = {
          pageId,
          expiresAt: o.expiresAt,
          offerId: o.offerId,
          pickup: o.pickup,
        };
      }
    });
  });
  return out;
};

/** Earliest expiry across all offers (for the prune timer). */
export const nextExpiry = (state: RideOffersState): number | undefined => {
  let min: number | undefined;
  Object.keys(state.byPage).forEach((pageId) =>
    state.byPage[pageId].forEach((o) => {
      if (min === undefined || o.expiresAt < min) min = o.expiresAt;
    })
  );
  return min;
};

// ---------------------------------------------------------------------------
// Store
// ---------------------------------------------------------------------------

const OFFERS_COMPONENT_UUID = "ride-offers";

let state: RideOffersState = EMPTY_OFFERS_STATE;
const listeners = new Set<() => void>();
let pruneTimer: any;

const schedulePrune = () => {
  clearTimeout(pruneTimer);
  pruneTimer = undefined;
  const at = nextExpiry(state);
  if (at === undefined) return;
  pruneTimer = setTimeout(() => {
    setState(pruneExpired(state, Date.now()));
  }, Math.max(0, at - Date.now()) + 50);
};

const setState = (next: RideOffersState) => {
  if (next !== state) {
    state = next;
    Array.from(listeners).forEach((fn) => {
      try {
        fn();
      } catch (e) {
        console.error("ride offers listener failed", e);
      }
    });
  }
  schedulePrune();
};

export const getRideOffersState = () => state;

const subscribeStore = (fn: () => void) => {
  listeners.add(fn);
  return () => {
    listeners.delete(fn);
  };
};

interface Connection {
  topic: string;
  serviceId: string;
  refs: number;
  unsubscribePageUpdates?: () => void;
}
let connection: Connection | undefined;

const disconnect = (socket: ISocket) => {
  if (!connection) return;
  socket.unSubscribeToEvent(
    SocketTopics.SubscribePageTopics,
    connection.topic,
    undefined,
    OFFERS_COMPONENT_UUID
  );
  connection.unsubscribePageUpdates?.();
  connection = undefined;
  setState(EMPTY_OFFERS_STATE);
};

/**
 * Ref-counted: the first consumer subscribes to the org invitation topic (and
 * ridePageUpdated, to clear offers of accepted/cancelled rides), the last one
 * to release unsubscribes. Returns the release function.
 */
export const connectRideOffers = (
  socket: ISocket,
  serviceId: any,
  userId?: any
): (() => void) => {
  if (!serviceId) return () => {};
  const sid = `${serviceId}`;
  const topic = LEGACY_INVITATION_WILDCARD
    ? getRideInvitationSubscriptionTopic()
    : getOrgRideInvitationSubscriptionTopic(sid);
  // Another org (re-login): start over.
  if (connection && connection.topic !== topic) disconnect(socket);
  if (!connection) {
    connection = { topic, serviceId: sid, refs: 0 };
    socket.subscribeToEvent(
      SocketTopics.SubscribePageTopics,
      topic,
      (response: any) => {
        const parsed = parseInvitation(response, sid, Date.now());
        if (!parsed) return;
        setState(addOffer(pruneExpired(state, Date.now()), parsed.pageId, parsed.offer));
      },
      OFFERS_COMPONENT_UUID
    );
  }
  const conn = connection;
  if (userId && !conn.unsubscribePageUpdates) {
    conn.unsubscribePageUpdates = subscribeRidePageUpdated(socket, userId, (event) =>
      setState(applyRideUpdate(state, event))
    );
  }
  conn.refs += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (connection !== conn) return;
    conn.refs -= 1;
    if (conn.refs <= 0) disconnect(socket);
  };
};

/** Test hook: reset the module state. */
export const __resetRideOffers = () => {
  clearTimeout(pruneTimer);
  pruneTimer = undefined;
  connection = undefined;
  state = EMPTY_OFFERS_STATE;
  listeners.clear();
};

// ---------------------------------------------------------------------------
// React
// ---------------------------------------------------------------------------

/**
 * Keeps the invitation subscription alive while mounted (when given a
 * socket and the org's serviceId).
 */
export const useRideOffersConnection = (
  socket: ISocket | undefined,
  serviceId: any,
  userId?: any
) => {
  useEffect(() => {
    if (!socket || !serviceId || !socket.client) return;
    return connectRideOffers(socket, serviceId, userId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [socket?.client, serviceId, userId]);
};

/**
 * All live offers: by ride and by driver. Pass the socket + org to also hold
 * the subscription (ref-counted); without them it only reads the store.
 */
export const useRideOffers = (
  socket?: ISocket,
  serviceId?: any,
  userId?: any
): { byPage: Record<string, RideOffer[]>; byDriver: Record<string, DriverOffer> } => {
  useRideOffersConnection(socket, serviceId, userId);
  const [snapshot, setSnapshot] = useState(state);
  useEffect(() => {
    setSnapshot(state);
    return subscribeStore(() => setSnapshot(state));
  }, []);
  const byDriver = useMemo(() => selectByDriver(snapshot), [snapshot]);
  return { byPage: snapshot.byPage, byDriver };
};

const NO_OFFERS: RideOffer[] = [];

/**
 * Live offers for one ride. Re-renders only when that ride's list changes,
 * so a table cell doesn't redraw on every other ride's offer.
 */
export const useRidePageOffers = (pageId?: string): RideOffer[] => {
  const read = () => (pageId && state.byPage[pageId]) || NO_OFFERS;
  const [offers, setOffers] = useState<RideOffer[]>(read);
  useEffect(() => {
    setOffers(read());
    return subscribeStore(() => setOffers(read()));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pageId]);
  return offers;
};
