import React from "react";
import { Button, Progress, Tooltip } from "antd";
import { CheckOutlined, CloseOutlined, ThunderboltOutlined } from "@ant-design/icons";
import { EmptyState, Pill } from "../../../common/ui";
import {
  AVAILABILITY_META,
  formatMinutes,
  PlanResult,
} from "../../../common/driverAvailability/availability";

interface Props {
  plan: PlanResult;
  applying?: { done: number; total: number };
  onAccept: (pageId: string) => void;
  onDismiss: (pageId: string) => void;
  onAcceptAll: () => void;
  onOpenJob: (pageId: string) => void;
  onClose: () => void;
}

/** Review list for the suggested plan; nothing is saved until accepted. */
const PlanPanel = ({
  plan,
  applying,
  onAccept,
  onDismiss,
  onAcceptAll,
  onOpenJob,
  onClose,
}: Props) => {
  const { proposals, unplanned } = plan;
  return (
    <div className="mx-plan">
      <div className="mx-plan__header">
        <div>
          <div className="mx-plan__title">
            <ThunderboltOutlined /> Suggested plan
          </div>
          <div className="mx-plan__subtitle">
            Based on shifts, time off and existing jobs. Nothing is saved until you accept.
          </div>
        </div>
        <div className="mx-plan__actions">
          <Button className="mx-btn-secondary" onClick={onClose} disabled={!!applying}>
            Close
          </Button>
          <Button
            className="mx-btn-primary"
            icon={<CheckOutlined />}
            disabled={!proposals.length}
            loading={!!applying}
            onClick={onAcceptAll}
          >
            Assign all ({proposals.length})
          </Button>
        </div>
      </div>

      {applying && (
        <Progress
          percent={Math.round((applying.done / applying.total) * 100)}
          size="small"
          format={() => `${applying.done}/${applying.total}`}
        />
      )}

      {proposals.length === 0 && unplanned.length === 0 ? (
        <EmptyState title="Nothing to plan" description="Every job for this day has a driver." />
      ) : (
        <div className="mx-plan__list">
          {proposals.map(({ job, evaluation }) => {
            const meta = AVAILABILITY_META[evaluation.availability];
            return (
              <div key={job.pageId} className="mx-plan__item">
                <span className="mx-plan__time">{formatMinutes(job.pickupMin)}</span>
                <a className="mx-plan__job" onClick={() => onOpenJob(job.pageId)}>
                  {job.label}
                </a>
                <span className="mx-plan__arrow">→</span>
                <span className="mx-plan__driver">{evaluation.driver.name}</span>
                <Pill tone={meta.tone} plain>
                  {meta.label}
                </Pill>
                <span className="mx-plan__reason">{evaluation.reasons[0]}</span>
                <span className="mx-plan__item-actions">
                  <Tooltip title="Assign">
                    <Button
                      size="small"
                      icon={<CheckOutlined />}
                      disabled={!!applying}
                      onClick={() => onAccept(job.pageId)}
                    />
                  </Tooltip>
                  <Tooltip title="Dismiss">
                    <Button
                      size="small"
                      icon={<CloseOutlined />}
                      disabled={!!applying}
                      onClick={() => onDismiss(job.pageId)}
                    />
                  </Tooltip>
                </span>
              </div>
            );
          })}
          {unplanned.map(({ job, reason }) => (
            <div key={job.pageId} className="mx-plan__item mx-plan__item--unplanned">
              <span className="mx-plan__time">
                {job.pickupMin !== undefined ? formatMinutes(job.pickupMin) : "--:--"}
              </span>
              <a className="mx-plan__job" onClick={() => onOpenJob(job.pageId)}>
                {job.label}
              </a>
              <Pill tone="amber" plain>
                Needs you
              </Pill>
              <span className="mx-plan__reason">{reason}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default PlanPanel;
