import React, { FC, useEffect, useRef, useState } from "react";
import { Button, Checkbox, Empty, Input, Skeleton, Tooltip } from "antd";
import { CheckOutlined, HistoryOutlined, PlusOutlined, SearchOutlined } from "@ant-design/icons";
import moment from "moment";
import { Pill } from "../Medical/common/ui";
import {
  FleetVehicle,
  hasLocation,
  STATUS_META,
  statusMeta,
  TRIP_META,
  TripStage,
  VehicleFilter,
  VehicleOffer,
  VehicleOffers,
} from "./fleetUtils";

/** How the host's per-vehicle action button looks for one vehicle. */
export interface VehicleActionSpec {
  label: string;
  /** Shown as done/on (e.g. already added to the dispatch). */
  active?: boolean;
  disabled?: boolean;
  tooltip?: string;
}

interface Props {
  vehicles: FleetVehicle[];
  /** Before filtering, for the status counts. */
  counts: Record<string, number>;
  /** Vehicles per ride stage, before filtering. */
  tripCounts?: Record<string, number>;
  total: number;
  filter: VehicleFilter;
  onFilter: (next: VehicleFilter) => void;
  loading: boolean;
  selectedId?: string;
  onSelect: (id: string | undefined) => void;
  onHistory: (vehicle: FleetVehicle) => void;
  /** Vehicles the host has picked (drawn highlighted). */
  highlightIds?: string[];
  /** Optional per-vehicle action (e.g. "Assign" in the Ride dispatch screen). */
  onAction?: (vehicle: FleetVehicle) => void;
  actionFor?: (vehicle: FleetVehicle, picked: boolean) => VehicleActionSpec;
  /** Pending ride offers by vehicle id (host-provided). */
  offers?: VehicleOffers;
  /** Vehicles (before filtering) with a pending offer. */
  offeredCount?: number;
}

/** Seconds left on an offer, on its own 1s timer (the list doesn't re-render). */
const SecondsLeft: FC<{ expiresAt: number }> = ({ expiresAt }) => {
  const left = () => Math.max(0, Math.ceil((expiresAt - Date.now()) / 1000));
  const [secs, setSecs] = useState(left);
  useEffect(() => {
    setSecs(left());
    const id = setInterval(() => {
      const next = left();
      setSecs(next);
      if (next <= 0) clearInterval(id);
    }, 1000);
    return () => clearInterval(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [expiresAt]);
  return <span className="flt-offer__secs">{secs}s</span>;
};

/** "Offer pending · 12s" with the ride in a tooltip. */
export const OfferPill: FC<{ offer: VehicleOffer }> = ({ offer }) => (
  <Tooltip title={offer.label || `Ride #${offer.pageId}`}>
    <span className="flt-offer" tabIndex={0} onClick={(e) => e.stopPropagation()}>
      <span className="flt-offer__dot" aria-hidden="true" />
      Offer pending · <SecondsLeft expiresAt={offer.expiresAt} />
    </span>
  </Tooltip>
);

/** The host's action button; shared by the list rows and the map card. */
export const VehicleActionButton: FC<{
  vehicle: FleetVehicle;
  spec: VehicleActionSpec;
  onAction: (vehicle: FleetVehicle) => void;
  block?: boolean;
}> = ({ vehicle, spec, onAction, block }) => (
  <Tooltip title={spec.tooltip}>
    <Button
      size={block ? "middle" : "small"}
      type={spec.active ? "primary" : "default"}
      className={`flt-action ${spec.active ? "is-active" : ""} ${block ? "w-100" : ""}`}
      icon={spec.active ? <CheckOutlined /> : <PlusOutlined />}
      disabled={spec.disabled}
      onClick={(e) => {
        e.stopPropagation();
        onAction(vehicle);
      }}
    >
      {spec.label}
    </Button>
  </Tooltip>
);

const VehiclePanel: FC<Props> = ({
  vehicles,
  counts,
  tripCounts,
  total,
  filter,
  onFilter,
  loading,
  selectedId,
  onSelect,
  onHistory,
  highlightIds,
  onAction,
  actionFor,
  offers,
  offeredCount = 0,
}) => {
  const listRef = useRef<HTMLDivElement>(null);
  const statuses = Array.from(new Set([...Object.keys(STATUS_META), ...Object.keys(counts)]));

  // Selecting on the map scrolls the row into view.
  useEffect(() => {
    if (!selectedId) return;
    listRef.current
      ?.querySelector(`[data-vehicle="${CSS.escape(selectedId)}"]`)
      ?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  }, [selectedId]);

  const toggleStatus = (status: string) =>
    onFilter({
      ...filter,
      statuses: filter.statuses.includes(status)
        ? filter.statuses.filter((s) => s !== status)
        : [...filter.statuses, status],
    });

  const trips = filter.trips ?? [];
  const toggleTrip = (trip: TripStage) =>
    onFilter({
      ...filter,
      trips: trips.includes(trip) ? trips.filter((t) => t !== trip) : [...trips, trip],
    });
  const showOffered = !!offers && (offeredCount > 0 || !!filter.offered);
  const showTrips =
    trips.length > 0 || Object.values(tripCounts ?? {}).some((n) => n > 0) || showOffered;
  const filtered = filter.statuses.length > 0 || trips.length > 0 || !!filter.search || !!filter.offered;

  return (
    <div className="flt-panel">
      <div className="flt-panel__section">
        <Input
          allowClear
          prefix={<SearchOutlined />}
          placeholder="Search vehicle, driver, phone or ID"
          value={filter.search}
          onChange={(e) => onFilter({ ...filter, search: e.target.value })}
        />
        <div className="flt-chips">
          {statuses.map((status) => {
            const meta = statusMeta(status);
            const active = filter.statuses.includes(status);
            return (
              <button
                key={status}
                type="button"
                className={`flt-chip flt-chip--${meta.tone} ${active ? "is-active" : ""}`}
                onClick={() => toggleStatus(status)}
              >
                <span className="flt-dot" />
                {meta.label}
                <span className="flt-chip__count">{counts[status] ?? 0}</span>
              </button>
            );
          })}
        </div>
        {showTrips && (
          <div className="flt-chips" aria-label="Ride progress">
            {(Object.keys(TRIP_META) as TripStage[]).map((trip) => {
              const meta = TRIP_META[trip];
              const active = trips.includes(trip);
              return (
                <button
                  key={trip}
                  type="button"
                  className={`flt-chip flt-chip--${meta.tone} ${active ? "is-active" : ""}`}
                  onClick={() => toggleTrip(trip)}
                >
                  <span className="flt-dot" />
                  {meta.label}
                  <span className="flt-chip__count">{tripCounts?.[trip] ?? 0}</span>
                </button>
              );
            })}
            {showOffered && (
              <button
                type="button"
                className={`flt-chip flt-chip--amber flt-chip--offered ${filter.offered ? "is-active" : ""}`}
                aria-pressed={!!filter.offered}
                onClick={() => onFilter({ ...filter, offered: !filter.offered })}
              >
                <span className="flt-dot" />
                Offered
                <span className="flt-chip__count">{offeredCount}</span>
              </button>
            )}
          </div>
        )}
        <div className="flt-panel__row">
          <Checkbox
            checked={filter.locatedOnly}
            onChange={(e) => onFilter({ ...filter, locatedOnly: e.target.checked })}
          >
            Only vehicles with a location
          </Checkbox>
          {filtered && (
            <Button
              type="link"
              size="small"
              onClick={() => onFilter({ ...filter, search: "", statuses: [], trips: [], offered: false })}
            >
              Clear
            </Button>
          )}
        </div>
        <div className="flt-muted">
          Showing {vehicles.length} of {total}
        </div>
      </div>

      <div className="flt-list" ref={listRef}>
        {loading && total === 0 ? (
          <div className="flt-panel__section">
            <Skeleton active paragraph={{ rows: 6 }} />
          </div>
        ) : vehicles.length === 0 ? (
          <Empty
            className="mt-5"
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description={total ? "No vehicles match these filters" : "No vehicles in this area"}
          />
        ) : (
          vehicles.map((v) => {
            const meta = statusMeta(v.status);
            const selected = v.id === selectedId;
            const picked = !!highlightIds?.includes(v.id);
            return (
              <div
                key={v.id}
                data-vehicle={v.id}
                className={`flt-vehicle ${selected ? "is-selected" : ""} ${picked ? "is-picked" : ""}`}
                onClick={() => onSelect(selected ? undefined : v.id)}
              >
                <img src={`/images/car-${meta.tone}.svg`} alt="" className="flt-vehicle__icon" />
                <div className="flt-vehicle__body">
                  <div className="flt-vehicle__name">{v.name}</div>
                  {v.subtitle && <div className="flt-muted">{v.subtitle}</div>}
                  {(v.driver?.phone || v.driver?.customId) && (
                    <div className="flt-muted flt-vehicle__contact">
                      {[v.driver.phone, v.driver.customId && `ID ${v.driver.customId}`]
                        .filter(Boolean)
                        .join(" · ")}
                    </div>
                  )}
                  <div className="flt-vehicle__meta">
                    <Pill tone={meta.tone}>{meta.label}</Pill>
                    {v.trip && <Pill tone={TRIP_META[v.trip].tone}>{TRIP_META[v.trip].label}</Pill>}
                    {offers?.[v.id] && <OfferPill offer={offers[v.id]} />}
                    {!hasLocation(v) ? (
                      <span className="flt-muted">No location</span>
                    ) : (
                      v.lastSeen && <span className="flt-muted">{moment(v.lastSeen).fromNow()}</span>
                    )}
                  </div>
                </div>
                {onAction && actionFor && (
                  <VehicleActionButton vehicle={v} spec={actionFor(v, picked)} onAction={onAction} />
                )}
                <Tooltip title="Breadcrumb history">
                  <Button
                    size="small"
                    icon={<HistoryOutlined />}
                    onClick={(e) => {
                      e.stopPropagation();
                      onHistory(v);
                    }}
                  />
                </Tooltip>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
};

export default VehiclePanel;
