import React, { FC, useCallback, useEffect, useMemo, useState } from "react";
import { Button, Drawer, Tabs, Tooltip } from "antd";
import type { ColumnsType } from "antd/es/table";
import { CopyOutlined, DownloadOutlined, PrinterOutlined, SendOutlined } from "@ant-design/icons";
import moment from "moment";
import { useSelector } from "react-redux";
import { RootState } from "reducers/rootReducer";
import { pushNotification } from "utils/notifications";
import { DataTableCard, EmptyState, Pill, matchesSearch } from "../Medical/common/ui";
import { BrandCouponTopic, useBrandCouponApi, useCouponQueries } from "./couponApi";
import { conditionLines, discountHeadline, formatMoney } from "./couponRules";
import { downloadDataUrl, printCards, renderCouponCardPng, slug } from "./card/renderCard";
import CardPreview from "./card/CardPreview";
import { REDEMPTION_COLUMNS } from "./screens/shared";
import { CouponLocationRecord, CouponRecord, RecipientRecord, RedemptionRecord } from "./types";

const DELIVERY_TONE = { sent: "green", failed: "red", pending: "gray" } as const;

interface Props {
  socket?: ISocket;
  coupon?: CouponRecord;
  open: boolean;
  refreshKey: number;
  locations: CouponLocationRecord[];
  onClose: () => void;
  onShare: (coupon: CouponRecord) => void;
}

const CouponDetailDrawer: FC<Props> = ({ socket, coupon, open, refreshKey, locations, onClose, onShare }) => {
  const { loadRecipients, loadRedemptions } = useCouponQueries();
  const call = useBrandCouponApi(socket);
  const { encrypted_token, projects } = useSelector((state: RootState) => state.auth);
  const [recipients, setRecipients] = useState<RecipientRecord[]>([]);
  const [redemptions, setRedemptions] = useState<RedemptionRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");
  const [selected, setSelected] = useState<string[]>([]);
  const [busy, setBusy] = useState<string | null>(null);

  const load = useCallback(async () => {
    if (!coupon) return;
    setLoading(true);
    const [r, d] = await Promise.all([
      loadRecipients(coupon.objectId),
      loadRedemptions({ couponId: coupon.objectId }),
    ]);
    setLoading(false);
    if (r) setRecipients(r);
    if (d) setRedemptions(d);
  }, [coupon, loadRecipients, loadRedemptions]);

  useEffect(() => {
    if (open) load();
    else {
      setRecipients([]);
      setRedemptions([]);
      setSelected([]);
      setSearch("");
    }
  }, [open, load, refreshKey]);

  const rows = useMemo(
    () => recipients.filter((r) => matchesSearch(search, r.info.name, r.info.email, r.info.phone)),
    [recipients, search]
  );

  if (!coupon) return null;
  const info = coupon.info;
  const ride = info.product === "ride";
  const locationNames = (info.locationIds || []).map(
    (id) => locations.find((l) => l.objectId === id)?.info.name || "Removed location"
  );
  const cancelledRides = redemptions.filter((r) => r.info.status === "cancelled").length;

  const card = (r: RecipientRecord) => renderCouponCardPng(info, { url: r.info.redeemUrl, caption: r.info.name });

  const download = async (r: RecipientRecord) => {
    downloadDataUrl(await card(r), `${slug(info.title)}-${slug(r.info.name || r.info.email || r.info.phone || "")}.png`);
  };

  const print = async (list: RecipientRecord[]) => {
    setBusy("print");
    const images = [];
    for (const r of list) images.push(await card(r));
    setBusy(null);
    if (!printCards(images, info.title)) pushNotification("Allow pop-ups to print the cards", "error", "TOP_CENTER", 3000);
  };

  const copy = (r: RecipientRecord) =>
    navigator.clipboard
      ?.writeText(r.info.viewUrl)
      .then(() => pushNotification("Coupon link copied", "success", "TOP_CENTER", 1500));

  const resend = async (r: RecipientRecord) => {
    setBusy(r.objectId);
    const image = r.info.email ? await card(r).catch(() => undefined) : undefined;
    const reply = await call<{ results: { status: string; error?: string }[] }>(BrandCouponTopic.Send, {
      userId: encrypted_token?.userId,
      cudbServiceId: projects?.userServiceId,
      couponId: coupon.objectId,
      deliveries: [{ recipientKey: r.info.recipientKey, image }],
    });
    setBusy(null);
    const result = reply?.data?.results?.[0];
    if (reply?.status && result?.status === "sent") {
      pushNotification("Coupon sent", "success", "TOP_CENTER", 1500);
      load();
    } else {
      pushNotification(result?.error || reply?.data?.details || "Could not send the coupon", "error", "TOP_CENTER", 3000);
    }
  };

  const columns: ColumnsType<RecipientRecord> = [
    {
      title: "Recipient",
      key: "who",
      render: (_, r) => (
        <div>
          <strong>{r.info.name || r.info.email || r.info.phone}</strong>
          <div className="cpn-muted">{[r.info.email, r.info.phone].filter(Boolean).join(" · ")}</div>
        </div>
      ),
    },
    {
      title: "Delivery",
      key: "delivery",
      render: (_, r) => (
        <Pill tone={DELIVERY_TONE[r.info.deliveryStatus] || "gray"} title={r.info.deliveryError || undefined}>
          {r.info.deliveryStatus === "sent"
            ? `Sent ${r.info.sentAt ? moment(r.info.sentAt).format("MMM D") : ""}`
            : r.info.deliveryStatus === "failed"
            ? "Failed"
            : "Not sent"}
        </Pill>
      ),
    },
    {
      title: "Scanned",
      key: "scanned",
      render: (_, r) => (r.info.scannedAt ? moment(r.info.scannedAt).format("MMM D, h:mm A") : "—"),
    },
    { title: "Uses", key: "uses", align: "right", render: (_, r) => r.info.usesCount || 0 },
    {
      title: "",
      key: "actions",
      align: "right",
      width: 170,
      render: (_, r) => (
        <span className="mx-row-actions">
          <Tooltip title="Download card">
            <Button size="small" icon={<DownloadOutlined />} onClick={() => download(r)} />
          </Tooltip>
          <Tooltip title="Print card">
            <Button size="small" icon={<PrinterOutlined />} onClick={() => print([r])} />
          </Tooltip>
          <Tooltip title="Copy link">
            <Button size="small" icon={<CopyOutlined />} onClick={() => copy(r)} />
          </Tooltip>
          <Tooltip title="Resend">
            <Button
              size="small"
              icon={<SendOutlined />}
              loading={busy === r.objectId}
              disabled={info.status !== "active"}
              onClick={() => resend(r)}
            />
          </Tooltip>
        </span>
      ),
    },
  ];

  const selectedRows = recipients.filter((r) => selected.includes(r.objectId));

  return (
    <Drawer
      open={open}
      onClose={onClose}
      width={980}
      title={info.title}
      className="cpn-drawer"
      extra={
        !ride && (
          <Button
            className="mx-btn-primary"
            icon={<SendOutlined />}
            disabled={info.status !== "active"}
            onClick={() => onShare(coupon)}
          >
            Share
          </Button>
        )
      }
    >
      <div className="cpn-drawer__summary">
        {!ride && (
          <CardPreview
            info={info}
            url={`${window.location.origin}/coupon/redeem?token=preview`}
            className="cpn-drawer__card"
          />
        )}
        <div className="cpn-drawer__facts">
          <div className="cpn-drawer__headline">{discountHeadline(info)}</div>
          <ul>
            {ride && (
              <>
                <li>
                  Ride coupon · code <strong>{info.code}</strong>
                </li>
                <li>
                  {info.accessType === "private"
                    ? `Only ${(info.allowedRecipients || []).length} listed passenger(s)`
                    : "Every passenger"}
                </li>
                <li>{locationNames.length ? `Pickups at ${locationNames.join(", ")}` : "Any pickup location"}</li>
              </>
            )}
            {conditionLines(info).map((line) => (
              <li key={line}>{line}</li>
            ))}
          </ul>
          {ride ? (
            <div className="cpn-drawer__stats">
              <div>
                <span>{coupon.stats.redeemed}</span>Used
              </div>
              <div>
                <span>{formatMoney(coupon.stats.discountTotal, info.currency)}</span>Discount given
              </div>
              <div>
                <span>{cancelledRides}</span>Rides cancelled
              </div>
            </div>
          ) : (
          <div className="cpn-drawer__stats">
            <div>
              <span>{coupon.stats.issued}</span>QR codes issued
            </div>
            <div>
              <span>{coupon.stats.sent}</span>Sent
            </div>
            <div>
              <span>{recipients.filter((r) => r.info.scannedAt).length}</span>Scanned
            </div>
            <div>
              <span>{coupon.stats.redeemed}</span>Used
            </div>
            <div>
              <span>{formatMoney(coupon.stats.discountTotal, info.currency)}</span>Discount given
            </div>
          </div>
          )}
        </div>
      </div>

      <Tabs
        items={[
          !ride && {
            key: "recipients",
            label: `Recipients (${recipients.length})`,
            children: (
              <DataTableCard<RecipientRecord>
                rowKey="objectId"
                loading={loading}
                caption={
                  <input
                    className="cpn-inline-search"
                    placeholder="Search recipients"
                    value={search}
                    onChange={(e) => setSearch(e.target.value)}
                  />
                }
                toolbar={
                  <Button
                    size="small"
                    icon={<PrinterOutlined />}
                    loading={busy === "print"}
                    disabled={!selectedRows.length}
                    onClick={() => print(selectedRows)}
                  >
                    Print {selectedRows.length || ""} {selectedRows.length === 1 ? "card" : "cards"}
                  </Button>
                }
                rowSelection={{ selectedRowKeys: selected, onChange: (keys) => setSelected(keys as string[]) }}
                columns={columns}
                dataSource={rows}
                pagination={rows.length > 50 ? { pageSize: 50, showSizeChanger: false } : false}
                scroll={{ x: true }}
                empty={
                  <EmptyState
                    title="Not shared yet"
                    description="Share this coupon to create a QR code for each customer."
                  />
                }
              />
            ),
          },
          {
            key: "redemptions",
            label: `Redemptions (${redemptions.length})`,
            children: (
              <DataTableCard<RedemptionRecord>
                rowKey="objectId"
                loading={loading}
                columns={REDEMPTION_COLUMNS.filter((c) => c.key !== "coupon")}
                dataSource={redemptions}
                pagination={redemptions.length > 50 ? { pageSize: 50, showSizeChanger: false } : false}
                scroll={{ x: true }}
                empty={<EmptyState title="No redemptions yet" />}
              />
            ),
          },
        ].filter(Boolean) as any}
      />
    </Drawer>
  );
};

export default CouponDetailDrawer;
