import moment from "moment";
import { STORAGE_KEYS } from "../constants";
import { TimeRangeKey, TimeRangeValue } from "../types";

// These ranges show the per-driver shift layout for a single day.
const SINGLE_DAY_RANGES: TimeRangeKey[] = ["today", "tomorrow", "specificDate"];

/**
 * Resolves a preset into timestamps. Relative presets are always recomputed
 * so a range saved yesterday as "today" still means today.
 */
export const resolveTimeRange = (value: TimeRangeValue): TimeRangeValue => {
  let start: number | undefined = value.startTimestamp;
  let end: number | undefined = value.endTimestamp;

  switch (value.selected) {
    case "today":
      start = moment().startOf("day").valueOf();
      end = moment().endOf("day").valueOf();
      break;
    case "todayAndBeyond":
      start = moment().startOf("day").valueOf();
      end = moment().add(100, "years").endOf("day").valueOf();
      break;
    case "allTime":
      start = moment().subtract(10, "years").startOf("day").valueOf();
      end = moment().add(10, "years").endOf("day").valueOf();
      break;
    case "tomorrow":
      start = moment().add(1, "day").startOf("day").valueOf();
      end = moment().add(1, "day").endOf("day").valueOf();
      break;
    case "nextWeek":
      start = moment().add(1, "week").startOf("week").valueOf();
      end = moment().add(1, "week").endOf("week").valueOf();
      break;
    case "customRange":
    case "specificDate":
      break;
    default:
      start = start ?? moment().startOf("day").valueOf();
      end = end ?? moment().endOf("day").valueOf();
  }

  // Normalise to whole days so the server query and the live-update
  // range check agree on exactly the same window.
  return {
    ...value,
    startTimestamp: start !== undefined ? moment(start).startOf("day").valueOf() : undefined,
    endTimestamp: end !== undefined ? moment(end).endOf("day").valueOf() : undefined,
  };
};

export const DEFAULT_TIME_RANGE: TimeRangeValue = { selected: "today" };

export const loadStoredTimeRange = (): TimeRangeValue => {
  try {
    const stored = JSON.parse(localStorage.getItem(STORAGE_KEYS.timeRange) || "null");
    if (stored?.selected) return resolveTimeRange(stored);
  } catch {
    // fall through to default
  }
  return resolveTimeRange(DEFAULT_TIME_RANGE);
};

export const saveTimeRange = (value?: TimeRangeValue) => {
  if (value) localStorage.setItem(STORAGE_KEYS.timeRange, JSON.stringify(value));
  else localStorage.removeItem(STORAGE_KEYS.timeRange);
};

/** Day (start-of-day timestamp) whose shifts should be shown, if any. */
export const getShiftDate = (value: TimeRangeValue): number | undefined =>
  SINGLE_DAY_RANGES.includes(value.selected) && value.startTimestamp
    ? moment(value.startTimestamp).startOf("day").valueOf()
    : undefined;
