import React from "react";
import { Modal, Form, Input, Button } from "antd";
import { useDispatchPanel } from "../context";

const VerifyCodeModal: React.FC = () => {
  const { verifyModal, setVerifyModal, error, setError, searching, onSubmitHandler } =
    useDispatchPanel();

  if (verifyModal === undefined) return null;

  return (
    <Modal
      visible={true}
      onOk={() => {
        setVerifyModal(undefined);
      }}
      onCancel={() => {
        setVerifyModal(undefined);
      }}
      width="480px"
      className="auth-layout"
      footer={null}
      destroyOnClose
    >
      <div className="page-container auth-page">
        <Form
          className="auth-form"
          name="resend-form"
          id="resend-form"
          layout="vertical"
          onFinish={(values) => {
            console.log("otp values", values);
            onSubmitHandler(verifyModal, values.verificationCode);
          }}
          requiredMark={false}
        >
          <h3>Verify Code</h3>
          <span>Please enter code you received email or phone</span>
          <Form.Item
            className="mt-2"
            name="verificationCode"
            rules={[{ required: true, message: "**Required Field" }]}
          >
            <Input type="text" placeholder="Booking Verification Code" />
          </Form.Item>
          {error && (
            <Form.Item>
              <p className="error">{error}</p>
            </Form.Item>
          )}
          <Form.Item>
            <Button
              className="btn"
              loading={searching}
              type="primary"
              htmlType="submit"
              onClick={() => setError("")}
            >
              Verify
            </Button>
          </Form.Item>
        </Form>
      </div>
    </Modal>
  );
};

export default VerifyCodeModal;
